"""
Memory Agent - Manages semantic and persistent memory
"""

import json;
import time;
import from tools.vector_memory { VectorMemory }
import from tools.db_memory { DatabaseMemory }

walker StoreMemory {
    """
    Stores research findings in semantic and database memory
    """
    has results: list;
    has session_id: str;
    has vector_memory: any = None;
    has db_memory: any = None;

    def init {
        self.vector_memory = VectorMemory();
        self.db_memory = DatabaseMemory();
    }

    can with Root entry {
        self.store_all_results();
    }

    def store_all_results {
        for result in self.results {
            self.store_semantic(result);
            self.store_persistent(result);
        }

        self.index_memory();
    }

    def store_semantic(result: dict) {
        task_id = result.get('task_id');
        content = result.get('analysis', result.get('search_results', ''));

        if content {
            entry_id = f"{self.session_id}_{task_id}";

            self.vector_memory.add(
                entry_id=entry_id,
                text=str(content),
                metadata={
                    'task_id': task_id,
                    'session_id': self.session_id,
                    'timestamp': time.time(),
                    'type': result.get('type', 'analysis')
                }
            );
        }
    }

    def store_persistent(result: dict) {
        task_id = result.get('task_id');
        status = result.get('status');
        content = result.get('analysis', json.dumps(result.get('search_results', [])));

        memory_entry = {
            'session_id': self.session_id,
            'task_id': task_id,
            'content': content,
            'status': status,
            'timestamp': time.time(),
            'type': result.get('type', 'result')
        };

        self.db_memory.insert(memory_entry);
    }

    def index_memory {
        self.vector_memory.build_index();
        report f"Memory indexed for session {self.session_id}";
    }
}

walker MemoryRetrieval {
    """
    Retrieves relevant information from memory
    """
    has query: str;
    has session_id: str;
    has vector_memory: any = None;
    has db_memory: any = None;
    has retrieved_memories: list = [];

    def init {
        self.vector_memory = VectorMemory();
        self.db_memory = DatabaseMemory();
    }

    can with Root entry {
        self.retrieve_semantic();
        self.retrieve_historical();
        self.merge_results();
    }

    def retrieve_semantic {
        results = self.vector_memory.search(self.query, top_k=5);
        self.retrieved_memories.extend(results);
    }

    def retrieve_historical {
        results = self.db_memory.query_by_session(self.session_id, limit=10);
        self.retrieved_memories.extend(results);
    }

    def merge_results {
        seen = set();
        unique_memories = [];

        for memory in self.retrieved_memories {
            memory_key = memory.get('entry_id', memory.get('task_id', ''));
            if memory_key not in seen {
                seen.add(memory_key);
                unique_memories.append(memory);
            }
        }

        self.retrieved_memories = unique_memories;
    }
}

"""
Planner Agent - Breaks down complex queries into executable tasks
"""

import json;
import from tools.llm_tool { LLMTool }

walker PlanTasks {
    """
    Analyzes user query and creates a structured task plan
    """
    has query: str;
    has tasks: list = [];
    has task_count: int = 0;
    has llm_tool: any = None;

    def init {
        self.llm_tool = LLMTool();
    }

    can with Root entry {
        self.task_breakdown();
    }

    def task_breakdown {
        prompt = f"""
Analyze this research query and break it down into 3-5 concrete, executable tasks.

Query: {self.query}

For each task, provide:
1. Task description
2. Required tool (search, reasoning, analysis)
3. Priority (1-5, with 5 being highest)
4. Success criteria

Format as JSON list with fields: description, tool, priority, criteria
""";

        response = self.llm_tool.call(prompt);

        try {
            tasks_data = json.loads(response);
            for (i, task_data) in enumerate(tasks_data) {
                task_obj = {
                    'task_id': f'task_{i+1}',
                    'description': task_data.get('description', ''),
                    'tool': task_data.get('tool', 'reasoning'),
                    'priority': int(task_data.get('priority', 3)),
                    'criteria': task_data.get('criteria', ''),
                    'status': 'pending'
                };
                self.tasks.append(task_obj);
            }
        } except Exception {
            self.tasks = [
                {
                    'task_id': 'task_1',
                    'description': f'Research and analyze: {self.query}',
                    'tool': 'search',
                    'priority': 5,
                    'criteria': 'Gather comprehensive information',
                    'status': 'pending'
                }
            ];
        }
    }

    def generate_execution_plan {
        self.prioritize_tasks();

        plan = {
            'total_tasks': len(self.tasks),
            'tasks': self.tasks,
            'execution_order': [t['task_id'] for t in sorted(self.tasks, key=lambda (x: dict) { -(x['priority'] as int) })]
        };

        report f"Plan generated: {len(self.tasks)} tasks";
    }

    def prioritize_tasks {
        self.tasks = sorted(self.tasks, key=lambda (x: dict) { -(x['priority'] as int) });
    }
}

"""
Reflection Agent - Evaluates results and determines if more research is needed
"""

import json;
import from tools.llm_tool { LLMTool }

walker ReflectOnResults {
    """
    Evaluates task results and determines quality/completeness
    """
    has query: str;
    has tasks: list;
    has results: list;
    has reflection_data: dict = {};
    has llm_tool: any = None;
    has confidence_threshold: float = 0.7;
    has assessment: dict = {};

    def init {
        self.llm_tool = LLMTool();
    }

    can with Root entry {
        self.evaluate_results();
    }

    def evaluate_results {
        self.assessment = {
            'total_tasks': len(self.tasks),
            'completed_tasks': 0,
            'failed_tasks': 0,
            'task_assessments': []
        };

        for result in self.results {
            task_assessment = self.assess_confidence(result);
            self.assessment['task_assessments'].append(task_assessment);

            if result.get('status') == 'completed' {
                self.assessment['completed_tasks'] += 1;
            } else {
                self.assessment['failed_tasks'] += 1;
            }
        }

        self.check_completeness();
    }

    def assess_confidence(result: dict) -> dict {
        result_id = result.get('task_id');

        confidence_prompt = f"""
Evaluate the quality and confidence of this research result.

Result:
{json.dumps(result, indent=2)}

Assess:
1. Information quality (0-100)
2. Completeness (0-100)
3. Reliability (0-100)
4. Need for additional research (yes/no)
5. Recommendations for improvement

Format as JSON with keys: quality, completeness, reliability, needs_more_research, recommendations
""";

        assessment_response = self.llm_tool.call(confidence_prompt);

        try {
            assessment = json.loads(assessment_response);
        } except Exception {
            assessment = {
                'quality': 70,
                'completeness': 70,
                'reliability': 70,
                'needs_more_research': False,
                'recommendations': 'Unable to parse detailed assessment'
            };
        }

        return {
            'task_id': result_id,
            'assessment': assessment,
            'avg_confidence': (assessment.get('quality', 50) + assessment.get('completeness', 50) + assessment.get('reliability', 50)) / 3
        };
    }

    def check_completeness {
        if self.assessment['completed_tasks'] == 0 {
            self.reflection_data['overall_status'] = 'insufficient_data';
        } elif self.assessment['failed_tasks'] > 0 {
            self.reflection_data['overall_status'] = 'partial_success';
        } else {
            self.reflection_data['overall_status'] = 'complete';
        }

        avg_confidence = sum([a['avg_confidence'] for a in self.assessment['task_assessments']]) / max(1, len(self.assessment['task_assessments']));
        self.reflection_data['average_confidence'] = avg_confidence;
        self.reflection_data['needs_more_research'] = avg_confidence < self.confidence_threshold;
    }

    def generate_feedback -> dict {
        feedback_prompt = f"""
Based on this research assessment, provide feedback on research completeness.

Query: {self.query}
Assessment: {json.dumps(self.assessment, indent=2)}

Provide:
1. Research quality summary
2. Key gaps remaining
3. Recommended next steps
4. Overall readiness for final report (yes/no)

Be concise and actionable.
""";

        feedback = self.llm_tool.call(feedback_prompt);
        self.reflection_data['feedback'] = feedback;

        return self.reflection_data;
    }
}

"""
Summarizer Agent - Generates final reports and recommendations
"""

import json;
import time;
import from tools.llm_tool { LLMTool }

walker GenerateReport {
    """
    Synthesizes all findings into a professional final report
    """
    has query: str;
    has tasks: list;
    has results: list;
    has reflection: dict;
    has final_report: str = "";
    has llm_tool: any = None;

    def init {
        self.llm_tool = LLMTool();
    }

    can with Root entry {
        self.synthesize_findings();
    }

    def synthesize_findings {
        synthesis_prompt = f"""
Create a comprehensive research synthesis report.

Original Query: {self.query}

Task Summary: {len(self.tasks)} tasks executed
Results: {json.dumps(self.results, indent=2, `default=str)}
Reflection: {json.dumps(self.reflection, indent=2)}

Generate a synthesis that:
1. Summarizes key findings
2. Identifies patterns and insights
3. Highlights confidence levels
4. Notes any contradictions
5. Provides evidence quality assessment

Be thorough and analytical.
""";

        synthesis = self.llm_tool.call(synthesis_prompt);
        self.final_report = synthesis;
        self.generate_recommendation();
    }

    def generate_recommendation {
        recommendation_prompt = f"""
Based on this research, provide a final recommendation/conclusion.

Query: {self.query}
Synthesis: {self.final_report}

Provide:
1. Clear recommendation
2. Supporting evidence
3. Risk assessment (if applicable)
4. Confidence level (0-100%)
5. Important caveats
""";

        recommendation = self.llm_tool.call(recommendation_prompt);
        self.format_report(recommendation);
    }

    def format_report(recommendation: str) -> dict {
        detailed_results = [];
        for result in self.results {
            detailed_results.append({
                'task_id': result.get('task_id'),
                'type': result.get('type'),
                'status': result.get('status'),
                'summary': result.get('analysis', 'N/A')[:200] + '...' if result.get('analysis') else 'N/A'
            });
        }

        formatted_report = {
            'query': self.query,
            'total_tasks': len(self.tasks),
            'completed_tasks': len([r for r in self.results if r.get('status') == 'completed']),
            'research_quality': self.reflection.get('overall_status'),
            'average_confidence': round(self.reflection.get('average_confidence', 0) * 100),
            'task_results': detailed_results,
            'synthesis': self.final_report,
            'recommendation': recommendation,
            'generated_at': time.time()
        };

        return formatted_report;
    }

    def include_reasoning_chain -> dict {
        reasoning_chain = {
            'planning_phase': [
                {'task_id': t.get('task_id'), 'description': t.get('description')}
                for t in self.tasks
            ],
            'execution_phase': [
                {'task_id': r.get('task_id'), 'status': r.get('status')}
                for r in self.results
            ],
            'reflection_phase': self.reflection,
            'decisions_made': [
                'Query analyzed and decomposed',
                'Appropriate tools selected',
                'Tasks executed with retries',
                'Results evaluated for completeness',
                'Final synthesis generated'
            ]
        };

        return reasoning_chain;
    }
}

"""Runnable Jac engine for Assumption Court.

Node owns HTTP/UI/persistence. Jac owns the agentic court pass:
it builds an object-spatial graph, links typed evidence edges, runs role walkers,
and returns a structured verdict for the application to commit.
"""

import datetime;
import json;
import math;
import os;
import sys;
import typing;

node Claim {
    has id: str;
    has text: str;
    has normalized: str;
    has status: str = "needs_human";
    has confidence: int = 0;
    has expires_at: str = "";
}

node Evidence {
    has id: str;
    has text: str;
    has stance: str = "neutral";
    has source_id: str = "";
    has source_label: str = "Unknown source";
    has reliability: float = 0.65;
    has observed_at: str = "";
}

edge Supports {
    has stance: str = "support";
}

edge Contradicts {
    has stance: str = "contradict";
}

edge Cites {
    has stance: str = "neutral";
}

obj VerdictPolish {
    has rationale: str;
    has next_action: str;
}

def polish_verdict_with_gemini(
    claim_text: str,
    status: str,
    confidence: int,
    rationale: str,
    next_action: str,
    prosecution: list[str],
    defense: list[str]
) -> VerdictPolish by llm(temperature=0.2);

sem polish_verdict_with_gemini = """
You are Assumption Court's Jac byLLM judge clerk.
Use only the provided claim, status, confidence, rationale, next action,
prosecution, and defense. Return concise JSON for VerdictPolish.
Do not change status or confidence. Improve only rationale and next_action.
""";

walker WitnessFinder {
    has evidence: list[typing.Any] = [];
    has summary: str = "";
    has counts: dict[str, typing.Any] = {"support": 0, "contradict": 0, "neutral": 0};

    can inspect with Claim entry {
        for ev in [<--][?:Evidence] {
            item = {
                "id": ev.id,
                "type": "evidence",
                "text": ev.text,
                "stance": ev.stance,
                "sourceId": ev.source_id,
                "source": {"id": ev.source_id, "label": ev.source_label},
                "reliability": ev.reliability,
                "observedAt": ev.observed_at,
                "matchType": "jac_graph_edge",
                "matchScore": 1
            };
            self.evidence.append(item);

            if ev.stance == "support" {
                self.counts["support"] += 1;
            } elif ev.stance == "contradict" {
                self.counts["contradict"] += 1;
            } else {
                self.counts["neutral"] += 1;
            }
        }

        self.summary = f"Jac WitnessFinder traversed typed graph edges and found {self.counts['support']} supporting, {self.counts['contradict']} contradicting, and {self.counts['neutral']} neutral evidence nodes.";
    }
}

walker Prosecutor {
    has arguments: list[str] = [];

    can prosecute with Claim entry {
        support = 0;
        contradictions = 0;
        stale = 0;

        for ev in [<--][?:Evidence] {
            if ev.stance == "support" {
                support += 1;
            } elif ev.stance == "contradict" {
                contradictions += 1;
            }

            if age_in_days(ev.observed_at) > 21 {
                stale += 1;
            }
        }

        if support + contradictions == 0 {
            self.arguments.append("Jac Prosecutor found no connected evidence for this claim.");
        }
        if contradictions > 0 {
            self.arguments.append(f"{contradictions} contradiction{'s' if contradictions != 1 else ''} challenge the claim.");
        }
        if contradictions > support {
            self.arguments.append("Contradicting evidence currently outnumbers supporting evidence.");
        }
        if here.expires_at and iso_expired(here.expires_at) {
            self.arguments.append("The claim has passed its review or delivery date.");
        }
        if stale > 0 and stale >= support {
            self.arguments.append("Much of the available evidence is stale for a fast-moving startup decision.");
        }
        if high_risk(here.text) and support < 2 {
            self.arguments.append("The claim affects scope, trust, market, or technical risk and needs stronger validation.");
        }
        if len(self.arguments) == 0 {
            self.arguments.append("Jac Prosecutor found no major objection beyond normal startup uncertainty.");
        }
    }
}

walker Defender {
    has arguments: list[str] = [];

    can defend with Claim entry {
        support = 0;
        high_reliability = 0;
        recent = 0;
        total = 0;

        for ev in [<--][?:Evidence] {
            total += 1;
            if ev.stance == "support" {
                support += 1;
                if ev.reliability >= 0.7 {
                    high_reliability += 1;
                }
                if age_in_days(ev.observed_at) <= 7 {
                    recent += 1;
                }
            }
        }

        if support > 0 {
            self.arguments.append(f"{support} evidence node{'s' if support != 1 else ''} support the claim.");
        }
        if high_reliability > 0 {
            self.arguments.append("At least one supporting source is relatively reliable.");
        }
        if recent > 0 {
            self.arguments.append("The supporting evidence is recent enough for a near-term product decision.");
        }
        if support == 0 and total > 0 {
            self.arguments.append("The claim has context, but none of it clearly supports the claim yet.");
        }
        if total == 0 {
            self.arguments.append("The claim may be useful as a hypothesis, but it should not be treated as proven.");
        }
    }
}

walker Judge {
    has prosecutor_case: list[str] = [];
    has defender_case: list[str] = [];
    has verdict: dict[str, typing.Any] = {};

    can judge with Claim entry {
        support_weight = 0.0;
        contradiction_weight = 0.0;
        neutral_count = 0;
        evidence_count = 0;

        for ev in [<--][?:Evidence] {
            evidence_count += 1;
            weight = ev.reliability;
            if age_in_days(ev.observed_at) > 21 {
                weight *= 0.45;
            }

            if ev.stance == "support" {
                support_weight += weight;
            } elif ev.stance == "contradict" {
                contradiction_weight += weight;
            } else {
                neutral_count += 1;
            }
        }

        expired = iso_expired(here.expires_at) if here.expires_at else False;
        missing_evidence = evidence_count == 0;
        both_sides_strong = support_weight >= 1.1 and contradiction_weight >= 1.1;
        status = "uncertain";

        if expired {
            status = "expired";
        } elif missing_evidence {
            status = "needs_human";
        } elif both_sides_strong {
            status = "uncertain";
        } elif contradiction_weight > support_weight + 0.35 {
            status = "rejected" if contradiction_weight >= 1.0 else "uncertain";
        } elif support_weight > contradiction_weight + 0.45 {
            status = "accepted";
        }

        confidence = confidence_score(
            status,
            support_weight,
            contradiction_weight,
            evidence_count,
            neutral_count,
            expired,
            missing_evidence
        );

        self.verdict = {
            "status": status,
            "confidence": confidence,
            "rationale": rationale(
                status,
                support_weight,
                contradiction_weight,
                self.prosecutor_case,
                self.defender_case,
                expired,
                missing_evidence
            ),
            "nextAction": next_action(status, here.normalized),
            "factors": {
                "supportWeight": round2(support_weight),
                "contradictWeight": round2(contradiction_weight),
                "evidenceCount": evidence_count,
                "neutralCount": neutral_count,
                "prosecutionCount": len(self.prosecutor_case),
                "defenseCount": len(self.defender_case),
                "expired": expired,
                "jacWalkers": ["WitnessFinder", "Prosecutor", "Defender", "Judge", "Bailiff"]
            }
        };
    }
}

walker Bailiff {
    has verdict: dict[str, typing.Any] = {};
    has task_draft: dict[str, typing.Any] | None = None;

    can create_action with Claim entry {
        status = self.verdict.get("status", "needs_human");
        if status == "accepted" {
            self.task_draft = None;
        } else {
            prefix = "Review";
            if status == "rejected" {
                prefix = "Replace or narrow";
            } elif status == "uncertain" {
                prefix = "Test assumption";
            } elif status == "expired" {
                prefix = "Refresh stale assumption";
            } elif status == "needs_human" {
                prefix = "Find evidence for";
            }

            self.task_draft = {
                "title": f"{prefix}: {here.normalized}",
                "owner": "Founder",
                "dueInDays": 1 if status == "expired" else 3,
                "reason": self.verdict.get("nextAction", "Court verdict requires follow-up evidence.")
            };
        }
    }
}

def load_claim(graph: typing.Any, claim_id: str) -> typing.Any {
    for claim in graph["nodes"]["claims"] {
        if claim["id"] == claim_id {
            return claim;
        }
    }
    raise Exception(f"Claim not found: {claim_id}");
}

def related_evidence(graph: typing.Any, claim_id: str) -> list[typing.Any] {
    evidence_ids: list[typing.Any] = [];
    for edge in graph["edges"] {
        if edge.get("to") == claim_id and edge.get("type") in ["supports", "contradicts", "cites"] {
            evidence_ids.append(edge.get("from"));
        }
    }

    items: list[typing.Any] = [];
    for ev in graph["nodes"]["evidence"] {
        if ev["id"] in evidence_ids {
            items.append(ev);
        }
    }
    return items;
}

def source_label(graph: typing.Any, source_id: str) -> str {
    for source in graph["nodes"]["sources"] {
        if source.get("id") == source_id {
            return str(source.get("label", "Unknown source"));
        }
    }
    return "Unknown source";
}

def age_in_days(value: str) -> float {
    if not value {
        return 0.0;
    }
    try {
        parsed = datetime.datetime.fromisoformat(value.replace("Z", "+00:00"));
        if parsed.tzinfo is None {
            parsed = parsed.replace(tzinfo=datetime.timezone.utc);
        }
        now = datetime.datetime.now(datetime.timezone.utc);
        return max(0.0, (now - parsed).total_seconds() / 86400.0);
    } except Exception {
        return 0.0;
    }
}

def iso_expired(value: str) -> bool {
    if not value {
        return False;
    }
    try {
        parsed = datetime.datetime.fromisoformat(value.replace("Z", "+00:00"));
        if parsed.tzinfo is None {
            parsed = parsed.replace(tzinfo=datetime.timezone.utc);
        }
        return parsed < datetime.datetime.now(datetime.timezone.utc);
    } except Exception {
        return False;
    }
}

def high_risk(text: str) -> bool {
    lower = text.lower();
    for token in ["ship", "integrat", "stable", "trust", "competitor", "security", "privacy", "revenue", "backend"] {
        if token in lower {
            return True;
        }
    }
    return False;
}

def confidence_score(
    status: str,
    support_weight: float,
    contradiction_weight: float,
    evidence_count: int,
    neutral_count: int,
    expired: bool,
    missing_evidence: bool
) -> int {
    if missing_evidence {
        return 24;
    }
    if expired {
        return 68;
    }
    total: float = support_weight + contradiction_weight + (neutral_count * 0.2);
    balance: float = abs(support_weight - contradiction_weight);
    base: int = 44 if status == "uncertain" else 48;
    evidence_lift: float = clamp(total * 12.0, 0.0, 28.0);
    balance_lift: float = clamp(balance * 14.0, 0.0, 22.0);
    ambiguity_penalty: int = 8 if status == "uncertain" else 0;
    return int(round(clamp(base + evidence_lift + balance_lift - ambiguity_penalty + evidence_count, 20, 94)));
}

def clamp(value: float, low: float, high: float) -> float {
    return max(low, min(high, value));
}

def round2(value: float) -> float {
    return math.floor((value * 100.0) + 0.5) / 100.0;
}

def rationale(
    status: str,
    support_weight: float,
    contradiction_weight: float,
    prosecution: list[str],
    defense: list[str],
    expired: bool,
    missing_evidence: bool
) -> str {
    if missing_evidence {
        return "Jac Judge found no connected evidence. Treat this as a hypothesis until a human supplies sources.";
    }
    if expired {
        return "Jac Judge marked this claim expired because it passed its review window.";
    }
    if status == "accepted" {
        return f"Jac Judge accepts the claim because support outweighs contradiction ({round2(support_weight)} vs {round2(contradiction_weight)}). {defense[0] if len(defense) else ''}";
    }
    if status == "rejected" {
        return f"Jac Judge rejects the claim because contradiction outweighs support ({round2(contradiction_weight)} vs {round2(support_weight)}). {prosecution[0] if len(prosecution) else ''}";
    }
    return f"Jac Judge keeps the claim uncertain because the evidence is mixed ({round2(support_weight)} support vs {round2(contradiction_weight)} contradiction).";
}

def next_action(status: str, normalized: str) -> str {
    if status == "accepted" {
        return "Keep watching for contradictions, but this assumption can guide near-term work.";
    }
    if status == "rejected" {
        return "Change the plan or narrow the claim before using it for roadmap decisions.";
    }
    if status == "expired" {
        return "Run a fresh check-in or test before relying on this time-sensitive claim.";
    }
    if status == "needs_human" {
        return f"Attach at least two sources that support or challenge \"{normalized}\".";
    }
    return "Create a small validation task that can produce new evidence within three days.";
}

def build_claim_node(data: typing.Any) -> Claim {
    return Claim(
        id=str(data["id"]),
        text=str(data["text"]),
        normalized=str(data.get("normalized", data["text"])),
        status=str(data.get("status", "needs_human")),
        confidence=int(data.get("confidence", 0)),
        expires_at=str(data.get("expiresAt", ""))
    );
}

def build_evidence_node(graph: typing.Any, data: typing.Any) -> Evidence {
    return Evidence(
        id=str(data["id"]),
        text=str(data["text"]),
        stance=str(data.get("stance", "neutral")),
        source_id=str(data.get("sourceId", "")),
        source_label=source_label(graph, str(data.get("sourceId", ""))),
        reliability=float(str(data.get("reliability", 0.65))),
        observed_at=str(data.get("observedAt", ""))
    );
}

def env_flag(name: str) -> bool {
    value = str(os.environ.get(name, "")).lower();
    return value in ["1", "true", "yes", "on"];
}

def env_disabled(name: str) -> bool {
    value = str(os.environ.get(name, "")).lower();
    return value in ["0", "false", "no", "off"];
}

def should_use_byllm() -> bool {
    has_key = bool(os.environ.get("GEMINI_API_KEY", "")) or bool(os.environ.get("GOOGLE_API_KEY", ""));
    if not has_key {
        return False;
    }
    if env_flag("COURT_RULES_ONLY") or env_disabled("COURT_JAC_BYLLM") {
        return False;
    }
    return True;
}

with entry {
    if len(sys.argv) < 2 {
        print(json.dumps({"error": "missing_input_path"}));
    } else {
        payload = json.loads(open(sys.argv[1], "r").read());
        graph: typing.Any = payload["graph"];
        claim_id: str = str(payload["claimId"]);
        disable_llm = bool(payload.get("disableLlm", False));
        claim_data = load_claim(graph, claim_id);
        claim = build_claim_node(claim_data);

        edge_count = 0;
        for ev_data in related_evidence(graph, claim_id) {
            ev = build_evidence_node(graph, ev_data);
            if ev.stance == "support" {
                ev +>:Supports:+> claim;
            } elif ev.stance == "contradict" {
                ev +>:Contradicts:+> claim;
            } else {
                ev +>:Cites:+> claim;
            }
            edge_count += 1;
        }

        witness = WitnessFinder();
        witness spawn claim;

        prosecutor = Prosecutor();
        prosecutor spawn claim;

        defender = Defender();
        defender spawn claim;

        judge = Judge(prosecutor_case=prosecutor.arguments, defender_case=defender.arguments);
        judge spawn claim;

        judge.verdict["factors"]["byLLM"] = "off";
        if should_use_byllm() and not disable_llm {
            judge.verdict["factors"]["byLLM"] = "unavailable";
            try {
                polish = polish_verdict_with_gemini(
                    claim.text,
                    str(judge.verdict.get("status", "uncertain")),
                    int(judge.verdict.get("confidence", 0)),
                    str(judge.verdict.get("rationale", "")),
                    str(judge.verdict.get("nextAction", "")),
                    prosecutor.arguments,
                    defender.arguments
                );
                if polish.rationale {
                    judge.verdict["rationale"] = polish.rationale;
                }
                if polish.next_action {
                    judge.verdict["nextAction"] = polish.next_action;
                }
                judge.verdict["factors"]["byLLM"] = "gemini";
            } except Exception {
                judge.verdict["factors"]["byLLM"] = "unavailable";
            }
        }

        bailiff = Bailiff(verdict=judge.verdict);
        bailiff spawn claim;

        print(json.dumps({
            "engine": "jac",
            "jac": {
                "version": "0.15.2",
                "features": [
                    "node archetypes",
                    "typed evidence edges",
                    "walker role separation",
                    "object-spatial traversal",
                    "byLLM Gemini verdict polish",
                    "structured verdict schema"
                ],
                "walkers": ["WitnessFinder", "Prosecutor", "Defender", "Judge", "Bailiff"],
                "topology": {"claimNodes": 1, "evidenceNodes": len(witness.evidence), "typedEdges": edge_count},
                "byLLM": judge.verdict["factors"].get("byLLM", "off")
            },
            "witness": {
                "evidence": witness.evidence,
                "summary": witness.summary,
                "counts": witness.counts
            },
            "prosecutorCase": prosecutor.arguments,
            "defenderCase": defender.arguments,
            "verdict": judge.verdict,
            "taskDraft": bailiff.task_draft
        }));
    }
}

