            </div>
            <div style={{"height": "6px", "background": "rgba(255,255,255,0.05)", "borderRadius": "3px", "overflow": "hidden"}}>
                <div
                    style={{
                        "height": "100%",
                        "width": str(pct) + "%",
                        "background": color,
                        "borderRadius": "3px",
                        "transition": "width 0.6s ease"
                    }}
                />
            </div>
        </div>;
}

