"""Async implementations for the ClientApp root component."""

# DEMO_USER_ID and DEMO_USER_PASSWORD are defined as globs in
# frontend.cl.jac so the production client bundle resolves them.

impl ClientApp.initAuth -> None {
    # Auth bootstrap that survives Factory rebuilds on free HF Spaces.
    #
    # Two compounding failure modes we have to handle:
    #
    # 1) On a fresh container, demo_user does not exist yet. The old
    #    code did login-first / signup-on-failure, but
    #    `ok = await jacLogin(...)` returns an object `{success: false, ...}`
    #    on failure — and `if not ok` is `false` for a truthy object,
    #    so the signup branch never fired. Fix: signup first (idempotent
    #    — 409 if user exists, fine), then login, then verify with
    #    `jacIsLoggedIn()` (the only reliable truthiness signal because
    #    it checks the actual stored token).
    #
    # 2) When the container restarts but the browser keeps the old token
    #    in localStorage, jacIsLoggedIn() returns true but the token
    #    references a user that no longer exists. Walker calls then 500
    #    with "User not found". Fix: probe /user/me with the stored
    #    token; if it 401s, clear it so the signup+login below runs.
    #
    # The runtime's __normalizeIdentity wraps the username string into
    # the correct flat {type, value} shape the server expects, so plain
    # string args to jacSignup/jacLogin are correct — verified via curl
    # against the deployed openapi.json schema.

    is_authed = False;

    # Stale-token check
    if jacIsLoggedIn() {
        try {
            probe = await fetch("/user/me", {
                "headers": {"Authorization": f"Bearer {localStorage.getItem('jac_token')}"}
            });
            if probe.status >= 400 {
                localStorage.removeItem("jac_token");
            }
        } except Exception as _ex {
            localStorage.removeItem("jac_token");
        }
    }

    if jacIsLoggedIn() {
        is_authed = True;
    } else {
        try {
            await jacSignup(DEMO_USER_ID, DEMO_USER_PASSWORD);
        } except Exception as _ex {}
        try {
            await jacLogin(DEMO_USER_ID, DEMO_USER_PASSWORD);
        } except Exception as _ex {}
        is_authed = jacIsLoggedIn();
    }

    if is_authed {
        user_id = DEMO_USER_ID;
        try {
            await root spawn SeedWalker(user_id=DEMO_USER_ID);
        } except Exception as _ex {}
    }
}

impl ClientApp.loadSession -> None {
    # Defensive gate — loadSession should only run after initAuth has
    # confirmed jacIsLoggedIn(). On a stale browser session whose token
    # has been revoked by a Factory rebuild, the cached app state will
    # still think we're authed; spawning walkers without a fresh login
    # gives the same "User not found" 500s. We re-run the same direct-
    # fetch auth flow as initAuth (see comments above) rather than the
    # @jac/runtime helpers, which silently no-op on shape mismatch.
    # Same stale-token probe as initAuth — guards against the case where
    # a Factory rebuild deleted the user but the browser still has the
    # old token. Without this, walker spawns below 500 with "User not
    # found" and we never recover.
    if jacIsLoggedIn() {
        try {
            probe = await fetch("/user/me", {
                "headers": {"Authorization": f"Bearer {localStorage.getItem('jac_token')}"}
            });
            if probe.status >= 400 {
                localStorage.removeItem("jac_token");
            }
        } except Exception as _ex {
            localStorage.removeItem("jac_token");
        }
    }

    if not jacIsLoggedIn() {
        try { await jacSignup(DEMO_USER_ID, DEMO_USER_PASSWORD); } except Exception as _ex {}
        try { await jacLogin(DEMO_USER_ID, DEMO_USER_PASSWORD); } except Exception as _ex {}
        if not jacIsLoggedIn() {
            session_data = {};
            return;
        }
        user_id = DEMO_USER_ID;
    }

    # Always re-run SeedWalker on session load so an already-authed user
    # whose root predates the demo-apps feature still picks them up on
    # next refresh. SeedWalker is idempotent — duplicate resource and
    # leads_to insertion is guarded; demo apps only seed when the
    # PersonNode has zero existing ApplicationNodes attached.
    try {
        await root spawn SeedWalker(user_id=user_id);
    } except Exception as _ex {}

    try {
        result = await root spawn MemoryWalker(
            user_id=user_id,
            mode="read_session"
        );
        raw = result.reports[0] if result.reports else None;
        if raw {
            session_data = raw;
        } else {
            session_data = {};
        }
    } except Exception as e {
        session_data = {};
    }
}

impl ClientApp.startApp -> None {
    # CTA from the landing page hides it and routes the user to the chat tab.
    # Auth runs on mount (initAuth in `with entry`). If it hasn't finished
    # yet, ChatPane's sendMessage will retry — don't block the UI here.
    show_landing = False;
    active_tab = "chat";
}

impl ClientApp.pushWalkerEvent(events: list) -> None {
    # Receives the FULL accumulated events list each call (not a delta).
    # This sidesteps React closure staleness when sendMessage fires many
    # updates in one synchronous burst — each call sets walker_events to
    # the full known list, so the last winner contains everything.
    walker_events = events;
}

impl ClientApp.navTab(tab_id: str, label: str) -> JsxElement {
    is_active = active_tab == tab_id;
    return
        <button
            onClick={lambda (_e: MouseEvent) { active_tab = tab_id; }}
            style={{
                "padding": "7px 14px",
                "background": ("#FFE500" if is_active else "transparent"),
                "color": ("#0A0A0A" if is_active else "rgba(255,255,255,0.55)"),
                "border": "none",
                "borderRadius": "8px",
                "fontSize": "13px",
                "fontWeight": ("600" if is_active else "500"),
                "cursor": "pointer",
                "transition": "all 0.2s ease",
                "display": "flex",
                "alignItems": "center",
                "gap": "7px"
            }}
        >
            {tabIcon(tab_id, is_active)}
            {label}
        </button>;
}

impl ClientApp.tabIcon(tab_id: str, is_active: bool) -> JsxElement {
    # Inline SVG traced icons — no emoji, no image files. Stroke color
    # tracks the active state so the active tab's black on yellow stays
    # visible while inactive tabs use a faded white.
    stroke = "#0A0A0A" if is_active else "rgba(255,255,255,0.7)";
    if tab_id == "chat" {
        # Speech bubble outline with a tail
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <path
                    d="M4 6.5 C 4 5.1 5.1 4 6.5 4 L 17.5 4 C 18.9 4 20 5.1 20 6.5 L 20 14 C 20 15.4 18.9 16.5 17.5 16.5 L 11 16.5 L 7 20 L 7 16.5 L 6.5 16.5 C 5.1 16.5 4 15.4 4 14 Z"
                    stroke={stroke}
                    strokeWidth="1.8"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                />
            </svg>;
    }
    if tab_id == "graph" {
        # Three connected nodes
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <circle cx="6" cy="6" r="2.5" stroke={stroke} strokeWidth="1.8"/>
                <circle cx="18" cy="8" r="2.5" stroke={stroke} strokeWidth="1.8"/>
                <circle cx="12" cy="18" r="2.5" stroke={stroke} strokeWidth="1.8"/>
                <path d="M8 7.5 L 15.5 8 M 17 10.5 L 13 15.5 M 7.5 8 L 10.5 16" stroke={stroke} strokeWidth="1.5" strokeLinecap="round"/>
            </svg>;
    }
    if tab_id == "plan" {
        # Checklist (rectangle + three rows + a check)
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <rect x="4" y="3" width="16" height="18" rx="2" stroke={stroke} strokeWidth="1.8"/>
                <path d="M8 8 L 10 10 L 13 7" stroke={stroke} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
                <path d="M8 14 L 16 14 M 8 17.5 L 14 17.5" stroke={stroke} strokeWidth="1.6" strokeLinecap="round"/>
            </svg>;
    }
    if tab_id == "telemetry" {
        # Bar chart, three ascending bars
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <rect x="4" y="13" width="3.5" height="7" rx="0.6" stroke={stroke} strokeWidth="1.6"/>
                <rect x="10.25" y="9" width="3.5" height="11" rx="0.6" stroke={stroke} strokeWidth="1.6"/>
                <rect x="16.5" y="5" width="3.5" height="15" rx="0.6" stroke={stroke} strokeWidth="1.6"/>
            </svg>;
    }
    if tab_id == "impact" {
        # Heart outline — anchors the Impact tab to its outcomes story
        return
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <path
                    d="M12 20 C 7 16 3 13 3 9 C 3 6 5.5 4 8 4 C 10 4 11.5 5 12 7 C 12.5 5 14 4 16 4 C 18.5 4 21 6 21 9 C 21 13 17 16 12 20 Z"
                    stroke={stroke}
                    strokeWidth="1.6"
                    strokeLinejoin="round"
                />
            </svg>;
    }
    return <span/>;
}

impl ClientApp.togglePalette -> None {
    palette_open = (not palette_open);
    palette_query = "";
    palette_idx = 0;
}

impl ClientApp.runPaletteAction(action: any) -> None {
    # Single dispatch site so the keyboard handler and the mouse click both
    # route through one place. Closes the palette after every action so the
    # user gets back to the work surface immediately.
    kind = str(action["kind"]);
    payload = str(action["payload"]);
    if kind == "tab" {
        active_tab = payload;
    } elif kind == "replay" {
        # Cheap "replay" — toggle the active tab to graph; the GraphViz
        # component's own Replay button is the canonical trigger and is
        # right there once you land.
        active_tab = "graph";
    } elif kind == "docs" {
        # Open the jac-scale auto-generated OpenAPI page in a new tab.
        # `window.open` is a JS builtin; jac compiles the bare name through.
        try {
            window.open("http://localhost:8001/docs", "_blank");
        } except Exception as _ex {}
    } elif kind == "reset" {
        # Reset the live walker_events buffer so the graph + telemetry
        # tabs show a clean slate without forcing a full page reload.
        walker_events = [];
    }
    palette_open = False;
    palette_query = "";
    palette_idx = 0;
}

impl ClientApp.renderPaletteItem(action: any, idx: int, sel: int) -> JsxElement {
    label = str(action["label"]);
    is_selected = idx == sel;
    return
        <div
            key={label}
            onClick={lambda (_e: MouseEvent) { runPaletteAction(action); }}
            onMouseEnter={lambda (_e: MouseEvent) { palette_idx = idx; }}
            style={{
                "padding": "10px 14px",
                "borderRadius": "8px",
                "background": ("rgba(255,229,0,0.1)" if is_selected else "transparent"),
                "border": ("0.5px solid rgba(255,229,0,0.35)" if is_selected else "0.5px solid transparent"),
                "color": ("#FFE500" if is_selected else "rgba(255,255,255,0.8)"),
                "fontSize": "13px",
                "cursor": "pointer",
                "display": "flex",
                "alignItems": "center",
                "gap": "10px",
                "transition": "all 0.12s ease"
            }}
        >
            <span style={{
                "fontFamily": "ui-monospace, monospace",
                "fontSize": "10px",
                "color": ("#FFE500" if is_selected else "rgba(255,255,255,0.3)"),
                "minWidth": "16px"
            }}>
                {"›"}
            </span>
            <span style={{"flex": "1"}}>{label}</span>
            {is_selected and <span style={{
                "fontSize": "9px",
                "fontFamily": "ui-monospace, monospace",
                "padding": "2px 6px",
                "background": "rgba(255,229,0,0.15)",
                "border": "0.5px solid rgba(255,229,0,0.3)",
                "borderRadius": "4px",
                "color": "#FFE500",
                "letterSpacing": "0.04em"
            }}>
                ENTER
            </span>}
        </div>;
}

impl ClientApp.renderPalette -> JsxElement {
    # Fuzzy substring filter — case-insensitive, no scoring beyond "contains".
    # Keeps the implementation tiny and predictable; the action list is short
    # enough that a fancier ranking would be lost on the user.
    q = palette_query.lower().strip();
    filtered: list = [];
    for a in palette_actions {
        lbl_lower = str(a["label"]).lower();
        if (not q) or (q in lbl_lower) {
            filtered = filtered + [a];
        }
    }
    sel = palette_idx;
    if sel >= len(filtered) and len(filtered) > 0 {
        sel = 0;
    }

    return
        <div
            onClick={lambda (_e: MouseEvent) { togglePalette(); }}
            style={{
                "position": "fixed",
                "inset": "0",
                "zIndex": "1000",
                "background": "rgba(5,5,8,0.65)",
                "backdropFilter": "blur(8px)",
                "display": "flex",
                "alignItems": "flex-start",
                "justifyContent": "center",
                "paddingTop": "14vh"
            }}
        >
            <div
                onClick={lambda (e: MouseEvent) { e.stopPropagation(); }}
                style={{
                    "width": "560px",
                    "maxWidth": "92vw",
                    "background": "linear-gradient(180deg, rgba(20,20,24,0.95), rgba(12,12,16,0.95))",
                    "border": "0.5px solid rgba(255,255,255,0.12)",
                    "borderRadius": "14px",
                    "boxShadow": "0 32px 72px -20px rgba(0,0,0,0.7), 0 0 0 1px rgba(255,229,0,0.06)",
                    "overflow": "hidden"
                }}
            >
                <div style={{"padding": "14px 16px 10px", "borderBottom": "0.5px solid rgba(255,255,255,0.06)", "display": "flex", "alignItems": "center", "gap": "10px"}}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" style={{"flexShrink": "0"}}>
                        <circle cx="11" cy="11" r="6.5" stroke="rgba(255,229,0,0.6)" strokeWidth="1.6"/>
                        <path d="M16 16 L 20 20" stroke="rgba(255,229,0,0.6)" strokeWidth="1.6" strokeLinecap="round"/>
                    </svg>
                    <input
                        value={palette_query}
                        onChange={lambda (e: ChangeEvent) { palette_query = e.target.value; palette_idx = 0; }}
                        onKeyDown={lambda (e: KeyboardEvent) {
                            if e.key == "ArrowDown" {
                                e.preventDefault();
                                if palette_idx + 1 < len(filtered) { palette_idx = palette_idx + 1; }
                            } elif e.key == "ArrowUp" {
                                e.preventDefault();
                                if palette_idx > 0 { palette_idx = palette_idx - 1; }
                            } elif e.key == "Enter" {
                                e.preventDefault();
                                if len(filtered) > 0 {
                                    runPaletteAction(filtered[sel]);
                                }
                            } elif e.key == "Escape" {
                                togglePalette();
                            }
                        }}
                        placeholder="Type a command — tabs, replay, docs, reset..."
                        autoFocus={True}
                        style={{
                            "flex": "1",
                            "background": "transparent",
                            "border": "none",
                            "outline": "none",
                            "color": "#FFFFFF",
                            "fontSize": "14px",
                            "fontFamily": "system-ui, sans-serif"
                        }}
                    />
                    <span style={{
                        "fontSize": "10px",
                        "color": "rgba(255,255,255,0.35)",
                        "fontFamily": "ui-monospace, monospace",
                        "padding": "3px 7px",
                        "background": "rgba(255,255,255,0.04)",
                        "border": "0.5px solid rgba(255,255,255,0.1)",
                        "borderRadius": "5px"
                    }}>
                        ESC
                    </span>
                </div>
                <div style={{"padding": "8px", "maxHeight": "50vh", "overflowY": "auto", "display": "flex", "flexDirection": "column", "gap": "2px"}}>
                    {(len(filtered) == 0) and <div style={{"padding": "20px", "textAlign": "center", "fontSize": "12px", "color": "rgba(255,255,255,0.4)"}}>
                        No matching commands.
                    </div>}
                    {[renderPaletteItem(filtered[i], i, sel) for i in range(len(filtered))]}
                </div>
                <div style={{
                    "padding": "8px 16px",
                    "borderTop": "0.5px solid rgba(255,255,255,0.06)",
                    "display": "flex",
                    "alignItems": "center",
                    "gap": "12px",
                    "fontSize": "10px",
                    "color": "rgba(255,255,255,0.4)",
                    "fontFamily": "ui-monospace, monospace"
                }}>
                    <span>↑↓ navigate</span>
                    <span>↵ run</span>
                    <span>esc close</span>
                    <span style={{"flex": "1"}}/>
                    <span>{str(len(filtered)) + " action" + ("" if len(filtered) == 1 else "s")}</span>
                </div>
            </div>
        </div>;
}

"""CivicMesh typed edge definitions.

Edges carry the relationship semantics that walkers traverse. Direction matters:
the source-to-target arrow in the comments is the directed edge as it exists
in the graph, and walkers follow that direction unless reversed explicitly.
"""

# PersonNode -> NeedNode
edge has_need {}
sem has_need is "A PersonNode currently has this NeedNode open. Created when extract_need_profile() lifts a need from conversation. Persists until the underlying need is resolved.";

# NeedNode -> ResourceNode
edge eligible_for {}
sem eligible_for is "A NeedNode could be fulfilled by this ResourceNode. Created by the EligibilityWalker after check_eligibility() returns is_eligible=true.";

# ResourceNode -> EligibilityRuleNode
edge governed_by {}
sem governed_by is "A ResourceNode is governed by this EligibilityRuleNode. Static schema relationship installed by the seed loader; not modified at runtime.";

# EligibilityRuleNode -> FormNode
edge requires_form {}
sem requires_form is "An EligibilityRuleNode requires this FormNode to be completed. Static schema relationship installed by the seed loader.";

# PersonNode -> ApplicationNode
edge applied_to {}
sem applied_to is "A PersonNode has filed (or started) an application captured in this ApplicationNode. Persists across sessions so returning users see their history.";

# ResourceNode -> ResourceNode
# Carries the real-world "progression" between civic resources. Used by
# PathfinderWalker to discover multi-step escape paths when a user has
# zero direct eligibility matches. The payload fields ground each hop in
# real bureaucratic transitions so the LLM-rendered chain reads as
# concrete advice ("submit Form X, then your priority bumps for Y") rather
# than generic links.
edge leads_to {
    has transition_reason: str = "",
        typical_days: int = 30,
        difficulty: str = "moderate";
}

sem leads_to is "Real-world progression between civic resources. Pre-seeded with curated transitions (Emergency Shelter -> Transitional Housing -> Section 8 priority). PathfinderWalker walks these edges with BFS to surface 2-3 step escape paths when EligibilityWalker has no direct match.";
sem leads_to.transition_reason is "One-line plain-language explanation of why one resource leads to the next (e.g. 'Emergency Shelter intake auto-creates a Section 8 priority application'). Surfaced verbatim to the user as the path step's caption.";
sem leads_to.typical_days is "Realistic number of days the transition takes in practice. Used to estimate total path duration for the user.";
sem leads_to.difficulty is "Perceived friction of making this hop. One of: 'easy' (auto-flow), 'moderate' (paperwork), 'hard' (legal advocate recommended).";

# PersonNode -> SessionInsight
edge reflected_on {}
sem reflected_on is "Connects a PersonNode to a SessionInsight written after each chat turn. IntakeWalker traverses these edges on the next turn to read the agent's own recent self-critique and prepend it as context — Reflexion-style self-improvement via pure graph memory, no external retrieval store.";

"""CivicMesh graph node definitions.

All six node types in the schema, plus a semstring on every field.
The semstrings are what the byLLM router uses to ground walker reasoning
when it inspects the graph at runtime - keep them dense and unambiguous.
"""

node PersonNode {
    has user_id: str = "",
        language: str = "en",
        location_zip: str = "",
        income_bracket: str = "",
        family_size: int = 1,
        preferred_contact: str = "phone",
        created_at: str = "";
}

sem PersonNode is "A vulnerable individual seeking assistance. Root of every session subgraph. Carries the profile fields used by EligibilityWalker to filter ResourceNodes.";
sem PersonNode.user_id is "Stable identifier tied to the authenticated session. Used to look up a returning user's prior ApplicationNodes.";
sem PersonNode.language is "ISO 639-1 language code (e.g. en, es, fr, vi) detected from the user's first message. All walker responses must be produced in this language.";
sem PersonNode.location_zip is "US zip code (5 digits) or city name. Used for proximity matching against ResourceNode.address and for state/county residency rules on EligibilityRuleNode.";
sem PersonNode.income_bracket is "Annual household income range. One of: '0-15k', '15k-30k', '30k-50k', '50k+'. Compared against EligibilityRuleNode.income_limit_annual during eligibility scoring.";
sem PersonNode.family_size is "Number of people in the household, including the user. Compared against EligibilityRuleNode.min_family_size and used to size SNAP/WIC/housing allocations.";
sem PersonNode.preferred_contact is "How the person wants follow-up to happen. One of: 'phone', 'email', 'in-person', 'online'. Drives which ResourceNode contact field the ActionPlan should surface first.";
sem PersonNode.created_at is "ISO 8601 timestamp of when this PersonNode was first created. Used to distinguish first-time vs returning users in session summaries.";

node NeedNode {
    has category: str = "",
        urgency: str = "within_weeks",
        details: str = "",
        created_at: str = "";
}

sem NeedNode is "A discrete need expressed by the PersonNode during conversation. One PersonNode can have many NeedNodes - e.g. housing + food + healthcare simultaneously.";
sem NeedNode.category is "Top-level domain of the need. One of: 'housing', 'food', 'healthcare', 'legal'. Must match ResourceNode.category exactly so EligibilityWalker can join the two sets.";
sem NeedNode.urgency is "How quickly the user needs the resource. One of: 'immediate' (homeless tonight, no food today, crisis), 'within_days' (eviction notice, prescription out), 'within_weeks' (long-term housing search, ongoing benefits). Drives ordering in ActionPlan.";
sem NeedNode.details is "Free-form description in the user's own words. Preserved verbatim for the LLM to pick up nuance the categorical fields lose - e.g. 'I have a service dog' or 'I am undocumented'.";
sem NeedNode.created_at is "ISO 8601 timestamp when the need was first surfaced in conversation. Lets the system track which needs are still open vs already routed.";

node ResourceNode {
    has agency_name: str = "",
        category: str = "",
        capacity: str = "open",
        languages_supported: list[str] = [],
        contact_phone: str = "",
        contact_email: str = "",
        address: str = "",
        online_url: str = "",
        description: str = "";
}

sem ResourceNode is "A real-world agency, program, or service that can fulfill a NeedNode. Connected to EligibilityRuleNode via governed_by, and to NeedNode via eligible_for after matching.";
sem ResourceNode.agency_name is "Official name of the agency or program (e.g. 'Section 8 Housing Choice Voucher', 'Catholic Charities Food Pantry'). Acts as a natural primary key - the seed loader treats it as unique.";
sem ResourceNode.category is "Domain of service provided. One of: 'housing', 'food', 'healthcare', 'legal'. Must match NeedNode.category for the resource to be considered.";
sem ResourceNode.capacity is "Current intake status. One of: 'open' (accepting now), 'waitlist' (apply but expect delay), 'closed' (do not refer). The router demotes 'closed' to escalation paths only.";
sem ResourceNode.languages_supported is "List of ISO 639-1 codes the agency can serve. PersonNode.language must appear here, or the ActionPlan must include an interpreter referral.";
sem ResourceNode.contact_phone is "Primary phone number (digits and standard punctuation). Preferred entry-point for users with preferred_contact='phone'.";
sem ResourceNode.contact_email is "Public intake email address. Empty string when the agency does not publish one.";
sem ResourceNode.address is "Street address including city, state, zip. Used for proximity ranking against PersonNode.location_zip.";
sem ResourceNode.online_url is "Public-facing intake URL or program page. The ActionPlan deep-links to this for users with preferred_contact='online'.";
sem ResourceNode.description is "One-paragraph summary of what the resource provides, in plain language. The LLM uses this to explain choices to the user.";

node EligibilityRuleNode {
    has rule_id: str = "",
        income_limit_annual: int = 0,
        residency_requirement: str = "none",
        min_family_size: int = 0,
        citizenship_required: bool = False,
        age_min: int = 0,
        age_max: int = 0,
        exceptions: str = "",
        criteria_summary: str = "",
        # Outcome-learning fields. MemoryWalker updates these whenever
        # an ApplicationNode this rule gated transitions to approved or
        # denied. EligibilityWalker reads prior_success_rate as a
        # prior on the LLM's match_score so the graph genuinely learns
        # from real outcomes.
        prior_success_rate: float = 0.5,
        prior_attempts: int = 0,
        prior_approvals: int = 0;
}

sem EligibilityRuleNode is "The structured eligibility criteria for a ResourceNode. Read by check_eligibility() to score how well a PersonNode's profile matches.";
sem EligibilityRuleNode.rule_id is "Stable identifier for this rule, typically '<agency_slug>-rule'. Used so multiple resources can share or reference the same rule without duplication.";
sem EligibilityRuleNode.income_limit_annual is "Maximum allowed annual household income in USD. A value of 0 means there is no income limit. Compared against the upper bound of PersonNode.income_bracket.";
sem EligibilityRuleNode.residency_requirement is "Geographic scope required for eligibility. One of: 'state', 'county', 'city', 'none'. Matched against PersonNode.location_zip.";
sem EligibilityRuleNode.min_family_size is "Minimum number of household members required. 0 means no minimum. Some programs (e.g. family shelters) require >= 2.";
sem EligibilityRuleNode.citizenship_required is "True if the program legally requires US citizenship or specific immigration status. False for programs that serve everyone regardless of status (food banks, ERs, many legal aid clinics).";
sem EligibilityRuleNode.age_min is "Minimum applicant age in years. 0 means no minimum. Used by youth/senior-specific programs.";
sem EligibilityRuleNode.age_max is "Maximum applicant age in years. 0 means no maximum. Used by youth-only programs.";
sem EligibilityRuleNode.exceptions is "Free-form description of edge cases, waivers, and special populations the rule treats differently. The LLM consults this for borderline matches before declaring ineligibility.";
sem EligibilityRuleNode.criteria_summary is "Human-readable one-sentence summary of the rule, suitable for LLM prompts and user-facing explanations. The primary surface check_eligibility() reads.";
sem EligibilityRuleNode.prior_success_rate is "Bayesian-style success prior in [0, 1]. Starts at 0.5 (uninformative). MemoryWalker updates it whenever an ApplicationNode this rule gated transitions to approved or denied. EligibilityWalker weights LLM match_scores by this prior so the system tracks real-world outcomes over time, not just static rules.";
sem EligibilityRuleNode.prior_attempts is "Total count of ApplicationNodes that reached approved/denied status against this rule. Used as the denominator for prior_success_rate.";
sem EligibilityRuleNode.prior_approvals is "Count of those attempts that ended in approved. Numerator for prior_success_rate. Persists across sessions because the graph itself persists.";

# SessionInsight — Reflexion-style self-reflection persisted in the graph.
# After every chat turn, CritiqueWalker computes a quality score from the
# walker chain telemetry (no LLM call) and writes one of these. Future
# IntakeWalker turns read the last few back as context-prefix so the agent
# literally learns from its own past performance.
node SessionInsight {
    has session_id: str = "",
        ts: str = "",
        walkers_fired: list[str] = [],
        llm_calls_est: int = 0,
        escalated: bool = False,
        pathfinder_used: bool = False,
        navigation_used: bool = False,
        eligible_count: int = 0,
        quality_score: int = 50,
        headline: str = "",
        user_prompt_snippet: str = "";
}

sem SessionInsight is "Agent self-reflection record. Written by CritiqueWalker after each chat turn — pure graph mutation, no LLM call. Future IntakeWalker turns read the last few to prepend as context so the agent learns from its own past sessions without external memory infrastructure. Reflexion in pure Jac.";
sem SessionInsight.session_id is "Stable identifier for the chat turn. Timestamp-based; lets the client deduplicate when multiple insights for the same turn would otherwise stack.";
sem SessionInsight.ts is "ISO 8601 timestamp the insight was written. Used by Telemetry's rolling-trend chart and by IntakeWalker's recency-weighted lookback.";
sem SessionInsight.walkers_fired is "Distinct list of walker names that produced events during this turn. Drives the quality_score formula and surfaces in the Telemetry self-reflection panel.";
sem SessionInsight.llm_calls_est is "Estimated number of byllm calls this turn made. Heuristic: 1 intake + N eligibility candidates + (1 navigation OR 1 escalation) + translation. Lets the Telemetry tab compute rolling free-tier budget burn.";
sem SessionInsight.escalated is "True if the chain routed through EscalationWalker — a session-quality penalty. Demo loop: if escalation keeps firing on the same user, the agent should improve its NeedProfile extraction next turn.";
sem SessionInsight.pathfinder_used is "True if PathfinderWalker found a multi-hop escape path. Counts as a positive outcome — the system found a route the flat eligibility check couldn't see.";
sem SessionInsight.navigation_used is "True if NavigationWalker produced a non-empty ActionPlan. The cleanest signal of a successful turn.";
sem SessionInsight.eligible_count is "Number of eligible resources scored above threshold this turn. Feeds into quality_score and lets Telemetry chart per-turn eligibility yield.";
sem SessionInsight.quality_score is "Integer in [0, 100]. Heuristic formula: navigation=+30, pathfinder=+25, eligible_count<=4=+5 each, escalated=-15, baseline=50. Surfaces in Telemetry as the rolling-quality chart so users can see the agent self-improving across turns.";
sem SessionInsight.headline is "One-line plain-language summary suitable for prefixing future conversations. Example: 'Prior turn matched 3 housing resources via Pathfinder, no escalation.' IntakeWalker reads the last 2 of these.";
sem SessionInsight.user_prompt_snippet is "First 80 chars of the user's prompt that triggered this turn. Used in the Telemetry timeline so users can scroll back through their session quality.";

node FormNode {
    has form_id: str = "",
        form_name: str = "",
        url: str = "",
        required_documents: list[str] = [],
        deadline_type: str = "rolling",
        submission_method: str = "online",
        estimated_minutes: int = 30;
}

sem FormNode is "An application form or intake artifact the user must complete to access the ResourceNode. Reached via the requires_form edge from EligibilityRuleNode.";
sem FormNode.form_id is "Stable identifier for the form (e.g. 'snap-application-il', 'hud-50058'). Treated as unique by the seed loader.";
sem FormNode.form_name is "Human-readable form name (e.g. 'SNAP Application', 'HUD-50058 Family Report'). Surfaced to the user verbatim in the ActionPlan.";
sem FormNode.url is "Public URL where the form can be downloaded, started, or submitted online. Empty string if no online version exists.";
sem FormNode.required_documents is "List of document names the user must gather before submitting (e.g. 'Photo ID', 'Proof of income', 'Birth certificate'). Drives the documents_needed field of ActionStep.";
sem FormNode.deadline_type is "Submission cadence. One of: 'rolling' (any time), 'monthly' (specific day each month), 'annual' (yearly cycle), 'one_time' (single window). Drives deadline_label in ActionStep.";
sem FormNode.submission_method is "How the completed form is delivered. One of: 'online', 'mail', 'in_person', 'phone'. Should match PersonNode.preferred_contact when feasible.";
sem FormNode.estimated_minutes is "Realistic time to complete the form for a first-time applicant, in minutes. Surfaced to users so they can budget time.";

node ApplicationNode {
    has application_id: str = "",
        status: str = "pending",
        resource_name: str = "",
        applied_at: str = "",
        updated_at: str = "",
        denial_reason: str = "",
        next_step_hint: str = "",
        notes: str = "";
}

sem ApplicationNode is "Represents one PersonNode's attempt to access one ResourceNode. Persists across sessions so returning users see their history. Connected to PersonNode via applied_to.";
sem ApplicationNode.application_id is "Stable identifier for this application instance, typically a UUID. Used as the natural primary key for ApplicationNodes.";
sem ApplicationNode.status is "Current lifecycle state. One of: 'pending' (not yet submitted), 'applied' (submitted, awaiting decision), 'approved', 'denied', 'withdrawn'. Drives session summary categorization.";
sem ApplicationNode.resource_name is "Denormalized copy of the linked ResourceNode.agency_name. Allows quick display in session summaries without an extra graph traversal.";
sem ApplicationNode.applied_at is "ISO 8601 timestamp of when the application moved into 'applied' status. Empty for pending applications.";
sem ApplicationNode.updated_at is "ISO 8601 timestamp of the most recent status change. Used to detect stale applications that may need follow-up.";
sem ApplicationNode.denial_reason is "Free-form reason text populated only when status='denied'. Read by generate_denial_next_step() to produce an empathetic, actionable response.";
sem ApplicationNode.next_step_hint is "LLM-generated guidance describing what the user should do next given the current status. Refreshed each time the status updates.";
sem ApplicationNode.notes is "Free-form notes the user or caseworker has attached to this application. Preserved verbatim; the LLM may reference it but never overwrites it.";

"""Idempotent seed loader for CivicMesh.

Reads data/resources.json and materializes ResourceNode + EligibilityRuleNode
+ FormNode triples into the graph rooted at `root`. Before inserting any
ResourceNode the loader walks root, filters by agency_name, and only spawns
when the result set is empty - so re-running this script never produces
duplicates.

Run: `jac run graph/seed_data.jac`
"""

import json;
import os;

import from graph.nodes { ResourceNode, EligibilityRuleNode, FormNode }
import from graph.edges { governed_by, requires_form }

def _resolve_data_path -> str {
    candidates = [
        os.path.join(os.getcwd(), "data", "resources.json"),
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "data", "resources.json"),
    ];
    for path in candidates {
        if os.path.exists(path) {
            return os.path.abspath(path);
        }
    }
    raise FileNotFoundError("Could not locate data/resources.json from cwd or script directory.");
}

def _load_resources -> list {
    path = _resolve_data_path();
    contents = "";
    with open(path, "r") as f {
        contents = f.read();
    }
    payload = json.loads(contents);
    return list(payload["resources"]);
}

def _resource_exists(agency: str) -> bool {
    # Idempotency check: graph traversal from root, filtered by agency_name.
    # When the scale plugin is active and MongoDB is running, this becomes a
    # constant-time lookup; in local `jac run` mode it walks the in-memory graph.
    matches = [root --> [?:ResourceNode, agency_name == agency]];
    return len(matches) > 0;
}

def _seed_one(record: any) -> bool {
    agency = str(record["agency_name"]);
    if _resource_exists(agency) {
        return False;
    }

    resource = ResourceNode(
        agency_name=agency,
        category=record["category"],
        capacity=record["capacity"],
        languages_supported=record["languages_supported"],
        contact_phone=record["contact_phone"],
        contact_email=record["contact_email"],
        address=record["address"],
        online_url=record["online_url"],
        description=record["description"]
    );
    root ++> resource;

    elig_raw = record["eligibility"];
    rule = EligibilityRuleNode(
        rule_id=elig_raw["rule_id"],
        income_limit_annual=elig_raw["income_limit_annual"],
        residency_requirement=elig_raw["residency_requirement"],
        min_family_size=elig_raw["min_family_size"],
        citizenship_required=elig_raw["citizenship_required"],
        age_min=elig_raw["age_min"],
        age_max=elig_raw["age_max"],
        exceptions=elig_raw["exceptions"],
        criteria_summary=elig_raw["criteria_summary"]
    );
    resource +>: governed_by() :+> rule;

    form_raw = record["form"];
    form = FormNode(
        form_id=form_raw["form_id"],
        form_name=form_raw["form_name"],
        url=form_raw["url"],
        required_documents=form_raw["required_documents"],
        deadline_type=form_raw["deadline_type"],
        submission_method=form_raw["submission_method"],
        estimated_minutes=form_raw["estimated_minutes"]
    );
    rule +>: requires_form() :+> form;

    return True;
}

def seed -> dict {
    inserted = 0;
    skipped = 0;
    records = _load_resources();
    for record in records {
        if _seed_one(record) {
            inserted += 1;
        } else {
            skipped += 1;
        }
    }
    return {"inserted": inserted, "skipped": skipped, "total": len(records)};
}

with entry {
    result = seed();
    print(f"Seeded {result['inserted']} resources, skipped {result['skipped']} duplicates (total in file: {result['total']}).");
}

"""byLLM function stubs for CivicMesh.

Phase 1 ships only the typed signatures (and the structured return types that
walkers will consume). The actual prompt templates and walker integration are
added in Phase 2. Defining the types here means walkers can import these names
today and the LLM router stays grounded by stable, named schemas.

The ModelPool is configured here as a module-level glob. Adding a fallback
model in Phase 2 is a one-line change to the `models=[...]` list - no
call-site edits required. Default model parameters come from jac.toml.
"""

import from byllm.lib { Model, ModelPool }

glob pool = ModelPool(
    models=[Model(model_name="nvidia_nim/meta/llama-3.1-8b-instruct")],
    strategy="fallback",
);

# ---------- Structured return types ----------

"""Profile of a person's situation, extracted from free-form conversation.

Every field has a default so the LLM can produce a partial profile when the
user has not volunteered everything yet; downstream walkers treat empty
strings and zero values as "unknown" rather than zero.
"""
obj NeedProfile {
    has category: str = "",
        urgency: str = "within_weeks",
        family_size: int = 1,
        income_bracket: str = "",
        location_zip: str = "",
        language: str = "en",
        details: str = "";
}

sem NeedProfile is "Structured snapshot of one user's stated need plus the demographic context required to evaluate eligibility. Produced by extract_need_profile() and consumed by check_eligibility() and generate_action_plan().";
sem NeedProfile.category is "Top-level need domain. One of: 'housing', 'food', 'healthcare', 'legal'.";
sem NeedProfile.urgency is "How quickly help is required. One of: 'immediate', 'within_days', 'within_weeks'.";
sem NeedProfile.family_size is "Household size, including the user. Used for eligibility scoring against EligibilityRuleNode.min_family_size.";
sem NeedProfile.income_bracket is "Annual household income range. One of: '0-15k', '15k-30k', '30k-50k', '50k+'.";
sem NeedProfile.location_zip is "User's zip code or city. Used to apply state/county/city residency rules.";
sem NeedProfile.language is "ISO 639-1 code the user is communicating in. All downstream responses must be produced in this language.";
sem NeedProfile.details is "Free-form description of the user's situation in their own words. Preserves nuance the categorical fields lose.";

"""Per-resource eligibility evaluation result.

The match_score is 0-100; >= 70 typically means the user should apply, 40-70
means apply with documentation gaps to address, < 40 means look elsewhere.
"""
obj EligibilityResult {
    has resource_name: str = "",
        match_score: int = 0,
        matched_criteria: list[str] = [],
        missing_criteria: list[str] = [],
        is_eligible: bool = False;
}

sem EligibilityResult is "Per-resource outcome of check_eligibility(). Walkers use is_eligible to filter and match_score to rank.";
sem EligibilityResult.resource_name is "ResourceNode.agency_name this evaluation refers to.";
sem EligibilityResult.match_score is "Confidence score from 0-100. 70+ = apply now, 40-70 = apply with documentation gaps, < 40 = look elsewhere.";
sem EligibilityResult.matched_criteria is "Human-readable list of criteria the user clearly meets. Shown to the user verbatim.";
sem EligibilityResult.missing_criteria is "Human-readable list of criteria the user does not meet or has not yet documented. Drives ActionStep.documents_needed.";
sem EligibilityResult.is_eligible is "True if the user likely qualifies. Walkers use this to gate the eligible_for edge.";

"""One step in an action plan - a concrete thing the user should do next."""
obj ActionStep {
    has step_number: int = 0,
        agency_name: str = "",
        action_description: str = "",
        documents_needed: list[str] = [],
        deadline_label: str = "",
        contact_info: str = "",
        estimated_minutes: int = 0,
        online_url: str = "";
}

sem ActionStep is "A single concrete action the user can take, drawn from a matched ResourceNode and its FormNode. Walkers concatenate these into an ActionPlan.";
sem ActionStep.step_number is "1-indexed ordinal of this step inside its ActionPlan. Used by the UI to render numbered lists.";
sem ActionStep.agency_name is "Agency the user is engaging in this step. Surfaced verbatim.";
sem ActionStep.action_description is "One-sentence imperative description of what the user should do, in the user's language.";
sem ActionStep.documents_needed is "List of documents the user must bring or upload for this step. Sourced from FormNode.required_documents.";
sem ActionStep.deadline_label is "Human-readable deadline phrasing (e.g. 'Apply by the 15th of each month', 'Open year-round'). Derived from FormNode.deadline_type.";
sem ActionStep.contact_info is "Best contact-string for this step, chosen based on PersonNode.preferred_contact. Phone number, email, or address.";
sem ActionStep.estimated_minutes is "How long this step is expected to take. Mirrors FormNode.estimated_minutes.";
sem ActionStep.online_url is "Deep-link to the online intake or form, when applicable. Empty string if step is not online.";

"""Ordered plan composed of ActionSteps plus a top-line summary."""
obj ActionPlan {
    has steps: list[ActionStep] = [],
        summary: str = "";
}

sem ActionPlan is "Top-level plan returned to the user. The summary is shown first, then steps render as a numbered list.";
sem ActionPlan.steps is "ActionSteps in the order the user should attempt them. Generated by generate_action_plan().";
sem ActionPlan.summary is "One-paragraph plain-language summary of what this plan accomplishes and why these steps were chosen.";

"""Context for triggering an escalation - dead-end, all-denied, or crisis."""
obj EscalationContext {
    has trigger_reason: str = "",
        profile: NeedProfile = NeedProfile(),
        denial_reasons: list[str] = [],
        urgency_level: str = "within_weeks";
}

sem EscalationContext is "Bundle of state passed to compose_escalation_message() when no resource path is viable. Drives crisis lines, appeal hints, and personalized messaging.";
sem EscalationContext.trigger_reason is "Free-form description of why escalation fired (e.g. 'all resources are full', 'every application denied', 'user reported active crisis').";
sem EscalationContext.profile is "Snapshot of the user's NeedProfile at the moment of escalation. Used to personalize tone and language.";
sem EscalationContext.denial_reasons is "List of denial reasons collected from prior ApplicationNodes. Each becomes a candidate for appeal advice.";
sem EscalationContext.urgency_level is "Mirrors NeedNode.urgency. 'immediate' escalations include crisis hotline numbers; lower urgency levels stay informational.";

"""Message produced for a dead-end or all-denied situation."""
obj EscalationMessage {
    has crisis_resources: list[str] = [],
        appeal_options: list[str] = [],
        personalized_message: str = "",
        is_emergency: bool = False;
}

sem EscalationMessage is "Output of compose_escalation_message(). The UI renders crisis_resources before everything else when is_emergency is True.";
sem EscalationMessage.crisis_resources is "Names and contact lines for 24/7 crisis resources (988, NDV hotline, SAMHSA) appropriate to the user's situation.";
sem EscalationMessage.appeal_options is "List of one-sentence appeal or alternative paths the user can try next, given their denial reasons.";
sem EscalationMessage.personalized_message is "Empathetic, plain-language message addressed directly to the user. Acknowledges the dead-end without minimizing it.";
sem EscalationMessage.is_emergency is "True when the user's situation warrants immediate crisis intervention. UI surfaces crisis_resources first.";

"""Language detection result for the user's first message."""
obj LanguageProfile {
    has detected_language: str = "en",
        confidence: float = 0.0,
        translated_intent: str = "";
}

sem LanguageProfile is "Output of detect_language_and_extract(). Walkers use detected_language to set PersonNode.language for all subsequent responses.";
sem LanguageProfile.detected_language is "ISO 639-1 code (e.g. 'en', 'es', 'vi') of the user's input.";
sem LanguageProfile.confidence is "0.0 - 1.0 confidence of the detection. Values under 0.6 trigger a clarification turn.";
sem LanguageProfile.translated_intent is "English translation of the user's first message, so downstream prompts stay grounded even in non-Latin scripts.";

"""Summary of a returning user's prior session state."""
obj SessionSummary {
    has approved: list[str] = [],
        pending: list[str] = [],
        denied: list[str] = [],
        next_recommended_step: str = "";
}

sem SessionSummary is "Output of summarize_session(). Drives the welcome message a returning user sees on their next visit.";
sem SessionSummary.approved is "Agency names where ApplicationNode.status='approved'. Surfaced as wins.";
sem SessionSummary.pending is "Agency names where status is 'pending' or 'applied'. Surfaced with a 'check status' prompt.";
sem SessionSummary.denied is "Agency names where status='denied'. Pairs with next_recommended_step to keep momentum.";
sem SessionSummary.next_recommended_step is "Single sentence advising the user what to focus on first in this session.";

# ---------- LLM function stubs ----------

"""Extract a structured NeedProfile from a free-form, possibly multilingual conversation transcript."""
def extract_need_profile(conversation: str) -> NeedProfile by pool();

sem extract_need_profile.conversation is "Full transcript of the user's chat turns so far, in whatever language they typed. May contain mixed scripts and informal phrasing; the model must lift a structured NeedProfile from it without losing nuance.";

"""Score how well a profile satisfies one resource's eligibility rule. Return matched and missing criteria plus a 0-100 score."""
def check_eligibility(
    profile: NeedProfile,
    criteria_summary: str,
    income_limit: int,
    citizenship_required: bool,
    residency_req: str,
    age_min: int,
    age_max: int,
    exceptions: str
) -> EligibilityResult by pool();

sem check_eligibility.profile is "The user's NeedProfile snapshot. Provides demographic context used to evaluate every criterion.";
sem check_eligibility.criteria_summary is "Human-readable summary of the resource's EligibilityRuleNode.criteria_summary. Primary surface the model reads when reasoning about the match.";
sem check_eligibility.income_limit is "EligibilityRuleNode.income_limit_annual in USD. 0 means no income limit and any bracket should match on income.";
sem check_eligibility.citizenship_required is "True if the resource legally requires US citizenship. Drives whether undocumented users should be excluded.";
sem check_eligibility.residency_req is "Residency scope required by the resource. One of: 'state', 'county', 'city', 'none'. Matched against profile.location_zip.";
sem check_eligibility.age_min is "Minimum applicant age accepted by the resource. 0 means no minimum.";
sem check_eligibility.age_max is "Maximum applicant age accepted by the resource. 0 means no maximum.";
sem check_eligibility.exceptions is "Free-form description of waivers and edge cases the resource grants. Consult before declaring ineligibility on a borderline match.";

"""Generate an ordered ActionPlan from a list of eligible resource names plus the user's profile. Order by urgency and deadline."""
def generate_action_plan(eligible_resources: list[str], profile: NeedProfile) -> ActionPlan by pool();

sem generate_action_plan.eligible_resources is "List of ResourceNode.agency_name strings that passed eligibility scoring. Order does not matter; the model is expected to re-sequence by urgency and deadline.";
sem generate_action_plan.profile is "The user's NeedProfile. Drives ordering: 'immediate' urgency comes first, language and preferred_contact shape the action_description tone.";

"""Compose a SHORT supporting message for a dead-end / all-denied scenario.

The walker prepends a deterministic lead line ("Call <agency>: <phone> — ...")
based on context.profile.category BEFORE showing this to the user, so you
DO NOT need to include a phone number or agency name in your response. Your
job is to write only the supporting context that follows the lead line.

REQUIRED SHAPE for personalized_message (1-2 sentences total, max ~40 words):
  Sentence 1: ONE concrete sentence telling the user what to say when they
              call. Tailor to their stated need from context.profile.details
              (e.g. "Tell the counselor you're a single mother in Houston
              earning $1,800/month and need help with rent this month.").
              NO generic "explain your situation."
  Sentence 2 (optional): ONE short empathetic line. NO "I'm so sorry to
              hear" or "I understand this is hard" boilerplate — those
              phrases are the failure mode this prompt exists to prevent.

DO NOT START with "Call ..." or any phone number — the walker handles that.
DO NOT mention 988, 211, 1-800 numbers, or any agency name — the walker
handles those too. Write only the human, contextual continuation.

REQUIRED for crisis_resources: 1-3 entries formatted as
"Name: phone — what they do". Choose entries RELEVANT to
context.profile.category (food → food banks / SNAP offices;
housing → shelters / rental assistance; legal → legal aid; healthcare →
clinics). Do NOT include 988 unless context.denial_reasons or
context.profile.details mention self-harm or suicide.

REQUIRED for appeal_options: list 2-4 concrete next-step actions, each
starting with an imperative verb ("Call 211 and ask for...", "Walk in to
the nearest shelter at..."). No generic "consider exploring" phrasing.

Uses ReAct-style tool calling to consult the live graph and assess safety
risk. The on_iteration callback fires between steps so the EscalationWalker
can stream progress and guard against doom-loops.

LANGUAGE: write personalized_message AND appeal_options ENTIRELY in
`context.profile.language` (ISO 639-1 code). Do NOT mix English and the
target language in any single string. If context.profile.language is empty,
'en', or 'english', write in English. crisis_resources hotline names and
phone numbers stay canonical (e.g. "988 Suicide and Crisis Lifeline") since
those are recognized search strings users would google."""
def compose_escalation_message(
    context: EscalationContext,
    tools: list = [],
    on_iteration: any = None
) -> EscalationMessage by pool();

sem compose_escalation_message.context is "EscalationContext bundle describing why escalation fired plus the user's NeedProfile. The primary input the model reasons over. context.profile.language dictates the language of personalized_message and appeal_options — do not translate after.";
sem compose_escalation_message.tools is "List of ReAct tool callables the model may invoke to consult the live graph (emergency resources, appeal orgs, safety risk). Order is not meaningful.";
sem compose_escalation_message.on_iteration is "Callback fired between ReAct iterations. Returns IterationAction.CONTINUE or ABORT_WITH_SUMMARY so the host walker can stream progress and cap runaway loops.";

"""Detect the language of the user's first message and translate intent into English for downstream prompts."""
def detect_language_and_extract(message: str) -> LanguageProfile by pool();

sem detect_language_and_extract.message is "The user's first chat message, exactly as typed. May be in any language and any script; the model must detect language and translate intent into English.";

"""Produce a short, empathetic next-step hint after a denial, given the agency, the denial reason, and the user's profile."""
def generate_denial_next_step(resource_name: str, denial_reason: str, profile: NeedProfile) -> str by pool();

sem generate_denial_next_step.resource_name is "ResourceNode.agency_name that denied the application. Surfaced verbatim in the hint.";
sem generate_denial_next_step.denial_reason is "Free-form ApplicationNode.denial_reason text. The model maps this to a concrete next-step action.";
sem generate_denial_next_step.profile is "The user's NeedProfile. Drives tone, language, and whether to suggest appeal vs alternative.";

"""Summarize a returning user's prior session: approved, pending, denied applications, plus one recommended next action."""
def summarize_session(
    approved: list[str],
    pending: list[str],
    denied: list[str],
    profile: NeedProfile
) -> SessionSummary by pool();

sem summarize_session.approved is "Agency names where ApplicationNode.status='approved'. The model frames these as wins in the welcome message.";
sem summarize_session.pending is "Agency names where status is 'pending' or 'applied'. Pair with a 'check status' prompt.";
sem summarize_session.denied is "Agency names where status='denied'. Pair with next_recommended_step to keep momentum.";
sem summarize_session.profile is "The user's NeedProfile. Drives language and tone of the summary.";

"""Translate a batch of English strings into the target language. CRITICAL: translate EVERY SINGLE string in the input list — do not skip any, do not leave any in English. Return a list of the SAME LENGTH as the input, in the SAME ORDER, with each entry being the translation of the corresponding input entry. Preserve meaning, tone, punctuation, emoji, and rhetorical question marks. If target_language is empty, 'en', or 'english', return the input unchanged. Target language may be an ISO code or natural-language name like 'hi', 'es', 'Hindi', 'Spanish', 'German', 'fr', 'French'. Even if a single string already appears to be in the target language, still include it in the output at the same index."""
def translate_batch(texts: list[str], target_language: str) -> list[str] by pool();

sem translate_batch.texts is "Ordered list of UI / bot strings in English. The model must return exactly this many entries in exactly this order, each translated.";
sem translate_batch.target_language is "ISO 639-1 code or natural-language name of the user's language (e.g. 'es', 'hi', 'Hindi'). Empty / 'en' / 'english' means pass through unchanged.";

"""Persona: 72-year-old SSI recipient facing illegal eviction with a court date
in two weeks. Multi-session test: intake → mark first step applied →
MemoryWalker resumes with the new status intact.
"""

import from walkers.intake { IntakeWalker }
import from walkers.memory { MemoryWalker }

test "elderly_legal_session_memory" {
    conversation = "I am 72 years old and my landlord is trying to evict me illegally. I cannot afford a lawyer. I have lived in this apartment for 15 years. My only income is Social Security of about $1,200 per month. I need legal help urgently. The court date is in 2 weeks.";

    intake = root spawn IntakeWalker(
        conversation=conversation,
        user_id="test_persona_003"
    );
    assert len(intake.reports) > 0;
    result1 = intake.reports[-1];

    assert result1["profile"]["category"] == "legal";

    elig = result1["eligibility_results"];
    if not elig["escalated"] {
        steps = elig["action_plan"]["action_plan"]["steps"];
        if len(steps) > 0 {
            first_agency = str(steps[0]["agency_name"]);
            update_walker = root spawn MemoryWalker(
                user_id="test_persona_003",
                mode="update_status",
                resource_name=first_agency,
                new_status="applied"
            );
            assert len(update_walker.reports) > 0;
            update = update_walker.reports[0];
            assert update["updated"];
        }
    }

    mem = root spawn MemoryWalker(
        user_id="test_persona_003",
        mode="read_session"
    );
    assert len(mem.reports) > 0;
    session = mem.reports[0];
    assert session["has_history"];
    assert session["application_count"] > 0;
    assert len(session["pending"]) > 0 or len(session["approved"]) > 0;

    print("✓ Persona: Elderly legal + session memory — PASSED");
}

"""Persona: Spanish-speaking single mother with two young children, $1,800/mo
income, 77001 (Houston), facing imminent eviction.

End-to-end pipeline check: IntakeWalker → EligibilityWalker → NavigationWalker
must surface housing or food resources, persist ApplicationNodes, and let a
follow-up MemoryWalker call read the session back.

Walker spawns return the walker instance; the `report` payload lives in
`walker.reports`. We always inspect the first report - that's the top-level
summary the walker emits on completion.
"""

import from walkers.intake { IntakeWalker }
import from walkers.memory { MemoryWalker }

test "single_mother_full_pipeline" {
    conversation = "Hola, soy madre soltera con 2 hijos pequenos. Necesito ayuda urgente con vivienda y comida. Gano aproximadamente $1,800 al mes. Vivimos en el codigo postal 77001 en Houston. Mis hijos tienen 4 y 7 anos. Estamos en riesgo de perder nuestro apartamento este mes.";

    intake = root spawn IntakeWalker(
        conversation=conversation,
        user_id="test_persona_001"
    );
    assert len(intake.reports) > 0;
    # Reports from child walkers (Navigation, Eligibility) flow into the
    # spawning walker's `.reports` list in completion order, so the IntakeWalker's
    # own top-level report is the last entry.
    result = intake.reports[-1];

    assert "profile" in result;
    assert result["profile"]["category"] in ["housing", "food"];
    assert result["language"] == "es";
    assert "eligibility_results" in result;

    elig = result["eligibility_results"];
    assert "escalated" in elig;

    if not elig["escalated"] {
        steps = elig["action_plan"]["action_plan"]["steps"];
        assert len(steps) > 0;
    }

    mem = root spawn MemoryWalker(
        user_id="test_persona_001",
        mode="read_session"
    );
    assert len(mem.reports) > 0;
    session = mem.reports[0];
    assert session["has_history"];
    assert session["application_count"] > 0;

    print("✓ Persona: Single mother — PASSED");
}

"""Persona: Undocumented parent of three children seeking healthcare.

The action plan should not surface Medicaid (citizenship_required=true in seed
data). Free clinics and FQHCs should remain in scope.
"""

import from walkers.intake { IntakeWalker }

test "undocumented_healthcare" {
    conversation = "I need help with healthcare for my children. I do not have social security number. I have 3 children ages 2, 5, and 8. We need to see a doctor but cannot afford it. I work but I have no papers. We live in Houston area.";

    intake = root spawn IntakeWalker(
        conversation=conversation,
        user_id="test_persona_002"
    );
    assert len(intake.reports) > 0;
    result = intake.reports[-1];

    assert result["profile"]["category"] == "healthcare";

    elig = result["eligibility_results"];
    assert "escalated" in elig;

    if not elig["escalated"] {
        steps = elig["action_plan"]["action_plan"]["steps"];
        assert len(steps) > 0;
        # Medicaid must not appear — its rule has citizenship_required=true.
        for s in steps {
            assert "medicaid" not in str(s["agency_name"]).lower();
        }
    }

    print("✓ Persona: Undocumented individual — PASSED");
}

