        explanation: str;
}

obj AppealLetter {
    has subject: str,
        salutation: str,
        body: str,
        citations: list[str],
        closing: str;
}

# ---- Persistent graph nodes (attached to root) --------------------------

node Claim {
    has claim_id: str,
        patient_name: str,
        member_id: str,
        cpt_code: str,
