"""Agent 3: Compliance Walker -- deterministic statute checks."""

import from ..graph.nodes { Contract, Clause, governed_by }
import from ..tools.clause_classifier { FOUNDATIONAL_KINDS }
import from ..tools.structural_rules { has_liability_cap, has_uncapped_indemnity }

walker ComplianceWalker {
    has jurisdiction: str = "US";
    has violations: list = [];

    def _privacy_leak(text: str) -> bool {
        t = text.lower();
        return ("sell" in t or "share" in t) and "personal data" in t and "without" in t and "consent" in t;
    }

    def _non_compete_overreach(text: str) -> bool {
        t = text.lower();
        return ("non-compete" in t or "noncompete" in t or "non compete" in t)
            and ("global" in t or "seven year" in t or "5 year" in t or "five year" in t);
    }

    def _check_gdpr_data_traps(all_clauses: list) -> bool {
        gdpr_clause: Clause | None = None;
        analytics_clause: Clause | None = None;
        for c in all_clauses {
            t = c.text.lower();
            if "gdpr" in t or "ccpa" in t {
                gdpr_clause = c;
            }
            if "user data" in t and ("analytic" in t or "anonymized" in t or "anonymised" in t) {
                analytics_clause = c;
            }
        }
        if gdpr_clause is not None and analytics_clause is not None {
            gdpr_clause.flagged = True;
            analytics_clause.flagged = True;
            self.violations.append({
                "clause_id": gdpr_clause.clause_id,
                "clause_kind": "data_processing",
                "statute": "GDPR Art. 28 / CCPA 1798.100",
                "detail": (
                    "GDPR/CCPA compliance claim conflicts with broad analytics use of User Data "
                    "without subprocessors, lawful basis, or consent flow."
                ),
                "severity": "high",
                "confidence": 0.91
            });
            return True;
        }
        return False;
    }

    can start with Contract entry {
        all_clauses = [-->[?Clause]];
        self._check_gdpr_data_traps(all_clauses);
        cap_clause: Clause | None = None;
        ind_clause: Clause | None = None;
        for c in all_clauses {
            if has_liability_cap(c.text) { cap_clause = c; }
            if has_uncapped_indemnity(c.text) { ind_clause = c; }
        }
        if cap_clause is not None and ind_clause is not None {
            self.violations.append({
                "clause_id": ind_clause.clause_id,
                "clause_kind": "indemnification",
                "statute": "UCC Sec. 2-302",
                "detail": (
                    f"Uncapped indemnity at Sec. {ind_clause.clause_id} vs cap at Sec. {cap_clause.clause_id}."
                ),
                "severity": "high",
                "confidence": 0.93
            });
            ind_clause.flagged = True;
            cap_clause.flagged = True;
            ind_clause +>:governed_by:+> cap_clause;
        }
        for c in all_clauses {
            if c.clause_kind in FOUNDATIONAL_KINDS { continue; }
            if self._privacy_leak(c.text) {
                c.flagged = True;
                self.violations.append({
                    "clause_id": c.clause_id,
                    "clause_kind": c.clause_kind or "data_processing",
                    "statute": "GDPR Art. 6 / CCPA 1798.120",
                    "detail": "Personal-data sale or share without consent.",
                    "severity": "critical",
                    "confidence": 0.95
                });
                continue;
            }
            if c.clause_kind == "liability" and has_liability_cap(c.text) {
                c.flagged = True;
                self.violations.append({
                    "clause_id": c.clause_id,
                    "clause_kind": "liability",
                    "statute": "UCC Sec. 2-302",
                    "detail": "Liability cap may be unconscionable relative to uncapped indemnity elsewhere.",
                    "severity": "high",
                    "confidence": 0.88
                });
            } elif c.clause_kind == "indemnification" and has_uncapped_indemnity(c.text) {
                c.flagged = True;
                self.violations.append({
                    "clause_id": c.clause_id,
                    "clause_kind": "indemnification",
                    "statute": "UCC Sec. 2-302",
                    "detail": "Uncapped indemnification scope appears unconscionable.",
                    "severity": "high",
                    "confidence": 0.90
                });
            } elif c.clause_kind == "non_compete" and self._non_compete_overreach(c.text) {
                c.flagged = True;
                self.violations.append({
                    "clause_id": c.clause_id,
                    "clause_kind": "non_compete",
                    "statute": "FTC Non-Compete Rule",
                    "detail": "Restrictive covenant scope may exceed enforceability under FTC guidance.",
                    "severity": "high",
                    "confidence": 0.91
                });
            } elif c.clause_kind == "data_processing" and ("gdpr" in c.text.lower() or "ccpa" in c.text.lower()) {
                c.flagged = True;
                self.violations.append({
                    "clause_id": c.clause_id,
                    "clause_kind": "data_processing",
                    "statute": "GDPR Art. 28",
                    "detail": "Data-processing terms require subprocessors, retention limits, and lawful basis for personal data.",
                    "severity": "high",
                    "confidence": 0.85
                });
            }
        }
        report {
            "agent": "ComplianceWalker",
            "jurisdiction": self.jurisdiction,
            "violations_found": len(self.violations),
            "violations": self.violations
        };
    }
}

"""Agent 2: Contradiction Walker -- deterministic pairwise structural analysis."""

import from ..graph.nodes { Contract, Clause, contradicts }
import from ..tools.clause_classifier { classify_clause, FOUNDATIONAL_KINDS }
import from ..tools.structural_rules { adjudicate_structural_pair }

glob COMPLEMENTARY_PAIRS = [
    ["ip_assignment", "indemnification"],
    ["warranty", "indemnification"],
    ["confidentiality", "indemnification"],
    ["liability", "insurance"],
    ["data_processing", "confidentiality"],
];

walker ContradictionWalker {
    has findings: list = [];
    has comparisons: int = 0;
    has structural_hits: int = 0;

    def _pair_match(k1: str, k2: str, pairs: list) -> bool {
        for p in pairs {
            if len(p) == 2 and k1 in p and k2 in p {
                return True;
            }
        }
        return False;
    }

    def _should_compare(kind_a: str, kind_b: str, linked: bool) -> bool {
        if kind_a in FOUNDATIONAL_KINDS or kind_b in FOUNDATIONAL_KINDS { return False; }
        if kind_a == kind_b and kind_a != "ip_assignment" and kind_a != "indemnification" { return False; }
        if self._pair_match(kind_a, kind_b, COMPLEMENTARY_PAIRS) { return False; }
        if linked { return True; }
        cross_pairs = [
            ["liability", "indemnification"],
            ["liability", "warranty"],
            ["termination", "renewal"],
            ["termination", "confidentiality"],
            ["termination", "non_compete"],
            ["indemnification", "indemnification"],
            ["ip_assignment", "ip_assignment"]
        ];
        if self._pair_match(kind_a, kind_b, cross_pairs) { return True; }
        if kind_a == "general" or kind_b == "general" { return True; }
        return False;
    }

    def _is_mesh_linked(a: Clause, b: Clause) -> bool {
        if b.clause_id and b.clause_id in a.text { return True; }
        if a.clause_id and a.clause_id in b.text { return True; }
        return False;
    }

    can start with Contract entry {
        all_clauses = [-->[?Clause]];
        n = len(all_clauses);
        for i in range(n) {
            a = all_clauses[i];
            if not a.clause_kind {
                a.clause_kind = classify_clause(a.text, a.section);
            }
            for j in range(i + 1, n) {
                b = all_clauses[j];
                if not b.clause_kind {
                    b.clause_kind = classify_clause(b.text, b.section);
                }
                kind_a = a.clause_kind;
                kind_b = b.clause_kind;
                linked = self._is_mesh_linked(a, b);
                if not self._should_compare(kind_a, kind_b, linked) {
                    continue;
                }
                self.comparisons += 1;
                structural = adjudicate_structural_pair(
                    a.text, kind_a,
                    b.text, kind_b
                );
                if not structural or not structural.get("contradicts", False) {
                    continue;
                }
                self.structural_hits += 1;
                a +>:contradicts(
                    severity=str(structural.get("severity", "potential")),
                    explanation=str(structural.get("explanation", "")),
                    confidence=float(structural.get("confidence", 0.85))
                ):+> b;
                a.flagged = True;
                b.flagged = True;
                self.findings.append({
                    "clause_a": a.clause_id,
                    "clause_b": b.clause_id,
                    "kind_a": kind_a,
                    "kind_b": kind_b,
                    "severity": structural.get("severity", "potential"),
                    "explanation": structural.get("explanation", ""),
                    "confidence": structural.get("confidence", 0.85)
                });
            }
        }
        report {
            "agent": "ContradictionWalker",
            "comparisons": self.comparisons,
            "structural_hits": self.structural_hits,
            "contradictions_found": len(self.findings),
            "findings": self.findings
        };
    }
}

"""Serialize Jac OSP graph to UI JSON (nodes, links, clauses, findings)."""

import from ..graph.nodes { Contract, Clause }


walker GraphExportWalker {
    has contradictions: list = [];
    has violations: list = [];
    has proposals: list = [];
    has report_text: str = "";
    has contract_intent: dict = {};
    has payload: dict = {};

    def clause_label(c: Clause) -> str {
        cid = c.clause_id if c.clause_id else "?";
        sec = (c.section or "").strip();
        if sec {
            short = sec if len(sec) <= 28 else sec[:26] + "…";
            return f"§{cid} {short}";
        }
        return f"§{cid}";
    }

    can export with Contract entry {
        all_clauses = [-->[?Clause]];
        contract_key = here.title if here.title else "contract";
        clauses_out = [];
        for c in all_clauses {
            ck = c.clause_id if c.clause_id else f"clause-{c.text[:20]}";
            clauses_out.append({
                "id": ck,
                "clause_id": c.clause_id,
                "title": f"Sec. {c.clause_id}" + (f" - {c.section}" if c.section else ""),
                "section": c.section,
                "risk_score": c.risk_score,
                "risk_level": c.risk_level,
                "clause_type": c.clause_type,
                "clause_kind": c.clause_kind,
                "flagged": c.flagged,
                "text": c.text
            });
        }

        id_map = {};
        for c in all_clauses {
            ck = c.clause_id if c.clause_id else f"clause-{c.text[:20]}";
            id_map[c.clause_id] = ck;
        }

        contradictions_out = [];
        for f in self.contradictions {
            contradictions_out.append({
                "clause_a": f.get("clause_a", ""),
                "clause_b": f.get("clause_b", ""),
                "clause_a_id": id_map.get(f.get("clause_a", ""), ""),
                "clause_b_id": id_map.get(f.get("clause_b", ""), ""),
                "severity": f.get("severity", "potential"),
                "description": f.get("explanation", ""),
                "confidence": f.get("confidence", 0)
            });
        }

        compliance_out = [];
        for v in self.violations {
            compliance_out.append({
                "clause": v.get("clause_id", ""),
                "statute": v.get("statute", ""),
                "severity": v.get("severity", "high"),
                "issue": v.get("detail", "")
            });
        }

        proposals_out = [];
        for p in self.proposals {
            proposals_out.append({
                "clause": p.get("clause_id", ""),
                "clause_kind": p.get("clause_kind", ""),
                "original": p.get("original", p.get("original_text", "")),
                "proposed": p.get("proposed", p.get("proposed_text", "")),
                "impact": p.get("impact", "medium"),
                "issue_detected": p.get("issue_detected", ""),
                "rationale": p.get("rationale", "")
            });
        }

        nodes = [{"id": contract_key, "label": here.title, "type": "contract", "risk": here.risk_score}];
        links = [];
        for c in all_clauses {
            ck = c.clause_id if c.clause_id else f"clause-{c.text[:20]}";
            nodes.append({
                "id": ck, "label": self.clause_label(c), "type": "clause",
                "risk": c.risk_score, "risk_level": c.risk_level, "flagged": c.flagged
            });
            links.append({"source": contract_key, "target": ck, "type": "contains"});
        }
        for f in self.contradictions {
            sa = id_map.get(f.get("clause_a", ""), "");
            sb = id_map.get(f.get("clause_b", ""), "");
            if sa and sb {
                links.append({"source": sa, "target": sb, "type": "contradicts"});
            }
        }

        self.payload = {
            "status": "complete",
            "title": here.title,
            "risk_score": here.risk_score,
            "clauses": clauses_out,
            "contradictions": contradictions_out,
            "compliance_issues": compliance_out,
            "proposals": proposals_out,
            "report": self.report_text,
            "contract_intent": self.contract_intent,
            "graph_data": {"nodes": nodes, "links": links}
        };
        # Avoid reporting the full payload: Jac prints reports to stdout and large
        # payloads crash on Windows (OSError 22) when stdout is not a real console.
        # Parent walkers read export_w.payload directly.
        report {"status": "complete", "title": here.title, "clauses": len(clauses_out)};
    }
}

"""Mesh enrichment walker — classify clauses and weave reference/modifies edges."""

import from ..graph.nodes { Contract, Clause, references, modifies }
import from ..tools.clause_classifier { classify_clause }
import from ..tools.graph_mesh { extract_section_refs, extract_modifies_target }
walker MeshEnrichmentWalker {
    has reference_edges: int = 0;
    has modifies_edges: int = 0;
    has all_clauses: list = [];

    can start with Contract entry {
        self.all_clauses = [-->[?Clause]];
        visit [-->];
    }

    can enrich with Clause entry {
        if not here.clause_kind {
            here.clause_kind = classify_clause(here.text, here.section);
        }

        all_clauses = self.all_clauses;
        for ref_id in extract_section_refs(here.text) {
            for tgt in all_clauses {
                if tgt.clause_id == ref_id and tgt.clause_id != here.clause_id {
                    here +>:references(context=f"references Section {ref_id}"):+> tgt;
                    self.reference_edges += 1;
                }
            }
        }
        for ref_id in extract_modifies_target(here.text) {
            for tgt in all_clauses {
                if tgt.clause_id == ref_id and tgt.clause_id != here.clause_id {
                    here +>:modifies(scope="limits"):+> tgt;
                    self.modifies_edges += 1;
                }
            }
        }
        visit [-->];
    }

    can finish with Contract exit {
        report {
            "agent": "MeshEnrichmentWalker",
            "reference_edges": self.reference_edges,
            "modifies_edges": self.modifies_edges
        };
    }
}

