                  rgb_reasoning: str, spill_detected: bool, confidence: float)
    -> DossierReport by llm();

# ---------------------------------------------------------------------------
# Walker
# ---------------------------------------------------------------------------

walker Watchdog {
    has mission: str = "";
    has rumor_parse: RumorParse = None;
    has web_intel: str = "";
    has entity_list: EntityList = None;
    has decision: InvestigatorDecision = None;
    has target_lat: float = 0.0;
    has target_lon: float = 0.0;
    has target_start: str = "";
    has target_end: str = "";
    has rgb_image_path: str = "";
    has sar_image_path: str = "";
    has rgb_verdict: SpillVerdict = None;
    has sar_verdict: SpillVerdict = None;
    has combined_verdict: SpillVerdict = None;
    has dossier: DossierReport = None;
    has investigator_node_ref: InvestigatorNode = None as InvestigatorNode;
    has satellite_node_ref: SatelliteVerificationNode = None as SatelliteVerificationNode;
    has synthesis_node_ref: SynthesisNode = None as SynthesisNode;

    can with Root entry {
        visit [-->];
    }

    can with MissionNode entry {
        print(f"[orion] Mission: {self.mission}");
        self.rumor_parse = parse_known_rumor(self.mission);
        if not has_known_rumor_parse(self.rumor_parse) {
            self.rumor_parse = parse_rumor(self.mission);
            self.rumor_parse = normalize_rumor_parse(self.mission, self.rumor_parse);
        }
        self.target_lat = self.rumor_parse.lat;
        self.target_lon = self.rumor_parse.lon;
        self.target_start = self.rumor_parse.start_date;
        self.target_end = self.rumor_parse.end_date;
        print(f"[orion] Initial target: {self.rumor_parse.location_name} ({self.target_lat}, {self.target_lon})");
        print(f"[orion] Date window: {self.target_start} -> {self.target_end}");
        visit [-->];
    }

    can with IntelligenceGatheringNode entry {
        print("[orion] Searching for corroborating intelligence...");
        result = search_web(self.rumor_parse.search_query);
        self.web_intel = result.articles;
        print(f"[orion] Found {result.source_count} sources.");

        if web_intel_absent(self.web_intel) {
            print("[orion] No usable web intel. Treating this as unknown, not disproven.");
            self.entity_list = empty_entity_list();
        } else {
            print("[orion] Extracting entities from intelligence...");
            self.entity_list = extract_entities(self.mission, self.web_intel);
        }

        for entity in self.entity_list.entities {
            new_node = EntityMemoryNode(
                name=entity.name,
                entity_type=entity.entity_type,
                description=entity.description,
                relevance=entity.relevance,
                suggested_lat=entity.suggested_lat,
                suggested_lon=entity.suggested_lon
            );
            here ++> new_node;
        }
        print(f"[orion] Knowledge graph: {len(self.entity_list.entities)} EntityMemoryNodes spawned.");
        visit [self.investigator_node_ref];
    }

    can with InvestigatorNode entry {
        print("[orion] Lead Investigator deliberating...");
        entities_summary = format_entities(self.entity_list);
        self.decision = investigate(self.mission, self.web_intel, entities_summary);
        self.decision = normalize_investigator_decision(
            self.mission,
            self.rumor_parse,
            self.web_intel,
            self.decision
        );
        print(f"[orion] Decision: {self.decision.action}");
        print(f"[orion] Reasoning: {self.decision.reasoning}");

        if self.decision.action == "PIVOT" {
            self.target_lat = self.decision.target_lat;
            self.target_lon = self.decision.target_lon;
            self.target_start = self.decision.target_date;
            self.target_end = next_date(self.target_start);
            print(f"[orion] Pivoting to ({self.target_lat}, {self.target_lon}) on {self.target_start}");
        }

        if self.decision.action == "ABORT" {
            print("[orion] Orbital tasking aborted. Proceeding directly to synthesis.");
            visit [self.synthesis_node_ref];
        } else {
            visit [self.satellite_node_ref];
        }
    }

    can with SatelliteVerificationNode entry {
        print("[orion] Acquiring Sentinel-2 RGB tile...");
        self.rgb_image_path = save_rgb_image_to_disk(
            self.target_lat,
            self.target_lon,
            self.target_start,
            self.target_end
        );
        if not self.rgb_image_path {
            print("[orion] No Sentinel-2 RGB imagery available. Skipping RGB classifier.");
            self.rgb_verdict = SpillVerdict(
                spill_detected=False,
                confidence=0.0,
                reasoning="No Sentinel-2 RGB imagery found for the requested location and date range."
            );
        } else {
            print(f"[orion] Running Hugging Face RGB classifier on {self.rgb_image_path}...");
            self.rgb_verdict = run_rgb_oil_slick_detection(self.rgb_image_path);
            print(f"[orion] RGB classifier: spill_detected={self.rgb_verdict.spill_detected} confidence={self.rgb_verdict.confidence:.0%}");
        }

        print("[orion] Acquiring Sentinel-1 SAR backup tile...");
        self.sar_image_path = save_sar_image_to_disk(
            self.target_lat,
            self.target_lon,
            self.target_start,
            self.target_end
        );
        if not self.sar_image_path {
            print("[orion] No Sentinel-1 SAR imagery available. Skipping SAR backup classifier.");
            self.sar_verdict = SpillVerdict(
                spill_detected=False,
                confidence=0.0,
                reasoning="No Sentinel-1 SAR imagery found for the requested location and date range."
            );
        } else {
            print(f"[orion] Running Hugging Face SAR backup classifier on {self.sar_image_path}...");
            self.sar_verdict = run_sar_oil_slick_detection(self.sar_image_path);
            print(f"[orion] SAR backup classifier: spill_detected={self.sar_verdict.spill_detected} confidence={self.sar_verdict.confidence:.0%}");
        }

        self.combined_verdict = combine_verdicts(self.rgb_verdict, self.sar_verdict);
        print(f"[orion] Combined satellite verdict: spill_detected={self.combined_verdict.spill_detected} confidence={self.combined_verdict.confidence:.0%}");
        visit [-->];
    }

    can with SynthesisNode entry {
        print("[orion] Writing Intelligence Dossier...");
        if self.combined_verdict {
            rgb_text = self.combined_verdict.reasoning;
            detected = self.combined_verdict.spill_detected;
            conf = self.combined_verdict.confidence;
        } else {
            rgb_text = "Orbital tasking aborted - no satellite imagery acquired.";
            detected = False;
            conf = 0.0;
        }
        web_mode = "live";
        if web_intel_absent(self.web_intel) {
            web_mode = "offline";
            self.dossier = write_offline_dossier(
                self.mission,
                self.rumor_parse.location_name,
                str(self.decision),
                rgb_text,
                detected,
                conf
            );
            path = save_named_dossier(self.dossier, no_web_dossier_path(self.rumor_parse.location_name));
        } else {
            self.dossier = write_dossier(
                self.mission,
                self.web_intel,
                str(self.decision),
                rgb_text,
                detected,
                conf
            );
            path = save_dossier(self.dossier, self.rumor_parse.location_name);
        }
        print(f"\n{self.dossier.body}\n");
        print(f"[orion] Dossier saved to {path}");

        manifest_path = save_run_manifest(
            self.rumor_parse.location_name,
            self.target_lat,
            self.target_lon,
            self.target_start,
            self.target_end,
            self.rgb_image_path,
            self.sar_image_path,
            self.rgb_verdict,
            self.sar_verdict,
            self.combined_verdict,
            path,
            web_mode
        );
        print(f"[orion] Manifest saved to {manifest_path}");
    }
}

# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

with entry {
    mission = get_cli_mission();
    if not mission {
        print("=========================================================");
        print("  Orion Watchdog v2 - Agentic OSINT Dossier Generator");
        print("=========================================================");
        print("  Usage:");
        print("    $env:ORION_MISSION = 'tanker spill Hormuz July 2021'");
        print("    jac run watchdog.jac");
        print("=========================================================");
        print("  No rumor supplied -- running with default.");
        print("");
        mission = "I heard a tanker dumped bilge in the Strait of Hormuz in July 2021.";
    }

    mission_node = MissionNode();
    intel_node = IntelligenceGatheringNode();
    investigator_node = InvestigatorNode();
    satellite_node = SatelliteVerificationNode();
    synthesis_node = SynthesisNode();

    root ++> mission_node;
    mission_node ++> intel_node;
    intel_node ++> investigator_node;
    investigator_node ++> satellite_node;
    investigator_node ++> synthesis_node;
    satellite_node ++> synthesis_node;

    root spawn Watchdog(
        mission=mission,
        investigator_node_ref=investigator_node,
        satellite_node_ref=satellite_node,
        synthesis_node_ref=synthesis_node
    );
}

"""Orion - Sentinel-2 RGB oil spill detector.

Primary language: Jac (jaclang 0.9).
Jac features:
  - Object Spatial Programming: node (SatelliteRegion) + walker (SpillMonitor)
  - byllm: `def monitor_region(...) -> dict by llm();` — LLM fills the return
    value by calling check_region_for_spill via the ReAct tool loop.

Python bridge: tools.py wraps GEE fetch + vision model call so raw image
bytes never cross the LLM tool-calling boundary.

Run: jac run monitor.jac
"""

import from featherless_model { FeatherlessModel, featherless_api_key }
import from tools { check_region_for_spill, SpillVerdict }

glob llm: FeatherlessModel = FeatherlessModel(
    model_name="Qwen/Qwen3.5-4B",
    base_url="https://api.featherless.ai/v1",
    api_key=featherless_api_key(),
    proxy=True
);

# --- Node: stateful representation of a monitored ocean region ---

node SatelliteRegion {
    has lat: float = 33.59;
    has lon: float = -118.05;
    has start_date: str = '2021-10-01';
    has end_date: str = '2021-10-05';
    has past_anomalies: list = [];
    has last_verdict: SpillVerdict = None;
}

# --- byllm ReAct: LLM autonomously calls the tool and returns a verdict ---

"""Check the given ocean region for oil spills using Sentinel-2 RGB imagery.
Use the check_region_for_spill tool with the provided coordinates and dates.
Return the resulting verdict as a dict with spill_detected, confidence, and reasoning."""
def monitor_region(lat: float, lon: float, start_date: str, end_date: str) -> SpillVerdict
    by llm(tools=[check_region_for_spill]);

# --- Walker: visits each SatelliteRegion and runs the monitor ---

walker SpillMonitor {
    # jaclang 0.9.0 expects the root walker handler in this anonymous form.
    can with Root entry {
        # Spawned on root — traverse to connected SatelliteRegion nodes.
        visit [-->];
    }

    can monitor with SatelliteRegion entry {
        print(f"Monitoring region ({here.lat}, {here.lon}) from {here.start_date} to {here.end_date}...");

        verdict = monitor_region(here.lat, here.lon, here.start_date, here.end_date);

        if verdict {
            here.last_verdict = verdict;
            if verdict.spill_detected {
                here.past_anomalies.append(verdict);
            }
            print("");
            print("--- Spill Detection Result ---");
            print(f"Spill detected : {verdict.spill_detected}");
            print(f"Confidence     : {verdict.confidence:.0%}");
            print(f"Reasoning      : {verdict.reasoning}");
        }
    }
}

# --- Entry point ---

with entry {
    print("[orion] Starting SpillMonitor walker...");
    region = SatelliteRegion(
        lat=33.59,
        lon=-118.05,
        start_date='2021-10-01',
        end_date='2021-10-05'
    );
    root ++> region;
    root spawn SpillMonitor();
    print("[orion] Walker complete.");
}

"""Orion v2 Satellite Verification — Jac orchestrator wrapping Python backend.

Nodes coordinate the 3x3 spatial SAR/RGB consensus scan.
Python (agent_tools, spatial_search) handles compute.
"""

import from agent_tools {
    run_spatial_sar_scan as py_spatial_scan,
    save_rgb_image_to_disk
}
import from spatial_search { SpatialSearchResult }

node scan_coordinator {
    has lat: float = 0.0;
    has lon: float = 0.0;
    has start_date: str = "";
    has end_date: str = "";
}

node sar_fetch {
    has target_locked: bool = False;
    has confidence_score: float = 0.0;
    has winning_sensor: str = "";
}

node rgb_fetch {
    has image_path: str = "";
}

node result_aggregator {
    has final_result: SpatialSearchResult = None;
}

walker orion_spatial_scan {
    has result: SpatialSearchResult = None;

    can with Root entry {
        visit [-->];
    }

    can with scan_coordinator entry {
        here.lat = self.result.lat if hasattr(self, 'result') and self.result else 0.0;
        here.lon = self.result.lon if hasattr(self, 'result') and self.result else 0.0;
        here.start_date = self.result.start_date if hasattr(self, 'result') and self.result else "";
        here.end_date = self.result.end_date if hasattr(self, 'result') and self.result else "";
        visit [-->];
    }

    can with sar_fetch entry {
        print(f"[orion] Dispatching spatial SAR/RGB scan: {self.result.lat:.4f}, {self.result.lon:.4f}");
        self.result = py_spatial_scan(
            lat=self.result.lat,
            lon=self.result.lon,
            start_date=self.result.start_date,
            end_date=self.result.end_date
        );
        here.target_locked = self.result.target_locked;
        here.confidence_score = self.result.confidence_score;
        here.winning_sensor = self.result.winning_sensor;
        print(f"[orion] Scan complete: locked={here.target_locked} confidence={here.confidence_score:.2f}");
        visit [-->];
    }

    can with rgb_fetch entry {
        if self.result and self.result.display_image_path {
            here.image_path = self.result.display_image_path;
        }
        print(f"[orion] RGB display path: {here.image_path}");
        visit [-->];
    }

    can with result_aggregator entry {
        here.final_result = self.result;
        print(f"[orion] Aggregation complete. Result locked for reporting.");
    }
}

