                pair_key = pair[0] + "|" + pair[1];
                if pair_key not in seen_pairs {
                    seen_pairs.append(pair_key);
                    is_flagged = inter["severity"] >= 2;
                    traversal_log.append({
                        "drug_a": pair[0],
                        "drug_b": pair[1],
                        "severity": inter["severity"],
                        "mechanism": inter["mechanism"],
                        "clinical_effect": inter["clinical_effect"],
                        "flagged": is_flagged
                    });
                    if is_flagged {
                        flagged_pairs.append({
                            "drug_a": pair[0],
                            "drug_b": pair[1],
                            "severity": inter["severity"],
                            "mechanism": inter["mechanism"],
                            "clinical_effect": inter["clinical_effect"],
                            "evidence_level": inter["evidence_level"]
                        });
                    }
                }
            }
        }

        user_condition_names = [c.lower() for c in extracted.conditions_mentioned];
        all_conditions = [-->[?Condition]];
        contraindications: list = [];

        for cond in all_conditions {
            if cond.name.lower() in user_condition_names {
                for contra_drug in cond.contraindicated_drugs {
                    if contra_drug.lower() in user_drug_names {
                        contraindications.append({
                            "condition": cond.name,
                            "drug": contra_drug,
                            "icd_code": cond.icd_code,
                            "reason": contra_drug + " is contraindicated in patients with " + cond.name
                        });
                    }
                }
            }
        }

        severity_max = 0;
        for pair in flagged_pairs {
            if pair["severity"] > severity_max {
                severity_max = pair["severity"];
            }
        }

        summary = generate_risk_summary(flagged_pairs, contraindications, matched_drugs);

        generated_at = datetime.utcnow().isoformat();
        report_node = RiskReport(
            flagged_pairs=flagged_pairs,
            severity_max=severity_max,
            summary=summary,
            generated_at=generated_at
        );
        profile ++> report_node;

        report {
            "flagged_pairs": flagged_pairs,
            "traversal_log": traversal_log,
            "contraindications": contraindications,
            "severity_max": severity_max,
            "matched_drugs": matched_drugs,
            "unrecognised_drugs": unrecognised_drugs,
            "summary": summary,
            "generated_at": generated_at
        };
        disengage;
    }

    class __specs__ {
        has auth: bool = False;
    }
}

import from ..graph.nodes { Drug, Condition, MedProfile, RiskReport }
import from ..graph.edges { Interaction }
import from data_loader { get_all_drugs, get_all_interactions, get_all_conditions }

walker seed_graph {
    has force_reseed: bool = False;

    can seed with Root entry {
        existing_drugs = [-->[?Drug]];
        if len(existing_drugs) > 0 and not self.force_reseed {
            report {"status": "already_seeded", "drug_count": len(existing_drugs)};
            disengage;
        }

        drug_nodes: dict = {};

        for d in get_all_drugs() {
            dn = Drug(
                name=d["name"],
                generic_name=d["generic_name"],
                drug_class=d["drug_class"],
                cyp_pathway=d["cyp_pathway"],
                half_life_hours=d["half_life_hours"]
            );
            here ++> dn;
            drug_nodes[d["name"]] = dn;
        }

        for c in get_all_conditions() {
            cn = Condition(
                name=c["name"],
                icd_code=c["icd_code"],
                contraindicated_drugs=c["contraindicated_drugs"]
            );
            here ++> cn;
        }

        edge_count = 0;
        for inter in get_all_interactions() {
            da_name = inter["drug_a"];
            db_name = inter["drug_b"];
            if da_name in drug_nodes and db_name in drug_nodes {
                da = drug_nodes[da_name];
                db = drug_nodes[db_name];
                da ++> db;
                db ++> da;
                edge_count += 1;
            }
        }

        report {
            "status": "seeded",
            "drug_count": len(drug_nodes),
            "edge_count": edge_count,
            "condition_count": len(get_all_conditions())
        };
    }

    class __specs__ {
        has auth: bool = False;
    }
}

