glob MAX_REASONING_DEPTH = 5;
glob DEFAULT_COMPLEXITY_THRESHOLD = 0.6;
glob CONFIDENCE_THRESHOLD = 0.7;

glob AGENT_TYPES = {
    "planner": "Orchestrates workflow based on complexity",
    "memory": "Retrieves related prior reasoning",
    "thesis": "Generates supporting claims",
    "antithesis": "Generates counter-claims",
    "evidence": "Gathers supporting evidence",
    "referee": "Evaluates logic and evidence",
    "synthesis": "Creates final structured output",
    "memory_update": "Persists reasoning to database"
};

glob COMPLEXITY_LEVELS = {
    "simple": {"threshold": 0.3, "agents": ["thesis", "antithesis", "referee", "synthesis"]},
    "moderate": {"threshold": 0.6, "agents": ["memory", "thesis", "antithesis", "evidence", "referee", "synthesis"]},
    "complex": {"threshold": 1.0, "agents": ["planner", "memory", "thesis", "antithesis", "evidence", "referee", "synthesis"]}
};

glob EVIDENCE_TYPES = ["statistical", "logical", "empirical", "anecdotal", "theoretical"];
glob RELATION_TYPES = ["supports", "attacks", "validated_by", "related_to", "generated_from", "discussed_in", "refines", "contradicts", "contributes_to"];

glob DB_PATH = "./truthforge.db";  # Can be overridden by process.env.TRUTHFORGE_DB_PATH
glob LOG_LEVEL = "info";  # debug, info, warn, error - can be overridden by process.env.LOG_LEVEL

"""
TruthForge AI - Edge Definitions
Defines all edge types connecting nodes in the reasoning graph
"""

# supports - Claim or Evidence supports a thesis/statement
edge supports {
    has weight: float = 1.0;
    has strength: float = 0.0;      # 0-1 confidence
    has explanation: str = "";
    has timestamp: str = "";
}

# attacks - CounterClaim attacks a Claim
edge attacks {
    has weight: float = 1.0;
    has strength: float = 0.0;      # How strong is the attack
    has explanation: str = "";
    has timestamp: str = "";
}

# validated_by - Claim validated by Evidence
edge validated_by {
    has weight: float = 1.0;
    has validation_score: float = 0.0;
    has evidence_quality: float = 0.0;
    has timestamp: str = "";
}

# related_to - Nodes with related topics/content
edge related_to {
    has weight: float = 1.0;
    has similarity_score: float = 0.0;
    has relation_type: str = "";    # "topical", "causal", "comparative"
    has timestamp: str = "";
}

# generated_from - Node derivation source
edge generated_from {
    has weight: float = 1.0;
    has generation_method: str = "";  # "planner", "thesis_walker", etc.
    has confidence: float = 0.0;
    has timestamp: str = "";
}

# discussed_in - Node is part of a debate session
edge discussed_in {
    has weight: float = 1.0;
    has discussion_depth: int = 0;
    has stage: int = 0;
    has timestamp: str = "";
}

# refines - Node evolves from prior reasoning
edge refines {
    has weight: float = 1.0;
    has improvement_score: float = 0.0;
    has changes: list[str] = [];
    has timestamp: str = "";
}

# contradicts - Node directly contradicts another
edge contradicts {
    has weight: float = 1.0;
    has contradiction_level: float = 0.0;  # 0-1 intensity
    has explanation: str = "";
    has timestamp: str = "";
}

# contributes_to - Node contributes to verdict/conclusion
edge contributes_to {
    has weight: float = 1.0;
    has contribution_score: float = 0.0;
    has contribution_type: str = "";  # "supporting", "constraining", "neutral"
    has timestamp: str = "";
}

# references - Node references an external source or document
edge references {
    has weight: float = 1.0;
    has citation: str = "";
    has url: str = "";
    has timestamp: str = "";
}

# similar_to - Node is semantically similar to another node
edge similar_to {
    has weight: float = 1.0;
    has similarity_score: float = 0.0;  # 0-1
    has relation_type: str = "semantic";
    has timestamp: str = "";
}

"""
TruthForge AI - Evidence Walker
Gathers structured evidence using Gemini, search capability, and graph memory.
Returns: { source_count, source_titles[], evidence[] }
No hardcoded evidence — all data comes from Gemini API.
"""

import from truthforge_nodes { * }
import from truthforge_config { * }

walker EvidenceWalker {
    has question_text: str = "";
    has thesis_claims: list[dict] = [];
    has counter_claims: list[dict] = [];
    has gathered_evidence: list[dict] = [];
    has source_count: int = 0;
    has source_titles: list[str] = [];
    has session_id: str = "";

    def gather_evidence() {
        print("[EVIDENCE] ===== EVIDENCE WALKER STARTING =====");
        print(f"[EVIDENCE] Question: {self.question_text[:50]}...");
        print(f"[EVIDENCE] Thesis claims to search: {len(self.thesis_claims)}");
        print(f"[EVIDENCE] Counter-claims to search: {len(self.counter_claims)}");

        # Evidence is populated by Gemini API call in TypeScript layer.

        self.source_count = len(self.source_titles);

        print(f"[EVIDENCE] Sources found: {self.source_count}");
        for title in self.source_titles {
            print(f"  - {title}");
        }

        print(f"[EVIDENCE] Evidence items: {len(self.gathered_evidence)}");
        for (i, ev) in enumerate(self.gathered_evidence) {
            print(f"  Evidence {i+1}:");
            print(f"    Content: {ev.get('content', '')[:60]}...");
            print(f"    Source: {ev.get('source_title', 'Unknown')}");
            print(f"    Type: {ev.get('source_type', 'general')}");
            print(f"    Supports: {ev.get('supports', 'both')}");
            print(f"    Credibility: {ev.get('credibility', 0):.2f}");
        }

        print("[EVIDENCE] ===== EVIDENCE WALKER COMPLETE =====");
    }

    def get_structured_result() -> dict {
        return {
            "source_count": self.source_count,
            "source_titles": self.source_titles,
            "evidence": self.gathered_evidence
        };
    }

    def gather(
        thesis_claims: list[dict],
        counter_claims: list[dict],
        session_id: str = ""
    ) -> list[dict] {
        self.thesis_claims = thesis_claims;
        self.counter_claims = counter_claims;
        self.session_id = session_id;

        self.gather_evidence();

        return self.gathered_evidence;
    }
}

"""
TruthForge AI - Main Orchestration
Entry point for the backend reasoning engine.
Coordinates all walkers in the execution order:
  Question → Planner → Memory → Thesis → Antithesis → Evidence → Referee → Synthesis → MemoryUpdate

NOTE: At runtime, the actual execution happens in TypeScript (truthforge_api.ts).
This file serves as the architectural specification and Jac-native entry point.
"""

import time;
import from truthforge_nodes { * }
import from truthforge_config { * }
import from truthforge_planner { PlannerWalker }
import from truthforge_memory { MemoryWalker }
import from truthforge_thesis { ThesisWalker }
import from truthforge_antithesis { AntithesisWalker }
import from truthforge_evidence { EvidenceWalker }
import from truthforge_referee { RefereeWalker }
import from truthforge_synthesis { SynthesisWalker }
import from truthforge_memory_update { MemoryUpdateWalker }

obj DebateGraph {
    has nodes: dict = {};
    has edges: dict = {};
    has execution_log: list[str] = [];
    has agent_events: list[dict] = [];

    def generate_session_id() -> str {
        return f"session_{len(self.nodes)}_{time.time()}";
    }

    def log_execution(message: str) {
        self.execution_log.append(message);
        print(message);
    }

    def emit_event(agent: str, status: str, detail: str) {
        event = {
            "agent": agent,
            "status": status,
            "detail": detail,
            "timestamp": "current_timestamp"
        };
        self.agent_events.append(event);
        self.log_execution(f"[{status.upper()}] {agent}: {detail}");
    }

    def run_debate(question: str) -> dict {
        session_id = self.generate_session_id();
        question_id = f"question_{session_id}";

        self.log_execution("\n╔════════════════════════════════════════════════════╗");
        self.log_execution("║          TRUTHFORGE AI - DEBATE ORCHESTRATION       ║");
        self.log_execution("╚════════════════════════════════════════════════════╝");

        # Store initial question
        self.nodes[session_id] = {
            "question": question,
            "question_id": question_id,
            "status": "in_progress"
        };

        # ── Step 1: PLANNER ──────────────────────────────────────────
        self.emit_event("planner", "started", "Classifying question type");

        planner = PlannerWalker();
        planner.question_text = question;
        planner.orchestrate();

        self.emit_event("planner", "complete",
            f"Type: {planner.question_type} | Domain: {planner.domain} | Complexity: {planner.complexity_score:.2f}");

        complexity = "simple";
        if planner.complexity_score >= 0.6 {
            complexity = "complex";
        }
        elif planner.complexity_score >= 0.3 {
            complexity = "moderate";
        }

        # ── Step 2: MEMORY ───────────────────────────────────────────
        self.emit_event("memory", "started", "Retrieving prior reasoning");

        memory = MemoryWalker();
        memory.question_text = question;
        memory.retrieve_memory();

        memory_count = len(memory.related_memories);
        self.emit_event("memory", "complete", f"Retrieved: {memory_count} prior analyses");

        # ── Step 3: THESIS ───────────────────────────────────────────
        self.emit_event("thesis", "started", "Generating supporting claims via Gemini");

        thesis = ThesisWalker();
        thesis.question_text = question;
        thesis.question_type = planner.question_type;
        thesis.domain = planner.domain;
        thesis_result = thesis.generate_thesis(session_id);

        claim_count = thesis_result.get("total_claims", 0);
        self.emit_event("thesis", "complete", f"Claims generated: {claim_count}");

        # ── Step 4: ANTITHESIS ───────────────────────────────────────
        self.emit_event("antithesis", "started", "Generating counter-arguments via Gemini");

        thesis_claims = thesis_result.get("claims", []) as list[dict];
        if len(thesis_claims) == 0 {
            thesis_claims = thesis_result.get("supporting_claims", []) as list[dict];
            if thesis_result.get("primary_claim", {}) {
                thesis_claims.insert(0, thesis_result["primary_claim"] as dict);
            }
        }

        antithesis = AntithesisWalker();
        antithesis_result = antithesis.generate_antithesis(thesis_claims, session_id);

        counter_count = antithesis_result.get("total_counter_claims", 0);
        self.emit_event("antithesis", "complete", f"Counterclaims generated: {counter_count}");

        # ── Step 5: EVIDENCE ─────────────────────────────────────────
        evidence_list: list[dict] = [];
        if "evidence" in planner.agents_to_activate {
            self.emit_event("evidence", "started", "Gathering structured evidence via Gemini");

            evidence = EvidenceWalker();
            evidence.question_text = question;
            counter_claims = antithesis_result.get("counter_claims", antithesis_result.get("supporting_counters", [])) as list[dict];
            evidence_list = evidence.gather(thesis_claims, counter_claims, session_id);

            self.emit_event("evidence", "complete", f"Evidence retrieved: {len(evidence_list)} sources");
        }

        # ── Step 6: REFEREE ──────────────────────────────────────────
        self.emit_event("referee", "started", "Evaluating debate quality");

        referee = RefereeWalker();
        counter_claims_for_referee = antithesis_result.get("counter_claims", antithesis_result.get("supporting_counters", [])) as list[dict];
        verdict = referee.evaluate(thesis_claims, counter_claims_for_referee, evidence_list, session_id);

        self.emit_event("referee", "complete",
            f"Logic: {(verdict.get('logic_strength', 0) as float):.2f} | Evidence: {(verdict.get('evidence_strength', 0) as float):.2f}");

        # ── Step 7: SYNTHESIS ────────────────────────────────────────
        self.emit_event("synthesis", "started", "Generating final analysis");

        synthesis = SynthesisWalker();
        synthesis_result = synthesis.synthesize(
            question,
            thesis_claims,
            counter_claims_for_referee,
            evidence_list,
            verdict,
            session_id
        );

        self.emit_event("synthesis", "complete",
            f"Confidence: {synthesis_result.get('confidence', 'Moderate')}");

        # ── Step 8: MEMORY UPDATE ────────────────────────────────────
        self.emit_event("memory_update", "started", "Persisting results to database");

        agents_executed = ["planner", "memory", "thesis", "antithesis"];
        if "evidence" in planner.agents_to_activate {
            agents_executed.append("evidence");
        }
        agents_executed.extend(["referee", "synthesis", "memory_update"]);

        memory_update = MemoryUpdateWalker();
        persistence_result = memory_update.persist(
            session_id,
            question_id,
            question,
            complexity,
            thesis_claims,
            counter_claims_for_referee,
            evidence_list,
            verdict,
            synthesis_result,
            agents_executed
        );

        self.emit_event("memory_update", "complete",
            f"Persisted: {'validated' if persistence_result.get('persistence_validated') else 'failed'}");

        # ── Summary ──────────────────────────────────────────────────
        self.log_execution("\n╔════════════════════════════════════════════════════╗");
        self.log_execution("║               DEBATE COMPLETE - SUMMARY              ║");
        self.log_execution("╚════════════════════════════════════════════════════╝");
        self.log_execution(f"\nSession: {session_id}");
        self.log_execution(f"Question Type: {planner.question_type}");
        self.log_execution(f"Complexity: {complexity}");
        self.log_execution(f"Claims: {claim_count} | Counter-claims: {counter_count}");
        self.log_execution(f"Evidence: {len(evidence_list)}");

        # Update session status
        self.nodes[session_id]["status"] = "completed";

        return {
            "session_id": session_id,
            "question_id": question_id,
            "question_type": planner.question_type,
            "complexity": complexity,
            "thesis": thesis_result,
            "antithesis": antithesis_result,
            "evidence": evidence_list,
            "verdict": verdict,
            "synthesis": synthesis_result,
            "persistence": persistence_result,
            "agent_events": self.agent_events,
            "execution_log": self.execution_log
        };
    }
}

# Main entry point
def initialize_truthforge() -> DebateGraph {
    debate_graph = DebateGraph();

    # Validate config
    required_edges = ["supports", "attacks", "validated_by", "related_to", "generated_from", "discussed_in", "references", "similar_to"];

    print("TruthForge AI - Backend Core Initialized");
    print("[VALIDATION] Verifying required relation types...");

    missing_relations = [];
    for rel in required_edges {
        if rel not in RELATION_TYPES {
            missing_relations.append(rel);
        }
    }

    if len(missing_relations) > 0 {
        print(f"[VALIDATION] ⚠ Missing relation types: {', '.join(missing_relations)}");
    }
    else {
        print("[VALIDATION] ✓ All required relation types present");
    }

    print("[VALIDATION] ✓ Agent pipeline: Planner → Memory → Thesis → Antithesis → Evidence → Referee → Synthesis → MemoryUpdate");

    return debate_graph;
}

"""
TruthForge AI - Memory Walker
Traverses graph to find related debates and retrieve prior reasoning
Provides historical context for current reasoning
"""

import from truthforge_nodes { * }
import from truthforge_config { * }

walker MemoryWalker {
    has question_text: str = "";
    has related_memories: list[dict] = [];
    has prior_claims: list[str] = [];
    has prior_counter_claims: list[str] = [];
    has prior_verdicts: list[str] = [];
    has confidence_history: dict = {};

    def search_related_topics() {
        print(f"[MEMORY] Searching for related memories on: {self.question_text[:50]}...");

        # In a real implementation, this would query the SQLite database
        # For now, we structure how it would work with graph traversal

        keywords = self.question_text.lower().split();
        min_keyword_length = 3;

        important_keywords = [];
        for keyword in keywords {
            if len(keyword) >= min_keyword_length {
                important_keywords.append(keyword);
            }
        }

        # Structure for memory results
        self.related_memories = [];

        # Fallback: ensure we return at least an empty structured memory to avoid empty responses
        if len(self.related_memories) == 0 {
            self.related_memories.append({
                "id": "memory_none",
                "summary": "No directly related memories found",
                "relevance": 0.0,
                "timestamp": "current_timestamp"
            });
        }
    }

    def traverse_prior_claims() {
        print("[MEMORY] Retrieving prior supporting claims...");

        # Graph traversal would look for edges connecting to prior claims
        # Structure: source --(related_to)--> prior_claim

        self.prior_claims = [];
    }

    def retrieve_counter_arguments() {
        print("[MEMORY] Retrieving prior counter-arguments...");

        # Graph traversal looking for counter-claim nodes
        # connected through related_to or contradicts edges

        self.prior_counter_claims = [];
    }

    def find_confidence_history() {
        print("[MEMORY] Extracting confidence history...");

        # Look for verdict nodes that evaluated similar claims
        # Build confidence patterns

        self.confidence_history = {
            "high_confidence_topics": [],
            "uncertain_areas": [],
            "controversial_areas": []
        };
    }

    def calculate_relevance_score(memory_entry_text: str) -> float {
        score = 0.0;

        # Simple keyword overlap scoring
        current_keywords = set(self.question_text.lower().split());
        memory_keywords = set(memory_entry_text.lower().split());

        overlap = len(current_keywords & memory_keywords);
        total = len(current_keywords | memory_keywords);

        if total > 0 {
            score = float(overlap) / float(total);
        }

        return score;
    }

    def aggregate_memory_context() -> dict {
        return {
            "related_memories_count": len(self.related_memories),
            "prior_claims": self.prior_claims,
            "prior_counter_claims": self.prior_counter_claims,
            "prior_verdicts": self.prior_verdicts,
            "confidence_patterns": self.confidence_history,
            "recommendations": self._extract_recommendations()
        };
    }

    def _extract_recommendations() -> list[str] {
        recommendations = [];

        if len(self.prior_claims) > 0 {
            recommendations.append("Consider prior supporting claims as starting points");
        }

        if len(self.prior_counter_claims) > 0 {
            recommendations.append("Address prior counter-arguments in reasoning");
        }

        if "uncertain_areas" in self.confidence_history {
            if len(self.confidence_history["uncertain_areas"]) > 0 {
                recommendations.append("Focus on gathering evidence for uncertain areas");
            }
        }

        return recommendations;
    }

    def retrieve_memory(depth: int = 1) {
        print(f"[MEMORY] Starting memory traversal (depth={depth})...");

        # Execute memory operations
        self.search_related_topics();
        self.traverse_prior_claims();
        self.retrieve_counter_arguments();
        self.find_confidence_history();

        context = self.aggregate_memory_context();

        print(f"[MEMORY] Found {context['related_memories_count']} related memories");
        print(f"[MEMORY] Prior claims: {len(context['prior_claims'])}");
        print(f"[MEMORY] Prior counter-claims: {len(context['prior_counter_claims'])}");
        print(f"[MEMORY] Recommendations: {len(context['recommendations'])}");

        for rec in context['recommendations'] {
            print(f"  - {rec}");
        }
    }
}

"""
TruthForge AI - Memory Update Walker
Persists complete reasoning cycle to database
Updates SQLite with all debate artifacts
"""

import from truthforge_nodes { * }
import from truthforge_config { * }

walker MemoryUpdateWalker {
    has session_id: str = "";
    has question_id: str = "";
    has question_text: str = "";
    has debate_complexity: str = "unknown";
    has thesis_claims: list[dict] = [];
    has counter_claims: list[dict] = [];
    has evidence_nodes: list[dict] = [];
    has verdict: dict = {};
    has synthesis_result: dict = {};
    has agents_executed: list[str] = [];

    def store_question() {
        print("[MEMORY_UPDATE] Storing question...");

        # In production: Store to questions table
        # question table schema:
        # id, text, complexity, domain, subtopics, created_at
    }

    def store_claims() {
        print(f"[MEMORY_UPDATE] Storing {len(self.thesis_claims)} claims...");

        # For each thesis claim, would store to claims table:
        # id, debate_id, statement, strength, reasoning, key_points, assumptions

        for (i, claim) in enumerate(self.thesis_claims) {
            print(f"  Storing claim {i+1}: {claim.get('statement', 'claim')[:50]}...");
        }
    }

    def store_counter_claims() {
        print(f"[MEMORY_UPDATE] Storing {len(self.counter_claims)} counter-claims...");

        # For each counter-claim, store to counter_claims table:
        # id, debate_id, statement, strength, reasoning, key_points, assumptions

        for (i, claim) in enumerate(self.counter_claims) {
            print(f"  Storing counter-claim {i+1}: {claim.get('statement', 'claim')[:50]}...");
        }
    }

    def store_evidence() {
        print(f"[MEMORY_UPDATE] Storing {len(self.evidence_nodes)} evidence nodes...");

        # For each evidence node, store to evidence table:
        # id, debate_id, content, source, credibility_score, evidence_type, date_published, retrieval_method

        for (i, evidence) in enumerate(self.evidence_nodes) {
            print(f"  Storing evidence {i+1}: {evidence.get('evidence_type', 'general')} from {evidence.get('source', 'unknown')[:30]}");
        }
    }

    def store_verdict() {
        print("[MEMORY_UPDATE] Storing verdict...");

        # Store to verdicts table:
        # id, debate_id, evaluation, logic_quality_score, evidence_strength_score, 
        # assumption_validity, overall_confidence, key_findings, reasoning_quality

        print(f"  Verdict: {self.verdict.get('evaluation', 'Not evaluated')[:50]}");
        print(f"  Overall Confidence: {self.verdict.get('overall_confidence', 0):.2f}");
    }

    def store_reasoning() {
        print("[MEMORY_UPDATE] Storing synthesis result...");

        # Store to reasonings table:
        # id, debate_id, analysis, supporting_signals, counterarguments, 
        # confidence, final_answer, reasoning_chain

        print(f"  Analysis: {len(self.synthesis_result.get('analysis', ''))} characters");
        print(f"  Supporting signals: {len(self.synthesis_result.get('supporting_signals', []))}");
        print(f"  Counterarguments: {len(self.synthesis_result.get('counterarguments', []))}");
    }

    def create_relationships() {
        print("[MEMORY_UPDATE] Creating relationships...");

        relationships_created = 0;

        # supports relationships: evidence -> claims
        for evidence in self.evidence_nodes {
            for claim in self.thesis_claims {
                # Store: source=evidence, target=claim, relation_type="supports"
                relationships_created += 1;
            }
        }

        # attacks relationships: counter_claims -> claims
        for counter in self.counter_claims {
            for claim in self.thesis_claims {
                # Store: source=counter, target=claim, relation_type="attacks"
                relationships_created += 1;
            }
        }

        # discussed_in relationships: all nodes -> debate_session
        for claim in self.thesis_claims {
            # Store: source=claim, target=debate_session, relation_type="discussed_in"
            relationships_created += 1;
        }

        print(f"  Created {relationships_created} relationships");
    }

    def update_debate_session() {
        print("[MEMORY_UPDATE] Updating debate session status...");

        # Update debates table:
        # Set status='completed', agents_activated, total_stages

        print(f"  Session {self.session_id}: pending -> completed");
        print(f"  Agents executed: {', '.join(self.agents_executed)}");
        print(f"  Complexity: {self.debate_complexity}");
    }

    def create_memory_snapshot() {
        print("[MEMORY_UPDATE] Creating memory snapshot...");

        # Create entry for memory_entries table:
        # question, summary, claims, counter_claims, verdict, confidence, timestamp, relevance_score

        summary = f"Debate on '{self.question_text[:50]}...': ";
        summary += f"{len(self.thesis_claims)} supporting claims vs ";
        summary += f"{len(self.counter_claims)} counter-claims";

        print(f"  Snapshot: {summary}");
    }

    def validate_persistence() -> bool {
        print("[MEMORY_UPDATE] Validating persistence...");

        validation_passed = True;

        if len(self.thesis_claims) == 0 {
            print("  ⚠ Warning: No thesis claims stored");
            validation_passed = False;
        }

        if len(self.counter_claims) == 0 {
            print("  ⚠ Warning: No counter-claims stored");
            validation_passed = False;
        }

        if self.verdict.get("overall_confidence", 0) == 0 {
            print("  ⚠ Warning: No verdict stored");
            validation_passed = False;
        }

        if validation_passed {
            print("  ✓ All data validated and persisted");
        }

        return validation_passed;
    }

    def persist(
        session_id: str,
        question_id: str,
        question_text: str,
        complexity: str,
        thesis_claims: list[dict],
        counter_claims: list[dict],
        evidence_nodes: list[dict],
        verdict: dict,
        synthesis_result: dict,
        agents_executed: list[str]
    ) -> dict {
        self.session_id = session_id;
        self.question_id = question_id;
        self.question_text = question_text;
        self.debate_complexity = complexity;
        self.thesis_claims = thesis_claims;
        self.counter_claims = counter_claims;
        self.evidence_nodes = evidence_nodes;
        self.verdict = verdict;
        self.synthesis_result = synthesis_result;
        self.agents_executed = agents_executed;

        print("[MEMORY_UPDATE] ===== MEMORY UPDATE WALKER STARTING =====");

        # Execute persistence operations
        self.store_question();
        self.store_claims();
        self.store_counter_claims();
        self.store_evidence();
        self.store_verdict();
        self.store_reasoning();
        self.create_relationships();
        self.update_debate_session();
        self.create_memory_snapshot();

        # Validate persistence
        validated = self.validate_persistence();

        print("[MEMORY_UPDATE] ===== MEMORY UPDATE WALKER COMPLETE =====");

        return {
            "session_id": session_id,
            "persistence_validated": validated,
            "stored_claims": len(thesis_claims),
            "stored_counter_claims": len(counter_claims),
            "stored_evidence": len(evidence_nodes),
            "timestamp": "current_timestamp"
        };
    }
}

"""
TruthForge AI - Core Node Definitions
Defines all node types for the debate and reasoning graph
"""

# Base node for all debate participants
node BaseNode {
    has id: str;
    has created_at: str;
    has metadata: dict = {};
}

# Question node - represents the user's question/topic
node Question(BaseNode) {
    has text: str;
    has complexity: float = 0.0;  # Estimated by PlannerWalker
    has domain: str = "";         # Topic domain (science, politics, ethics, etc.)
    has subtopics: list[str] = [];
    has estimated_agents_needed: list[str] = [];
}

# Topic node - extracted main topic from question
node Topic(BaseNode) {
    has name: str;
    has category: str;
    has description: str = "";
    has related_topics: list[str] = [];
    has confidence: float = 0.0;
}

# Claim node - a supporting thesis position
node Claim(BaseNode) {
    has statement: str;
    has strength: float = 0.0;    # How strong is this claim (0-1)
    has reasoning: str = "";
    has key_points: list[str] = [];
    has assumptions: list[str] = [];
    has supporting_count: int = 0;
}

# CounterClaim node - attacks thesis claims
node CounterClaim(BaseNode) {
    has statement: str;
    has strength: float = 0.0;
    has reasoning: str = "";
    has key_points: list[str] = [];
    has assumptions: list[str] = [];
    has attacks_count: int = 0;
}

# Evidence node - supporting data/facts
node Evidence(BaseNode) {
    has content: str;
    has source: str = "";
    has credibility_score: float = 0.0;  # 0-1 scale
    has evidence_type: str = "";         # "statistical", "logical", "empirical", "anecdotal"
    has date_published: str = "";
    has retrieval_method: str = "";      # "web_search", "api", "knowledge_base"
}

# Verdict node - referee's evaluation
node Verdict(BaseNode) {
    has evaluation: str;
    has logic_quality_score: float = 0.0;      # 0-1
    has evidence_strength_score: float = 0.0;   # 0-1
    has assumption_validity: float = 0.0;       # 0-1
    has overall_confidence: float = 0.0;        # 0-1
    has key_findings: list[str] = [];
    has reasoning_quality: str = "";
}

# DebateSession node - container for complete reasoning cycle
node DebateSession(BaseNode) {
    has session_id: str;
    has question_id: str;
    has status: str = "pending";           # pending, in_progress, completed
    has complexity_level: str = "unknown"; # simple, moderate, complex
    has agents_activated: list[str] = [];
    has stage: int = 0;                    # Current stage of debate
    has total_stages: int = 0;
}

# PlanStep node - represents planning decision
node PlanStep(BaseNode) {
    has step_number: int;
    has agent_name: str;
    has reason: str = "";
    has priority: float = 0.0;
    has dependencies: list[str] = [];
}

# MemoryEntry node - stored reasoning from prior sessions
node MemoryEntry(BaseNode) {
    has question: str;
    has summary: str;
    has claims: list[str] = [];
    has counter_claims: list[str] = [];
    has verdict: str = "";
    has confidence: float = 0.0;
    has timestamp: str = "";
    has relevance_score: float = 0.0;
}

# SynthesisResult node - final output
node SynthesisResult(BaseNode) {
    has analysis: str;
    has supporting_signals: list[str] = [];
    has counterarguments: list[str] = [];
    has confidence: str = "";
    has final_answer: str = "";
    has reasoning_chain: list[str] = [];
}

# MemoryRecord alias for backward compatibility
node MemoryRecord(MemoryEntry) {
}

"""
TruthForge AI - Planner Walker
Classifies question type and dynamically decides which agents to activate.
Question types: factual, prediction, controversial, strategic, philosophical
"""

import from truthforge_nodes { * }
import from truthforge_config { * }

walker PlannerWalker {
    has question_text: str = "";
    has question_type: str = "factual";
    has complexity_score: float = 0.0;
    has domain: str = "general";
    has agents_to_activate: list[str] = [];
    has plan_steps: list[dict] = [];

    def classify_question_type() {
        q = self.question_text.lower();

        # Prediction indicators
        prediction_signals = ["will", "going to", "forecast", "predict", "future", "2025", "2026", "2027", "next year", "outlook"];
        for signal in prediction_signals {
            if signal in q {
                self.question_type = "prediction";
                return;
            }
        }

        # Controversial indicators
        controversial_signals = ["should", "ethical", "moral", "right or wrong", "debate", "controversial", "opinion", "disagree"];
        for signal in controversial_signals {
            if signal in q {
                self.question_type = "controversial";
                return;
            }
        }

        # Strategic indicators
        strategic_signals = ["strategy", "best approach", "how to", "optimize", "decision", "trade-off", "invest", "choose"];
        for signal in strategic_signals {
            if signal in q {
                self.question_type = "strategic";
                return;
            }
        }

        # Philosophical indicators
        philosophical_signals = ["meaning", "existence", "consciousness", "free will", "purpose", "reality", "truth"];
        for signal in philosophical_signals {
            if signal in q {
                self.question_type = "philosophical";
                return;
            }
        }

        # Default to factual
        self.question_type = "factual";
    }

    def analyze_complexity() {
        complexity = 0.3;
        q = self.question_text.lower();

        # Multi-dimensional questions are more complex
        complexity_signals = ["why", "how", "what if", "compare", "versus", "implications", "consequences"];
        for signal in complexity_signals {
            if signal in q {
                complexity += 0.12;
            }
        }

        # Longer questions tend to be more complex
        word_count = len(self.question_text.split());
        if word_count > 15 {
            complexity += 0.1;
        }
        if word_count > 30 {
            complexity += 0.1;
        }

        # Certain question types are inherently more complex
        if self.question_type in ["controversial", "philosophical"] {
            complexity += 0.15;
        }
        elif self.question_type == "prediction" {
            complexity += 0.10;
        }

        self.complexity_score = min(complexity, 1.0);
    }

    def detect_domain() -> str {
        q = self.question_text.lower();

        domain_map = {
            "economics": ["rate", "inflation", "gdp", "economy", "market", "price", "trade", "finance", "bank", "debt", "deficit", "monetary"],
            "technology": ["ai", "software", "code", "tech", "digital", "computer", "algorithm", "machine learning", "quantum"],
            "science": ["physics", "biology", "chemistry", "research", "experiment", "climate", "evolution"],
            "politics": ["government", "policy", "political", "election", "law", "regulation", "democracy"],
            "ethics": ["moral", "ethics", "right", "wrong", "value", "principle", "justice"],
            "philosophy": ["philosophy", "existence", "being", "knowledge", "truth", "meaning", "consciousness"],
            "health": ["health", "medical", "disease", "treatment", "vaccine", "mental health", "nutrition"]
        };

        for (domain, keywords) in domain_map.items() {
            for keyword in keywords {
                if keyword in q {
                    self.domain = domain;
                    return domain;
                }
            }
        }

        self.domain = "general";
        return "general";
    }

    def determine_agents_needed() {
        # Always include these core agents
        self.agents_to_activate = ["thesis", "antithesis", "referee", "synthesis", "memory_update"];

        # Add memory for non-trivial questions
        if self.complexity_score >= 0.3 or self.question_type != "factual" {
            self.agents_to_activate.insert(0, "memory");
        }

        # Add evidence for prediction, controversial, and complex questions
        if self.question_type in ["prediction", "controversial", "strategic"] or self.complexity_score >= 0.5 {
            # Insert evidence after antithesis
            idx = self.agents_to_activate.index("referee");
            self.agents_to_activate.insert(idx, "evidence");
        }
    }

    def create_execution_plan() {
        step_number = 1;

        for agent in self.agents_to_activate {
            reason = "";
            if agent == "memory" {
                reason = "Retrieve related prior reasoning from database";
            }
            elif agent == "thesis" {
                reason = "Generate 2-4 concrete supporting claims via Gemini";
            }
            elif agent == "antithesis" {
                reason = "Attack each thesis claim individually via Gemini";
            }
            elif agent == "evidence" {
                reason = "Gather structured evidence with sources via Gemini";
            }
            elif agent == "referee" {
                reason = "Score logic_strength, evidence_strength, assumption_risk, agreement_level";
            }
            elif agent == "synthesis" {
                reason = "Generate structured final analysis: Analysis → Supporting Factors → Counterarguments → Final Answer";
            }
            elif agent == "memory_update" {
                reason = "Persist all reasoning artifacts to database";
            }

            self.plan_steps.append({
                "step": step_number,
                "agent": agent,
                "reason": reason,
                "priority": 1.0 - (step_number * 0.05)
            });
            step_number += 1;
        }
    }

    def orchestrate() {
        print(f"[PLANNER] Analyzing question: {self.question_text[:60]}...");

        self.classify_question_type();
        self.analyze_complexity();
        self.detect_domain();
        self.determine_agents_needed();
        self.create_execution_plan();

        print(f"[PLANNER] Question Type: {self.question_type}");
        print(f"[PLANNER] Complexity: {self.complexity_score:.2f}");
        print(f"[PLANNER] Domain: {self.domain}");
        print(f"[PLANNER] Agents: {', '.join(self.agents_to_activate)}");

        for step in self.plan_steps {
            print(f"  Step {step['step']}: {step['agent']} - {step['reason']}");
        }
    }
}

"""
TruthForge AI - Referee Walker
Evaluates debate quality with real scores derived from actual agent outputs.
Scores: logic_strength, evidence_strength, assumption_risk, agreement_level
"""

import from truthforge_nodes { * }
import from truthforge_config { * }

walker RefereeWalker {
    has thesis_claims: list[dict] = [];
    has counter_claims: list[dict] = [];
    has evidence_nodes: list[dict] = [];
    has verdict: dict = {};
    has session_id: str = "";

    def evaluate_debate() {
        print("[REFEREE] ===== REFEREE WALKER STARTING =====");
        print(f"[REFEREE] Evaluating {len(self.thesis_claims)} claims vs {len(self.counter_claims)} counter-claims");
        print(f"[REFEREE] Evidence pieces: {len(self.evidence_nodes)}");

        # Verdict is populated by Gemini API call in TypeScript layer.

        if len(self.verdict.keys()) > 0 {
            print(f"[REFEREE] Logic Strength: {self.verdict.get('logic_strength', 0):.2f}");
            print(f"[REFEREE] Evidence Strength: {self.verdict.get('evidence_strength', 0):.2f}");
            print(f"[REFEREE] Assumption Risk: {self.verdict.get('assumption_risk', 0):.2f}");
            print(f"[REFEREE] Agreement Level: {self.verdict.get('agreement_level', 0):.2f}");
            print(f"[REFEREE] Stronger Position: {self.verdict.get('stronger_position', 'balanced')}");

            findings = self.verdict.get("key_findings", []);
            if len(findings) > 0 {
                print("[REFEREE] Key Findings:");
                for finding in findings {
                    print(f"  - {finding}");
                }
            }

            print(f"[REFEREE] Reasoning: {self.verdict.get('reasoning', '')[:100]}");
        }

        print("[REFEREE] ===== REFEREE WALKER COMPLETE =====");
    }

    def evaluate(
        thesis_claims: list[dict],
        counter_claims: list[dict],
        evidence_nodes: list[dict],
        session_id: str = ""
    ) -> dict {
        self.thesis_claims = thesis_claims;
        self.counter_claims = counter_claims;
        self.evidence_nodes = evidence_nodes;
        self.session_id = session_id;

        self.evaluate_debate();

        return self.verdict;
    }
}

"""
TruthForge AI - Synthesis Walker
Generates the final structured output shown to the user.
Output format: Analysis → Perspective Exploration → Supporting Factors →
               Counterarguments → Historical Context → Confidence Assessment → Final Answer

NEVER uses template phrases like "The evidence suggests X and Y are interconnected"
"""

import from truthforge_nodes { * }
import from truthforge_config { * }

walker SynthesisWalker {
    has question_text: str = "";
    has question_type: str = "factual";
    has thesis_claims: list[dict] = [];
    has counter_claims: list[dict] = [];
    has evidence_nodes: list[dict] = [];
    has verdict: dict = {};
    has session_id: str = "";

    def build_synthesis() -> dict {
        print("[SYNTHESIS] Building structured final analysis...");
        print(f"[SYNTHESIS] Question: {self.question_text[:50]}...");
        print(f"[SYNTHESIS] Integrating {len(self.thesis_claims)} claims, {len(self.counter_claims)} counter-claims, {len(self.evidence_nodes)} evidence items");

        # Synthesis result is populated by Gemini API call in TypeScript layer.
        # The result dict will contain all sections listed above.

        return {};
    }

    def render_synthesis(result: dict) {
        print("[SYNTHESIS] ===== FINAL SYNTHESIS =====");

        if "analysis" in result {
            print(f"\nANALYSIS:\n{result['analysis']}");
        }

        if "perspective_exploration" in result and result["perspective_exploration"] != "" {
            print(f"\nPERSPECTIVE EXPLORATION:\n{result['perspective_exploration']}");
        }

        if "supporting_factors" in result {
            print("\nSUPPORTING FACTORS:");
            for factor in result["supporting_factors"] {
                print(f"  ✓ {factor}");
            }
        }

        if "counterarguments" in result {
            print("\nCOUNTERARGUMENTS:");
            for counter in result["counterarguments"] {
                print(f"  ✗ {counter}");
            }
        }

        if "historical_context" in result and result["historical_context"] != "" {
            print(f"\nHISTORICAL CONTEXT:\n{result['historical_context']}");
        }

        if "confidence_assessment" in result and result["confidence_assessment"] != "" {
            print(f"\nCONFIDENCE ASSESSMENT:\n{result['confidence_assessment']}");
        }

        if "final_answer" in result {
            print(f"\nFINAL ANSWER:\n{result['final_answer']}");
        }

        print(f"\nCONFIDENCE: {result.get('confidence', 'Moderate')}");
        print("[SYNTHESIS] ===== END SYNTHESIS =====");
    }

    def synthesize(
        question_text: str,
        thesis_claims: list[dict],
        counter_claims: list[dict],
        evidence_nodes: list[dict],
        verdict: dict,
        session_id: str = ""
    ) -> dict {
        self.question_text = question_text;
        self.thesis_claims = thesis_claims;
        self.counter_claims = counter_claims;
        self.evidence_nodes = evidence_nodes;
        self.verdict = verdict;
        self.session_id = session_id;

        print("[SYNTHESIS] ===== SYNTHESIS WALKER STARTING =====");

        result = self.build_synthesis();
        self.render_synthesis(result);

        print("[SYNTHESIS] ===== SYNTHESIS WALKER COMPLETE =====");

        return result;
    }
}

"""
TruthForge AI - Thesis Walker
Generates 2-4 CONCRETE supporting claims from the question.
All claims come from Gemini API — no hardcoded placeholders.
"""

import from truthforge_nodes { * }
import from truthforge_config { * }

walker ThesisWalker {
    has question_text: str = "";
    has question_type: str = "factual";
    has domain: str = "general";
    has memory_context: str = "";
    has generated_claims: list[dict] = [];
    has session_id: str = "";

    def generate_claims() {
        print(f"[THESIS] Generating concrete claims for: {self.question_text[:50]}...");
        print(f"[THESIS] Question type: {self.question_type}, Domain: {self.domain}");

        # Claims are populated by Gemini API call in TypeScript layer.
        # Each claim has: statement, reasoning, strength
        # The prompt demands specificity and forbids template language.

        print(f"[THESIS] Generated {len(self.generated_claims)} claims");
        for (i, claim) in enumerate(self.generated_claims) {
            print(f"  Claim {i+1}: {claim.get('statement', '')[:80]}...");
            print(f"    Reasoning: {claim.get('reasoning', '')[:60]}");
            print(f"    Strength: {claim.get('strength', 0):.2f}");
        }
    }

    def synthesize_thesis() -> dict {
        return {
            "total_claims": len(self.generated_claims),
            "claims": self.generated_claims,
            "primary_claim": self.generated_claims[0] if len(self.generated_claims) > 0 else {},
            "supporting_claims": self.generated_claims[1:] if len(self.generated_claims) > 1 else []
        };
    }

    def generate_thesis(session_id: str = "") -> dict {
        self.session_id = session_id;

        print("[THESIS] ===== THESIS WALKER STARTING =====");

        self.generate_claims();
        result = self.synthesize_thesis();

        print(f"[THESIS] Total claims: {result['total_claims']}");
        print("[THESIS] ===== THESIS WALKER COMPLETE =====");

        return result;
    }
}

"""Veritas — Agentic fact checker."""

node Claim {
    has text: str;
    has status: str = "unverified";
    has confidence: float = 0.0;
    has evidence_log: list = [];
}

node Evidence {
    has url: str;
    has snippet: str;
    has supports: bool = False;
    has confidence: float = 0.0;
    has credibility: float = 0.5;
}

node Task {
    has query: str;
    has step: str;
    has done: bool = False;
}

node Verdict {
    has summary: str;
    has confidence: float;
    has reasoning: str;
}

edge Supports { has strength: float; }
edge Contradicts { has severity: float; }
edge Discovered { has search_term: str; }
edge Requires {}

def decompose_claim(claim_text: str) -> list[str] by llm();
sem decompose_claim = "Break claim into 2-3 search queries. Return JSON list.";
sem decompose_claim.claim_text = "Claim to verify.";

def assess_evidence(snippet: str, claim: str) -> str by llm();
sem assess_evidence = "Return JSON: {supports: bool, confidence: float}.";
sem assess_evidence.snippet = "Web text.";
sem assess_evidence.claim = "Claim being checked.";

def assess_credibility(snippet: str, url: str) -> float by llm();
sem assess_credibility = "Rate 0.0-1.0. Return float only.";
sem assess_credibility.snippet = "Web text.";
sem assess_credibility.url = "Source URL.";

def synthesize_verdict(claim: str, evidence_list: list) -> str by llm();
sem synthesize_verdict = "Return JSON: {summary: str, confidence: float, reasoning: str}.";
sem synthesize_verdict.claim = "Original claim.";
sem synthesize_verdict.evidence_list = "Evidence list.";

walker:pub Investigator {
    has max_results: int = 3;
    has target_claim: Claim | None = None;

    can investigate with Task entry {
        claim_node: Claim | None = self.target_claim;
        if not claim_node {
            here.done = True;
            disengage;
        }

        import json;
        import duckduckgo_search;
        ddgs = duckduckgo_search.DDGS();
        results = ddgs.text(here.query, max_results=self.max_results);

        for r in results {
            cred = assess_credibility(r["body"], r["href"]);
            assessment = json.loads(assess_evidence(r["body"], claim_node.text));

            ev = Evidence(
                url=r["href"],
                snippet=r["body"][:200],
                supports=bool(assessment["supports"]),
                confidence=float(assessment["confidence"]),
                credibility=cred
            );

            here +>: Discovered(search_term=here.query) :+> ev;

            if assessment["supports"] {
                ev +>: Supports(strength=cred) :+> claim_node;
                claim_node.confidence += float(assessment["confidence"]) * cred;
            } else {
                ev +>: Contradicts(severity=1.0 - cred) :+> claim_node;
                claim_node.confidence -= float(assessment["confidence"]) * cred;
            }

            claim_node.evidence_log.append({
                "url": r["href"],
                "snippet": r["body"][:200],
                "supports": assessment["supports"],
                "confidence": assessment["confidence"],
                "credibility": str(cred)
            });
        }

        here.done = True;
    }
}

walker:pub VerdictAgent {
    can judge with Claim entry {
        import json;
        ev_list = here.evidence_log;

        result = json.loads(synthesize_verdict(here.text, ev_list));

        v = Verdict(
            summary=result["summary"],
            confidence=float(result["confidence"]),
            reasoning=result["reasoning"]
        );

        here ++> v;
        here.status = "verified";

        report v;
    }
}

walker:pub VerifyClaim {
    has claim_text: str;
    has max_results: int = 3;

    can verify with entry {
        import json;
        report {"probe": "walker_started"};

        try {
            c = Claim(text=self.claim_text);
            root ++> c;
            report {"probe": "claim_created", "claim_text": self.claim_text};

            queries = decompose_claim(self.claim_text);
            if not queries {
                queries = [self.claim_text];
            }

            import ddgs;

            for q in queries {
                t = Task(query=q, step="search", done=False);
                c +>: Requires() :+> t;
                evidence_count = 0;

                try {
                    searcher = ddgs.DDGS();
                    results = list(searcher.text(q, max_results=self.max_results));
                    report {"probe": "search_results", "query": q, "count": len(results)};

                    for r in results {
                        try {
                            url: str = str(r.get("href") or r.get("link") or "");
                            snippet: str = str(r.get("body") or r.get("snippet") or "");

                            if not snippet {
                                continue;
                            }

                            cred = assess_credibility(snippet, url);
                            assessment = json.loads(assess_evidence(snippet, self.claim_text));

                            ev = Evidence(
                                url=str(url),
                                snippet=str(snippet[:200]),
                                supports=bool(assessment["supports"]),
                                confidence=float(assessment["confidence"]),
                                credibility=float(cred)
                            );

                            t +>: Discovered(search_term=q) :+> ev;

                            if assessment["supports"] {
                                ev +>: Supports(strength=cred) :+> c;
                            } else {
                                ev +>: Contradicts(severity=1.0 - cred) :+> c;
                            }

                            c.evidence_log.append({
                                "url": url,
                                "snippet": snippet[:200],
                                "supports": assessment["supports"],
                                "confidence": assessment["confidence"],
                                "credibility": str(cred)
                            });

                            evidence_count += 1;
                        } except Exception as result_err {
                            report {"probe": "result_error", "query": q, "error": str(result_err)};
                        }
                    }
                    t.done = True;
                } except Exception as search_err {
                    report {"probe": "search_error", "query": q, "error": str(search_err)};
                }

                report {"probe": "investigator_run", "query": q, "evidence_count": evidence_count};
            }

            if not c.evidence_log {
                report {"probe": "no_evidence", "claim": self.claim_text};
                disengage;
            }

            result = json.loads(synthesize_verdict(self.claim_text, c.evidence_log));
            report {"probe": "verdict_spawned"};

            c.status = "verified";
            c.confidence = float(result["confidence"]);
            report {"probe": "verdict_collected", "verdict": result};

            report {
                "summary": result["summary"],
                "confidence": result["confidence"],
                "reasoning": result["reasoning"],
                "evidence": c.evidence_log
            };
            report {"probe": "walker_finished"};
        } except Exception as e {
            report {"probe": "outer_exception", "error": str(e)};
        }
    }
}

