"""HIPAA compliance guards for PHI access and audit logging."""

import from datetime { datetime }
import from os { environ }

# PHI field names that require audit logging on access
glob PHI_FIELDS: list[str] = [
    "name", "dob", "medicare_id", "medicaid_id", "ssn",
    "address", "phone", "email", "diagnosis_codes", "icd_codes",
    "cpt_codes", "raw_content", "extracted_text", "letter_content",
    "account_number", "routing_number", "plaid_access_token"
];

# Audit log storage (in production, write to secure append-only store)
glob _audit_log: list[dict] = [];

"""Log PHI access for HIPAA compliance audit trail."""
def audit_phi_access(user_id: str, patient_id: str, action: str, fields: list[str]) -> None {
    `entry = {
        "timestamp": datetime.utcnow().isoformat(),
        "user_id": user_id,
        "patient_id": patient_id,
        "action": action,
        "fields_accessed": fields,
        "environment": environ.get("APP_ENV", "development")
    };
    _audit_log.append(`entry);
    if environ.get("APP_ENV") != "development" {
        print(f"[HIPAA_AUDIT] {action} on patient {patient_id} by {user_id}: {fields}");
    }
}

"""Mask PHI values for logging and display."""
def mask_phi(value: str, field_name: str) -> str {
    if field_name in ["ssn"] {
        return f"***-**-{value[-4:]}" if len(value) >= 4 else "***";
    }
    if field_name in ["medicare_id", "medicaid_id"] {
        return f"****{value[-4:]}" if len(value) >= 4 else "****";
    }
    if field_name in ["account_number", "routing_number"] {
        return f"****{value[-4:]}" if len(value) >= 4 else "****";
    }
    if field_name == "dob" {
        # Show only year
        return value[:4] + "-**-**" if len(value) >= 4 else "****-**-**";
    }
    return value;
}

"""Retrieve audit log entries, optionally filtered by patient."""
def get_audit_log(patient_id: str = "") -> list[dict] {
    if patient_id == "" {
        return _audit_log;
    }
    return [e for e in _audit_log if e["patient_id"] == patient_id];
}

"""Filter requested fields to minimum necessary for stated purpose."""
def check_minimum_necessary(fields_requested: list[str], purpose: str) -> list[str] {
    purpose_field_map = {
        "billing_audit": ["name", "medicare_id", "dob"],
        "appeal": ["name", "medicare_id", "dob", "diagnosis_codes", "cpt_codes"],
        "notification": ["name", "phone", "email"],
        "financial_review": ["name", "account_number"],
        "full_record": PHI_FIELDS
    };
    allowed = purpose_field_map.get(purpose, []);
    return [f for f in fields_requested if f in allowed];
}

"""Permission checks for AgeWise operations."""

import from auth.roles { ROLES, ROLE_HIERARCHY }

# Permission action constants
glob PERM_VIEW_CLAIMS: str = "view_claims";
glob PERM_VIEW_DISPUTES: str = "view_disputes";
glob PERM_CREATE_DISPUTE: str = "create_dispute";
glob PERM_SUBMIT_APPEAL: str = "submit_appeal";
glob PERM_VIEW_FINANCIAL: str = "view_financial";
glob PERM_VIEW_LEGAL: str = "view_legal";
glob PERM_INITIATE_CALL: str = "initiate_call";
glob PERM_VIEW_NOTIFICATIONS: str = "view_notifications";
glob PERM_MANAGE_USERS: str = "manage_users";
glob PERM_EXPORT_DATA: str = "export_data";

"""Check if a role has permission to perform an action."""
def has_permission(role: str, action: str) -> bool {
    if role == "ADMIN" {
        return True;
    }
    role_config = ROLES.get(role, {});
    if role_config.get("all_permissions", False) {
        return True;
    }
    # Map actions to role fields
    action_map = {
        PERM_VIEW_CLAIMS: "can_view_own_data",
        PERM_VIEW_DISPUTES: "can_view_own_data",
        PERM_CREATE_DISPUTE: "can_view_own_data",
        PERM_SUBMIT_APPEAL: "can_approve_appeals",
        PERM_VIEW_FINANCIAL: "can_view_financial",
        PERM_VIEW_LEGAL: "can_view_legal",
        PERM_INITIATE_CALL: "can_initiate_calls",
        PERM_VIEW_NOTIFICATIONS: "can_view_own_data",
        PERM_MANAGE_USERS: "all_permissions",
        PERM_EXPORT_DATA: "can_approve_appeals"
    };
    field = action_map.get(action, "");
    if field == "" {
        return False;
    }
    return role_config.get(field, False);
}

"""Raise ValueError if role lacks permission."""
def require_permission(role: str, action: str) -> None {
    if not has_permission(role, action) {
        raise ValueError(f"Role '{role}' does not have permission '{action}'");
    }
}

"""Session management for AgeWise user sessions."""

import from datetime { datetime, timedelta }
import from uuid { uuid4 }

# Session store (in production, use Redis or DB)
glob _sessions: dict = {};

# Session timeout in minutes
glob SESSION_TIMEOUT_MINUTES: int = 30;
glob EXTENDED_TIMEOUT_MINUTES: int = 480;  # 8 hours for caregivers

"""Create a new session and return the session token."""
def create_session(user_id: str, role: str, patient_id: str, extended: bool = False) -> str {
    token = str(uuid4());
    timeout = EXTENDED_TIMEOUT_MINUTES if extended else SESSION_TIMEOUT_MINUTES;
    _sessions[token] = {
        "user_id": user_id,
        "role": role,
        "patient_id": patient_id,
        "created_at": datetime.utcnow().isoformat(),
        "expires_at": (datetime.utcnow() + timedelta(minutes=timeout)).isoformat(),
        "last_activity": datetime.utcnow().isoformat()
    };
    return token;
}

"""Validate a session token and return session data or empty dict."""
def validate_session(token: str) -> dict {
    session = _sessions.get(token, {});
    if not session {
        return {};
    }
    expiry = datetime.fromisoformat(session["expires_at"]);
    if datetime.utcnow() > expiry {
        del _sessions[token];
        return {};
    }
    # Refresh last activity
    session["last_activity"] = datetime.utcnow().isoformat();
    return session;
}

"""Invalidate (logout) a session."""
def invalidate_session(token: str) -> None {
    if token in _sessions {
        del _sessions[token];
    }
}

"""Return all active sessions for a user."""
def get_active_sessions(user_id: str) -> list[dict] {
    now = datetime.utcnow();
    return [
        s for s in _sessions.values()
        if s["user_id"] == user_id and datetime.fromisoformat(s["expires_at"]) > now
    ];
}

"""Invalidate all sessions for a user. Returns count removed."""
def invalidate_all_sessions(user_id: str) -> int {
    tokens_to_remove = [t for (t, s) in _sessions.items() if s["user_id"] == user_id];
    for t in tokens_to_remove {
        del _sessions[t];
    }
    return len(tokens_to_remove);
}

