"""SubscriptionIdentifier walker — identifies recurring charges and creates subscription nodes."""

import from graph.nodes.patient { Patient }
import from graph.nodes.transaction { Transaction }
import from graph.nodes.financial_account { FinancialAccount }
import from graph.nodes.subscription { Subscription }
import from datetime { datetime }
import from uuid { uuid4 }

walker SubscriptionIdentifier {
    has subscriptions_found: int = 0,
        min_occurrences: int = 2;

    can identify with Patient entry {
        merchant_charges: dict = {};
        existing_subs = {n.merchant_id for n in [here-->] if isinstance(n, Subscription)};

        for acct in [here-->] {
            if not isinstance(acct, FinancialAccount) {
                continue;
            }
            for txn in [acct-->] {
                if not isinstance(txn, Transaction) or txn.amount >= 0 {
                    continue;
                }
                key = txn.merchant_name.strip().lower();
                if key not in merchant_charges {
                    merchant_charges[key] = [];
                }
                merchant_charges[key].append({"date": txn.date, "amount": abs(txn.amount)});
            }
        }

        for (merchant, charges) in merchant_charges.items() {
            if len(charges) < self.min_occurrences {
                continue;
            }
            merchant_id = merchant.replace(" ", "_")[:32];
            if merchant_id in existing_subs {
                continue;
            }
            avg_cost = sum(c["amount"] for c in charges) / len(charges);
            sub = Subscription(
                subscription_id=str(uuid4()),
                service_name=merchant.title(),
                merchant_id=merchant_id,
                monthly_cost=avg_cost,
                annual_cost=avg_cost * 12,
                classification="UNKNOWN",
                first_seen_date=min(c["date"] for c in charges),
                last_charge_date=max(c["date"] for c in charges),
                created_at=datetime.utcnow().isoformat()
            );
            here ++> sub;
            existing_subs.add(merchant_id);
            self.subscriptions_found += 1;
        }

        report {"patient": here.name, "subscriptions_found": self.subscriptions_found};
    }
}

"""SubscriptionReviewer walker — identifies unused/duplicate subscriptions to cancel."""

import from graph.nodes.patient { Patient }
import from graph.nodes.subscription { Subscription }
import from graph.nodes.notification { Notification }
import from abilities.llm_abilities { assess_subscription_utility }

import from datetime { datetime }
import from uuid { uuid4 }

glob REVIEW_AGE_DAYS: int = 90;  # Flag subscriptions unused for 90+ days

walker SubscriptionReviewer {
    has patient_name: str = "";
    has flagged: int = 0;


    can start with Patient entry {
        self.patient_name = here.name;
        self.flagged = 0;
        visit [-->];
    }

    can review with Subscription entry {
        if here.status != "ACTIVE" {
            disengage;
        }

        should_flag = False;
        reason = "";

        # Check if unused
        if not here.is_used and here.monthly_cost > 0 {
            should_flag = True;
            reason = f"Subscription '{here.service_name}' (${here.monthly_cost:.2f}/mo) may be unused.";
        }

        # Low utility score
        if here.utility_score < 0.2 and here.monthly_cost > 5.0 {
            should_flag = True;
            reason = f"Subscription '{here.service_name}' has low utility score ({here.utility_score:.1f}).";
        }

        if should_flag {
            notif = Notification(
                notification_id=str(uuid4()),
                notification_type="ACTION_REQUIRED",
                severity="LOW",
                title=f"Review Subscription: {here.service_name}",
                message=f"{reason} Consider cancelling at: {here.cancel_url or here.cancel_phone or 'contact provider'}.",
                created_at=datetime.utcnow().isoformat()
            );
            here ++> notif;
            self.flagged += 1;
            print(f"[SubscriptionReviewer] Flagged: {here.service_name} (${here.monthly_cost:.2f}/mo)");
        }
    }

    can finish with Patient entry {
        if self.flagged > 0 {
            print(f"[SubscriptionReviewer] {self.flagged} subscription(s) flagged for review for {self.patient_name}");
        }
        report {"patient": self.patient_name, "flagged_subscriptions": self.flagged};
    }
}

"""AppealFormFiller walker — populates CMS appeal forms (CMS-20027, CMS-20031) with dispute data."""

import from graph.nodes.patient { Patient }
import from graph.nodes.dispute { Dispute }
import from graph.nodes.appeal { Appeal }
import from abilities.llm_abilities { fill_appeal_form }

import from datetime { datetime }

walker AppealFormFiller {
    has patient: any = None;

    has appeal_level: int = 1,
        form_type: str = "";  # "CMS-20027" | "CMS-20031" | "ALJ"

    can start with Patient entry {
        self.patient = here;
        visit [-->];
    }

    can fill with Dispute entry {
        if here.status not in ["OPEN", "SUBMITTED"] {
            disengage;
        }
        if here.appeal_level != self.appeal_level - 1 {
            disengage;
        }

        # Determine form type by level
        form = self.form_type;
        if form == "" {
            if self.appeal_level == 1 {
                form = "CMS-20027";
            } elif self.appeal_level == 2 {
                form = "CMS-20031";
            } else {
                form = "ALJ-HEARING-REQUEST";
            }
        }

        filled = fill_appeal_form(
            form_type=form,
            dispute_id=here.dispute_id,
            error_type=here.error_type,
            description=here.description,
            amount_disputed=here.amount_disputed,
            appeal_level=self.appeal_level,
            patient_name=self.patient.name,
            patient_dob=self.patient.dob,
            medicare_id=self.patient.medicare_id
        );

        print(f"[AppealFormFiller] Form {form} filled for dispute {here.dispute_id}");
        report {"dispute_id": here.dispute_id, "form_type": form, "form_data": filled};
    }
}

"""AppealLetterGenerator walker — generates appeal letters for open disputes.

Walks Dispute nodes that are OPEN or IN_PROGRESS and generates formal
Medicare appeal letters via by llm(), attaching them as Appeal nodes.
"""

import from graph.nodes.patient { Patient }
import from graph.nodes.claim { Claim }
import from graph.nodes.line_item { LineItem }
import from graph.nodes.dispute { Dispute }
import from graph.nodes.appeal { Appeal }
import from abilities.llm_abilities { generate_appeal_letter }

import from datetime { datetime, timedelta }
import from uuid { uuid4 }

# Appeal deadlines: Level 1 = 120 days, Level 2 = 180 days
glob APPEAL_DEADLINES = {1: 120, 2: 180, 3: 60, 4: 90, 5: 60};
glob APPEAL_FORMS = {1: "CMS-20027", 2: "CMS-20033", 3: "ALJ-HEARING", 4: "MAC-REVIEW", 5: "DISTRICT-COURT"};
glob APPEAL_ADDRESSES = {
    1: "Medicare Administrative Contractor (MAC)",
    2: "Qualified Independent Contractor (QIC)",
    3: "Office of Medicare Hearings and Appeals (OMHA)",
    4: "Medicare Appeals Council (MAC-DAB)",
    5: "Federal District Court"
};
walker AppealLetterGenerator {
    has current_claim: any = None;

    has patient_name: str = "",
        patient_medicare_id: str = "",
        force_regenerate: bool = False;

    can start with Patient entry {
        self.patient_name = here.name;
        self.patient_medicare_id = here.medicare_id;
        visit [-->];
    }

    can process_claim with Claim entry {
        self.current_claim = here;
        visit [-->];
    }

    can process_line_item with LineItem entry {
        visit [-->];
    }

    can generate_for_dispute with Dispute entry {
        if here.status not in ["OPEN", "IN_PROGRESS"] {
            disengage;
        }

        # Check if there's already a pending appeal at this level
        existing_appeals = [a for a in [here-->] if isinstance(a, Appeal) and a.appeal_level == here.appeal_level + 1];
        if len(existing_appeals) > 0 and not self.force_regenerate {
            disengage;
        }

        next_level = here.appeal_level + 1 if here.appeal_level > 0 else 1;
        days_to_deadline = APPEAL_DEADLINES.get(next_level, 120);
        deadline = (datetime.utcnow() + timedelta(days=days_to_deadline)).strftime("%Y-%m-%d");

        # Get prior decision summaries
        prior_appeals = [a for a in [here-->] if isinstance(a, Appeal)];
        prior_decisions = [
            f"Level {a.appeal_level}: {a.decision} — {a.decision_rationale[:200]}"
            for a in prior_appeals if a.decision != "PENDING"
        ];

        # Generate the letter via LLM
        letter = generate_appeal_letter(
            dispute_description=here.description,
            error_type=here.error_type,
            amount_disputed=here.amount_disputed,
            patient_name=self.patient_name,
            patient_medicare_id=self.patient_medicare_id,
            claim_number=getattr(self, "current_claim", None) and self.current_claim.claim_number or "UNKNOWN",
            service_dates=getattr(self, "current_claim", None) and self.current_claim.service_date_start or "",
            provider_name="",
            cpt_code=here.error_type,
            denial_reason="\n".join(here.citations),
            appeal_level=next_level,
            prior_decision_summary="\n".join(prior_decisions) if prior_decisions else "No prior decisions"
        );

        appeal = Appeal(
            appeal_id=str(uuid4()),
            appeal_level=next_level,
            form_type=APPEAL_FORMS.get(next_level, "CMS-20027"),
            due_date=deadline,
            decision="PENDING",
            amount_requested=here.amount_disputed,
            letter_content=letter,
            submitted_to=APPEAL_ADDRESSES.get(next_level, "Medicare Administrative Contractor"),
            created_at=datetime.utcnow().isoformat()
        );
        here ++> appeal;
        here.status = "APPEALED";
        here.appeal_level = next_level;
        here.deadline = deadline;

        print(
            f"[AppealLetterGenerator] Generated Level {next_level} appeal "
            f"for dispute {here.dispute_id} (due {deadline})"
        );
    }
}

"""AppealTracker walker — monitors appeal deadlines and auto-escalates.

Walks all active disputes and their appeals, checking:
1. Whether filing deadlines are approaching (warns at 30 days)
2. Whether deadlines have passed (auto-escalates if possible)
3. Whether decisions have come in and need follow-up
"""

import from graph.nodes.claim { Claim }
import from graph.nodes.line_item { LineItem }
import from graph.nodes.patient { Patient }
import from graph.nodes.dispute { Dispute }
import from graph.nodes.appeal { Appeal }
import from graph.nodes.notification { Notification }

import from datetime { datetime, timedelta }
import from uuid { uuid4 }

glob DEADLINE_WARNING_DAYS = 30;

walker AppealTracker {
    has today: any = None;
    has patient_name: str = "";


    can start with Patient entry {
        self.today = datetime.utcnow().strftime("%Y-%m-%d");
        self.patient_name = here.name;
        visit [-->];
    }

    can check_claim_disputes with Claim entry {
        visit [-->];
    }

    can check_line_item_disputes with LineItem entry {
        visit [-->];
    }

    can track_dispute with Dispute entry {
        if here.status not in ["OPEN", "IN_PROGRESS", "APPEALED"] {
            disengage;
        }

        # Check deadline proximity
        if here.deadline != "" {
            try {
                deadline_dt = datetime.strptime(here.deadline, "%Y-%m-%d");
                today_dt = datetime.strptime(self.today, "%Y-%m-%d");
                days_remaining = (deadline_dt - today_dt).days;

                if days_remaining < 0 {
                    # Deadline PASSED — escalate
                    here.status = "ESCALATED";
                    print(
                        f"[AppealTracker] DEADLINE PASSED for dispute {here.dispute_id} "
                        f"(was {here.deadline})"
                    );
                    notif = Notification(
                        notification_id=str(uuid4()),
                        notification_type="APPEAL_DEADLINE",
                        severity="CRITICAL",
                        title=f"Appeal Deadline Missed — Immediate Action Required",
                        message=(
                            f"The {here.appeal_level}-level appeal deadline for "
                            f"${here.amount_disputed:.2f} dispute passed on {here.deadline}. "
                            f"Please contact a Medicare counselor immediately."
                        ),
                        created_at=datetime.utcnow().isoformat()
                    );
                    here ++> notif;

                } elif days_remaining <= DEADLINE_WARNING_DAYS {
                    print(
                        f"[AppealTracker] Deadline in {days_remaining} days for "
                        f"dispute {here.dispute_id} (${here.amount_disputed:.2f})"
                    );
                    severity = "URGENT" if days_remaining <= 7 else "WARNING";
                    notif = Notification(
                        notification_id=str(uuid4()),
                        notification_type="APPEAL_DEADLINE",
                        severity=severity,
                        title=f"Appeal Deadline in {days_remaining} Days",
                        message=(
                            f"Level {here.appeal_level} appeal deadline is {here.deadline} "
                            f"({days_remaining} days). Dispute: {here.description[:100]}. "
                            f"Amount: ${here.amount_disputed:.2f}"
                        ),
                        created_at=datetime.utcnow().isoformat()
                    );
                    here ++> notif;
                }
            } except Exception as e {
                print(f"[AppealTracker] Error parsing deadline for {here.dispute_id}: {e}");
            }
        }

        # Walk into appeal nodes for decision tracking
        visit [-->];
    }

    can check_appeal_decision with Appeal entry {
        # If decision came in and is unfavorable, escalate to next level
        if here.decision == "UNFAVORABLE" and here.appeal_level < 5 {
            # Find parent dispute
            parent_disputes = [d for d in [here<--] if isinstance(d, Dispute)];
            for dispute in parent_disputes {
                if dispute.appeal_level == here.appeal_level {
                    dispute.status = "OPEN";  # Reopen for next level
                    print(
                        f"[AppealTracker] Unfavorable Level {here.appeal_level} — "
                        f"dispute {dispute.dispute_id} eligible for Level {here.appeal_level + 1}"
                    );
                }
            }
        }
    }
}

"""CoveragePolicyChecker walker — flags services not covered under the patient's policy."""

import from graph.nodes.patient { Patient }
import from graph.nodes.claim { Claim }
import from graph.nodes.line_item { LineItem }
import from graph.nodes.policy { Policy }
import from graph.nodes.dispute { Dispute }

import from datetime { datetime }
import from uuid { uuid4 }

walker CoveragePolicyChecker {
    has active_policies: list = [];


    can start with Patient entry {
        # Get active policies
        self.active_policies = [p for p in [here-->] if isinstance(p, Policy) and p.termination_date == ""];
        visit [-->];
    }

    can check_claim with Claim entry {
        visit [-->];
    }

    can check_line_item with LineItem entry {
        if here.cpt_code == "" or len(self.active_policies) == 0 {
            disengage;
        }

        # Basic coverage check — coinsurance overage check
        for policy in self.active_policies {
            if policy.plan_type in ["MEDICARE_PART_B", "MEDICARE_PART_A"] {
