                    amount_disputed=0.0,
                    status="OPEN",
                    flagged_date=datetime.utcnow().isoformat(),
                    confidence_score=0.95,
                    severity="MEDIUM",
                    citations=["ICD-10-CM Official Guidelines — Specificity requirement"]
                );
                here ++> dispute;
                here.has_errors = True;
                here.error_count += 1;
                print(f"[DiagnosisCodeAuditor] Header code used: {pointer}");
            }
        }
    }
}

"""DisputeCreator walker — creates Dispute nodes from all detected errors.

This walker is the aggregator: it runs AFTER all audit walkers have flagged
line items, then calls assess_billing_error() via by llm() for each flagged
item to get a richer dispute assessment with regulatory citations.
"""

import from graph.nodes.patient { Patient }
import from graph.nodes.claim { Claim }
import from graph.nodes.line_item { LineItem }
import from graph.nodes.dispute { Dispute }
import from abilities.llm_abilities { assess_billing_error }

import from datetime { datetime }
import from uuid { uuid4 }

walker DisputeCreator {

    can start with Patient entry {
        visit [-->];
    }

    can check_claim with Claim entry {
        visit [-->];
    }

    can check_line_item with LineItem entry {
        if not here.has_errors {
            disengage;
        }

        # Call LLM for richer assessment of already-flagged items
        assessment = assess_billing_error(
            cpt_code=here.cpt_code,
            description=here.description,
            billed_amount=here.charge_amount,
            fee_schedule_rate=here.fee_schedule_rate,
            units=here.units,
            mue_limit=here.mue_limit,
            ncci_flags=here.ncci_flags,
            modifier=here.modifier_1,
            diagnosis_pointers=here.icd_diagnosis_pointers,
            diagnosis_codes=[]
        );

        if assessment.get("has_error", False) {
            # Update or create a comprehensive dispute node
            existing_disputes = [d for d in [here-->] if isinstance(d, Dispute)];

            if len(existing_disputes) == 0 {
                # No dispute yet — create one from LLM assessment
                dispute = Dispute(
                    dispute_id=str(uuid4()),
                    error_type=assessment.get("error_type", "BILLING_ERROR"),
                    description=assessment.get("description", ""),
                    amount_disputed=float(assessment.get("amount_disputed", 0) or 0),
                    expected_amount=here.charge_amount - float(assessment.get("amount_disputed", 0) or 0),
                    status="OPEN",
                    flagged_date=datetime.utcnow().isoformat(),
                    confidence_score=float(assessment.get("confidence", 0.5) or 0.5),
                    severity="HIGH" if float(assessment.get("amount_disputed", 0) or 0) > 100 else "MEDIUM",
                    citations=[assessment.get("regulatory_citation", "")] if assessment.get("regulatory_citation") else []
                );
                here ++> dispute;
            } else {
                # Enrich the existing dispute with LLM citations
                for d in existing_disputes {
                    if assessment.get("regulatory_citation") {
                        d.citations = list(set(d.citations + [assessment.get("regulatory_citation", "")]));
                    }
                }
            }
        }
    }
}

"""DuplicateClaimDetector walker — finds duplicate or overlapping claims.

Walks all of a patient's claims and identifies:
1. Exact duplicate claims (same provider, date, CPT, amount)
2. Overlapping service lines (same CPT billed twice on the same DOS)
"""

import from graph.nodes.patient { Patient }
import from graph.nodes.claim { Claim }
import from graph.nodes.line_item { LineItem }
import from graph.nodes.dispute { Dispute }

import from datetime { datetime }
import from uuid { uuid4 }
import from collections { defaultdict }

walker DuplicateClaimDetector {

    can start with Patient entry {
        # Collect all claims and their line items for pairwise comparison
        claims = [c for c in [here-->] if isinstance(c, Claim)];

        # Build a map of (service_date, cpt_code, provider) → list of line items
        service_map = defaultdict(list);

        for claim in claims {
            line_items = [li for li in [claim-->] if isinstance(li, LineItem)];
            for item in line_items {
                key = f"{item.service_date}|{item.cpt_code}|{claim.claim_number[:4]}";
                service_map[key].append({
                    "claim_number": claim.claim_number,
                    "line_item": item,
                    "amount": item.charge_amount
                });
            }
        }

        # Flag any key with more than one entry as a potential duplicate
        for (key, entries) in service_map.items() {
            if len(entries) > 1 {
                parts = key.split("|");
                service_date = parts[0];
                cpt_code = parts[1];

                for i in range(1, len(entries)) {
                    dup_item = (entries[i]["line_item"] as LineItem);
                    total_dup_amount = sum(e["amount"] for e in entries[1:]);

                    dispute = Dispute(
                        dispute_id=str(uuid4()),
                        error_type="DUPLICATE_CHARGE",
                        description=(
                            f"CPT {cpt_code} appears to be billed {len(entries)} times "
                            f"on {service_date}. "
                            f"Potential duplicate on claims: "
                            f"{', '.join(e['claim_number'] for e in entries)}"
                        ),
                        amount_disputed=total_dup_amount,
                        expected_amount=entries[0]["amount"],
                        status="OPEN",
                        flagged_date=datetime.utcnow().isoformat(),
                        confidence_score=0.80,
                        severity="MEDIUM",
                        citations=["CMS Duplicate Claim Policy — same day, same provider, same service"]
                    );
                    dup_item ++> dispute;
                    dup_item.has_errors = True;
                    dup_item.error_count += 1;
                    print(
                        f"[DuplicateClaimDetector] Duplicate: {cpt_code} on {service_date} "
                        f"x{len(entries)} (${total_dup_amount:.2f} disputed)"
                    );
                }
            }
        }
    }
}

"""FeeScheduleAuditor walker — checks line item charges vs. Medicare fee schedule.

Walks Patient → Claim → LineItem nodes and cross-references each CPT/HCPCS
code against the Medicare Physician Fee Schedule in PostgreSQL. Flags line items
where the billed amount exceeds the fee schedule allowable by more than 10%.
"""

import from graph.nodes.patient { Patient }
import from graph.nodes.claim { Claim }
import from graph.nodes.line_item { LineItem }
import from graph.nodes.dispute { Dispute }
import from abilities.llm_abilities { assess_billing_error }
import from reference_data.db { query_fee_schedule }

import from datetime { datetime }
import from uuid { uuid4 }

glob FEE_SCHEDULE_OVERAGE_THRESHOLD = 0.10;  # 10% over allowable = flag

walker FeeScheduleAuditor {
    has patient_state: str = "XX";   # 2-letter state code for locality pricing

    can start with Patient entry {
        self.patient_state = here.state or "XX";
        visit [-->];
    }

    can check_claim with Claim entry {
        visit [-->];
    }

    can audit_line_item with LineItem entry {
        if here.cpt_code == "" or here.charge_amount == 0 {
            disengage;
        }

        # Look up fee schedule rate in PostgreSQL
        rate = query_fee_schedule(
            cpt_code=here.cpt_code,
            state=self.patient_state
        );

        if rate is None or rate == 0 {
            disengage;  # Code not in fee schedule (e.g., HCPCS supply code)
        }

        here.fee_schedule_rate = rate;
        adjusted_rate = rate * here.units;
        overage = here.charge_amount - adjusted_rate;
        overage_pct = overage / adjusted_rate if adjusted_rate > 0 else 0;

        here.fee_schedule_overage = overage;

        if overage_pct > FEE_SCHEDULE_OVERAGE_THRESHOLD {
            here.has_errors = True;
            here.error_count += 1;

            dispute = Dispute(
                dispute_id=str(uuid4()),
                error_type="FEE_SCHEDULE_OVERAGE",
                description=(
                    f"CPT {here.cpt_code} billed at ${here.charge_amount:.2f} "
                    f"but Medicare fee schedule allows ${adjusted_rate:.2f} "
                    f"({overage_pct*100:.1f}% over limit)"
                ),
                amount_disputed=overage,
                expected_amount=adjusted_rate,
                status="OPEN",
                flagged_date=datetime.utcnow().isoformat(),
                confidence_score=0.90,
                severity="HIGH" if overage > 100 else "MEDIUM",
                citations=[
                    "42 CFR 414.20 — Computation of fee schedule amounts",
                    f"CMS Medicare Physician Fee Schedule {here.cpt_code}"
                ]
            );
            here ++> dispute;
            print(
                f"[FeeScheduleAuditor] Flagged {here.cpt_code}: "
                f"${here.charge_amount:.2f} billed vs ${adjusted_rate:.2f} allowed "
                f"(+{overage_pct*100:.1f}%)"
            );
        }
    }
}

