"""Judge Agent — neutral synthesis walker."""

import from ..graph.nodes { Asset, BullNode, BearNode, TemporalSnapshot, VerdictNode }
import from ..graph.edges { HasCoalition, HasSnapshot, HasVerdict }
import from ..prompts.judge_prompts { JudgeVerdict, synthesize_verdict }

def confidence_label(score: int) -> str {
    if score >= 70 {
        return "strong";
    } elif score >= 45 {
        return "moderate";
    }
    return "weak";
}

def build_momentum(snapshots: list[TemporalSnapshot]) -> str {
    # Build a momentum string from sorted snapshots, e.g. "weak -> moderate -> strong"
    if len(snapshots) == 0 {
        return "no prior data";
    }
    sorted_snaps = sorted(snapshots, key=lambda (s: TemporalSnapshot) { s.run_number; });
    labels = [confidence_label(s.confidence) for s in sorted_snaps];
    return " -> ".join(labels);
}

walker JudgeWalker {
    has insufficient_data_threshold: int = 35;

    can enter_asset with Asset entry {
        bull_nodes = [->:HasCoalition:side=="bull":->][?:BullNode];
        bear_nodes = [->:HasCoalition:side=="bear":->][?:BearNode];

        if len(bull_nodes) == 0 or len(bear_nodes) == 0 {
            verdict_node = here ++> VerdictNode(
                verdict="insufficient data",
                judge_confidence=0,
                rationale="Missing coalition data — one or both sides did not deposit findings.",
                condition=""
            );
            report verdict_node[0];
            disengage;
        }

        bull = bull_nodes[0];
        bear = bear_nodes[0];

        # Collect temporal snapshots for momentum detection
        bull_snapshots = [bull ->:HasSnapshot:->][?:TemporalSnapshot];
        bear_snapshots = [bear ->:HasSnapshot:->][?:TemporalSnapshot];

        bull_momentum = build_momentum(bull_snapshots);
        bear_momentum = build_momentum(bear_snapshots);

        # Epistemic humility — both sides low confidence
        if bull.confidence < self.insufficient_data_threshold
           and bear.confidence < self.insufficient_data_threshold {
            verdict_node = here +>:HasVerdict:+> VerdictNode(
                verdict="insufficient data",
                judge_confidence=0,
                rationale=f"Both coalitions returned low confidence (bull: {bull.confidence}%, bear: {bear.confidence}%). Neither side found sufficient evidence to build a credible case. Re-evaluate after new data.",
                condition=""
            );
            report verdict_node[0];
            disengage;
        }

        # Call LLM for verdict synthesis
        result = synthesize_verdict(
            ticker=here.ticker,
            bull_argument=bull.argument,
            bull_confidence=bull.confidence,
            bear_argument=bear.argument,
            bear_confidence=bear.confidence,
            bull_momentum=bull_momentum,
            bear_momentum=bear_momentum
        );

        # Create verdict node and attach to asset
        verdict_node = here +>:HasVerdict:+> VerdictNode(
            verdict=result.verdict,
            judge_confidence=result.judge_confidence,
            rationale=result.rationale,
            condition=result.condition
        );

        report verdict_node[0];
    }
}

"""Portfolio Meta Agent — cross-asset reasoning walker."""

import from ..graph.nodes { PortfolioNode, Asset, BullNode, BearNode, VerdictNode, PortfolioAnnotation }
import from ..graph.edges { BelongsToPortfolio, HasCoalition, HasVerdict, HasAnnotation }
import from ..prompts.portfolio_prompts { PortfolioInsight, synthesize_portfolio_annotation }

def build_asset_summaries_text(summaries: list[dict]) -> str {
    lines: list[str] = [];
    for s in summaries {
        line = f"{s['ticker']} | sector={s['sector']} | bull={s['bull_argument']} (conf {s['bull_confidence']}%) | bear={s['bear_argument']} (conf {s['bear_confidence']}%) | verdict={s['verdict']} (conf {s['judge_confidence']}%)";
        lines.append(line);
    }
    return "\n".join(lines);
}

walker PortfolioMetaWalker {
    has asset_summaries: list[dict] = [];

    can enter_portfolio with PortfolioNode entry {
        visit [->:BelongsToPortfolio:->][?:Asset];
    }

    can enter_asset with Asset entry {
        bull_nodes: list[BullNode] = [->:HasCoalition:side=="bull":->][?:BullNode];
        bear_nodes: list[BearNode] = [->:HasCoalition:side=="bear":->][?:BearNode];
        verdict_nodes: list[VerdictNode] = [->:HasVerdict:->][?:VerdictNode];

        ticker: str = here.ticker;
        sector: str = here.sector;
        bull_arg: str = "no data";
        bull_conf: int = 0;
        bear_arg: str = "no data";
        bear_conf: int = 0;
        verd_str: str = "no verdict";
        judge_conf: int = 0;

        if len(bull_nodes) > 0 {
            bull_arg = bull_nodes[0].argument;
            bull_conf = bull_nodes[0].confidence;
        }
        if len(bear_nodes) > 0 {
            bear_arg = bear_nodes[0].argument;
            bear_conf = bear_nodes[0].confidence;
        }
        if len(verdict_nodes) > 0 {
            verd_str = verdict_nodes[0].verdict;
            judge_conf = verdict_nodes[0].judge_confidence;
        }

        summary = {
            "ticker": ticker,
            "sector": sector,
            "bull_argument": bull_arg,
            "bull_confidence": bull_conf,
            "bear_argument": bear_arg,
            "bear_confidence": bear_conf,
            "verdict": verd_str,
            "judge_confidence": judge_conf
        };
        self.asset_summaries.append(summary);
    }

    can exit_portfolio with PortfolioNode exit {
        if len(self.asset_summaries) == 0 {
            report None;
            disengage;
        }

        summaries_text = build_asset_summaries_text(self.asset_summaries);
        result = synthesize_portfolio_annotation(
            asset_summaries=summaries_text
        );

        annotation_node = here +>:HasAnnotation:+> PortfolioAnnotation(
            annotation=result.annotation,
            correlated_theme=result.correlated_theme,
            hedging_gaps=result.hedging_gaps,
            portfolio_conviction=result.portfolio_conviction
        );

        report annotation_node;
    }
}

"""Query Walker — natural language Q&A over the live graph."""

import from ..graph.nodes {
    PortfolioNode, Asset, BullNode, BearNode,
    TemporalSnapshot, VerdictNode, PortfolioAnnotation
}
import from ..graph.edges {
    BelongsToPortfolio, HasCoalition, HasSnapshot,
    HasVerdict, HasAnnotation
}
import from ..prompts.query_prompts { QueryAnswer, answer_query }

obj AssetContextBlockIn {
    has ticker: str;
    has sector: str;
    has price: float;
    has bull_momentum: str;
    has bear_momentum: str;
    has bull: BullNode | None = None;
    has bear: BearNode | None = None;
    has verdict: VerdictNode | None = None;
}

def confidence_label(score: int) -> str {
    if score >= 70 {
        return "strong";
    } elif score >= 45 {
        return "moderate";
    }
    return "weak";
}

def build_momentum_string(snapshots: list[TemporalSnapshot], depth: int) -> str {
    if len(snapshots) == 0 {
        return "no prior data";
    }
    sorted_snaps: list[TemporalSnapshot] = sorted(
        snapshots,
        key=lambda (s: TemporalSnapshot) { s.run_number; }
    );
    trimmed: list[TemporalSnapshot];
    if len(sorted_snaps) > depth {
        trimmed = sorted_snaps[-depth:];
    } else {
        trimmed = sorted_snaps;
    }
    labels = [confidence_label(s.confidence) for s in trimmed];
    return " -> ".join(labels);
}

def build_asset_context_block(ctx: AssetContextBlockIn) -> str {
    lines: list[str] = [];
    lines.append(f"ASSET: {ctx.ticker} | sector={ctx.sector} | price={ctx.price}");

    if ctx.bull is not None {
        lines.append(f"BULL: {ctx.bull.argument} | confidence={ctx.bull.confidence}%");
        lines.append(f"  News: {ctx.bull.news_finding} ({ctx.bull.news_confidence}%) | Quant: {ctx.bull.quant_finding} ({ctx.bull.quant_confidence}%) | Macro: {ctx.bull.macro_finding} ({ctx.bull.macro_confidence}%)");
        lines.append(f"  Momentum: {ctx.bull_momentum}");
    } else {
        lines.append("BULL: no data");
    }

    if ctx.bear is not None {
        lines.append(f"BEAR: {ctx.bear.argument} | confidence={ctx.bear.confidence}%");
        lines.append(f"  News: {ctx.bear.news_finding} ({ctx.bear.news_confidence}%) | Quant: {ctx.bear.quant_finding} ({ctx.bear.quant_confidence}%) | Macro: {ctx.bear.macro_finding} ({ctx.bear.macro_confidence}%)");
        lines.append(f"  Momentum: {ctx.bear_momentum}");
    } else {
        lines.append("BEAR: no data");
    }

    if ctx.verdict is not None {
        lines.append(f"VERDICT: {ctx.verdict.verdict} | confidence={ctx.verdict.judge_confidence}%");
        lines.append(f"  Rationale: {ctx.verdict.rationale}");
        if ctx.verdict.condition {
            lines.append(f"  Condition: {ctx.verdict.condition}");
        }
    } else {
        lines.append("VERDICT: no verdict");
    }

    return "\n".join(lines);
}

walker QueryWalker {
    has question: str;
    has asset_contexts: list[str] = [];
    has portfolio_context: str = "";
    has snapshot_depth: int = 4;

    can enter_portfolio with PortfolioNode entry {
        # Read portfolio-level annotations if available
        annotations = [->:HasAnnotation:->][?:PortfolioAnnotation];
        if len(annotations) > 0 {
            # Take the most recent annotation by run_number
            sorted_annots = sorted(annotations, key=lambda (a: PortfolioAnnotation) { a.run_number; });
            latest = sorted_annots[-1];
            self.portfolio_context = (
                "PORTFOLIO ANNOTATION:\n"
                + f"  Summary: {latest.annotation}\n"
                + f"  Correlated Theme: {latest.correlated_theme}\n"
                + f"  Hedging Gaps: {latest.hedging_gaps}\n"
                + f"  Portfolio Conviction: {latest.portfolio_conviction}"
            );
        }

        visit [->:BelongsToPortfolio:->][?:Asset];
    }

    can enter_asset with Asset entry {
        bull_nodes = [->:HasCoalition:side=="bull":->][?:BullNode];
        bear_nodes = [->:HasCoalition:side=="bear":->][?:BearNode];
        verdict_nodes = [->:HasVerdict:->][?:VerdictNode];

        bull: BullNode | None = None;
        bear: BearNode | None = None;
        verdict: VerdictNode | None = None;
        bull_momentum: str;
        bear_momentum: str;

        if len(bull_nodes) > 0 {
            bull = bull_nodes[0];
            bull_snapshots = [bull ->:HasSnapshot:->][?:TemporalSnapshot];
            bull_momentum = build_momentum_string(bull_snapshots, self.snapshot_depth);
        } else {
            bull_momentum = "no prior data";
        }
        if len(bear_nodes) > 0 {
            bear = bear_nodes[0];
            bear_snapshots = [bear ->:HasSnapshot:->][?:TemporalSnapshot];
            bear_momentum = build_momentum_string(bear_snapshots, self.snapshot_depth);
        } else {
            bear_momentum = "no prior data";
        }
        if len(verdict_nodes) > 0 {
            verdict = verdict_nodes[0];
        }

        block = build_asset_context_block(
            AssetContextBlockIn(
                ticker=here.ticker,
                sector=here.sector,
                price=here.price,
                bull_momentum=bull_momentum,
                bear_momentum=bear_momentum,
                bull=bull,
                bear=bear,
                verdict=verdict
            )
        );
        self.asset_contexts.append(block);
    }

    can exit_portfolio with PortfolioNode exit {
        if len(self.asset_contexts) == 0 and self.portfolio_context == "" {
            report QueryAnswer(
                answer="No data available in the portfolio to answer this question.",
                cited_tickers=[],
                confidence_note="Portfolio graph is empty — no assets or annotations found."
            );
            disengage;
        }

        # Assemble full graph context
        sections: list[str] = [];
        if self.portfolio_context != "" {
            sections.append(self.portfolio_context);
        }
        for ctx in self.asset_contexts {
            sections.append(ctx);
        }
        full_context = "\n\n".join(sections);

        result = answer_query(
            question=self.question,
            graph_context=full_context
        );

        report result;
    }
}

"""Headless Jac pipeline for the FastAPI service — same graph as main.jac, returns JSON."""

import from graph.nodes { PortfolioNode, Asset, VerdictNode, BullNode, BearNode }
import from graph.edges { BelongsToPortfolio, HasVerdict, HasCoalition }
import from agents.bull_coalition_walker { BullCoalitionWalker }
import from agents.bear_coalition_walker { BearCoalitionWalker }
import from agents.judge_agent { JudgeWalker }

def json_str(s: str) -> str {
    t: str = s;
    t = t.replace("\\", "\\\\");
    t = t.replace("\"", "\\\"");
    t = t.replace("\n", "\\n");
    t = t.replace("\r", "\\r");
    t = t.replace("\t", "\\t");
    return "\"" + t + "\"";
}

"""Run bull/bear coalitions + judge per ticker; return a JSON array string for Python to parse."""
def run_pipeline_for_tickers(tickers: list[str], signals_json: str = "{}") -> str {
    import json;
    signals_map = json.loads(signals_json);

    row_strings: list[str] = [];
    portfolio = PortfolioNode(name="AlphaWalker API");
    root ++> portfolio;

    for ticker in tickers {
        asset = Asset(ticker=ticker);
        asset.quant_signals = signals_map.get(ticker, "");
        portfolio +>:BelongsToPortfolio:+> asset;

        asset spawn BullCoalitionWalker(ticker=ticker);
        asset spawn BearCoalitionWalker(ticker=ticker);

        asset spawn JudgeWalker();

        verdicts = [asset ->:HasVerdict:->][?:VerdictNode];
        bull_nodes = [asset ->:HasCoalition:side=="bull":->][?:BullNode];
        bear_nodes = [asset ->:HasCoalition:side=="bear":->][?:BearNode];

        v_verdict: str = "";
        v_jc: int = 0;
        v_rat: str = "";
        v_cond: str = "";
        if len(verdicts) > 0 {
            v = verdicts[0];
            v_verdict = v.verdict;
            v_jc = v.judge_confidence;
            v_rat = v.rationale;
            v_cond = v.condition;
        }

        b_arg: str = "";
        b_conf: int = 0;
        if len(bull_nodes) > 0 {
            b = bull_nodes[0];
            b_arg = b.argument;
            b_conf = b.confidence;
        }

        br_arg: str = "";
        br_conf: int = 0;
        if len(bear_nodes) > 0 {
            br = bear_nodes[0];
            br_arg = br.argument;
            br_conf = br.confidence;
        }

        row = (
            "{"
            + "\"ticker\":" + json_str(ticker)
            + ",\"verdict\":" + json_str(v_verdict)
            + ",\"judge_confidence\":" + str(v_jc)
            + ",\"rationale\":" + json_str(v_rat)
            + ",\"condition\":" + json_str(v_cond)
            + ",\"bull_argument\":" + json_str(b_arg)
            + ",\"bull_confidence\":" + str(b_conf)
            + ",\"bear_argument\":" + json_str(br_arg)
            + ",\"bear_confidence\":" + str(br_conf)
            + "}"
        );
        row_strings.append(row);
    }

    return "[" + ",".join(row_strings) + "]";
}

"""Analysis engines for AlphaWalker."""


import from api.models {
    AnalysisRequest,
    AnalysisResult,
    GraphData,
    GraphEdge,
    GraphNode,
    HoldingAnalysis,
    Recommendation
}

obj EngineEvent {
    has agent: str;
    has stage: str;
    has message: str;
    has progress: float | None = None;
}

class RuleBasedAnalysisEngine {
    def analyze(self: RuleBasedAnalysisEngine, request: AnalysisRequest, emit: any) -> AnalysisResult {
        positive = {"NVDA", "MSFT", "AAPL", "AMZN", "META", "GOOGL"};
        negative = {"TSLA", "SMCI", "COIN", "MSTR", "PLTR"};
        holdings = request.portfolio.holdings;

        emit(
            EngineEvent(
                agent="portfolio_ingestor",
                stage="started",
                message="Normalized " + str(len(holdings)) + " holdings for analysis",
                progress=0.1
            )
        );
        emit(
            EngineEvent(
                agent="researcher",
                stage="running",
                message="Scanning the portfolio for concentration and crowding risk",
                progress=0.25
            )
        );

        holding_results: list[HoldingAnalysis] = [];
        recommendations: list[Recommendation] = [];
        graph_nodes: list[GraphNode] = [];
        graph_edges: list[GraphEdge] = [];

        weighted_risk_total: float = 0.0;
        sentiment_scores: list[int] = [];

        index: int = 0;
        for holding in holdings {
            index = index + 1;
            ticker = holding.ticker.upper();
            concentration_penalty: int = min(int(holding.weight * 100), 35);
            ord_sum: int = 0;
            for ch in ticker {
                oc: int = ord(ch);
                ord_sum = ord_sum + oc;
            }
            base_risk: int = 35 + concentration_penalty + ((ord_sum % 17) * 2);

            sentiment = "neutral";
            sentiment_score: int = 0;
            if ticker in positive {
                base_risk = base_risk - 8;
                sentiment = "positive";
                sentiment_score = 1;
            } elif ticker in negative {
                base_risk = base_risk + 10;
                sentiment = "negative";
                sentiment_score = -1;
            }

            risk_score: int = max(5, min(base_risk, 95));
            weighted_risk_total = weighted_risk_total + (float(risk_score) * holding.weight);
            sentiment_scores.append(sentiment_score);

            summary = self._build_summary(
                ticker=ticker,
                weight=holding.weight,
                risk_score=risk_score,
                sentiment=sentiment
            );
            w_rounded = int(holding.weight * 10000) / 10000.0;
            holding_results.append(
                HoldingAnalysis(
                    ticker=ticker,
                    weight=w_rounded,
                    risk_score=risk_score,
                    sentiment=sentiment,
                    summary=summary
                )
            );

            if holding.weight >= 0.2 or risk_score >= 70 {
                tw = max(holding.weight * 0.7, 0.05);
                target_weight = int(tw * 10000) / 10000.0;
                recommendations.append(
                    Recommendation(
                        ticker=ticker,
                        action="reduce",
                        reason="position concentration and volatility",
                        target_weight=target_weight
                    )
                );
            }

            if request.options.include_graph {
                asset_id = "asset:" + ticker;
                graph_nodes.extend(
                    [
                        GraphNode(id=asset_id, label=ticker, kind="asset"),
                        GraphNode(id="bull:" + ticker, label=ticker + " Bull", kind="bull"),
                        GraphNode(id="bear:" + ticker, label=ticker + " Bear", kind="bear"),
                        GraphNode(id="judge:" + ticker, label=ticker + " Judge", kind="judge")
                    ]
                );
                graph_edges.extend(
                    [
                        GraphEdge(source=asset_id, target="bull:" + ticker, label="analyzed_by"),
                        GraphEdge(source=asset_id, target="bear:" + ticker, label="analyzed_by"),
                        GraphEdge(source="bull:" + ticker, target="judge:" + ticker, label="debated"),
                        GraphEdge(source="bear:" + ticker, target="judge:" + ticker, label="debated")
                    ]
                );
            }

            denom: int = len(holdings);
            if denom < 1 {
                denom = 1;
            }
            prog: float = 0.25 + (0.4 * float(index) / float(denom));
            if prog > 0.65 {
                prog = 0.65;
            }
            emit(
                EngineEvent(
                    agent="risk_analyzer",
                    stage="running",
                    message="Evaluated " + ticker + " with risk score " + str(risk_score),
                    progress=prog
                )
            );
        }

        emit(
            EngineEvent(
                agent="sentiment_agent",
                stage="running",
                message="Synthesizing cross-holding sentiment and allocation pressure",
                progress=0.8
            )
        );

        overall_risk_score = int(round(weighted_risk_total));
        risk_band = self._risk_band(overall_risk_score);
        sentiment_summary = self._sentiment_summary(sentiment_scores);

        if request.options.include_rebalancing and len(recommendations) == 0 and len(holding_results) > 0 {
            lowest = holding_results[0];
            for h in holding_results {
                if h.risk_score < lowest.risk_score {
                    lowest = h;
                }
            }
            tw_m = int(lowest.weight * 10000) / 10000.0;
            recommendations.append(
                Recommendation(
                    ticker=lowest.ticker,
                    action="maintain",
                    reason="portfolio looks balanced relative to current signals",
                    target_weight=tw_m
                )
            );
        }

        emit(
            EngineEvent(
                agent="judge_agent",
                stage="completed",
                message="Finished portfolio verdict and rebalancing recommendations",
                progress=1.0
            )
        );

        graph = GraphData();
        if request.options.include_graph {
            graph = GraphData(nodes=graph_nodes, edges=graph_edges);
        }

        return AnalysisResult(
            overall_risk_score=overall_risk_score,
            risk_band=risk_band,
            sentiment_summary=sentiment_summary,
            rebalancing_suggestions=recommendations
                if request.options.include_rebalancing
                else [],
            holdings=holding_results,
            graph=graph
        );
    }

    def _build_summary(
        self: RuleBasedAnalysisEngine,
        ticker: str,
        weight: float,
        risk_score: int,
        sentiment: str
    ) -> str {
        if sentiment == "positive" {
            tone = "favorable momentum with manageable downside";
        } elif sentiment == "negative" {
            tone = "elevated downside sensitivity and headline risk";
        } else {
            tone = "mixed signals with no decisive catalyst";
        }
        pct = int(weight * 1000) / 10.0;
        return (
            ticker + " is " + str(pct) + "% of the portfolio with a "
            + str(risk_score) + "/100 risk score, suggesting " + tone + "."
        );
    }

    def _risk_band(self: RuleBasedAnalysisEngine, score: int) -> str {
        if score >= 70 {
            return "high";
        }
        if score >= 45 {
            return "moderate";
        }
        return "low";
    }

    def _sentiment_summary(self: RuleBasedAnalysisEngine, scores: list[int]) -> str {
        score: int = 0;
        for s in scores {
            score = score + s;
        }
        if score > 0 {
            return "Positive skew across core holdings";
        }
        if score < 0 {
            return "Mixed to negative across the portfolio";
        }
        return "Mixed";
    }
}

"""Maps the Jac multi-agent graph (`alphawalker_pipeline.jac`) into API `AnalysisResult` models."""

import logging;
import os;

import from api.engine { EngineEvent, RuleBasedAnalysisEngine }
import from api.jac_bridge { run_jac_pipeline }
import from api.models {
    AnalysisRequest,
    AnalysisResult,
    GraphData,
    GraphEdge,
    GraphNode,
    HoldingAnalysis,
    Recommendation
}

glob logger = logging.getLogger("api.jac_engine");

def _risk_band(score: int) -> str {
    if score >= 70 {
        return "high";
    }
    if score >= 45 {
        return "moderate";
    }
    return "low";
}

def _sentiment_summary(scores: list[int]) -> str {
    total: int = 0;
    for s in scores {
        total = total + s;
    }
    if total > 0 {
        return "Positive skew across core holdings";
    }
    if total < 0 {
        return "Mixed to negative across the portfolio";
    }
    return "Mixed";
}

def _has_any(hay: str, needles: list[str]) -> bool {
    for n in needles {
        if n in hay {
            return True;
        }
    }
    return False;
}

def _sentiment_from_row(verdict: str, bull_c: int, bear_c: int) -> str {
    v = (verdict or "").lower();
    if _has_any(v, ["buy", "accumulate", "overweight", "add"]) {
        return "positive";
    }
    if _has_any(v, ["sell", "reduce", "underweight", "trim"]) {
        return "negative";
    }
    if bull_c > bear_c + 15 {
        return "positive";
    }
    if bear_c > bull_c + 15 {
        return "negative";
    }
    return "neutral";
}

def _risk_score(row: dict[str, any], weight: float) -> int {
    jc = int(row.get("judge_confidence", 0) or 0);
    bc = int(row.get("bear_confidence", 0) or 0);
    buc = int(row.get("bull_confidence", 0) or 0);
    base: int = max(10, 100 - min(100, jc));
    diff: int = abs(bc - buc);
    tilt: int = diff // 5;
    concentration: int = min(25, int(weight * 100));
    score: int = base + tilt + (concentration // 2);
    return max(5, min(95, score));
}

def _pct_one(weight: float) -> str {
    v = int(weight * 1000) / 10.0;
    return str(v);
}

def _summary(row: dict[str, any], weight: float, risk: int, sentiment: str) -> str {
    t = str(row.get("ticker", ""));
    rationale_raw = row.get("rationale", "");
    rationale = str(rationale_raw or "").strip();
    verdict_raw = row.get("verdict", "");
    verdict = str(verdict_raw or "").strip();
    pct = _pct_one(weight);
    if rationale != "" {
        clip: str;
        if len(rationale) > 400 {
            clip = rationale[0:397] + "...";
        } else {
            clip = rationale;
        }
        return (
            t + " (" + pct + "% weight): judge verdict «" + verdict + "» ("
            + str(risk) + "/100 risk, " + sentiment + "). " + clip
        );
    }
    vv = verdict;
    if vv == "" {
        vv = "n/a";
    }
    return (
        t + " is " + pct + "% of the portfolio with risk " + str(risk) + "/100 "
        + "and " + sentiment + " tone; verdict: " + vv + "."
    );
}

def _round4(x: float) -> float {
    return int(x * 10000) / 10000.0;
}

def _build_graph(tickers: list[str]) -> GraphData {
    nodes: list[GraphNode] = [];
    edges: list[GraphEdge] = [];
    for ticker in tickers {
        aid = "asset:" + ticker;
        nodes.append(GraphNode(id=aid, label=ticker, kind="asset"));
        nodes.append(GraphNode(id="bull:" + ticker, label=ticker + " bull coalition", kind="bull"));
        nodes.append(GraphNode(id="bear:" + ticker, label=ticker + " bear coalition", kind="bear"));
        nodes.append(GraphNode(id="judge:" + ticker, label=ticker + " judge", kind="judge"));
        edges.append(GraphEdge(source=aid, target="bull:" + ticker, label="coalition"));
        edges.append(GraphEdge(source=aid, target="bear:" + ticker, label="coalition"));
        edges.append(GraphEdge(source="bull:" + ticker, target="judge:" + ticker, label="synthesis"));
        edges.append(GraphEdge(source="bear:" + ticker, target="judge:" + ticker, label="synthesis"));
    }
    return GraphData(nodes=nodes, edges=edges);
}

class JacAnalysisEngine {
    has _fallback: RuleBasedAnalysisEngine;

    def __init__(self: JacAnalysisEngine, fallback: RuleBasedAnalysisEngine | None = None) {
        if fallback is not None {
            self._fallback = fallback;
        } else {
            self._fallback = RuleBasedAnalysisEngine();
        }
    }

    def analyze(self: JacAnalysisEngine, request: AnalysisRequest, emit: any) -> AnalysisResult {
        holdings = request.portfolio.holdings;
        tickers: list[str] = [];
        for h in holdings {
            tickers.append(h.ticker.strip().upper());
        }

        emit(
            EngineEvent(
                agent="portfolio_ingestor",
                stage="started",
                message="Ingested " + str(len(tickers)) + " tickers for Jac graph execution",
                progress=0.08
            )
        );
        emit(
            EngineEvent(
                agent="jac_graph",
                stage="running",
                message="Running bull/bear coalitions and judge walkers (Jac multi-agent engine)",
                progress=0.15
            )
        );

        fb_raw = os.getenv("ALPHAWALKER_JAC_FALLBACK", "1").lower();
        fallback_on_error = fb_raw in ["1", "true", "yes"];

        rows_raw: list[dict[str, any]] = [];
        try {
            rows_raw = run_jac_pipeline(tickers);
        } except Exception as exc {
            logger.warning("Jac pipeline error: %s", str(exc));
            if not fallback_on_error {
                raise exc;
            }
            emit(
                EngineEvent(
                    agent="jac_graph",
                    stage="degraded",
                    message="Jac engine unavailable (" + str(exc) + "); using deterministic fallback",
                    progress=0.2
                )
            );
            return self._fallback.analyze(request, emit);
        }

        by_ticker: dict[str, dict[str, any]] = {};
        for r in rows_raw {
            if isinstance(r, dict) {
                tk = str(r.get("ticker", "")).upper();
                by_ticker[tk] = r;
            }
        }

        holding_results: list[HoldingAnalysis] = [];
        recommendations: list[Recommendation] = [];
        weighted_risk: float = 0.0;
        sentiment_scores: list[int] = [];
        n_hold: int = len(holdings);
        if n_hold < 1 {
            n_hold = 1;
        }

        i: int = 0;
        for holding in holdings {
            i = i + 1;
            t = holding.ticker.strip().upper();
            row: dict[str, any] = {};
            if t in by_ticker {
                row = by_ticker[t];
            }
            sentiment = _sentiment_from_row(
                str(row.get("verdict", "")),
                int(row.get("bull_confidence", 0) or 0),
                int(row.get("bear_confidence", 0) or 0)
            );
            risk = _risk_score(row, holding.weight);
            weighted_risk = weighted_risk + (float(risk) * holding.weight);
            if sentiment == "positive" {
                sentiment_scores.append(1);
            } elif sentiment == "negative" {
                sentiment_scores.append(-1);
            } else {
                sentiment_scores.append(0);
            }

            holding_results.append(
                HoldingAnalysis(
                    ticker=t,
                    weight=_round4(holding.weight),
                    risk_score=risk,
                    sentiment=sentiment,
                    summary=_summary(row, holding.weight, risk, sentiment)
                )
            );

            if request.options.include_rebalancing and (holding.weight >= 0.2 or risk >= 70) {
                tw = holding.weight * 0.75;
                if tw < 0.05 {
                    tw = 0.05;
                }
                recommendations.append(
                    Recommendation(
                        ticker=t,
                        action="reduce",
                        reason="concentration or elevated risk from Jac synthesis",
                        target_weight=_round4(tw)
                    )
                );
            }

            prog: float = 0.2 + 0.55 * float(i) / float(n_hold);
            if prog > 0.75 {
                prog = 0.75;
            }
            emit(
                EngineEvent(
                    agent="risk_analyzer",
                    stage="running",
                    message="Jac synthesis complete for " + t + " (risk " + str(risk) + ")",
                    progress=prog
                )
            );
        }

        overall_risk = int(weighted_risk + 0.5);
        risk_band = _risk_band(overall_risk);
        sentiment_summary = _sentiment_summary(sentiment_scores);

        if request.options.include_rebalancing and len(recommendations) == 0 and len(holding_results) > 0 {
            best = holding_results[0];
            for h in holding_results {
                if h.risk_score < best.risk_score {
                    best = h;
                }
            }
            recommendations.append(
                Recommendation(
                    ticker=best.ticker,
                    action="maintain",
                    reason="Jac graph suggests no mandatory trim vs. current policy",
                    target_weight=_round4(best.weight)
                )
            );
        }

        emit(
            EngineEvent(
                agent="sentiment_agent",
                stage="running",
                message="Aggregated cross-holding sentiment from Jac coalitions",
                progress=0.85
            )
        );
        emit(
            EngineEvent(
                agent="judge_agent",
                stage="completed",
                message="Jac judge walkers finished; portfolio verdict materialized",
                progress=1.0
            )
        );

        out_graph: GraphData = GraphData();
        if request.options.include_graph {
            g_tickers: list[str] = [];
            for h in holdings {
                g_tickers.append(h.ticker.strip().upper());
            }
            out_graph = _build_graph(g_tickers);
        }

        rec_out: list[Recommendation] = [];
        if request.options.include_rebalancing {
            rec_out = recommendations;
        }

        return AnalysisResult(
            overall_risk_score=overall_risk,
            risk_band=risk_band,
            sentiment_summary=sentiment_summary,
            rebalancing_suggestions=rec_out,
            holdings=holding_results,
            graph=out_graph
        );
    }
}

"""FastAPI application exposing AlphaWalker analysis runs.

Analysis executes the Jac multi-agent graph (`alphawalker_pipeline.jac`) by default,
with SQLite-backed run state for polling. See `DEPLOYMENT.md` for env vars.
