        if tab == "completed" {
            if upd != "" {
                return "Finished " + upd;
            }
            return "Completed";
        }
        if tab == "overdue" {
            if due != "" {
                return "Was due " + due;
            }
            if exp != "" {
                return "Target was " + exp;
            }
            return "Overdue";
        }
        return "";
    }

