"""
Legal AI Agentic System - Jac-compatible rewrite.
Uses walker/node/enum graph primitives with correct Jac syntax.
"""

import os;
import requests;
import json;
import from jaclang.byllm.lib { Model }

glob llm: Model = Model(model_name="ollama/qwen2.5");

# ---------------------------------------------------------------------------
# Enum
# ---------------------------------------------------------------------------

enum ImmigrationAspect {
    CASE_ASSESSMENT,
    RIGHTS_PROTECTIONS,
    URGENT_STEPS,
    CRITICAL_WARNINGS,
    FOLLOW_UP_QUESTIONS,
    LEGAL_GLOSSARY,
    HELP_CONTACTS,
    PROCESS_OUTLOOK
}

# ---------------------------------------------------------------------------
# Nodes
# ---------------------------------------------------------------------------

node LegalNode {
    has aspect: ImmigrationAspect;
    has label: str = "";
    has value: str = "";
    has is_ready: bool = False;
    has history: list = [];
    has model: str = "qwen2.5";
    has loop_count: int = 0;
    has dataset: str = "";
    has is_done: bool = False;
    has final_summary: str = "";

    def load_context() -> str {
        import os;
        docs_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "docs");
        doc_path = os.path.join(docs_dir, self.label + ".md");
        if os.path.exists(doc_path) {
            with open(doc_path, "r") as f {
                return f.read();
            }
        }
        return "";
    }

    def get_advice(user_situation: str, context: str) -> str by llm;

    def get_follow_up_questions(user_situation: str, context: str) -> list[str] by llm;

    # Bypassing EVERYTHING to test the pipe (mock legalNode retrieve_value)
    def retrieve_value(prompt: str) -> str {
        return "The system is working! This is mock data for " + self.label;
    }

    def generate_summary() -> str {
        self.final_summary = (
            "Immigration Case Summary for " + self.label + ":\n\n"
            + "Advice: Based on INA and USCIS policy, document your status and maintain all official correspondence.\n\n"
            + "Key Resources:\n"
            + "- USCIS main portal: uscis.gov\n"
            + "- ICE detainee locator: locator.ice.gov\n"
            + "- AILA attorney finder: aila.org/find-a-lawyer\n\n"
            + "Critical: Do not miss any Notice to Appear (NTA) deadlines."
        );
        return self.final_summary;
    }

    def update_value(new_value: str) {
        self.history.append({
            "previous": self.value,
            "timestamp": "now"
        });
        self.value = new_value;
    }

    def switch_model(new_model: str) {
        # Updated allowed list to include your local qwen
        allowed = ["qwen2.5", "llama3", "ollama", "gpt-4o", "gemini-1.5-pro"];
        if new_model in allowed {
            self.model = new_model;
        }
    }

    def reset() {
        self.history = [];
        self.value = "";
        self.is_ready = False;
        self.loop_count = 0;
        self.is_done = False;
        self.final_summary = "";
    }
}

sem LegalNode.get_advice = """You are an immigration legal assistant. Using ONLY the content in the 'context' parameter (a government/legal reference document), provide specific and actionable advice for the user's situation. Cite relevant form numbers, INA statutes, or deadlines from the document. Do not invent information not present in the context.""";

sem LegalNode.get_advice.user_situation = "The user's immigration situation as they described it.";
sem LegalNode.get_advice.context = "A government or legal reference document covering this specific aspect of US immigration law. Ground your answer strictly in this document.";

sem LegalNode.get_follow_up_questions = """You are an immigration legal assistant. Review the 'Follow-up Questions' section of the context document. Return a list of 2-3 targeted questions from that section that are most relevant to the user's situation and would help clarify the case. If the situation is already fully described and no critical information is missing, return an empty list.""";

sem LegalNode.get_follow_up_questions.user_situation = "The user's immigration situation as described so far.";
sem LegalNode.get_follow_up_questions.context = "A government or legal reference document whose 'Follow-up Questions' section contains question templates for this aspect of immigration law.";

node SummaryNode {
    has value: str = "";
    has is_ready: bool = False;
    has generated_at_loop: int = 0;
}

node DocumentChunk {
    has content: str = "";
    has source: str = "";
    has topic: str = "";
}

# ---------------------------------------------------------------------------
# Walkers
# ---------------------------------------------------------------------------

walker:pub SwitchModel {
    has target_label: str = "";
    has new_model: str = "";

    can visit_root with Root entry {
        visit [-->];
    }

    can do_switch with LegalNode entry {
        if here.label == self.target_label or self.target_label == "all" {
            here.switch_model(self.new_model);
            report {
                "label": here.label,
                "model": here.model
            };
        }
        visit [-->];
    }
}

# ---------------------------------------------------------------------------

walker:pub AnalyzeSituation {
    has user_input: str = "";
    has results: dict = {};

    can visit_root with Root entry {
        visit [-->];
    }

    can visit_node with LegalNode entry {
        here.reset();
        new_val = here.retrieve_value(self.user_input);
        here.update_value(new_val);

        self.results[here.label] = {
            "value": here.retrieve_value(self.user_input),
            "model": here.model,
            "is_ready": here.is_ready,
            "loop_count": here.loop_count
        };

        # visit [-->];
    }

    can report_results with Root exit {
        report self.results;
    }
}

# ---------------------------------------------------------------------------

walker:pub FollowUp {
    has original_input: str = "";
    has follow_up_answer: str = "";
    has accumulated_context: str = "";
    has max_loops: int = 3;
    has results: dict = {};
    has limit_reached: bool = False;
    has node_outputs: dict = {};

    can start with Root entry {
        self.accumulated_context = (
            self.original_input
            + " Additional context from follow-up: "
            + self.follow_up_answer
        );

        for n in [-->] {
            if isinstance(n, LegalNode) {
                self.node_outputs[n.label] = n.value;
            }
        }

        visit [-->];
    }

    can collect with LegalNode entry {
        if here.loop_count >= self.max_loops {
            self.limit_reached = True;
            self.node_outputs[here.label] = here.value;
            visit [-->];
            return;
        }

        if here.label == "follow_up_questions" {
            questions = here.get_follow_up_questions(
                user_situation=self.accumulated_context,
                context=here.load_context()
            );
            if len(questions) == 0 {
                here.is_done = True;
                here.generate_summary();
                here.update_value("No further questions needed.");
            } else {
                here.update_value("\n".join(questions));
            }
        } else {
            new_val = here.retrieve_value(self.accumulated_context);
            here.update_value(new_val);
        }

        self.results[here.label] = {
            "value": here.value,
            "model": here.model,
            "loop_count": here.loop_count,
            "history_count": len(here.history),
            "limit_reached": False,
            "is_done": here.is_done,
            "final_summary": here.final_summary
        };
        visit [-->];
    }

    can finish with Root exit {
        if self.limit_reached {
            summarizer = Summarize(
                node_outputs=self.node_outputs,
                accumulated_context=self.accumulated_context
            );
            root spawn summarizer;
        } else {
            report {
                "results": self.results,
                "limit_reached": False
            };
        }
    }
}

# ---------------------------------------------------------------------------

walker Summarize {
    has node_outputs: dict = {};
    has accumulated_context: str = "";
    has summary: str = "";

    can build_summary with Root entry {
        assessment  = str(self.node_outputs.get("case_assessment", ""));
        rights      = str(self.node_outputs.get("rights_protections", ""));
        urgent      = str(self.node_outputs.get("urgent_steps", ""));
        warnings    = str(self.node_outputs.get("critical_warnings", ""));
        who         = str(self.node_outputs.get("help_contacts", ""));
        outlook     = str(self.node_outputs.get("process_outlook", ""));

        self.summary = (
            "IMMIGRATION CASE SUMMARY\n\n"
            + "Situation Assessment: " + assessment + "\n\n"
            + "Your Rights: " + rights + "\n\n"
            + "Do This Now: " + urgent + "\n\n"
            + "Avoid This: " + warnings + "\n\n"
            + "Who to Contact: " + who + "\n\n"
            + "What Happens Next: " + outlook + "\n\n"
            + "Full context gathered: " + self.accumulated_context
        );

        for n in [-->] {
            if isinstance(n, SummaryNode) {
                n.value = self.summary;
                n.is_ready = True;
                n.generated_at_loop = 3;
            }
        }

        report {
            "summary": self.summary,
            "limit_reached": True,
            "message": "Maximum follow-up rounds reached. Here is your full case summary to share with an immigration attorney."
        };
    }
}

# ---------------------------------------------------------------------------

walker GetHistory {
    has target_label: str = "all";
    has results: list = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with LegalNode entry {
        if here.label == self.target_label or self.target_label == "all" {
            self.results.append({
                "label": here.label,
                "current_value": here.value,
                "model": here.model,
                "loop_count": here.loop_count,
                "history": here.history
            });
        }
        visit [-->];
    }
}

# ---------------------------------------------------------------------------

walker:pub ResetAll {
    has results: list = [];

    can start with Root entry {
        visit [-->];
    }

    can do_reset with LegalNode entry {
        here.reset();
        self.results.append({"label": here.label, "status": "reset"});
        visit [-->];
    }

    can finish with Root exit {
        report self.results;
    }
}

# ---------------------------------------------------------------------------

walker IngestDocument {
    has content: str = "";
    has source: str = "";
    has topic: str = "";

    can ingest with Root entry {
        chunks = self.chunk_text(self.content);
        for chunk in chunks {
            doc = DocumentChunk(
                content=chunk,
                source=self.source,
                topic=self.topic
            );
            here ++> doc;
        }
        report {"status": "ingested", "chunks": len(chunks)};
    }

    def chunk_text(text: str) -> list {
        words = text.split(" ");
        chunks = [];
        chunk_size = 200;
        i = 0;
        while i < len(words) {
            chunk = " ".join(words[i:i + chunk_size]);
            chunks.append(chunk);
            i += chunk_size;
        }
        return chunks;
    }
}

# ---------------------------------------------------------------------------
# Graph bootstrap
# ---------------------------------------------------------------------------

with entry {
    case_assessment_node = root ++> LegalNode(
        label="case_assessment",
        aspect=ImmigrationAspect.CASE_ASSESSMENT
    );

    rights_protections_node = root ++> LegalNode(
        label="rights_protections",
        aspect=ImmigrationAspect.RIGHTS_PROTECTIONS
    );

    urgent_steps_node = root ++> LegalNode(
        label="urgent_steps",
        aspect=ImmigrationAspect.URGENT_STEPS
    );
    critical_warnings_node = root ++> LegalNode(
        label="critical_warnings",
        aspect=ImmigrationAspect.CRITICAL_WARNINGS
    );
    follow_up_questions_node = root ++> LegalNode(
        label="follow_up_questions",
        aspect=ImmigrationAspect.FOLLOW_UP_QUESTIONS
    );
    legal_glossary_node = root ++> LegalNode(
        label="legal_glossary",
        aspect=ImmigrationAspect.LEGAL_GLOSSARY
    );
    help_contacts_node = root ++> LegalNode(
        label="help_contacts",
        aspect=ImmigrationAspect.HELP_CONTACTS
    );
    case_summary = root ++> LegalNode(
        label="case_summary",
        aspect=ImmigrationAspect.PROCESS_OUTLOOK
    );
}

import from server {
    LegalNode, SummaryNode, DocumentChunk, ImmigrationAspect,
    SwitchModel, AnalyzeSituation, FollowUp, Summarize, GetHistory,
    ResetAll, IngestDocument
}

# ---------------------------------------------------------------------------
# Test 1: AnalyzeSituation populates all 8 nodes
# ---------------------------------------------------------------------------

walker TestAnalyzeSituation {
    has test_input: str = "I received a Notice to Appear and my green card application is pending.";
    has passed: bool = False;

    can run with Root entry {
        analyzer = root spawn AnalyzeSituation(user_input=self.test_input);

        results = analyzer.results;
        expected_keys = [
            "case_assessment", "rights_protections", "urgent_steps", "critical_warnings",
            "follow_up_questions", "legal_glossary", "help_contacts", "process_outlook"
        ];

        all_present = True;
        for key in expected_keys {
            if key not in results {
                all_present = False;
            } elif results[key]["value"] == "" {
                all_present = False;
            }
        }

        self.passed = all_present;
        report {
            "test": "TestAnalyzeSituation",
            "passed": self.passed,
            "result_keys": list(results.keys())
        };
    }
}

# ---------------------------------------------------------------------------
# Test 2: SwitchModel updates the correct node's model
# ---------------------------------------------------------------------------

walker TestSwitchModel {
    has passed: bool = False;

    can run with Root entry {
        root spawn SwitchModel(
            target_label="case_assessment",
            new_model="claude-sonnet-4-6"
        );

        for n in [root -->] {
            if isinstance(n, LegalNode) and n.label == "case_assessment" {
                self.passed = (n.model == "claude-sonnet-4-6");
            }
        }

        report {
            "test": "TestSwitchModel",
            "passed": self.passed
        };
    }
}

# ---------------------------------------------------------------------------
# Test 3: SwitchModel rejects invalid models
# ---------------------------------------------------------------------------

walker TestSwitchModelInvalid {
    has passed: bool = False;

    can run with Root entry {
        root spawn SwitchModel(
            target_label="rights_protections",
            new_model="fake-model-xyz"
        );

        for n in [root -->] {
            if isinstance(n, LegalNode) and n.label == "rights_protections" {
                self.passed = (n.model != "fake-model-xyz");
            }
        }

        report {
            "test": "TestSwitchModelInvalid",
            "passed": self.passed
        };
    }
}

# ---------------------------------------------------------------------------
# Test 4: ResetAll clears all nodes
# ---------------------------------------------------------------------------

walker TestResetAll {
    has passed: bool = False;

    can run with Root entry {
        # First populate nodes
        root spawn AnalyzeSituation(user_input="Test input for reset.");

        # Then reset
        root spawn ResetAll();

        # Check all nodes are cleared
        all_reset = True;
        for n in [root -->] {
            if isinstance(n, LegalNode) {
                if n.value != "" or n.loop_count != 0 or n.is_ready != False {
                    all_reset = False;
                }
            }
        }

        self.passed = all_reset;
        report {
            "test": "TestResetAll",
            "passed": self.passed
        };
    }
}

# ---------------------------------------------------------------------------
# Test 5: FollowUp accumulates context and updates nodes
# ---------------------------------------------------------------------------

walker TestFollowUp {
    has passed: bool = False;

    can run with Root entry {
        # First analyze
        root spawn AnalyzeSituation(user_input="My H-1B visa expires next month.");

        # Then follow up
        followup = root spawn FollowUp(
            original_input="My H-1B visa expires next month.",
            follow_up_answer="My employer has already filed an I-129 extension petition."
        );

        results = followup.results;
        self.passed = len(results) > 0;

        report {
            "test": "TestFollowUp",
            "passed": self.passed,
            "result_keys": list(results.keys())
        };
    }
}

# ---------------------------------------------------------------------------
# Test 6: FollowUp hits max_loops and triggers Summarize
# ---------------------------------------------------------------------------

walker TestMaxLoops {
    has passed: bool = False;

    can run with Root entry {
        root spawn AnalyzeSituation(user_input="I am applying for a green card through my spouse.");

        i = 0;
        followup = FollowUp(
            original_input="I am applying for a green card through my spouse.",
            follow_up_answer="Answer number 1"
        );
        while i < 3 {
            followup = root spawn FollowUp(
                original_input="I am applying for a green card through my spouse.",
                follow_up_answer="Answer number " + str(i + 1)
            );
            i += 1;
        }

        self.passed = followup.limit_reached;
        report {
            "test": "TestMaxLoops",
            "passed": self.passed,
            "limit_reached": followup.limit_reached
        };
    }
}

# ---------------------------------------------------------------------------
# Test 7: IngestDocument creates DocumentChunk nodes
# ---------------------------------------------------------------------------

walker TestIngestDocument {
    has passed: bool = False;

    can run with Root entry {
        root spawn IngestDocument(
            content="Green card applicants must file Form I-485 to adjust status. Asylum seekers must file Form I-589 within one year of arrival in the United States.",
            source="USCIS Policy Manual",
            topic="green_card_asylum"
        );

        chunk_count = 0;
        for n in [root -->] {
            if isinstance(n, DocumentChunk) {
                chunk_count += 1;
            }
        }

        self.passed = (chunk_count > 0);
        report {
            "test": "TestIngestDocument",
            "passed": self.passed,
            "chunk_count": chunk_count
        };
    }
}

# ---------------------------------------------------------------------------
# Run all tests
# ---------------------------------------------------------------------------

with entry {
    # Bootstrap the graph for testing
    root ++> LegalNode(label="case_assessment", aspect=ImmigrationAspect.CASE_ASSESSMENT);
    root ++> LegalNode(label="rights_protections", aspect=ImmigrationAspect.RIGHTS_PROTECTIONS);
    root ++> LegalNode(label="urgent_steps", aspect=ImmigrationAspect.URGENT_STEPS);
    root ++> LegalNode(label="critical_warnings", aspect=ImmigrationAspect.CRITICAL_WARNINGS);
    root ++> LegalNode(label="follow_up_questions", aspect=ImmigrationAspect.FOLLOW_UP_QUESTIONS);
    root ++> LegalNode(label="legal_glossary", aspect=ImmigrationAspect.LEGAL_GLOSSARY);
    root ++> LegalNode(label="help_contacts", aspect=ImmigrationAspect.HELP_CONTACTS);
    root ++> LegalNode(label="process_outlook", aspect=ImmigrationAspect.PROCESS_OUTLOOK);
    root ++> SummaryNode();

    print("Running test suite...\n");

    r1 = root spawn TestAnalyzeSituation();
    print("TestAnalyzeSituation: ", r1);

    r2 = root spawn TestSwitchModel();
    print("TestSwitchModel: ", r2);

    r3 = root spawn TestSwitchModelInvalid();
    print("TestSwitchModelInvalid: ", r3);

    r4 = root spawn TestResetAll();
    print("TestResetAll: ", r4);

    r5 = root spawn TestFollowUp();
    print("TestFollowUp: ", r5);

    r6 = root spawn TestMaxLoops();
    print("TestMaxLoops: ", r6);

    r7 = root spawn TestIngestDocument();
    print("TestIngestDocument: ", r7);

    print("\nAll tests complete.");
}

import from ..services.recognition { recognize_lego_frame, get_llm_color }
import from byllm.lib { Image }

def:pub CountdownApp() -> JsxElement {
    has analyzing: bool = False;
    has status: str = "Camera ready";
    has permission: str = "Idle";
    has camera_active: bool = False;
    has captured_frame: str = "";
    has active_name: str = "No result yet";
    has active_confidence: str = "";
    has active_notes: str = "Start the webcam and capture a snapshot to identify a LEGO part.";
    has active_part_id: str = "—";
    has active_years: str = "Unknown";
    has active_years_start: str = "";
    has active_years_end: str = "";
    has active_years_source: str = "BrickLink";
    has active_release_range: str = "Unknown";
    has active_known_colors: list = [];
    has active_known_colors_label: str = "Unknown";
    has active_known_colors_source: str = "BrickLink";
    has active_bricklink_url: str = "";
    has provider: str = "Brickognize";
    has payload_text: str = "image/png · 0 bytes";
    has candidate_text: str = "0 matches returned";
    has llm_predict_color: str = "Unknown";

    def get_video() -> any {
        return document.getElementById("scanner-video");
    }

    def get_canvas() -> any {
        return document.getElementById("scanner-canvas");
    }

    def normalize_known_colors(payload: any) -> list {
        if payload == None {
            return [];
        }

        if payload and payload.length != None {
            normalized = [];
            for item in payload {
                color_name = str(item).strip();
                if color_name != "" and color_name not in normalized {
                    normalized = normalized + [color_name];
                }
            }
            return normalized;
        }

        raw_text = str(payload).strip();
        if raw_text == "" {
            return [];
        }

        normalized_text = raw_text.replace(" / ", ",").replace("|", ",").replace(";", ",");
        colors = [];
        for piece in normalized_text.split(",") {
            color_name = piece.strip();
            if color_name != "" and color_name not in colors {
                colors = colors + [color_name];
            }
        }
        return colors;
    }

    def clear_stream() -> None {
        stream: any = globalThis.__legoScannerStream;
        if stream {
            for track in stream.getTracks() {
                track.stop();
            }
        }
        video = get_video();
        if video {
            try {
                video.pause();
            } except Exception {
            }
            video.srcObject = None;
        }
        globalThis.__legoScannerStream = None;
        camera_active = False;
    }

    async def start_camera() -> None {
        try {
            permission = "Requesting";
            status = "Requesting webcam access...";
            camera_active = False;

            media_devices: any = (navigator as any).mediaDevices;
            if not media_devices or not media_devices.getUserMedia {
                permission = "Unavailable";
                status = "This browser does not support webcam access";
                return;
            }

            clear_stream();

            video = get_video();
            if not video {
                permission = "Unavailable";
                status = "Video element not found";
                return;
            }

            video.muted = True;
            video.autoplay = True;
            video.playsInline = True;
            video.setAttribute("autoplay", "true");
            video.setAttribute("muted", "true");
            video.setAttribute("playsinline", "true");

            stream: any = await media_devices.getUserMedia({"video": True, "audio": False});
            if not stream {
                permission = "Unavailable";
                status = "Unable to create webcam stream";
                return;
            }

            tracks: any = stream.getVideoTracks();
            if not tracks or len(tracks) == 0 {
                clear_stream();
                permission = "Unavailable";
                status = "No video track available";
                return;
            }

            video.srcObject = stream;
            globalThis.__legoScannerStream = stream;

            try {
                await video.play();
            } except Exception {
            }

            permission = "Granted";
            camera_active = True;
            status = "Webcam active";
        } except Exception as e {
            clear_stream();
            permission = "Denied";
            status = "Unable to start webcam: " + str(e);
        }
    }

    def stop_camera() -> None {
        clear_stream();
        permission = "Stopped";
        status = "Camera stopped";
    }

    async def analyze_frame(frame_data: str) -> None {
        analyzing = True;
        status = "Analyzing snapshot...";
        try {
            result = await recognize_lego_frame(frame_data);
            if result and result["success"] {
                match_info = result["active_match"] or {};
                telemetry = result["telemetry"] or {};
                years_info = (match_info and match_info["years_released"]) or {};
                known_colors_info = (match_info and match_info["known_colors"]) or {};
                active_name = str((match_info and match_info["name"]) or "Unknown part");
                active_confidence = str((match_info and match_info["confidence"]) or "");
                active_notes = str((match_info and match_info["notes"]) or "Recognition complete.");
                active_part_id = str((match_info and match_info["specific_part_number"]) or (match_info and match_info["part_id"]) or "—");
                years_label = (years_info and years_info["label"]) or (match_info and match_info["years_released_label"]) or "Unknown";
                years_start = (years_info and years_info["start"]) or (match_info and match_info["years_released_start"]) or "";
                years_end = (years_info and years_info["end"]) or (match_info and match_info["years_released_end"]) or "";
                active_years = str(years_label);
                active_years_start = str(years_start);
                active_years_end = str(years_end);
                if years_start != "" and years_end != "" {
                    active_release_range = str((years_start == years_end) and years_start or (str(years_start) + " → " + str(years_end)));
                } elif years_start != "" {
                    active_release_range = str(years_start);
                } else {
                    active_release_range = "Unknown";
                }
                active_years_source = str((years_info and years_info["source"]) or (match_info and match_info["years_released_source"]) or "BrickLink");
                active_known_colors = normalize_known_colors((known_colors_info and known_colors_info["items"]) or (known_colors_info and known_colors_info["label"]) or []);
                active_known_colors_source = str((known_colors_info and known_colors_info["source"]) or "BrickLink");
                active_bricklink_url = str(match_info["bricklink_url"] or "");
                provider = str(telemetry["provider"] or "Brickognize");
                payload_text = str(telemetry["mime_type"] or "image/png") + " · " + str(telemetry["bytes"] or 0) + " bytes";
                candidate_text = str(telemetry["candidate_count"] or 0) + " matches returned";
                llm_predict_color = "Unknown";
                status = "Analysis complete";
            } else {
                status = str((result and result["error"]) or "Recognition failed");
            }
        } except Exception as e {
            status = "Recognition failed: " + str(e);
        }
        analyzing = False;
    }

    async def capture_frame() -> None {
        if analyzing {
            status = "Recognition already in progress";
            return;
        }
        video = get_video();
        canvas = get_canvas();
        if not video or not canvas {
            status = "Camera surface not ready";
            return;
        }
        if not video.srcObject or not camera_active {
            status = "Start the webcam first";
            return;
        }
        width = int(video.videoWidth or 640);
        height = int(video.videoHeight or 480);
        canvas.width = width;
        canvas.height = height;
        context = canvas.getContext("2d");
        if not context {
            status = "Unable to capture snapshot";
            return;
        }
        context.drawImage(video, 0, 0, width, height);
        frame_data = canvas.toDataURL("image/png");
        captured_frame = frame_data;
        await analyze_frame(frame_data);
        llm_predict_color = await get_llm_color(frame_data, active_known_colors);
    }

    return (
        <div className="mx-auto grid max-w-6xl gap-6 px-4 py-6 lg:grid-cols-[1.2fr_0.8fr]">
            <section className="rounded-3xl border border-border/90 bg-card/95 p-6 shadow-card backdrop-blur sm:p-8">
                <div className="flex flex-wrap items-center justify-between gap-3">
                    <div>
                        <p className="text-sm font-medium tracking-wide text-sky-200">LEGO recognition</p>
                        <h1 className="mt-1 text-3xl font-semibold text-white sm:text-4xl">Minimal scanner</h1>
                    </div>
                    <div className="rounded-full border border-slate-600 bg-slate-900/80 px-3 py-1 text-sm font-medium text-slate-100">{permission}</div>
                </div>

                <p className="mt-4 max-w-2xl text-sm leading-6 text-slate-300">Use the webcam, capture a snapshot, and send the image to Brickognize for part recognition. After the piece is identified, BrickLink is used to look up the known color variants and release-year details for that part.</p>

                <div className="mt-6 overflow-hidden rounded-2xl border border-slate-700 bg-black shadow-inner shadow-black/30">
                    <div className="relative min-h-80 bg-neutral-950">
                        <video id="scanner-video" className="h-full min-h-80 w-full object-cover" autoPlay={True} muted={True} playsInline={True}></video>
                        {not camera_active and (<div className="absolute inset-0 flex items-center justify-center bg-black/60 px-6 text-center text-sm text-white/80">
                            Start the webcam to preview the live camera feed.
                        </div>)}
                    </div>
                </div>

                <canvas id="scanner-canvas" className="hidden"></canvas>

                <div className="mt-5 flex flex-wrap gap-3">
                    <button className="rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground transition hover:bg-sky-300 focus:outline-none focus:ring-2 focus:ring-sky-300/40" onClick={start_camera}>Start webcam</button>
                    <button className="rounded-xl border border-slate-600 bg-slate-900/80 px-4 py-2.5 text-sm font-medium text-slate-100 transition hover:bg-slate-800 focus:outline-none focus:ring-2 focus:ring-sky-300/30 disabled:cursor-not-allowed disabled:opacity-60" onClick={capture_frame} disabled={analyzing or (not camera_active)}>{analyzing and "Analyzing..." or "Capture snapshot"}</button>
                    <button className="rounded-xl border border-slate-600 bg-slate-950/80 px-4 py-2.5 text-sm font-medium text-slate-200 transition hover:bg-slate-800 focus:outline-none focus:ring-2 focus:ring-sky-300/30" onClick={stop_camera}>Stop webcam</button>
                </div>

                <div className="mt-4 rounded-2xl border border-slate-700 bg-slate-950/70 px-4 py-3 text-sm text-slate-300">
                    <span className="mr-2 font-semibold text-white">Status:</span>{status}
                </div>
            </section>

            <section className="flex flex-col gap-6">
                <div className="rounded-3xl border border-border/90 bg-card/95 p-6 shadow-soft backdrop-blur">
                    <p className="text-sm font-medium tracking-wide text-sky-200">Result</p>
                    <h2 className="mt-1 text-2xl font-semibold text-white">Top match</h2>
                    <div className="grid w-full mt-4 rounded-2xl border border-slate-700 bg-slate-950/70 p-4">
                        <div className="flex items-start justify-between gap-3">
                            <div>
                                <p className="grid w-full grid-cols-[1fr_auto] items-center text-xs uppercase tracking-[0.2em] text-slate-400">
                                    <span>Detected part</span>
                                    {active_confidence and (<span className="rounded-full border border-slate-600 bg-slate-900/90 px-3 py-1 text-sm font-semibold normal-case tracking-normal text-white">
                                        {active_confidence}
                                    </span>)}
                                </p>

                                <h3 className="mt-1 text-lg font-semibold text-white">{active_name}</h3>
                                <div className="mt-3 flex flex-wrap gap-2">
                                    <div className="inline-flex items-center gap-2 rounded-full border border-violet-400/30 bg-violet-400/10 px-3 py-1.5 text-sm text-violet-100">
                                        <span className="text-[11px] font-medium uppercase tracking-wide text-violet-200/80">Years</span>
