walker :pub list_sessions {
    has phone_number: str;

    can start with Root entry {
        anchor = root;
        all_sessions = [s for s in [anchor -->][?:UserSession] if s.phone_number == self.phone_number];
        summaries: list = [];
        for s in all_sessions {
            msg_count = len(s.transcript);
            first_user_msg = "";
            for m in s.transcript {
                role = m["role"] if isinstance(m, dict) else m.role;
                content = m["content"] if isinstance(m, dict) else m.content;
                if role == "user" {
                    first_user_msg = content[:80];
                    break;
                }
            }
            summaries.append({
                "session_id": s.session_id,
                "created_at": s.created_at,
                "updated_at": s.updated_at,
                "message_count": msg_count,
                "preview": first_user_msg,
                "location": s.location,
                "symptoms": s.extracted_symptoms[:3],
                "intervention_active": s.intervention_active
            });
        }
        summaries = sorted(summaries, key=lambda (x: dict) { x["updated_at"]; }, reverse=True);
        report {"sessions": summaries};
    }
}

walker :pub load_session {
    has session_id: str;

    can start with Root entry {
        session = find_session(self.session_id);
        if session == None {
            report {"error": "Session not found"};
            disengage;
        }
        report build_payload(session, "", False);
    }
}

walker :pub load_demo {
    has case_id: int = 1;

    can start with Root entry {
        sid = new_session_id();
        now = iso_now();
        session: UserSession = root ++> UserSession(session_id=sid, created_at=now, updated_at=now);
        messages = [
            "I've been dizzy for two days and I missed one of my blood pressure pills. I'm in Austin, TX.",
            "I've had nausea and stomach pain since yesterday evening. I'm in Denver, CO.",
            "I feel like I want to die. Nothing is worth it anymore."
        ];
        msg = messages[0];
        if self.case_id == 2 { msg = messages[1]; }
        elif self.case_id == 3 { msg = messages[2]; }
        payload = run_pipeline(session, msg);
        commit();
        report payload;
    }
}

"""Summary agent — generates a grounded care coordination summary."""

import from ..models.session { UserSession, CareSummary }
import from ..services.common { transcript_excerpt }

def _is_icd_code(s: str) -> bool {
    if len(s) < 3 { return False; }
    first_upper = s[0].isupper();
    second_digit = s[1].isdigit();
    return first_upper and second_digit;
}

def _natural_symptoms(raw: list) -> list {
    result: list = [];
    for s in raw {
        words = s.strip().split();
        if words and not _is_icd_code(words[0]) {
            result.append(s);
        }
    }
    return result;
}

def _build_summary(session: UserSession, code_labels: list, specs: list) -> str {
    parts: list = [];

    readable = _natural_symptoms(session.extracted_symptoms);
    if readable {
        parts.append("The patient reported: " + ", ".join(readable[:5]) + ".");
    } elif session.extracted_symptoms {
        parts.append("The patient reported " + str(len(session.extracted_symptoms)) + " symptom(s).");
    }

    if code_labels {
        parts.append("Conditions considered: " + "; ".join(code_labels[:3]) + ".");
    }

    if specs {
        step = "Referral to " + " or ".join(specs[:2]) + " recommended for further evaluation.";
        parts.append(step);
    } elif session.provider_options {
        parts.append(str(len(session.provider_options)) + " provider(s) matched for follow-up.");
    }

    if not parts {
        return "Session summary pending.";
    }
    return " ".join(parts);
}

def run_summary_agent(session: UserSession) -> str {
    if not session.location or session.location.strip() == "" {
        return session.summary_text if session.summary_text else "";
    }
    if not session.assigned_codes or len(session.assigned_codes) == 0 {
        return session.summary_text if session.summary_text else "";
    }

    session.agent_path.append("Summary Agent:active");

    code_labels: list = [];
    for c in session.assigned_codes {
        if isinstance(c, dict) {
            code_labels.append(c["code"] + " — " + c["description"]);
        } else {
            code_labels.append(c.code + " — " + c.description);
        }
    }

    specs: list = [];
    for p in session.provider_options {
        spec = p["specialty"] if isinstance(p, dict) else p.specialty;
        if spec not in specs { specs.append(spec); }
    }

    summary = _build_summary(session, code_labels, specs);
    session.summary_text = summary;
    session.agent_path.append("Summary Agent:completed");
    return summary;
}

def build_care_summary(session: UserSession) -> CareSummary {
    excerpt = transcript_excerpt(session.transcript, 6);
    return CareSummary(
        symptom_codes=session.assigned_codes,
        provider_options=session.provider_options,
        summary=session.summary_text if session.summary_text else "",
        location=session.location if session.location else "",
        insurance=session.insurance if session.insurance else "",
        risk_flags=session.risk_flags,
        agent_path=session.agent_path,
        transcript_excerpt=excerpt
    );
}

"""Root application shell. Owns all session and auth state."""

import "../styles/main.css";

import from react { useEffect }

import from ..agents.orchestrator {
    create_session,
    process_message,
    export_json,
    export_pdf,
    load_demo,
    list_sessions,
    load_session
}
import from ..agents.auth { get_user_by_token, logout }

def set_auth_cookie(token: str) -> None {
    document.cookie = "care_anchor_token=" + token + "; path=/; SameSite=Strict; max-age=604800";
}

def get_auth_cookie() -> str {
    name = "care_anchor_token=";
    parts = document.cookie.split(";");
    for p in parts {
        c = p.strip();
        if c.startswith(name) {
            return c[len(name):];
        }
    }
    return "";
}

def clear_auth_cookie() -> None {
    document.cookie = "care_anchor_token=; path=/; max-age=0";
}

import from .ChatWindow { ChatWindow }
import from .CrisisBanner { CrisisBanner }
import from .LandingPage { LandingPage }
import from .LoginScreen { LoginScreen, format_phone }
import from .SessionList { SessionList }
import from .SessionPdf { build_session_pdf_attachment }
import from .SummaryPanel { SummaryPanel }

def tab_class(active_tab: str, tab_name: str) -> str {
    base = "dashboard-tab";
    if active_tab == tab_name {
        return base + " dashboard-tab--active";
    }
    return base;
}

def empty_session() -> dict {
    return {
        "transcript": [],
        "extracted_symptoms": [],
        "risk_flags": [],
        "assigned_codes": [],
        "provider_options": [],
        "active_agent": "Conversation Agent",
        "agent_trace": [
            {"name": "Intervention Agent", "status": "listening"},
            {"name": "Conversation Agent", "status": "idle"},
            {"name": "Calling Agent", "status": "idle"},
            {"name": "Diagnosis Agent", "status": "idle"},
            {"name": "Messaging Agent", "status": "idle"},
            {"name": "Summary Agent", "status": "idle"}
        ],
        "intervention_active": False,
        "intervention_resolved": False,
        "location": None,
        "insurance": None,
        "summary_text": None,
        "doctor_notes": None,
        "disclaimer": "AnchorCare is an AI-powered care coordination platform. It does not replace emergency care or professional diagnosis."
    };
}

def build_pdf_chat_message(payload: dict, attachment: dict) -> dict {
    timestamp = payload["generated_at"] if "generated_at" in payload else "";
    return {
        "role": "assistant",
        "content": "Your AnchorCare session summary is ready as a PDF attachment.",
        "timestamp": timestamp,
        "agent": "Summary Agent",
        "attachment": attachment
    };
}

def current_path() -> str {
    path = window.location.pathname;
    return path if path != "" else "/";
}

def is_known_route(path: str) -> bool {
    return path == "/" or path == "/login" or path == "/dashboard";
}

def:pub AppShell() -> JsxElement {
    has loggedIn: bool = False;
    has authReady: bool = False;
    has currentPath: str = current_path();
    has phoneNumber: str = "";
    has userId: str = "";
    has authToken: str = "";
    has sessionId: str = "";
    has session: dict = empty_session();
    has draft: str = "";
    has sending: bool = False;
    has booting: bool = False;
    has exportStatus: str = "";
    has errorText: str = "";
    has activeTab: str = "chat";
    has localTranscript: list = [];
    has pastSessions: list = [];
    has showSessions: bool = False;

    def syncRoute() -> None {
        currentPath = current_path();
    }

    def routeTo(path: str, replace: bool = False) -> None {
        target = path if path != "" else "/";
        if currentPath == target and window.location.pathname == target { return; }
        if replace {
            window.history.replaceState(None, "", target);
        } else {
            window.history.pushState(None, "", target);
        }
        currentPath = target;
        window.scrollTo({"top": 0, "left": 0});
    }

    async def fetchSessions(phone: str) -> None {
        try {
            result = root spawn list_sessions(phone_number=phone);
            if len(result.reports) > 0 {
                payload = result.reports[0];
                pastSessions = payload["sessions"] if "sessions" in payload else [];
            }
        } except Exception as e {
            0;
        }
    }

    async def bootstrap(phone: str) -> None {
        booting = True;
        errorText = "";
        exportStatus = "";
        session = empty_session();
        localTranscript = [];
        sessionId = "";
        draft = "";
        try {
            result = root spawn create_session(phone_number=phone);
            if len(result.reports) > 0 {
                payload = result.reports[0];
                sessionId = payload["session_id"];
                session = payload["session"];
                fetchSessions(phone);
            } else {
                errorText = "Unable to start an AnchorCare session. Is the backend running?";
            }
        } except Exception as e {
            errorText = "Connection error. Please check that the backend is running.";
        }
        booting = False;
    }

    async def selectSession(sid: str) -> None {
        if sid == sessionId { showSessions = False; return; }
        booting = True;
        errorText = "";
        exportStatus = "";
        localTranscript = [];
        draft = "";
        try {
            result = root spawn load_session(session_id=sid);
            if len(result.reports) > 0 {
                payload = result.reports[0];
                if "error" in payload {
                    errorText = payload["error"];
                } else {
                    sessionId = payload["session_id"];
                    session = payload["session"];
                    showSessions = False;
                }
            }
        } except Exception as e {
            errorText = "Could not load session.";
        }
        booting = False;
    }

    def setAuthState(user: dict, token: str) -> None {
        phoneNumber = user["phone_number"];
        userId = user["user_id"];
        authToken = token;
        if token != "" { set_auth_cookie(token); }
        loggedIn = True;
    }

    def handleLogin(payload: dict) -> None {
        user = payload["user"];
        token = payload["token"] if "token" in payload else "";
        setAuthState(user, token);
        showSessions = False;
        pastSessions = [];
        bootstrap(user["phone_number"]);
        routeTo("/dashboard", True);
    }

    def handleRestoreLogin(payload: dict) -> None {
        user = payload["user"];
        token = payload["token"] if "token" in payload else "";
        setAuthState(user, token);
        showSessions = False;
        pastSessions = [];
        bootstrap(user["phone_number"]);
    }

    async def handleLogout() -> None {
        if authToken != "" {
            try { root spawn logout(token=authToken); } except Exception as e { 0; }
        }
        clear_auth_cookie();
        loggedIn = False;
        phoneNumber = "";
        userId = "";
        authToken = "";
        sessionId = "";
        session = empty_session();
        draft = "";
        errorText = "";
        exportStatus = "";
        localTranscript = [];
        pastSessions = [];
        showSessions = False;
        routeTo("/login", True);
    }

    async def restoreSession() -> None {
        token = get_auth_cookie();
        if token == "" {
            authReady = True;
            return;
        }
        try {
            result = root spawn get_user_by_token(token=token);
            if len(result.reports) > 0 {
                payload = result.reports[0];
                if "user" in payload {
                    handleRestoreLogin({"user": payload["user"], "token": token});
                } else {
                    clear_auth_cookie();
                }
            }
        } except Exception as e {
            clear_auth_cookie();
        }
        authReady = True;
    }

    useEffect(lambda () {
        syncRoute();
        win: any = window;
        win.onpopstate = lambda (_event: any) { syncRoute(); };
    }, []);

    useEffect(lambda () { restoreSession(); }, []);

    useEffect(lambda () {
        if not authReady { return; }
        if not is_known_route(currentPath) {
            routeTo("/dashboard" if loggedIn else "/", True);
            return;
        }
        if loggedIn and currentPath == "/login" {
            routeTo("/dashboard", True);
            return;
        }
        if not loggedIn and currentPath == "/dashboard" {
            routeTo("/login", True);
        }
    }, [authReady, loggedIn, currentPath]);

    async def send_message() -> None {
        if sending or booting or draft.strip() == "" or sessionId == "" { return; }
        sending = True;
        errorText = "";
        outbound = draft;
        draft = "";
        now_ts = str(Date.now());
        pending_msg = {"role": "user", "content": outbound, "timestamp": now_ts, "agent": "User"};
        localTranscript = localTranscript + ([pending_msg]);
        try {
            result = root spawn process_message(session_id=sessionId, message=outbound);
            if len(result.reports) > 0 {
                payload = result.reports[0];
                if "session" in payload {
                    session = payload["session"];
                    localTranscript = [];
                }
            } else {
                errorText = "The message could not be processed. Please try again.";
                localTranscript = [];
            }
        } except Exception as e {
            errorText = "Network error sending message.";
            localTranscript = [];
        }
        sending = False;
    }

    async def do_export_pdf() -> None {
        if sessionId == "" { return; }
        exportStatus = "Exporting...";
        try {
            result = root spawn export_pdf(session_id=sessionId);
            if len(result.reports) > 0 {
                payload = result.reports[0];
                if "session" in payload {
                    session = payload["session"];
                }
                if "error" in payload {
                    exportStatus = payload["error"];
                } elif "html_content" in payload {
                    attachment = await build_session_pdf_attachment(payload);
                    if attachment != None {
                        localTranscript = localTranscript + ([build_pdf_chat_message(payload, attachment)]);
                        exportStatus = "PDF ready in chat.";
                        activeTab = "chat";
                    } else {
                        exportStatus = "PDF export failed.";
                    }
                } else {
                    exportStatus = "PDF export failed.";
                }
            } else {
                exportStatus = "PDF export failed.";
            }
        } except Exception as e {
            exportStatus = "PDF export failed.";
        }
    }

    async def do_export_json() -> None {
        if sessionId == "" { return; }
        exportStatus = "Exporting...";
        try {
            result = root spawn export_json(session_id=sessionId);
            if len(result.reports) > 0 {
                payload = result.reports[0];
                exportStatus = "JSON saved: " + payload["file_path"];
            }
        } except Exception as e {
            exportStatus = "JSON export failed.";
        }
    }

    async def run_demo(case_id: int) -> None {
        sending = True;
        errorText = "";
        exportStatus = "";
        try {
            result = root spawn load_demo(case_id=case_id);
            if len(result.reports) > 0 {
                payload = result.reports[0];
                sessionId = payload["session_id"];
                session = payload["session"];
                draft = "";
            } else {
                errorText = "Demo case could not be loaded.";
            }
        } except Exception as e {
            errorText = "Error loading demo case.";
        }
        sending = False;
    }

    if currentPath == "/" {
        return <LandingPage
            onGetStarted={lambda () { routeTo("/login"); }}
            onSignIn={lambda () { routeTo("/login"); }}
        />;
    }

    if currentPath == "/login" {
        if loggedIn {
            return <div className="route-loading">
                <div className="route-loading__card panel panel--glass">Opening dashboard...</div>
            </div>;
        }
        return <LoginScreen
            onLogin={handleLogin}
            onGoHome={lambda () { routeTo("/"); }}
        />;
    }

    if not authReady {
        return <div className="route-loading">
            <div className="route-loading__card panel panel--glass">Opening AnchorCare...</div>
        </div>;
    }

    if not loggedIn {
        return <div className="route-loading">
            <div className="route-loading__card panel panel--glass">Redirecting to sign in...</div>
        </div>;
    }

    if showSessions {
        return <div className="session-chooser">
            <header className="session-chooser__header">
                <div className="session-chooser__header-left">
                    <button className="btn btn--sm btn--ghost" onClick={lambda () { showSessions = False; }}>← Back</button>
                    <div className="brand-mark">ANCHORCARE</div>
                </div>
                <div className="header-user">
                    <span className="header-phone">{format_phone(phoneNumber)}</span>
                    <button className="btn btn--sm header-signout" onClick={lambda () { handleLogout(); }}>Sign out</button>
                </div>
            </header>
            <div className="session-chooser__body">
                <section className="session-chooser__hero panel panel--glass">
                    <div className="session-chooser__hero-copy">
                        <div className="panel__eyebrow">Care coordination workspace</div>
                        <h1 className="session-chooser__title">Sessions</h1>
                        <p className="session-chooser__subtitle">Review previous conversations and continue care coordination.</p>
                    </div>
                    <div className="session-chooser__hero-meta">
                        <div className="session-chooser__stat">
                            <span>Saved sessions</span>
                            <strong>{len(str(pastSessions))}</strong>
                        </div>
                    </div>
                </section>
                <SessionList
                    sessions={pastSessions}
                    currentSessionId={sessionId}
                    onSelect={lambda (sid: str) { selectSession(sid); }}
                    onNew={lambda () { showSessions = False; bootstrap(phoneNumber); }}
                />
            </div>
        </div>;
    }

    active_agent = session["active_agent"] if "active_agent" in session else "Conversation Agent";
    intervention_active = session["intervention_active"] if "intervention_active" in session else False;
    risk_flags = session["risk_flags"] if "risk_flags" in session else [];
    disclaimer = session["disclaimer"] if "disclaimer" in session else "AnchorCare is an AI-powered care coordination platform. It does not replace emergency care or professional diagnosis.";
    transcript = session["transcript"] if "transcript" in session else [];
    providers = session["provider_options"] if "provider_options" in session else [];
    summary_text = session["summary_text"] if "summary_text" in session else "";
    session_state = "Preparing session..." if booting else "Session ready";
    combined_transcript = transcript + (localTranscript);

    return <div className="dashboard-shell">
        <div className="dashboard-frame">
            <header className="dashboard-header">
                <div className="dashboard-header__brand">
                    <div className="dashboard-header__logo" aria-hidden="True"></div>
                    <div className="dashboard-header__copy">
                        <div className="brand-mark">ANCHORCARE</div>
                        <h1>AnchorCare Dashboard</h1>
                        <p>{disclaimer}</p>
                    </div>
                </div>

                <div className="dashboard-header__controls">
                    <div className="session-pill">{session_state}</div>
                    <div className="dashboard-tabs">
                        <button
                            type="button"
                            className={tab_class(activeTab, "chat")}
                            onClick={lambda () { activeTab = "chat"; }}
                        >
                            Chat
                        </button>
                        <button
                            type="button"
                            className={tab_class(activeTab, "call")}
                            onClick={lambda () { activeTab = "call"; }}
                        >
                            Call
                        </button>
                    </div>
                    <div className="header-user">
                        <button className="btn btn--sm header-sessions" onClick={lambda () { fetchSessions(phoneNumber); showSessions = True; }}>Sessions</button>
                        <span className="header-phone">{format_phone(phoneNumber)}</span>
                        <button className="btn btn--sm header-signout" onClick={lambda () { handleLogout(); }}>Sign out</button>
                    </div>
                </div>
            </header>

            <CrisisBanner active={intervention_active} riskFlags={risk_flags} />

            {errorText != "" and
                <div className="error-banner">{errorText}</div>
            }

            <main className="dashboard-main">
                <section className="dashboard-main__primary">
                    {activeTab == "chat" and
                        <ChatWindow
                            transcript={combined_transcript}
                            draft={draft}
                            sending={sending or booting}
                            activeAgent={active_agent}
                            onDraftChange={lambda (value: str) { draft = value; }}
                            onSend={lambda () { send_message(); }}
                            onDemo={lambda (case_id: any) { run_demo(case_id); }}
                            onPdf={lambda () { do_export_pdf(); }}
                            onReset={lambda () { bootstrap(phoneNumber); }}
                            exportStatus={exportStatus}
                            exportDisabled={sessionId == ""}
                        />
                    }

                    {activeTab == "call" and
                        <div className="call-stage">
                            <div className="call-stage__badge">Voice workspace</div>
                            <h2>Ready to start a guided phone consultation?</h2>
                            <p>
                                This Jac client now matches the imported dashboard structure.
                                Voice actions are still backend-driven, so this tab currently acts
                                as a launch surface for the future call flow.
                            </p>

                            <div className="call-stage__stats">
                                <div className="call-stat">
                                    <span className="call-stat__label">Active agent</span>
                                    <strong>{active_agent}</strong>
                                </div>
                                <div className="call-stat">
                                    <span className="call-stat__label">Messages captured</span>
                                    <strong>{len(str(transcript))}</strong>
                                </div>
                                <div className="call-stat">
                                    <span className="call-stat__label">Providers matched</span>
                                    <strong>{len(str(providers))}</strong>
                                </div>
                            </div>

                            <div className="call-stage__notes">
                                <div className="call-stage__note">
                                    <h3>What is wired today</h3>
                                    <p>Chat triage, risk escalation, provider matching, and export workflows remain live.</p>
                                </div>
                                <div className="call-stage__note">
                                    <h3>Suggested next step</h3>
                                    <p>Use the chat tab to collect patient context, then continue the voice UX from this same dashboard shell.</p>
                                </div>
                            </div>
                        </div>
                    }
                </section>

                <aside className="dashboard-main__side">
                    <div className="panel panel--glass">
                        <div className="panel__eyebrow">Session overview</div>
                        <div className="overview-grid">
                            <div className="overview-stat">
                                <span>Transcript</span>
                                <strong>{len(str(transcript))}</strong>
                            </div>
                            <div className="overview-stat">
                                <span>Providers</span>
                                <strong>{len(str(providers))}</strong>
                            </div>
                            <div className="overview-stat">
                                <span>Risk flags</span>
                                <strong>{len(str(risk_flags))}</strong>
                            </div>
                            <div className="overview-stat">
                                <span>Summary</span>
                                <strong>{"Ready" if summary_text != "" else "Pending"}</strong>
                            </div>
                        </div>
                    </div>

                    <SummaryPanel session={session} />
                </aside>
            </main>
        </div>
    </div>;
}

"""Button component for the Jac client application."""

def:pub Button(label: str, onClick: any, variant: str = "primary", disabled: bool = False) -> JsxElement {
    base_styles = {
        "padding": "0.75rem 1.5rem",
        "fontSize": "1rem",
        "fontWeight": "600",
        "borderRadius": "0.5rem",
        "border": "none",
        "cursor": "not-allowed" if disabled else "pointer",
        "transition": "all 0.2s ease"
    };

    variant_styles = {
        "primary": {
            "backgroundColor": "#9ca3af" if disabled else "#3b82f6",
            "color": "#ffffff"
        },
        "secondary": {
            "backgroundColor": "#e5e7eb" if disabled else "#6b7280",
            "color": "#ffffff"
        }
    };

    return <button
        style={{**base_styles, **variant_styles[variant]}}
        type="button"
        onClick={onClick}
        disabled={disabled}
    >
        {label}
    </button>;
}

"""Chat message feed and composer."""

import from react { useEffect, useRef }
import from .MessageBubble { MessageBubble }

def:pub ChatWindow(
    transcript: list,
    draft: str,
    sending: bool,
    activeAgent: str,
    onDraftChange: any,
    onSend: any,
    onDemo: any,
    onPdf: any,
    onReset: any,
    exportStatus: str,
    exportDisabled: bool
) -> JsxElement {
    endRef = useRef(None);

    useEffect(lambda () {
        if endRef.current { endRef.current.scrollIntoView({"behavior": "smooth"}); }
