                        id="password"
                        type="password"
                        className="login-input"
                        placeholder="Enter your password"
                        value={password}
                        onChange={lambda (e: any) { password = e.target.value; }}
                        onKeyDown={handleKeyDown}
                        disabled={loading}
                    />
                </div>

                <button
                    className="btn btn--primary login-btn"
                    onClick={lambda () { handleSubmit(); }}
                    disabled={loading}
                >
                    {btn_label}
