"""You are a crisis safety monitor embedded in a medical care coordination app. Your sole job
is to assess whether a user's message indicates they may be experiencing a mental health crisis
that requires immediate safety intervention — such as suicidal ideation, self-harm urges, or
expressions of hopelessness or despair severe enough that the person may be at risk of harming
themselves.

Set is_crisis=True ONLY if the message clearly suggests the person may intentionally harm
themselves, no longer wants to live, or is expressing active suicidal or self-harm intent.

Set is_crisis=False for ALL of the following:
- Physical injuries or accidents (broken bones, cuts, burns, sprains, etc.)
- Normal medical complaints (pain, illness, fever, nausea, dizziness, etc.)
- Chronic conditions or symptoms (headaches, back pain, stomach issues, etc.)
- Figurative speech ("I'm dying of hunger", "this headache is killing me")
- General frustration, sadness, or stress without self-harm intent
- Questions about mental health in the abstract
- Describing past self-harm without current intent

Do NOT flag physical injuries as crisis. "I broke my wrist" is NOT a crisis.
Do NOT flag symptoms as crisis. "I have chest pain" is NOT a crisis.

Set reason to a short phrase describing why you made the decision.
Set urgency to "high" if is_crisis is True, otherwise "routine".
Set response_markdown to an empty string — it will be filled in separately.
Set can_resume_if_user_declines to True."""
def llm_assess_crisis(message: str) -> InterventionDecision by llm();

def detect_crisis(message: str) -> InterventionDecision {
    try {
        result = llm_assess_crisis(message);
        if result.is_crisis {
            return InterventionDecision(
                is_crisis=True,
                reason=result.reason,
                urgency="high",
                response_markdown=CRISIS_RESPONSE_MARKDOWN,
                can_resume_if_user_declines=True
            );
        }
        return InterventionDecision(
            is_crisis=False,
            reason=result.reason,
            urgency="routine",
            response_markdown="",
            can_resume_if_user_declines=True
        );
    } except Exception as e {
        normalized = normalize_text(message);
        for phrase in CRISIS_PHRASES {
            if phrase in normalized {
                return InterventionDecision(
                    is_crisis=True,
                    reason="self-harm or suicidal language detected",
                    urgency="high",
                    response_markdown=CRISIS_RESPONSE_MARKDOWN,
                    can_resume_if_user_declines=True
                );
            }
        }
        return InterventionDecision(
            is_crisis=False,
            reason="no crisis language detected",
            urgency="routine",
            response_markdown="",
            can_resume_if_user_declines=True
        );
    }
}

def detect_resume(message: str) -> bool {
    normalized = normalize_text(message);
    for phrase in RESUME_PHRASES {
        if phrase in normalized { return True; }
    }
    return False;
}

"""
Symptom-to-ICD mapping with RAG retrieval and optional LLM enrichment.

Pipeline
--------
1. RAG search  - BM25 over 74 K ICD-10-CM codes (fast, no LLM required)
2. Keyword gate - original hand-crafted keyword map for high-precision rules
3. LLM enrich  - optional re-ranking / narrative via byllm
"""

import from os { getenv }
import from ..models.codes { DiagnosisCode }
import from ..models.session { DiagnosisResult }
import from ..data.icd_codes { get_icd_code_library, search_icd_by_text, lookup_icd_code }

glob LLM_READY: bool = True;

# ---------------------------------------------------------------------------
# Hand-crafted keyword rules (fast, high-precision for the demo set)
# ---------------------------------------------------------------------------

glob SYMPTOM_KEYWORD_MAP: dict[str, list[str]] = {
    "R42":   ["dizzy", "dizziness", "lightheaded", "vertigo", "spinning"],
    "I10":   ["blood pressure", "hypertension", "hypertensive", "bp pill", "bp medication"],
    "R11.0": ["nausea", "nauseated", "nauseous", "queasy"],
    "R10.9": ["stomach pain", "abdominal pain", "belly ache", "stomach ache", "cramps"],
    "R51.9": ["headache", "head pain", "head hurts"],
    "G43.909":["migraine", "migraines", "migraine headache", "hemiplegic migraine"],
    "R05.9": ["cough", "coughing", "dry cough", "wet cough"],
    "R06.00":["shortness of breath", "cant breathe", "can not breathe", "breathless", "dyspnea"],
    "R50.9": ["fever", "temperature", "chills", "sweating", "sweats"],
    "F32.9": ["depressed", "depression", "sad", "hopeless", "worthless"],
    "F41.9": ["anxiety", "anxious", "panic attack", "worried", "nervous"],
    "F90.9": ["adhd", "attention deficit", "hyperactivity", "trouble focusing", "difficulty focusing",
              "cant focus", "can't focus", "inattentive", "impulsive", "impulsivity",
              "cant sit still", "can't sit still", "attention span", "constantly distracted",
              "trouble concentrating", "difficulty concentrating"],
    "Z91199":["missed medication", "missed pill", "skipped dose", "forgot my medicine"],
    "R55":   ["fainted", "fainting", "passed out", "blacked out", "syncope"],
    "K2100": ["heartburn", "acid reflux", "gerd", "indigestion", "burning chest"],
    "M5450": ["back pain", "lower back", "spine", "lumbar"],
    "R00.0": ["heart racing", "heart pounding", "palpitations", "fast heartbeat", "tachycardia"]
};

# ---------------------------------------------------------------------------
# Specialty routing
# ---------------------------------------------------------------------------

glob CATEGORY_SPECIALTY_MAP: dict[str, str] = {
    "Circulatory":           "Cardiology",
    "Mental Health":         "Psychiatry",
    "Digestive":             "Gastroenterology",
    "Respiratory":           "Pulmonology",
    "Musculoskeletal":       "Orthopedics",
    "Nervous System":        "Neurology",
    "Endocrine / Metabolic": "Endocrinology",
    "Genitourinary":         "Urology",
    "Sensory Organs":        "Ophthalmology / ENT",
    "Skin":                  "Dermatology",
    "Neoplasms":             "Oncology",
    "Infectious Diseases":   "Infectious Disease"
};

def _specialty_for_category(category: str) -> str {
    for key in CATEGORY_SPECIALTY_MAP {
        if key in category {
            return CATEGORY_SPECIALTY_MAP[key];
        }
    }
    return "Internal Medicine";
}

# ---------------------------------------------------------------------------
# Step 1 - keyword gate
# ---------------------------------------------------------------------------

def extract_symptom_keywords(message: str) -> list[str] {
    lower_msg = message.lower();
    found: list[str] = [];
    for code in SYMPTOM_KEYWORD_MAP {
        keywords = SYMPTOM_KEYWORD_MAP[code];
        for kw in keywords {
            if kw in lower_msg {
                if code not in found { found.append(code); }
            }
        }
    }
    return found;
}

def codes_from_keywords(symptom_text: str) -> list[DiagnosisCode] {
    matched_codes = extract_symptom_keywords(symptom_text);
    results: list[DiagnosisCode] = [];
    for code in matched_codes {
        resolved = lookup_icd_code(code);
        if resolved {
            results.append(DiagnosisCode(
                code=resolved.code,
                description=resolved.description,
                category=resolved.category,
                confidence=0.80,
                source="keyword_rule"
            ));
        }
    }
    return results;
}

# ---------------------------------------------------------------------------
# Step 2 - RAG search (covers everything the keyword map misses)
# ---------------------------------------------------------------------------

"""BM25 search over the full 74 K ICD dataset.
Returns up to top_k ranked DiagnosisCode objects."""
def codes_from_rag(symptom_text: str, top_k: int = 8) -> list[DiagnosisCode] {
    return search_icd_by_text(symptom_text, top_k);
}

# ---------------------------------------------------------------------------
# Step 3 - merge keyword + RAG results, de-duplicate
# ---------------------------------------------------------------------------

def merge_codes(
    keyword_codes: list[DiagnosisCode],
    rag_codes: list[DiagnosisCode]
) -> list[DiagnosisCode] {
    seen: dict[str, DiagnosisCode] = {};

    # Keyword codes take priority (high precision)
    for c in keyword_codes {
        seen[c.code] = c;
    }

    # RAG codes fill in everything else; boost confidence if already seen
    for c in rag_codes {
        if c.code in seen {
            existing = seen[c.code];
            boosted: float = existing.confidence + 0.10;
            if boosted > 1.0 { boosted = 1.0; }
            seen[c.code] = DiagnosisCode(
                code=existing.code,
                description=existing.description,
                category=existing.category,
                confidence=boosted,
                source="keyword_rule+rag"
            );
        } else {
            seen[c.code] = c;
        }
    }

    # Collect values from the dict and sort by confidence descending
    merged: list[DiagnosisCode] = [];
    for code_key in seen {
        merged.append(seen[code_key]);
    }

    # Insertion sort by confidence (descending) - avoids lambda type issues
    i: int = 1;
    while i < len(merged) {
        current = merged[i];
        j: int = i - 1;
        while j >= 0 and merged[j].confidence < current.confidence {
            merged[j + 1] = merged[j];
            j -= 1;
        }
        merged[j + 1] = current;
        i += 1;
    }

    return merged;
}

# ---------------------------------------------------------------------------
# Step 4 - LLM enrichment
# ---------------------------------------------------------------------------

"""You are a clinical coding assistant. You will receive a symptom description and a candidate list of ICD-10-CM codes.
Your task: select the 2-3 codes from the candidate list that BEST match the patient's PRIMARY complaints.
STRICT RULES:
1. Only use codes that appear in the provided candidate_codes list. Do NOT invent or add any new codes.
2. Exclude symptom-only codes (R-, Y-, Z- prefixes) when a specific diagnosis code (F-, G-, I-, J-, K-, M- etc.) is available.
3. Assign confidence 0.0-1.0. Only include codes with confidence >= 0.6.
4. Return at most 3 codes in symptom_codes.
Return a complete DiagnosisResult object."""
def llm_enrich_diagnosis(
    symptom_text: str,
    candidate_codes: list[DiagnosisCode],
    inferred_specialties: list[str]
) -> DiagnosisResult by llm();

# ---------------------------------------------------------------------------
# Main entry point
# ---------------------------------------------------------------------------

def build_diagnosis_result(
    symptom_list: list[str],
    all_transcript_text: str
) -> DiagnosisResult {
    combined = " ".join(symptom_list) + " " + all_transcript_text;

    # --- retrieval ---
    keyword_codes = codes_from_keywords(combined);
    rag_codes      = codes_from_rag(combined, top_k=3);
    merged         = merge_codes(keyword_codes, rag_codes);

    # Cap to top 3 results to avoid over-coding
    if len(merged) > 3 { merged = merged[:3]; }

    # --- specialty inference ---
    specialties: list[str] = [];
    for c in merged {
        sp = _specialty_for_category(c.category);
        if sp not in specialties {
            specialties.append(sp);
        }
    }
    if not specialties { specialties.append("General Practice"); }

    # --- LLM enrichment (optional) ---
    if LLM_READY and merged {
        try {
            result = llm_enrich_diagnosis(combined, merged, specialties);
            # Validate: keep only codes that exist in our merged candidates
            valid_codes = [c.code for c in merged];
            filtered: list = [];
            for c in result.symptom_codes {
                code_val = c.code if hasattr(c, "code") else c.get("code", "");
                if code_val in valid_codes { filtered.append(c); }
            }
            if filtered {
                result.symptom_codes = filtered;
                return result;
            }
            # LLM returned no valid codes — fall through to rule-based
        } except Exception as e {
            0;  # fall through to rule-based result
        }
    }

    query_terms: list[str] = [];
    for c in merged { query_terms.append(c.description); }

    return DiagnosisResult(
        symptom_codes=merged,
        inferred_specialties=specialties,
        provider_query_terms=query_terms,
        narrative_reasoning="Based on reported symptoms, the following conditions may be relevant. This is not a diagnosis.",
        confidence_note="RAG + keyword match (LLM enrichment not available)."
    );
}

"""Structured field extraction from free-text messages."""

import re;
import from os { getenv }
import from ..models.session { ConversationStateUpdate }
import from .common { first_non_empty, merge_strings, normalize_text, transcript_excerpt }
import from .symptom_mapper { extract_symptom_keywords, codes_from_keywords }
glob LLM_READY: bool = True;

glob INSURANCE_ALIASES: dict[str, list[str]] = {
    "Aetna": ["aetna"],
    "Blue Cross Blue Shield": ["blue cross", "blue shield", "bcbs", "blue cross blue shield"],
    "Cigna": ["cigna"],
    "UnitedHealthcare": ["unitedhealthcare", "united healthcare", "uhc"],
    "Humana": ["humana"],
    "Medicare": ["medicare"],
    "Medicaid": ["medicaid"]
};

def rule_extract_insurance(text: str) -> str {
    lower = text.lower();
    for canonical in INSURANCE_ALIASES {
        aliases = INSURANCE_ALIASES[canonical];
        for alias in aliases {
            if alias in lower { return canonical; }
        }
    }
    return "";
}

def rule_extract_location(text: str) -> str {
    # Extract "City, ST" or "City, State" patterns (e.g. "San Francisco, CA" or "Portland, Maine").
    # One to three Title-Case words followed by a state abbreviation or full state name.
    matches = re.findall(r'\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2}),\s*([A-Z]{2})\b', text);
    if not matches {
        matches = re.findall(r'\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2}),\s*([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)\b', text);
    }
    if matches {
        locations = [m[0].strip() + ", " + m[1] for m in matches];
        return " or ".join(locations);
    }
    return "";
}

def rule_extract_duration(text: str) -> str {
    lower = text.lower();
    patterns = ["for two days", "for a week", "since yesterday", "since last", "for three days",
                "for a few days", "for months", "for years", "since this morning"];
    for p in patterns {
        if p in lower { return p; }
    }
    return "";
}

def rule_extract_severity(text: str) -> str {
    lower = text.lower();
    if any([w in lower for w in ["severe", "excruciating", "unbearable", "worst"]]) { return "severe"; }
    if any([w in lower for w in ["moderate", "medium", "noticeable"]]) { return "moderate"; }
    if any([w in lower for w in ["mild", "slight", "minor", "a little"]]) { return "mild"; }
    return "";
}

"""You are a medical intake coordinator. Extract structured care coordination fields from the
user message and conversation history. Do NOT diagnose. Do NOT speculate beyond what the user
explicitly states.

Fields to extract:
- extracted_symptoms: list of symptom phrases (verbatim from user)
- follow_up_question: a single clarifying question to ask next (location if missing,
  duration if missing, severity if missing, or "" if all known)
- enough_for_diagnosis: True only if we have at least 1 symptom AND location
- location: ALL locations the user mentions they can be seen in, normalized to
  "City, ST" format with the official USPS two-letter state abbreviation
  (e.g. "San Francisco, CA", "New York, NY", "Chicago, IL").
  If the user names a well-known city without a state, infer the primary state
  (e.g. "San Francisco" → "San Francisco, CA", "Miami" → "Miami, FL").
  If the user gives multiple locations, join them with " or "
  (e.g. "Seattle, WA or Portland, OR"). Return None if no location is mentioned.
- duration: how long symptoms have been present, or None
- severity: "mild" | "moderate" | "severe" | None

Return a ConversationStateUpdate object. Never fabricate information not present in the message."""
def llm_extract_fields(
    message: str,
    recent_transcript: str,
    known_symptoms: list[str],
    known_location: str
) -> ConversationStateUpdate by llm();

def build_conversation_state_update(
    message: str,
    transcript_messages: list,
    known_symptoms: list[str],
    known_location: str | None
) -> ConversationStateUpdate {
    loc_str = known_location if known_location else "";

    rule_loc = rule_extract_location(message);
    rule_dur = rule_extract_duration(message);
    rule_sev = rule_extract_severity(message);
    rule_codes = extract_symptom_keywords(message);

    merged_loc = first_non_empty(rule_loc, loc_str);
    merged_symptoms = list(known_symptoms);
    for code in rule_codes {
        if code not in merged_symptoms { merged_symptoms.append(code); }
    }

    if LLM_READY {
        try {
            excerpt = transcript_excerpt(transcript_messages, 6);
            llm_result = llm_extract_fields(
                message, excerpt, merged_symptoms, merged_loc
            );
            llm_loc = llm_result.location if llm_result.location else "";
            # Only trust LLM location if the city name actually appears in the message
            # — prevents the local model hallucinating cities like "Seattle" from "i hurt my leg"
            llm_city = llm_loc.split(",")[0].lower().strip() if llm_loc else "";
            msg_lower: str = message.lower();
            llm_loc_grounded = llm_city != "" and llm_city in msg_lower;
            effective_llm_loc = llm_loc if llm_loc_grounded else "";
            final_loc = first_non_empty(merged_loc, effective_llm_loc);
            all_syms = list(merged_symptoms);
            for s in llm_result.extracted_symptoms {
                if s not in all_syms { all_syms.append(s); }
            }
            ready = (len(all_syms) >= 1 and final_loc != "");
            return ConversationStateUpdate(
                extracted_symptoms=all_syms,
                follow_up_question=llm_result.follow_up_question,
                enough_for_diagnosis=ready,
                location=final_loc if final_loc != "" else None,
                insurance=None,
                duration=llm_result.duration if llm_result.duration else rule_dur if rule_dur else None,
                severity=llm_result.severity if llm_result.severity else rule_sev if rule_sev else None
            );
        } except Exception as e {
            0;
        }
    }

    missing: list[str] = [];
    if not merged_loc or merged_loc == "" { missing.append("location (city and state)"); }
    if not merged_symptoms { missing.append("a description of your symptoms"); }

    follow_up = "";
    if missing { follow_up = "Could you share your " + missing[0] + "?"; }
    ready = (len(merged_symptoms) >= 1 and merged_loc != "");

    return ConversationStateUpdate(
        extracted_symptoms=merged_symptoms,
        follow_up_question=follow_up,
        enough_for_diagnosis=ready,
        location=merged_loc if merged_loc != "" else None,
        insurance=None,
        duration=rule_dur if rule_dur != "" else None,
        severity=rule_sev if rule_sev != "" else None
    );
}

"""Agent 1: Lookout Agent - Fetches and identifies current market trends from news."""

import from byllm.lib { Model }
import requests;
import json;
import from env_loader { OPENAI_API_KEY, NEWS_API_KEY }

glob llm = Model(model_name="gpt-4o-mini", api_key=OPENAI_API_KEY);

"""Represents a single article/trend with title and description."""
obj Trend {
    has title: str = "";
    has description: str = "";
}

"""Fetch top headlines from News API for a given category."""
def fetch_top_headlines(
    category: str = "technology", country: str = "us", page_size: int = 20
) -> list[dict[str, str]] {
    url: str = "https://newsapi.org/v2/top-headlines";
    params: dict[str, str] = {
        "apiKey": NEWS_API_KEY,
        "category": category,
        "country": country,
        "pageSize": str(page_size)
    };
    resp: any = requests.get(url, params=params);
    data: any = resp.json();
    articles: list[dict[str, str]] = [];
    if data.get("status") == "ok" {
        for article in data.get("articles", []) {
            articles.append(
                {
                    "title": article.get("title", ""),
                    "description": article.get("description", ""),
                    "source": article.get("source", {}).get("name", ""),
                    "publishedAt": article.get("publishedAt", ""),
                    "url": article.get("url", "")
                }
            );
        }
    }
    print(f"Fetched articles from {category}");
    return articles;
}

"""Search for news articles about a specific topic or keyword."""
def search_news(query: str, page_size: int = 20) -> list[dict[str, str]] {
    url: str = "https://newsapi.org/v2/everything";
    params: dict[str, str] = {
        "apiKey": NEWS_API_KEY,
        "q": query,
        "pageSize": str(page_size),
        "sortBy": "publishedAt",
        "language": "en"
    };
    resp: any = requests.get(url, params=params);
    data: any = resp.json();
    articles: list[dict[str, str]] = [];
    if data.get("status") == "ok" {
        for article in data.get("articles", []) {
            articles.append(
                {
                    "title": article.get("title", ""),
                    "description": article.get("description", ""),
                    "source": article.get("source", {}).get("name", ""),
                    "publishedAt": article.get("publishedAt", ""),
                    "url": article.get("url", "")
                }
            );
        }
    }
    return articles;
}

"""Extract top 10 articles from multiple categories."""
def get_top_trends() -> list[Trend] {
    trends: list[Trend] = [];
    categories: list[str] = ["technology", "business", "science"];

    for category in categories {
        articles: list[dict[str, str]] = fetch_top_headlines(
            category=category, page_size=5
        );
        for article in articles {
            if len(trends) < 10 {
                trends.append(
                    Trend(
                        title=article.get("title", ""),
                        description=article.get("description", "")
                    )
                );
            }
        }
    }
    return trends;
}

walker LookoutAgent {
    can run with Root entry {
        print("LookoutAgent: Fetching top trends...");
        trends: list[Trend] = get_top_trends();
        report trends;
        print(f"LookoutAgent: Fetched {len(trends)} trends.");
    }
}

with entry {
    result: any = root spawn LookoutAgent();
    raw_trends: list[Trend] = result.reports[0];
    output: list[dict[str, any]] = [];
    for t in raw_trends {
        output.append({"title": t.title, "description": t.description});
    }
    print(json.dumps(output, indent=2));
}

"""Agent 2: Data Gathering Agent - Groups news articles from Agent 1 into categories."""

import from byllm.lib { Model }
import json;
import from agent1_lookout { Trend, get_top_trends }
import from env_loader { OPENAI_API_KEY }

glob llm = Model(model_name="gpt-4o-mini", api_key=OPENAI_API_KEY);

"""A single news article with title and description."""
obj ArticleItem {
    has title: str = "";
    has description: str = "";
}

"""A group of related news articles under a common category."""
obj NewsCategory {
    has category_name: str = "";
    has summary: str = "";
    has articles: list[ArticleItem] = [];
}

"""Group similar news articles into meaningful categories."""
def group_news_into_categories(articles: list[ArticleItem]) -> list[NewsCategory] by llm;

sem group_news_into_categories = """
You are a news editor. Given a list of news articles (each with a title and description),
group them into meaningful categories based on their topics and themes.
Rules:
- Create 3-6 categories that best represent the themes in the articles
- Each article must belong to exactly one category
- Give each category a clear, descriptive name (e.g. 'Artificial Intelligence', 'Space Exploration', 'Financial Markets')
- Write a brief summary describing what the category covers based on the articles within it
- Every article from the input list must appear in exactly one of the output categories
- Each category must have at least 1 article
""";

"""Regroup articles into categories, applying the reviewer's feedback to improve quality."""
def regroup_with_feedback(
    articles: list[ArticleItem], feedback: str
) -> list[NewsCategory] by llm;

sem regroup_with_feedback = """
You are a news editor. Regroup the provided articles into meaningful categories.
You have received feedback from a reviewer — apply it carefully to improve the groupings.
Rules:
- Create 3-6 categories that best represent the themes in the articles
- Each article must belong to exactly one category
- Give each category a clear, descriptive name
- Write a brief summary describing what the category covers
- Every article from the input list must appear in exactly one output category
- Each category must have at least 1 article
- Address all points raised in the reviewer feedback
""";

