  background: linear-gradient(90deg, rgba(125, 211, 255, 0), rgba(125, 211, 255, 0.92), rgba(82, 229, 213, 0));
  opacity: 0.82;
  animation: gwScan 4.8s linear infinite;
}

.gw-preview-shell {
  border-radius: 30px;
  padding: 22px;
}

.gw-preview-topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 18px;
  margin-bottom: 18px;
}

.gw-preview-topbar-left,
.gw-preview-topbar-right {
  display: flex;
  gap: 10px;
  align-items: center;
}

.gw-preview-pill,
.gw-preview-dot {
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(220, 239, 255, 0.08);
}

.gw-preview-pill {
  height: 34px;
}

.gw-preview-pill-wide {
  width: 180px;
}

.gw-preview-pill-small {
  width: 98px;
}

.gw-preview-dot {
  width: 34px;
  height: 34px;
}

.gw-preview-body {
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr);
  gap: 16px;
  min-height: 320px;
}

.gw-preview-sidebar {
  border-radius: 24px;
  padding: 16px;
  display: grid;
  gap: 12px;
}

.gw-preview-sidebar-line {
  height: 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
}

.gw-preview-content {
  display: grid;
  gap: 16px;
}

.gw-preview-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.gw-preview-card {
