  border-radius: 22px;
  padding: 16px;
}

.gw-preview-card-label {
  color: var(--text-tertiary);
  font-size: 0.76rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
}

.gw-preview-card-value {
  margin-top: 0.9rem;
  font-family: var(--font-display);
  font-size: 1.45rem;
  letter-spacing: -0.04em;
}

.gw-preview-graph {
  position: relative;
  min-height: 192px;
  border-radius: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  text-align: center;
}

.gw-preview-graph::after {
  content: "";
  position: absolute;
  inset: 18px;
  border-radius: 20px;
  border: 1px dashed rgba(220, 239, 255, 0.18);
}

.gw-cta-panel {
  border-radius: 30px;
  padding: 30px;
  display: flex;
  justify-content: space-between;
  gap: 22px;
  align-items: flex-end;
}

.gw-cta-copy h3 {
  margin: 0 0 12px;
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 4vw, 3rem);
  letter-spacing: -0.05em;
}

.gw-cta-copy p {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.8;
}

.gw-cta-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.gw-auth-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: 30px;
  align-items: center;
  min-height: calc(100vh - 72px);
}

.gw-auth-story {
  position: relative;
  display: grid;
  gap: 20px;
}

.gw-auth-title {
  margin: 8px 0 0;
  max-width: 10ch;
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 6vw, 5.2rem);
  line-height: 0.94;
  letter-spacing: -0.06em;
  font-weight: var(--weight-black);
}

.gw-auth-copy {
  margin: 0;
  max-width: 48ch;
  color: var(--text-secondary);
  line-height: 1.85;
}

.gw-auth-visual {
  width: min(100%, 520px);
  margin-top: 10px;
}

.gw-auth-surface {
  display: grid;
  gap: 18px;
}

.gw-auth-card,
.gw-auth-note-card {
  border-radius: 30px;
}

.gw-auth-card {
  padding: 30px;
}

.gw-auth-form {
  display: grid;
  gap: 16px;
}

.gw-auth-card-header h2 {
  margin: 0 0 10px;
  font-family: var(--font-display);
  font-size: 2rem;
  letter-spacing: -0.04em;
}

.gw-auth-card-header p {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.7;
}

.gw-provider-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.gw-provider-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 0.96rem 1rem;
  border-radius: 18px;
  border: 1px solid rgba(220, 239, 255, 0.12);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02)),
    rgba(18, 24, 31, 0.62);
  color: var(--text-primary);
  cursor: pointer;
  transition: transform 180ms var(--ease-out), border-color 180ms var(--ease-out);
}

.gw-provider-button:hover {
  transform: translateY(-2px);
  border-color: rgba(220, 239, 255, 0.2);
}

.gw-provider-icon {
  width: 20px;
  height: 20px;
}

.gw-auth-divider {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  color: var(--text-tertiary);
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
}

.gw-auth-divider::before,
.gw-auth-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(220, 239, 255, 0), rgba(220, 239, 255, 0.18), rgba(220, 239, 255, 0));
}

.gw-auth-field {
  display: grid;
  gap: 0.55rem;
}

.gw-auth-label {
  font-size: 0.8rem;
  color: rgba(220, 239, 255, 0.7);
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gw-auth-input {
  width: 100%;
  border-radius: 18px;
  border: 1px solid rgba(220, 239, 255, 0.12);
  background: rgba(8, 11, 15, 0.5);
  padding: 1rem 1.05rem;
  min-height: 56px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transition: border-color 180ms var(--ease-out), background 180ms var(--ease-out);
}

.gw-auth-input::placeholder {
  color: rgba(125, 136, 152, 0.72);
}

.gw-auth-input:hover,
.gw-auth-input:focus-visible {
  border-color: rgba(125, 211, 255, 0.3);
  background: rgba(10, 14, 19, 0.65);
}

.gw-auth-legal {
  color: var(--text-tertiary);
  font-size: 0.82rem;
  line-height: 1.7;
}

.gw-auth-note-card {
  padding: 22px 24px;
}

.gw-note-list {
  display: grid;
  gap: 12px;
  margin-top: 16px;
}

.gw-note-item {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 0.88rem 0.96rem;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(220, 239, 255, 0.06);
  color: var(--text-secondary);
}

.gw-note-item span:first-child {
  color: var(--text-primary);
}

.gw-app-shell {
  display: grid;
  grid-template-columns: 286px minmax(0, 1fr);
  gap: 22px;
  min-height: calc(100vh - 48px);
}

.gw-sidebar {
  border-radius: 32px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.gw-sidebar-nav {
  display: grid;
  gap: 10px;
}

.gw-sidebar-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.92rem 1rem;
  border-radius: 20px;
