  gap: 14px;
}

.gw-demo-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  width: fit-content;
  padding: 0.7rem 0.88rem;
  border-radius: 999px;
  background: rgba(82, 229, 213, 0.07);
  border: 1px solid rgba(82, 229, 213, 0.14);
  color: rgba(220, 255, 250, 0.92);
  font-size: 0.8rem;
  font-weight: var(--weight-label);
}

.gw-demo-badge::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--accent-aqua);
  box-shadow: 0 0 18px rgba(82, 229, 213, 0.5);
}

.gw-profile-card {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.92rem 1rem;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(220, 239, 255, 0.08);
}

.gw-avatar {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.18), transparent 40%),
    linear-gradient(180deg, rgba(125, 211, 255, 0.24), rgba(17, 22, 29, 0.8));
  border: 1px solid rgba(220, 239, 255, 0.16);
  font-family: var(--font-display);
  font-weight: var(--weight-bold);
}

.gw-profile-meta {
  display: grid;
  gap: 0.2rem;
}

.gw-profile-meta strong {
  font-size: 0.92rem;
}

.gw-profile-meta span {
  color: var(--text-tertiary);
  font-size: 0.78rem;
}

.gw-workspace {
  display: grid;
  gap: 18px;
}

.gw-workspace--connect {
  min-height: calc(100vh - 120px);
  place-content: center;
}

.gw-topbar {
  border-radius: 30px;
  padding: 18px 20px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
}

.gw-topbar-heading {
  display: grid;
  gap: 0.5rem;
}

.gw-topbar-heading h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  letter-spacing: -0.04em;
}

.gw-topbar-heading p {
  margin: 0;
  color: var(--text-secondary);
}

.gw-topbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.gw-repo-select,
.gw-icon-button,
.gw-search-shell {
  border-radius: 18px;
  border: 1px solid rgba(220, 239, 255, 0.1);
  background: rgba(8, 11, 15, 0.34);
  min-height: 52px;
}

.gw-repo-select {
  display: inline-flex;
  align-items: center;
  gap: 0.78rem;
  padding: 0 1rem;
}

.gw-repo-label {
