  gap: 0.16rem;
  text-align: left;
}

.gw-repo-label strong {
  font-size: 0.92rem;
}

.gw-repo-label span {
  font-size: 0.76rem;
  color: var(--text-tertiary);
}

.gw-search-shell {
  display: inline-flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0 0.9rem;
