  background: transparent;
  border: 0;
  outline: none;
}

.gw-icon-button {
  width: 52px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  cursor: pointer;
}

.gw-icon-badge {
  position: absolute;
  top: 9px;
  right: 9px;
  min-width: 18px;
  height: 18px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 123, 144, 0.92);
  color: #10131a;
  font-size: 0.68rem;
  font-weight: var(--weight-bold);
}

.gw-command-banner {
  border-radius: 24px;
  padding: 16px 18px;
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
}

.gw-command-banner strong {
  font-size: 0.88rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(220, 239, 255, 0.78);
}

.gw-command-banner p {
  margin: 0.45rem 0 0;
  color: var(--text-secondary);
  line-height: 1.7;
}

.gw-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 20px;
}

.gw-main-grid--single {
  grid-template-columns: minmax(0, 1fr);
}

.gw-wordmark-link {
  text-decoration: none;
  color: inherit;
  border-radius: 20px;
