}

.gw-data-table th,
.gw-data-table td {
  text-align: left;
  padding: 0.65rem 0.75rem;
  border-bottom: 1px solid rgba(220, 239, 255, 0.08);
  vertical-align: top;
}

.gw-data-table th {
  color: var(--text-tertiary);
  font-weight: var(--weight-label);
