  letter-spacing: 0.12em;
  font-size: 0.68rem;
}

.gw-data-table--compact td {
  padding: 0.5rem 0.75rem;
}

.gw-repo-row-current {
  background: rgba(125, 211, 255, 0.06);
}

.gw-settings-column {
  gap: 16px;
}

.gw-settings-block {
  border-radius: 24px;
  padding: 1.25rem 1.35rem 1.35rem;
  display: grid;
  gap: 0.85rem;
}

.gw-settings-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-secondary);
  font-size: 0.88rem;
  cursor: pointer;
}

.gw-settings-label {
  min-width: 160px;
  color: var(--text-secondary);
  font-size: 0.86rem;
}

.gw-settings-select {
  flex: 1;
  max-width: 220px;
  border-radius: 14px;
  border: 1px solid rgba(220, 239, 255, 0.14);
  background: rgba(6, 10, 18, 0.55);
  color: var(--text-primary);
  padding: 0.45rem 0.65rem;
  font-size: 0.86rem;
}

.gw-settings-hint {
  margin: 1rem 0 0;
  font-size: 0.8rem;
  color: var(--text-tertiary);
  line-height: 1.55;
}

.gw-main-column {
  display: grid;
  gap: 18px;
}

.gw-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.gw-summary-card {
  border-radius: 24px;
  padding: 20px;
  display: grid;
  gap: 1rem;
}

.gw-summary-card.is-frost {
  border-color: rgba(220, 239, 255, 0.18);
}

.gw-summary-card.is-cyan {
  border-color: rgba(125, 211, 255, 0.2);
}

.gw-summary-card.is-aqua {
  border-color: rgba(82, 229, 213, 0.2);
}

.gw-summary-card.is-amber {
  border-color: rgba(255, 191, 105, 0.22);
}

.gw-summary-label {
  color: var(--text-tertiary);
  font-size: 0.76rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
}

.gw-summary-value {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: var(--weight-black);
  letter-spacing: -0.05em;
}

.gw-summary-delta {
  color: var(--text-secondary);
