        return;
    }
    report {"error": "incident not found"};
}

# walkers/ghostwatch/impl/gap_analysis.impl.jac

import from graph.nodes { FileNode, TestNode, DocumentationNode, GapAnalysisNode }
import from lib.manifest { rank_gap_candidates, impl_likely_has_conventional_test }
import from integrations.discord { notify_discord_gap_digest }
import from time { time }

impl GapAnalysisWalker._word_suggestion(path: str, gap_kind: str) -> dict {
    return {
        "title": f"Improve {path}",
        "description": f"Address gap ({gap_kind}) for {path}",
        "difficulty": "intermediate",
        "file_path": path,
        "suggestion_type": gap_kind
    };
}

impl GapAnalysisWalker.run with Root entry {
    paths = [];
    test_paths = set();
    doc_paths = set();
    for fn in [root -->][?:FileNode] {
        paths.append(fn.path);
    }
    for tn in [root -->][?:TestNode] {
        test_paths.add(tn.path);
    }
    for dn in [root -->][?:DocumentationNode] {
        doc_paths.add(dn.path);
    }
    core_prefixes = ["graph/", "walkers/", "lib/", "integrations/", "frontend/"];
    ranked = rank_gap_candidates(paths, test_paths, doc_paths, core_prefixes);
    suggestions = [];
    max_n = 5;
    for item in ranked {
        if len(suggestions) >= max_n {
            break;
        }
        p = str(item.get("path", ""));
        if not p {
            continue;
        }
        cov_t = impl_likely_has_conventional_test(p, test_paths);
        cov_d = (not p.endswith(".jac")) or (p in doc_paths);
        ph = "placeholder" in str(p).lower() or "todo" in str(p).lower();
        if cov_t and cov_d and not ph {
            continue;
        }
        gap_kind = "missing_tests";
        if ph {
            gap_kind = "incomplete_feature";
        } elif not cov_t {
            gap_kind = "missing_tests";
        } elif p.endswith(".jac") and p not in doc_paths {
            gap_kind = "missing_docs";
        }
        try {
            sug = self._word_suggestion(path=p, gap_kind=gap_kind);
        } except Exception {
            sug = {
                "title": f"Improve {p}",
                "description": f"Address gap ({gap_kind}) for {p}",
                "difficulty": "intermediate",
                "file_path": p,
                "suggestion_type": gap_kind
            };
        }
        suggestions.append(sug);
    }
    if len(suggestions) < 3 {
        for item in ranked {
            if len(suggestions) >= 3 {
                break;
            }
            p = str(item.get("path", ""));
            if not p {
                continue;
            }
            dup_path = False;
            for s in suggestions {
                if str(s.get("file_path", "")) == p {
                    dup_path = True;
                    break;
                }
            }
            if dup_path {
                continue;
            }
            suggestions.append(
                {
                    "title": f"Cover {p}",
                    "description": "Add tests or documentation as appropriate.",
                    "difficulty": "good-first-issue",
                    "file_path": p,
                    "suggestion_type": "missing_tests"
                }
            );
        }
    }
    ts = str(int(time()));
    _ = (root ++> GapAnalysisNode(merge_commit_sha=self.merge_commit_sha, suggestions=suggestions, created_at=ts))[0];
    notify_discord_gap_digest({"merge_commit_sha": self.merge_commit_sha, "suggestions": suggestions});
    report {"suggestions": len(suggestions)};
}

# walkers/ghostwatch/impl/github_system2_webhook.impl.jac

import from os { environ }
import from integrations.github { validate_webhook_signature, list_commit_files, get_parent_commit_sha }
import from walkers.ghostwatch.dep_diff { DependencyDiffWalker }
import from walkers.ghostwatch.gap_analysis { GapAnalysisWalker }

impl GitHubSystem2WebhookWalker.run with Root entry {
    secret = environ.get("GITHUB_WEBHOOK_SECRET", "");
    if secret and self.signature and self.raw_body {
        payload_bytes = self.raw_body.encode("utf-8");
        if not validate_webhook_signature(payload_bytes, self.signature, secret) {
            report {"status": 401, "error": "Invalid webhook signature"};
            return;
        }
    }
    ev = self.event_type;
    if ev == "push" {
        repo_obj = self.payload.get("repository", {});
        repo_full = str(repo_obj.get("full_name", ""));
        commit_sha = str(self.payload.get("after", ""));
        if not repo_full or not commit_sha {
            report {"status": "ignored", "reason": "missing repo or after sha"};
            return;
        }
        parent_sha = get_parent_commit_sha(repo_full, commit_sha);
        files = list_commit_files(repo_full, commit_sha);
        manifests = [];
        for f in files {
            fs = str(f);
            is_m = False;
            if fs.endswith("package.json") {
                is_m = True;
            }
            if fs.endswith("requirements.txt") {
                is_m = True;
            }
            if fs.endswith("pyproject.toml") {
                is_m = True;
            }
            if fs.endswith("jac.toml") {
                is_m = True;
            }
            if is_m {
                manifests.append(fs);
            }
        }
        if manifests {
            _ = root spawn DependencyDiffWalker(
                repo_full_name=repo_full,
                commit_sha=commit_sha,
                parent_sha=parent_sha,
                manifest_paths=manifests
            );
            report {"status": "dependency_diff_dispatched", "manifest_count": len(manifests)};
            return;
        }
        report {"status": "push_no_manifest"};
        return;
    }
    if ev == "pull_request" {
        action = str(self.payload.get("action", ""));
        repo_full = "";
        merge_sha = "";
        try {
            pr = self.payload["pull_request"];
            merged = pr["merged"];
            if action == "closed" and merged {
                brepo = pr["base"]["repo"];
                repo_full = str(brepo["full_name"]);
                merge_sha = str(pr["merge_commit_sha"]);
            }
        } except Exception {
            repo_full = "";
            merge_sha = "";
        }
        if repo_full and merge_sha {
            _ = root spawn GapAnalysisWalker(repo_full_name=repo_full, merge_commit_sha=merge_sha);
            report {"status": "gap_analysis_dispatched"};
            return;
        }
        report {"status": "pr_ignored", "action": action};
        return;
    }
    report {"status": "noop", "event": ev};
}

# walkers/ghostwatch/impl/pr_creator.impl.jac

import from graph.nodes { GhostwatchIncidentNode }
import from integrations.github {
    create_branch_from_sha,
    update_file_on_branch,
    open_pull_request,
    get_default_branch,
    get_branch_head_sha
}
import from integrations.discord { notify_discord_incident }
import from time { time }
import threading;

impl GhostwatchPRCreatorWalker._format_pr_body(incident: dict) -> str {
    dep = str(incident.get("dependency_name", ""));
    return f"## GhostWatch auto-fix\nDependency: `{dep}`\n";
}

def _escalation_job(jid_arg: str) -> None {
    print(f"GhostWatch escalation tick for {jid_arg}");
}

impl GhostwatchPRCreatorWalker.run with Root entry {
    for target in [root -->][?:GhostwatchIncidentNode] {
        if str(jid(target)) != self.incident_jid {
            continue;
        }
        if target.fix_pr_url {
            report {"status": "idempotent_skip", "pr": target.fix_pr_url};
            return;
        }
        base = get_default_branch(target.repo_full_name);
        head_sha = get_branch_head_sha(target.repo_full_name, base);
        if not head_sha {
            report {"error": "no head sha"};
            return;
        }
        ts = int(time());
        safe_dep = target.dependency_name.replace("/", "-").replace("@", "")[:40];
        branch = f"ghostwatch/auto-fix-{safe_dep}-{ts}";
        create_branch_from_sha(target.repo_full_name, branch, head_sha);
        update_file_on_branch(
            target.repo_full_name,
            target.manifest_path,
            branch,
            self.validated_fix_content,
            f"GhostWatch: remove/repair {target.dependency_name}"
        );
        inc_dict = {
            "dependency_name": target.dependency_name,
            "manifest_path": target.manifest_path,
            "sandbox_result": target.sandbox_result,
            "behavioral_trace": target.behavioral_trace,
            "rule_codes": target.rule_codes
        };
        try {
            body = self._format_pr_body(incident=inc_dict);
        } except Exception {
            body = f"## GhostWatch auto-fix\nDependency: `{target.dependency_name}`\nManifest: `{target.manifest_path}`\n";
        }
        pr_url = open_pull_request(
            target.repo_full_name,
            f"GhostWatch: address malicious dependency {target.dependency_name}",
            body,
            branch,
            base
        );
        target.fix_pr_url = pr_url;
        target.fix_branch_name = branch;
        target.alert_state = "pr_opened";
        target.updated_at = str(ts);
        target.next_escalation_at = str(ts + 7200);
        notify_discord_incident(
            {
                "dependency_name": target.dependency_name,
                "status": "malicious_with_fix_pr",
                "repo": target.repo_full_name,
                "summary": pr_url
            }
        );
        t = threading.Timer(7200.0, _escalation_job, args=[self.incident_jid]);
        t.daemon = True;
        t.start();
        report {"pr_url": pr_url, "branch": branch};
        return;
    }
    report {"error": "incident not found"};
}

# walkers/ghostwatch/impl/sandbox.impl.jac

import from graph.nodes { GhostwatchIncidentNode }
import from lib.sandbox_exec { run_dependency_install_sandbox }
import from walkers.ghostwatch.fix_gen { FixGenerationWalker }
import from time { time }

impl SandboxExecutorWalker._interpret_behavior(raw_evidence: dict) -> dict {
    if raw_evidence.get("credential_path_access") or raw_evidence.get("self_delete_indicators") {
        return {
            "summary": "Sandbox logs matched credential-path or self-delete heuristics",
            "verdict": "malicious",
            "iocs": []
        };
    }
    if raw_evidence.get("install_ok", False) {
        return {
            "summary": "Install completed without structured hostile signals in the local sandbox",
            "verdict": "cleared",
            "iocs": []
        };
    }
    return {
        "summary": "Install failed or sandbox error — human review recommended",
        "verdict": "needs_human_review",
        "iocs": []
    };
}

impl SandboxExecutorWalker.run with Root entry {
    handled = False;
    for target in [root -->][?:GhostwatchIncidentNode] {
        if str(jid(target)) != self.incident_jid {
            continue;
        }
        handled = True;
        target.status = "sandboxed";
        target.updated_at = str(int(time()));
        eco = "pip";
        if target.manifest_path.endswith("package.json") {
            eco = "npm";
        }
        raw = run_dependency_install_sandbox(eco, target.dependency_name, target.dependency_version, "");
        target.sandbox_result = raw;
        try {
            bt = self._interpret_behavior(raw_evidence=raw);
        } except Exception {
            bt = {"summary": "LLM interpretation failed", "verdict": "needs_human_review", "iocs": []};
        }
        if str(target.risk_level).lower() == "critical" {
            bt = {
                "summary": "Critical static risk — automated remediation path",
                "verdict": "malicious",
                "iocs": []
            };
        }
        target.behavioral_trace = bt;
        v = str(bt["verdict"]) if isinstance(bt, dict) and "verdict" in bt else "needs_human_review";
        v = str(v).lower();
        if v == "malicious" {
            target.status = "malicious";
        } elif v == "cleared" {
            target.status = "cleared";
        } else {
            target.status = "needs_human_review";
        }
        target.updated_at = str(int(time()));
        if target.status == "malicious" {
            _ = root spawn FixGenerationWalker(incident_jid=self.incident_jid);
        }
        report {"status": target.status, "jid": self.incident_jid};
        break;
    }
    if not handled {
        report {"error": "incident not found", "jid": self.incident_jid};
    }
}

