            labelNode = document.querySelector("label[for=\"" + CSS.escape(fieldId) + "\"]");  # jac:ignore[E1032,E1055]
            if labelNode {
                labelText = truncateText(labelNode.innerText or labelNode.textContent or "", 140);  # jac:ignore[E1030]
                if labelText {
                    return labelText;
                }
