            results.push({  # jac:ignore[E1030]
                "action": truncateText(form.getAttribute("action") or "", 240),  # jac:ignore[E1032]
                "method": truncateText(form.getAttribute("method") or "GET", 16).toUpperCase(),  # jac:ignore[E1030,E1032]
