# ── Walkers ──────────────────────────────────────────

walker :pub BuildGraph {
    has packages: list[dict] = [];

    can build with Root entry {
        report build_graph(self.packages);
    }
}

walker :pub Infect {
    has target_name: str = "";
    has compromised_ids: list[str] = [];
    has compromised_packages: list[dict] = [];
    has total_damage: int = 0;
    has found: bool = False;

    can start with Root entry {
        for pkg in [-->][?:Package] {
            if pkg.name == self.target_name {
                self.found = True;
                visit pkg;
                return;
            }
        }
    }

    can spread with Package entry {
        if jid(here) in self.compromised_ids {
            return;
        }

        if here.compromise_depth < 0 {
            if len(self.compromised_ids) == 0 {
                here.compromise_depth = 0;
            } else {
                parent_depths = [parent.compromise_depth for parent in [-->][?:Package] if parent.compromise_depth >= 0];
                here.compromise_depth = min(parent_depths) + 1 if parent_depths else 1;
            }
        }

        here.compromised = True;
        self.compromised_ids.append(jid(here));
        self.compromised_packages.append({
            "name": here.name,
            "depth": here.compromise_depth,
            "weekly_downloads": here.weekly_downloads
        });
        self.total_damage += here.weekly_downloads;

        visit [<--][?:Package];
    }

    can finish with Root exit {
        if self.found {
            report {
                "success": True,
                "target": self.target_name,
                "compromised_count": len(self.compromised_ids),
                "affected_weekly_downloads": self.total_damage,
                "compromised_packages": self.compromised_packages
            };
        } else {
            report {"success": False, "error": "Package not found", "target": self.target_name};
        }
    }
}

walker :pub Assess {
    has assessed: int = 0;

    can start with Root entry {
        visit [-->][?:Package];
        report {"success": True, "assessed": self.assessed};
    }

    can summarize with Package entry {
        if here.compromised {
            dependent_count = len([<--][?:Package]);
            here.threat_summary = assess_package_threat(
                package_name=here.name,
                weekly_downloads=here.weekly_downloads,
                compromise_depth=here.compromise_depth,
                dependent_count=dependent_count
            );
            self.assessed += 1;
        }
    }
}

walker :pub Reset {
    has reset_count: int = 0;

    can start with Root entry {
        visit [-->][?:Package];
        report {"success": True, "reset_count": self.reset_count};
    }

    can clear with Package entry {
        here.compromised = False;
        here.compromise_depth = -1;
        here.threat_summary = "";
        self.reset_count += 1;
    }
}

walker :pub GetGraph {
    has packages: list[dict] = [];

    can start with Root entry {
        visit [-->][?:Package];
        report {
            "success": True,
            "package_count": len(self.packages),
            "packages": self.packages
        };
    }

    can collect with Package entry {
        self.packages.append(package_to_dict(here));
    }
}

walker :pub RiskHeatmap {
    has packages: list[dict] = [];

    can start with Root entry {
        visit [-->][?:Package];
    }

    can collect with Package entry {
        self.packages.append({
            "name": here.name,
            "weekly_downloads": here.weekly_downloads,
            "dependent_count": here.dependent_count,
            "risk_score": here.risk_score,
            "blast_radius": here.blast_radius,
            "cve_count": here.cve_count,
            "compromised": here.compromised,
            "compromise_depth": here.compromise_depth
        });
    }
}

walker :pub BlastRadius {
    has target_name: str = "";
    has affected: list[dict] = [];
    has visited_names: list[str] = [];
    has total_downloads: int = 0;
    has max_depth: int = 0;
    has by_depth: dict = {};
    has found: bool = False;

    can start with Root entry {
        for pkg in [-->][?:Package] {
            if pkg.name == self.target_name {
                self.found = True;
                visit pkg;
                return;
            }
        }
    }

    can propagate with Package entry {
        if here.name in self.visited_names {
            return;
        }

        depth = 0;
        if len(self.visited_names) > 0 {
            depth = self.max_depth + 1;
        }

        self.visited_names.append(here.name);
        self.affected.append({
            "name": here.name,
            "depth": depth,
            "weekly_downloads": here.weekly_downloads,
            "dependent_count": here.dependent_count,
            "risk_score": here.risk_score
        });
        self.total_downloads += here.weekly_downloads;
        if depth > self.max_depth {
            self.max_depth = depth;
        }

        depth_key = str(depth);
        if depth_key not in self.by_depth {
            self.by_depth[depth_key] = [];
        }
        self.by_depth[depth_key].append({
            "name": here.name,
            "downloads": here.weekly_downloads
        });

        # Walk reverse edges: packages that depend on this one
        visit [<--][?:Package];
    }
}

walker :pub GetScenarios {
    has scenarios: list[dict] = [];

    can start with Root entry {
        visit [-->][?:AttackScenario];
    }

    can collect with AttackScenario entry {
        self.scenarios.append({
            "id": here.scenario_id,
            "display_title": here.display_title,
            "year": here.year,
            "attack_type": here.attack_type,
            "description": here.description,
            "affected_packages": here.affected_packages,
            "timeline": here.timeline,
            "blast_radius_snapshot": here.blast_radius_snapshot,
            "cascade_data": here.cascade_data
        });
    }
}

# LLM-powered relationship assessment, contradiction detection, path scoring

obj RelationshipAssessment {
    has related: bool;
    has relationship_type: str;
    has strength: float;
    has explanation: str;
}

obj ContradictionAssessment {
    has contradicts: bool;
    has tension: str;
    has severity: float;
}

obj PathRelevanceScore {
    has relevance: float;
    has explanation: str;
    has key_connections: list[str];
}


sem assess_relationship = """
Assess whether two concepts are meaningfully related. Consider semantic similarity,
causal connections, analogical parallels, and prerequisite relationships. Return whether
they are related, what type of relationship exists (relates_to, builds_upon, contradicts,
or inspired_by), the strength of the relationship (0.0 to 1.0), and a brief explanation.
Be selective - only mark concepts as related if there is a genuine intellectual connection,
not just surface-level word overlap.
""";

sem detect_contradiction = """
Determine if two claims contradict each other. Claims may directly conflict, be in logical
tension, or represent incompatible perspectives. Return whether they contradict, a description
of the tension, and severity (0.0 = minor nuance difference, 1.0 = direct logical
contradiction). Only flag genuine contradictions, not complementary perspectives on the
same topic.
""";

sem score_path_relevance = """
Given a question and a path of concepts through a knowledge graph, score how relevant this
path is to answering the question. Consider: does the path connect concepts that help answer
the question? Are the intermediate concepts logical stepping stones? Return a relevance
score (0.0 to 1.0), an explanation of why this path is or isn't relevant, and a list of
the key connections along the path that matter most.
""";


def assess_relationship(
    concept_a: str,
    desc_a: str,
    concept_b: str,
    desc_b: str
) -> RelationshipAssessment by llm(temperature=0.1);

def detect_contradiction(
    claim_a: str,
    claim_b: str
) -> ContradictionAssessment by llm(temperature=0.0);

def score_path_relevance(
    question: str,
    path_concepts: list[str],
    path_descriptions: list[str]
) -> PathRelevanceScore by llm(temperature=0.2);

# LLM-powered concept, people, and relationship extraction

obj ConceptExtraction {
    has name: str;
    has description: str;
    has domain: str;
    has depth: str;
}

obj PersonExtraction {
    has name: str;
    has context: str;
}

obj RelationshipExtraction {
    has source_concept: str;
    has target_concept: str;
    has relationship_type: str;
    has strength: float;
    has explanation: str;
}


sem extract_concepts = """
Extract key concepts from the given text. Return a list of concepts, each with:
name (concise label), description (1-2 sentences explaining the concept),
domain (e.g., machine_learning, philosophy, business, science, arts, cross_domain),
and depth (surface for briefly mentioned, intermediate for explained, deep for
thoroughly discussed). Focus on substantive intellectual concepts, not trivial mentions.
The source_type parameter indicates the format of the input (article, tweet, note,
highlight, conversation, lecture) - adjust extraction granularity accordingly:
tweets yield fewer, broader concepts; articles yield more, deeper ones.
""";

sem extract_people = """
Extract people mentioned in the text. Return their name and context
(how they relate to the content - e.g., 'author of the paper', 'proposed this theory',
'CEO of the company'). Only include real, named individuals - not pronouns or
generic references.
""";

sem extract_relationships = """
Given a list of concept names and their descriptions, identify relationships between them.
For each relationship, specify: source_concept and target_concept (exact names from the
input list), relationship_type (one of: relates_to, builds_upon, contradicts, inspired_by),
strength (0.0 to 1.0, where 1.0 is very strong), and explanation (brief description of
how they relate). Only include relationships that are meaningful and supported by the
concepts' definitions. Prefer fewer, high-quality relationships over many weak ones.
Use builds_upon when one concept is a prerequisite or foundation for another.
Use contradicts when concepts present opposing views or incompatible claims.
Use inspired_by when one concept historically or logically led to the development of another.
Use relates_to for all other meaningful connections.
""";


def extract_concepts(text: str, source_type: str) -> list[ConceptExtraction]
    by llm(temperature=0.3);

def extract_people(text: str) -> list[PersonExtraction]
    by llm(temperature=0.1);

def extract_relationships(concepts: list[str], descriptions: list[str]) -> list[RelationshipExtraction]
    by llm(temperature=0.3);

# LLM-powered path narration, contradiction descriptions, daily digests

obj PathNarration {
    has narration: str;
}

obj ContradictionDescription {
    has description: str;
}

obj DailyDigest {
    has digest: str;
}


sem narrate_path = """
Narrate a walker's journey through a knowledge graph path as if telling a story. Describe
how each concept connects to the next, what the edges between them represent, and how this
path answers or relates to the original question. Use engaging, first-person language like
'Starting from X, we follow the thread to Y, because...' Make it feel like an intellectual
adventure, not a dry listing. Keep it to 3-5 sentences.
""";

sem describe_contradiction = """
Describe a contradiction found between two claims in a user's knowledge graph. Present both
sides fairly, explain the tension, and suggest how the user might resolve or reconcile the
contradiction. Be intellectually honest - some contradictions are genuine paradoxes, others
are context-dependent. Keep it to 3-4 sentences.
""";

sem generate_digest = """
Generate a daily knowledge digest summarizing what's happening in the user's knowledge graph.
Mention new insights discovered (if any), knowledge connections that are fading and might
need review, and areas where the graph has gaps. Write in a friendly, encouraging tone -
like a knowledgeable assistant giving a morning briefing. Keep it to 4-6 sentences.
""";


def narrate_path(
    path_nodes: list[str],
    path_edges: list[str],
    question: str
) -> PathNarration by llm(temperature=0.6);

def describe_contradiction(
