# Edge archetypes — strength decays via Ebbinghaus: S(t) = S_0 * e^(-lambda*t) + S_base

# General semantic relationship between concepts.
edge relates_to {
    has strength: float = 0.5,
        relationship: str = "",
        created_at: float = 0.0,
        last_reinforced: float = 0.0,
        reinforcement_count: int = 1;
}

# Directional: source concept is foundation for target.
edge builds_upon {
    has strength: float = 0.7,
        explanation: str = "",
        created_at: float = 0.0;
}

# Conflicting concepts or claims.
edge contradicts {
    has strength: float = 0.5,
        tension: str = "",
        resolved: bool = False,
        created_at: float = 0.0;
}

# Links back to source material.
edge sourced_from {
    has relevance: float = 0.8,
        excerpt: str = "";
}

# Learning X led to thinking about Y.
edge inspired_by {
    has created_at: float = 0.0,
        context: str = "";
}

# Concept applied in a project.
edge applied_in {
    has how: str = "";
}

# Person referenced or discussed a concept.
edge mentioned_by {
    has context: str = "";
}

# Time-ordered connection.
edge temporal {
    has timestamp: float = 0.0,
        sequence_type: str = "";
}

# Node archetypes for the knowledge graph

# Concept — backbone of the graph, represents a discrete unit of knowledge.
node Concept {
    has name: str,
        description: str,
        domain: str,
        importance: float = 0.5,
        created_at: float = 0.0,
        last_accessed: float = 0.0,
        access_count: int = 0,
        depth: str = "surface";
}

# Source — raw input material, preserves provenance.
node Source {
    has title: str,
        source_type: str,
        content: str,
        url: str = "",
        ingested_at: float = 0.0,
        summary: str = "";
}

# Insight — discovered connection between concepts (generated by Explorer).
node Insight {
    has title: str,
        description: str,
        confidence: float = 0.5,
        path: list = [],
        generated_at: float = 0.0,
        validated: bool = False;
}

# Question — user query answered by Pathfinder via graph traversal.
node Question {
    has text: str,
        asked_at: float = 0.0,
        answered: bool = False,
        answer_path: list = [],
        answer_text: str = "";
}

# Person — someone referenced in knowledge sources.
node Person {
    has name: str,
        context: str = "";
}

# Project — tracks how knowledge is applied in practice.
node Project {
    has name: str,
        description: str = "",
        status: str = "active";
}

# Loads demo knowledge base from JSON into the Jac graph

import json;
import time;
import os;

import from graph.nodes { Concept, Source, Insight, Question, Person, Project }
import from graph.edges { relates_to, builds_upon, contradicts, sourced_from, inspired_by, applied_in, mentioned_by, temporal }

walker SeedGraph {
    has data_path: str = "data/demo_knowledge.json";
    has node_map: dict = {};
    has node_count: int = 0;
    has edge_count: int = 0;

    can seed with Root entry {
        now = time.time();

        json_path = self.data_path;
        if not os.path.isabs(json_path) {
            for base in [os.getcwd(), os.path.dirname(os.path.abspath(__file__))] {
                candidate = os.path.join(base, json_path);
                if os.path.exists(candidate) {
                    json_path = candidate;
                    break;
                }
            }
            if not os.path.exists(json_path) {
                file_dir = os.path.dirname(os.path.abspath(__file__));
                project_root = os.path.dirname(os.path.dirname(file_dir));
                candidate = os.path.join(project_root, self.data_path);
                if os.path.exists(candidate) {
                    json_path = candidate;
                }
            }
        }

        with open(json_path, "r") as f {
            data = json.load(f);
        }

        for node_data in data.get("nodes", []) {
            node_id = node_data["id"];
            new_node = self.create_node(node_data, now);
            if new_node is not None {
                here ++> (new_node as Concept);
                self.node_map[node_id] = new_node;
                self.node_count += 1;
            }
        }

        for edge_data in data.get("edges", []) {
            source_id = edge_data.get("source", "");
            target_id = edge_data.get("target", "");
            source_node = self.node_map.get(source_id);
            target_node = self.node_map.get(target_id);

            if source_node is None or target_node is None {
                continue;
            }

            self.create_edge(source_node, target_node, edge_data, now);
            self.edge_count += 1;
        }

        print(
            f"[ORBIT Seed] Graph seeded: {self.node_count} nodes, "
            f"{self.edge_count} edges created."
        );
    }

    def create_node(data: dict, now: float) -> any {
        node_type = data.get("type", "");

        if node_type == "Concept" {
            return Concept(
                name=data.get("name", ""),
                description=data.get("description", ""),
                domain=data.get("domain", "general"),
                importance=data.get("importance", 0.5),
                created_at=now,
                last_accessed=now,
                access_count=0,
                depth=data.get("depth", "surface")
            );
        } elif node_type == "Source" {
            return Source(
                title=data.get("title") or data.get("name", ""),
                source_type=data.get("source_type", "article"),
                content=data.get("content") or data.get("description", ""),
                url=data.get("url", ""),
                ingested_at=now,
                summary=data.get("summary", "")
            );
        } elif node_type == "Insight" {
            return Insight(
                title=data.get("title") or data.get("name", ""),
                description=data.get("description", ""),
                confidence=data.get("confidence", 0.5),
                path=data.get("path", []),
                generated_at=now,
                validated=data.get("validated", False)
            );
        } elif node_type == "Question" {
            return Question(
                text=data.get("text", ""),
                asked_at=now,
                answered=data.get("answered", False),
                answer_path=data.get("answer_path", []),
                answer_text=data.get("answer_text", "")
            );
        } elif node_type == "Person" {
            return Person(
                name=data.get("name", ""),
                context=data.get("context", "")
            );
        } elif node_type == "Project" {
            return Project(
                name=data.get("name", ""),
                description=data.get("description", ""),
                status=data.get("status", "active")
            );
        } else {
            print(f"[ORBIT Seed] Warning: Unknown node type '{node_type}', skipping.");
            return None;
        }
    }

    def create_edge(src: any, tgt: any, data: dict, now: float) {
        edge_type = data.get("type", "relates_to");

        if edge_type == "relates_to" {
            src +>:relates_to(
                strength=data.get("strength", 0.5),
                relationship=data.get("relationship", ""),
                created_at=now,
                last_reinforced=now,
                reinforcement_count=1
            ):+> tgt;
        } elif edge_type == "builds_upon" {
            src +>:builds_upon(
                strength=data.get("strength", 0.7),
                explanation=data.get("explanation", ""),
                created_at=now
            ):+> tgt;
        } elif edge_type == "contradicts" {
            src +>:contradicts(
                strength=data.get("strength", 0.5),
                tension=data.get("tension", ""),
                resolved=data.get("resolved", False),
                created_at=now
            ):+> tgt;
        } elif edge_type == "sourced_from" {
            src +>:sourced_from(
                relevance=data.get("relevance", 0.8),
                excerpt=data.get("excerpt", "")
            ):+> tgt;
        } elif edge_type == "inspired_by" {
            src +>:inspired_by(
                created_at=now,
                context=data.get("context", "")
            ):+> tgt;
        } elif edge_type == "applied_in" {
            src +>:applied_in(
                how=data.get("how", "")
            ):+> tgt;
        } elif edge_type == "mentioned_by" {
            src +>:mentioned_by(
                context=data.get("context", "")
            ):+> tgt;
        } elif edge_type == "temporal" {
            src +>:temporal(
                timestamp=data.get("timestamp", now),
                sequence_type=data.get("sequence_type", "")
            ):+> tgt;
        } else {
            print(f"[ORBIT Seed] Warning: Unknown edge type '{edge_type}', using relates_to.");
            src +>:relates_to(
                strength=data.get("strength", 0.5),
                relationship=data.get("relationship", f"unknown type: {edge_type}"),
                created_at=now,
                last_reinforced=now,
                reinforcement_count=1
            ):+> tgt;
        }
    }
}

def seed_knowledge_graph(root_node: Root, data_path: str = "data/demo_knowledge.json") -> dict {
    seeder = root_node spawn SeedGraph(data_path=data_path);
    return seeder.node_map;
}

# Cartographer walker — maps intellectual territory by domain, finds
# bridge concepts, and identifies isolated knowledge islands.

import time;

import from graph.nodes { Concept, Source, Insight, Question, Person, Project }
import from ai.synthesize { generate_cluster_summary }


walker Cartographer {
    has dense_threshold: int = 10;
    has moderate_threshold: int = 5;
    has bridge_min_domains: int = 2;

    has traversal_path: list = [];
    has visited_ids: list = [];

    has domain_concepts: dict = {};
    has concept_edge_counts: dict = {};
    has concept_domains_touched: dict = {};
    has domain_edge_pairs: dict = {};

    has total_concepts: int = 0;
    has total_sources: int = 0;
    has total_insights: int = 0;
    has total_persons: int = 0;
    has total_projects: int = 0;
    has total_questions: int = 0;
    has total_edges_seen: int = 0;

    has territories: list = [];
    has bridges: list = [];
    has islands: list = [];

    can begin with Root entry {
        visit [-->];
    }

    can map_concept with Concept entry {
        node_id = here.__jac__.id;
        if node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(node_id);

        self.traversal_path.append({
            "type": "concept",
            "name": here.name,
            "domain": here.domain
        });

        here.access_count += 1;
        here.last_accessed = time.time();
        self.total_concepts += 1;

        domain = here.domain;
        if domain not in self.domain_concepts {
            self.domain_concepts[domain] = [];
        }
        self.domain_concepts[domain].append({
            "name": here.name,
            "description": here.description,
            "importance": here.importance,
            "depth": here.depth,
            "access_count": here.access_count
        });

        neighbors = [-->][?:Concept];
        also_back = [<--][?:Concept];
        all_neighbors: list = [];
        seen_neighbor_ids: list = [];
        for n in neighbors {
            nid = n.__jac__.id;
            if nid not in seen_neighbor_ids {
                seen_neighbor_ids.append(nid);
                all_neighbors.append(n);
            }
        }
        for n in also_back {
            nid = n.__jac__.id;
            if nid not in seen_neighbor_ids {
                seen_neighbor_ids.append(nid);
                all_neighbors.append(n);
            }
        }

        edge_count = len(all_neighbors);
        self.concept_edge_counts[here.name] = edge_count;
        self.total_edges_seen += edge_count;

        domains_touched: list = [];
        for n in all_neighbors {
            n_domain = n.domain;
            if n_domain != domain and n_domain not in domains_touched {
                domains_touched.append(n_domain);
            }
            if n_domain != domain {
                pair_key = "|".join(sorted([domain, n_domain]));
                if pair_key not in self.domain_edge_pairs {
                    self.domain_edge_pairs[pair_key] = 0;
                }
                self.domain_edge_pairs[pair_key] += 1;
            }
        }
        self.concept_domains_touched[here.name] = domains_touched;

        visit [-->];
    }

    can count_source with Source entry {
        node_id = here.__jac__.id;
        if node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(node_id);
        self.total_sources += 1;
        self.traversal_path.append({
            "type": "source",
            "name": here.title
        });
        visit [-->];
    }

    can count_insight with Insight entry {
        node_id = here.__jac__.id;
        if node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(node_id);
        self.total_insights += 1;
        self.traversal_path.append({
            "type": "insight",
            "name": here.title
        });
        visit [-->];
    }

    can count_question with Question entry {
        node_id = here.__jac__.id;
        if node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(node_id);
        self.total_questions += 1;
        self.traversal_path.append({
            "type": "question",
            "name": here.text
        });
        visit [-->];
    }

    can count_person with Person entry {
        node_id = here.__jac__.id;
        if node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(node_id);
        self.total_persons += 1;
        self.traversal_path.append({
            "type": "person",
            "name": here.name
        });
        visit [-->];
    }

    can count_project with Project entry {
        node_id = here.__jac__.id;
        if node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(node_id);
        self.total_projects += 1;
        self.traversal_path.append({
            "type": "project",
            "name": here.name
        });
        visit [-->];
    }

    can finish with Root exit {
        total_nodes = (self.total_concepts + self.total_sources
                       + self.total_insights + self.total_persons
                       + self.total_projects + self.total_questions);

        for domain in self.domain_concepts {
            concepts = self.domain_concepts[domain];
            concept_names = [c["name"] for c in concepts];
            concept_descriptions = [c["description"] for c in concepts];
            concept_count = len(concepts);

            density = "sparse";
            if concept_count >= self.dense_threshold {
                density = "dense";
            } elif concept_count >= self.moderate_threshold {
                density = "moderate";
            }

            avg_importance = 0.0;
            depth_counts: dict = {"surface": 0, "intermediate": 0, "deep": 0};
            total_access = 0;
            for c in concepts {
                avg_importance += c["importance"];
                total_access += c["access_count"];
                d = c["depth"];
                if d in depth_counts {
                    depth_counts[d] += 1;
                }
            }
            avg_importance = avg_importance / concept_count if concept_count > 0 else 0.0;

            cross_connections = 0;
            connected_domains: list = [];
            for pair_key in self.domain_edge_pairs {
                if domain in pair_key.split("|") {
                    cross_connections += self.domain_edge_pairs[pair_key];
                    parts = pair_key.split("|");
                    other = parts[1] if parts[0] == domain else parts[0];
                    if other not in connected_domains {
                        connected_domains.append(other);
                    }
                }
            }

            is_island = cross_connections == 0 and concept_count > 0;

            domain_bridges: list = [];
            for c in concepts {
                name = c["name"];
                if name in self.concept_domains_touched {
                    touched = self.concept_domains_touched[name];
                    if len(touched) >= self.bridge_min_domains {
                        domain_bridges.append({
                            "name": name,
                            "domains_connected": touched,
                            "edge_count": self.concept_edge_counts.get(name, 0)
                        });
                    }
                }
            }

            cluster_label = domain;
            cluster_theme = "";
            cluster_knowledge_level = "surface";
            if concept_count >= 2 {
                try {
                    summary = generate_cluster_summary(
                        concepts=concept_names,
                        descriptions=concept_descriptions
                    );
                    cluster_label = summary.label;
                    cluster_theme = summary.theme;
                    cluster_knowledge_level = summary.knowledge_level;
                } except Exception as e {
                    cluster_label = domain.replace("_", " ").title();
                    cluster_theme = f"A collection of {concept_count} concepts in {domain}";
                    if density == "deep" {
                        cluster_knowledge_level = "deep";
                    } elif density == "moderate" {
                        cluster_knowledge_level = "intermediate";
                    }
                }
            }

            territory = {
                "domain": domain,
                "label": cluster_label,
                "theme": cluster_theme,
                "concept_count": concept_count,
                "concepts": concept_names,
                "density": density,
                "avg_importance": round(avg_importance, 3),
                "depth_distribution": depth_counts,
                "total_access": total_access,
                "cross_connections": cross_connections,
                "connected_domains": connected_domains,
                "is_island": is_island,
                "bridges": domain_bridges,
                "knowledge_level": cluster_knowledge_level
            };
            self.territories.append(territory);

            if is_island {
                self.islands.append(domain);
            }
        }

        density_order = {"dense": 0, "moderate": 1, "sparse": 2};
        self.territories.sort(
            key=lambda (t: dict) { (density_order.get(t["density"], 3), -t["concept_count"]); }
        );

        for concept_name in self.concept_domains_touched {
            touched = self.concept_domains_touched[concept_name];
            if len(touched) >= self.bridge_min_domains {
                self.bridges.append({
                    "name": concept_name,
                    "domains_connected": touched,
                    "edge_count": self.concept_edge_counts.get(concept_name, 0)
                });
        }
        }
        self.bridges.sort(key=lambda (b: dict) { len(b["domains_connected"]); }, reverse=True);

        # Domain-level meta-graph
        domain_adjacency: list = [];
        for pair_key in self.domain_edge_pairs {
            parts = pair_key.split("|");
            domain_adjacency.append({
                "source": parts[0],
                "target": parts[1],
                "weight": self.domain_edge_pairs[pair_key]
            });
        }
        domain_adjacency.sort(key=lambda (d: dict) { d["weight"]; }, reverse=True);

        report {
            "status": "complete",
            "traversal_path": self.traversal_path,
            "territories": self.territories,
            "bridges": self.bridges,
            "islands": self.islands,
            "domain_adjacency": domain_adjacency,
            "stats": {
                "total_nodes": total_nodes,
                "total_concepts": self.total_concepts,
                "total_sources": self.total_sources,
                "total_insights": self.total_insights,
                "total_persons": self.total_persons,
                "total_projects": self.total_projects,
                "total_questions": self.total_questions,
                "total_edges": self.total_edges_seen // 2,
                "num_domains": len(self.domain_concepts),
                "num_bridges": len(self.bridges),
                "num_islands": len(self.islands)
            }
        };
    }
}

# Consolidator walker — cluster summarization, edge decay detection,
# and orphan detection across the knowledge graph.

import time;
import math;

import from graph.nodes { Concept, Insight }
import from graph.edges { builds_upon }
import from ai.synthesize { generate_cluster_summary }


def build_adjacency(concept_nodes: list, neighbor_map: dict) -> dict {
    adjacency: dict = {};
    for node_name in neighbor_map {
        adjacency[node_name] = set(neighbor_map[node_name]);
    }
    return adjacency;
}


# Greedy clustering: grow clusters from seeds by neighbor overlap
def find_dense_clusters(
    concept_names: list,
    adjacency: dict,
    min_cluster_size: int = 3,
    overlap_threshold: float = 0.3
) -> list {
    clusters: list = [];
    assigned: set = set();

    for name in concept_names {
        if name in assigned or name not in adjacency {
            continue;
        }
        cluster: list = [name];
        cluster_set: set = {name};

        neighbors = adjacency.get(name, set());
        for neighbor in neighbors {
            if neighbor in assigned or neighbor not in adjacency {
                continue;
            }
            neighbor_adj = adjacency.get(neighbor, set());
            shared = len(neighbors & neighbor_adj);
            total = max(len(neighbors | neighbor_adj), 1);
            if shared / total >= overlap_threshold or shared >= 2 {
                cluster.append(neighbor);
                cluster_set.add(neighbor);
            }
        }

        if len(cluster) >= min_cluster_size {
            for c in cluster {
                assigned.add(c);
            }
            clusters.append(cluster);
        }
    }

    return clusters;
}


walker Consolidator {
    has decay_threshold: float = 0.2;
    has min_cluster_size: int = 3;
    has min_neighbors: int = 2;
    has max_cluster_concepts: int = 20;

    has traversal_path: list = [];
    has concepts_visited: list = [];
    has concept_data: dict = {};
    has neighbor_map: dict = {};
    has weak_edges_found: list = [];
    has orphans_found: list = [];
    has summaries_created: list = [];
    has edges_inspected: int = 0;
    has visited_ids: list = [];

    can begin with Root entry {
        concepts = [-->][?:Concept];
        if len(concepts) == 0 {
            report {
                "status": "empty_graph",
                "traversal_path": [],
                "concepts_analyzed": 0,
                "weak_edges": [],
                "orphans": [],
                "summaries_created": []
            };
            disengage;
        }
        visit concepts;
    }

    can analyze with Concept entry {
        node_id = here.__jac__.id;
        if node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(node_id);

        self.traversal_path.append(here.name);
        self.concepts_visited.append(here.name);
        here.access_count += 1;
        here.last_accessed = time.time();

        self.concept_data[here.name] = {
            "description": here.description,
            "domain": here.domain,
            "importance": here.importance,
            "depth": here.depth
        };

        neighbor_names: list = [];
        outgoing_edges: list = [edge <-->];
        for e in outgoing_edges {
            self.edges_inspected += 1;

            if hasattr(e, "strength") {
                if e.strength < self.decay_threshold {
                    target_name = "";
                    if hasattr(e, "relationship") {
                        target_name = e.relationship;
                    }
                    self.weak_edges_found.append({
                        "from": here.name,
                        "edge_type": type(e).__name__,
                        "strength": round(e.strength, 3),
                        "relationship": target_name,
                        "last_reinforced": getattr(e, "last_reinforced", 0.0),
                        "message": "Connection from '" + here.name + "' is fading (strength: " + str(round(e.strength, 3)) + ")"
                    });
                }
            }
        }

        concept_neighbors = [-->][?:Concept];
        for n in concept_neighbors {
            neighbor_names.append(n.name);
        }
        incoming_neighbors = [<--][?:Concept];
        for n in incoming_neighbors {
            if n.name not in neighbor_names {
                neighbor_names.append(n.name);
            }
        }
        self.neighbor_map[here.name] = neighbor_names;

        total_connections = len(concept_neighbors) + len(incoming_neighbors);
        if total_connections < self.min_neighbors {
            self.orphans_found.append({
                "name": here.name,
                "domain": here.domain,
                "connections": total_connections,
                "message": "'" + here.name + "' is isolated with only " + str(total_connections) + " connection(s). Consider linking it to related concepts."
            });
        }

        unvisited: list = [];
        for n in concept_neighbors {
            if n.__jac__.id not in self.visited_ids {
                unvisited.append(n);
            }
        }
        if len(unvisited) > 0 {
            visit unvisited;
        }
    }

    can finish with Root exit {
        if len(self.concepts_visited) >= self.min_cluster_size {
            adjacency = build_adjacency(self.concepts_visited, self.neighbor_map);
            clusters = find_dense_clusters(
                self.concepts_visited,
                adjacency,
                min_cluster_size=self.min_cluster_size
            );

            for cluster in clusters {
                cluster_limited = cluster[:self.max_cluster_concepts];
                descriptions: list = [];
                for name in cluster_limited {
                    if name in self.concept_data {
                        descriptions.append(self.concept_data[name]["description"]);
                    } else {
                        descriptions.append("");
                    }
                }

                summary = generate_cluster_summary(
                    cluster_limited,
                    descriptions
                );

                insight_node = Insight(
                    title=summary.label,
                    description=summary.theme,
                    confidence=0.7,
                    path=cluster_limited,
                    generated_at=time.time()
                );

                root ++> insight_node;

                self.summaries_created.append({
                    "title": summary.label,
                    "theme": summary.theme,
                    "key_concepts": summary.key_concepts,
                    "knowledge_level": summary.knowledge_level,
                    "cluster_size": len(cluster_limited)
                });
            }
        }

        report {
            "status": "complete",
            "traversal_path": self.traversal_path,
            "concepts_analyzed": len(self.concepts_visited),
            "edges_inspected": self.edges_inspected,
            "weak_edges": self.weak_edges_found,
            "weak_edge_count": len(self.weak_edges_found),
            "orphans": self.orphans_found,
            "orphan_count": len(self.orphans_found),
            "summaries_created": self.summaries_created,
            "clusters_found": len(self.summaries_created)
        };
    }
}

# Explorer walker — random walks biased toward weak edges to discover
# hidden connections and reinforce traversed edges (spaced repetition).

import time;
import random;
import math;

import from graph.nodes { Concept, Insight }
import from graph.edges { sourced_from }
import from ai.synthesize { generate_insight }

def pick_start_node(concepts: list) -> any {
    if len(concepts) == 0 {
        return None;
    }
    now = time.time();
    weights: list = [];
    for c in concepts {
        recency_bonus = math.exp(-(now - c.created_at) / 86400.0) if c.created_at > 0 else 0.1;
        w = c.importance + 0.3 * recency_bonus;
        weights.append(max(w, 0.01));
    }
    return random.choices(concepts, weights=weights, k=1)[0];
}

# Inverse-strength weighting: weaker edges = higher selection probability
def pick_weak_neighbor(current_node: any, neighbors: list) -> tuple {
    if len(neighbors) == 0 {
        return (None, None);
    }
    edge_info: list = [];
    for n in neighbors {
        edge_info.append((n, 0.5));
    }
    weights: list = [];
    for (n, strength) in edge_info {
        inv_weight = 1.0 / (strength + 0.05);
        weights.append(inv_weight);
    }
    chosen = random.choices([ei[0] for ei in edge_info], weights=weights, k=1)[0];
    chosen_strength = 0.5;
    for (n, s) in edge_info {
        if n is chosen {
            chosen_strength = s;
            break;
        }
    }
    return (chosen, chosen_strength);
}

# Traversed edges get a small strength boost (spaced repetition)
def reinforce_edge(e: any) -> None {
    e.last_reinforced = time.time();
    e.reinforcement_count = e.reinforcement_count + 1;
    e.strength = min(e.strength + 0.02, 1.0);
}


walker Explorer {
    has max_hops: int = 6;
    has min_confidence: float = 0.5;

    has traversal_path: list = [];
    has path_descriptions: list = [];
    has path_domains: list = [];
    has discoveries: list = [];
    has visited_ids: list = [];
    has hops_taken: int = 0;
    has start_concept: str = "";

    can begin with Root entry {
        concepts = [-->][?:Concept];
        if len(concepts) == 0 {
            report {
                "status": "empty_graph",
                "traversal_path": [],
                "discoveries": [],
                "hops_taken": 0
            };
            disengage;
        }
        starter = pick_start_node(concepts);
        if starter is not None {
            visit (starter as Concept);
        } else {
            report {
                "status": "no_start",
                "traversal_path": [],
                "discoveries": [],
                "hops_taken": 0
            };
            disengage;
        }
    }

    can explore with Concept entry {
        self.traversal_path.append(here.name);
        self.path_descriptions.append(here.description);
        self.path_domains.append(here.domain);
        self.visited_ids.append(here.__jac__.id);
        here.access_count += 1;
        here.last_accessed = time.time();
        self.hops_taken += 1;

        if self.hops_taken == 1 {
            self.start_concept = here.name;
        }

        for e in ([edge <-->] as list) {
            if hasattr(e, "last_reinforced") {
                reinforce_edge(e);
            }
        }

        if self.hops_taken >= self.max_hops {
            self._try_generate_insight(here);
            report {
                "status": "complete",
                "traversal_path": self.traversal_path,
                "path_domains": self.path_domains,
                "discoveries": self.discoveries,
                "hops_taken": self.hops_taken
            };
            disengage;
        }

        neighbors = [-->][?:Concept];
        unvisited: list = [];
        for n in neighbors {
            if n.__jac__.id not in self.visited_ids {
                unvisited.append(n);
            }
        }
        candidates = unvisited if len(unvisited) > 0 else neighbors;

        if len(candidates) == 0 {
            self._try_generate_insight(here);
            report {
                "status": "dead_end",
                "traversal_path": self.traversal_path,
                "path_domains": self.path_domains,
                "discoveries": self.discoveries,
                "hops_taken": self.hops_taken
            };
            disengage;
        }

        (next_node, _) = pick_weak_neighbor(here, candidates);
        if next_node is not None {
            visit next_node;
        } else {
            report {
                "status": "no_next",
                "traversal_path": self.traversal_path,
                "discoveries": self.discoveries,
                "hops_taken": self.hops_taken
            };
            disengage;
        }
    }

    def _try_generate_insight(end_node: Concept) -> None {
        if len(self.traversal_path) < 3 {
            return;
        }
        if self.traversal_path[0] == self.traversal_path[-1] {
            return;
        }

        insight_result = generate_insight(
            start_concept=self.traversal_path[0],
            end_concept=end_node.name,
            path=self.traversal_path,
            path_descriptions=self.path_descriptions
        );

        if insight_result.confidence >= self.min_confidence {
            new_insight = Insight(
                title=insight_result.title,
                description=insight_result.description,
                confidence=insight_result.confidence,
                path=self.traversal_path,
                generated_at=time.time()
            );
            root ++> new_insight;
            new_insight +>:sourced_from(relevance=0.9, excerpt=""):+> end_node;

            discovery = {
                "title": insight_result.title,
                "description": insight_result.description,
                "confidence": insight_result.confidence,
                "analogy": insight_result.analogy,
                "path": self.traversal_path,
                "domains_crossed": list(set(self.path_domains))
            };
            self.discoveries.append(discovery);
        }
    }
}

# Ingestor walker — ingests raw text, extracts concepts, and walks the
# existing graph to find connections (graph traversal, not RAG).

import time;

import from graph.nodes { Concept, Source, Person }
import from graph.edges { relates_to, builds_upon, contradicts, sourced_from, inspired_by, mentioned_by, temporal }
import from ai.extract { extract_concepts, extract_people, extract_relationships }
import from ai.assess { assess_relationship }


walker Ingestor {
    has text: str;
    has source_type: str = "note";
    has url: str = "";

    has traversal_path: list = [];
    has new_concepts: list = [];
    has new_people: list = [];
    has new_edges: list = [];
    has source_node: Source | None = None;
    has concept_names: list = [];
    has concept_descriptions: list = [];
    has max_existing_visits: int = 50;
    has existing_visited: int = 0;
    has visited_ids: list = [];

    can ingest with Root entry {
        now = time.time();

        # IMPORTANT: collect existing Persons/Concepts BEFORE we create anything new.
        # Jac's here++> operator appears to reset the `[-->]` cursor during the
        # walker ability, so we must snapshot the graph state first.
        existing_people_by_name: dict = {};
        existing_concepts_by_name: dict = {};
        for p_node in [-->][?:Person] {
            p_key = p_node.name.lower().strip();
            existing_people_by_name[p_key] = p_node;
        }
        for c_node in [-->][?:Concept] {
            c_key = c_node.name.lower().strip();
            existing_concepts_by_name[c_key] = c_node;
        }

        title_text = self.text[:80];
        if len(self.text) > 80 {
            title_text = title_text + "...";
        }

        self.source_node = Source(
            title=title_text,
            source_type=self.source_type,
            content=self.text,
            url=self.url,
            ingested_at=now,
            summary=""
        );
        here ++> (self.source_node as Source);

        # Extract people FIRST so we can skip any Concepts that are really persons.
        person_names_lower: set = set();
        try {
            extracted_people = extract_people(self.text);
            for person_data in extracted_people {
                key = person_data.name.lower().strip();
                person_names_lower.add(key);
                if key in existing_people_by_name {
                    # Reuse existing Person node, link it to the new Source
                    existing_person = existing_people_by_name[key];
                    existing_person +>:mentioned_by(
                        context=person_data.context
                    ):+> (self.source_node as Source);
                    continue;
                }
                new_person = Person(
                    name=person_data.name,
                    context=person_data.context
                );
                here ++> new_person;
                self.new_people.append(new_person);
            }
        } except Exception as e {
            self.new_people = [];
        }

        try {
            extracted_concepts = extract_concepts(self.text, self.source_type);
        } except Exception as e {
            extracted_concepts = [];
        }

        for concept_data in extracted_concepts {
            # Skip if this "concept" is actually a person name we just added
            key = concept_data.name.lower().strip();
            if key in person_names_lower {
                continue;
            }
            # Skip if a Concept with this name already exists; just link Source to it
            if key in existing_concepts_by_name {
                existing_c = existing_concepts_by_name[key];
                existing_c +>:sourced_from(relevance=0.85, excerpt=""):+> (self.source_node as Source);
                existing_c.access_count = existing_c.access_count + 1;
                continue;
            }
            new_concept = Concept(
                name=concept_data.name,
                description=concept_data.description,
                domain=concept_data.domain,
                importance=0.5,
                created_at=now,
                last_accessed=now,
                access_count=1,
                depth=concept_data.depth
            );
            here ++> new_concept;

            new_concept +>:sourced_from(
                relevance=0.9,
                excerpt=""
            ):+> (self.source_node as Source);

            self.new_concepts.append(new_concept);
            self.concept_names.append(concept_data.name);
            self.concept_descriptions.append(concept_data.description);
        }

        # Link each Person to the Source they came from
        for person_node in self.new_people {
            person_node +>:mentioned_by(
                context=person_node.context
            ):+> (self.source_node as Source);
        }

        # Wire relationships between newly extracted concepts
        # (LLM tool-calling fails on short/simple inputs like "X is smart" —
        # wrap to keep the walker alive with partial progress)
        if len(self.concept_names) > 1 {
            try {
                intra_rels = extract_relationships(
                    self.concept_names,
                    self.concept_descriptions
                );
                for rel in intra_rels {
                    src_node: Concept | None = None;
                    tgt_node: Concept | None = None;
                    for c in self.new_concepts {
                        if c.name == rel.source_concept {
                            src_node = c;
                        }
                        if c.name == rel.target_concept {
                            tgt_node = c;
                        }
                    }
                    if src_node is not None and tgt_node is not None and src_node is not tgt_node {
                        self.create_typed_edge(
                            src_node, tgt_node,
                            rel.relationship_type,
                            rel.strength,
                            rel.explanation,
                            now
                        );
                    }
                }
            } except Exception as e {
                _ = 0;
            }
        }

        for person_node in self.new_people {
            for concept_node in self.new_concepts {
                person_node +>:mentioned_by(
                    context=person_node.context
                ):+> concept_node;
            }
        }

        # Temporal edges capture co-occurrence in the same ingestion
        if len(self.new_concepts) > 1 {
            for i in range(len(self.new_concepts) - 1) {
                self.new_concepts[i] +>:temporal(
                    timestamp=now,
                    sequence_type="same_ingestion"
                ):+> self.new_concepts[i + 1];
            }
        }

        # Now walk existing concepts to find cross-connections.
        # CANNOT use `visit [-->][?:Concept]` here — Jac's `here ++>` operator
        # earlier in this ability invalidated the `[-->]` enumeration, so it
        # would only see the newly created nodes. Instead, visit the existing
        # concept nodes we snapshotted before the mutation.
        existing_concept_nodes: list = [];
        for ec in existing_concepts_by_name.values() {
            existing_concept_nodes.append(ec);
        }
        if len(existing_concept_nodes) > 0 {
            visit existing_concept_nodes;
        }
    }

    can assess_connections with Concept entry {
        node_id = here.__jac__.id;
        if node_id in self.visited_ids { return; }
        self.visited_ids.append(node_id);

        # Skip nodes we just created
        is_new = False;
        for nc in self.new_concepts {
            if nc is here {
                is_new = True;
                break;
            }
        }
        if is_new {
            if self.existing_visited < self.max_existing_visits {
                neighbors = [-->][?:Concept];
                unvisited = [n for n in neighbors if n.__jac__.id not in self.visited_ids];
                if len(unvisited) > 0 { visit unvisited; }
            }
            return;
        }

        self.traversal_path.append(here.name);
        self.existing_visited += 1;

        here.access_count = here.access_count + 1;
        here.last_accessed = time.time();

        for new_concept in self.new_concepts {
            try {
                assessment = assess_relationship(
                    new_concept.name,
                    new_concept.description,
                    here.name,
                    here.description
                );
                if assessment.related and assessment.strength > 0.3 {
                    now = time.time();
                    self.create_typed_edge(
                        new_concept, here,
                        assessment.relationship_type,
                        assessment.strength,
                        assessment.explanation,
                        now
                    );
                }
            } except Exception as e {
                _ = 0;
            }
        }

        if self.existing_visited < self.max_existing_visits {
            neighbors = [-->][?:Concept];
            unvisited = [n for n in neighbors if n.__jac__.id not in self.visited_ids];
            if len(unvisited) > 0 { visit unvisited; }
        }
    }

    can finish with Root exit {
        concept_names: list = [];
        for c in self.new_concepts {
            concept_names.append(c.name);
        }
        people_names: list = [];
        for p in self.new_people {
            people_names.append(p.name);
        }

        report {
            "source_title": self.source_node.title if self.source_node is not None else "",
            "source_type": self.source_type,
            "new_concepts": concept_names,
            "new_people": people_names,
            "new_concepts_count": len(self.new_concepts),
            "new_people_count": len(self.new_people),
            "new_edges_count": len(self.new_edges),
            "existing_concepts_visited": self.existing_visited,
            "traversal_path": self.traversal_path,
            "new_edges": self.new_edges
        };
    }

    def create_typed_edge(
        src: Concept,
        tgt: Concept,
        rel_type: str,
        strength: float,
        explanation: str,
        now: float
    ) {
        if rel_type == "builds_upon" {
            src +>:builds_upon(
                strength=strength,
                explanation=explanation,
                created_at=now
            ):+> tgt;
        } elif rel_type == "contradicts" {
            src +>:contradicts(
                strength=strength,
                tension=explanation,
                resolved=False,
                created_at=now
            ):+> tgt;
        } elif rel_type == "inspired_by" {
            src +>:inspired_by(
                created_at=now,
                context=explanation
            ):+> tgt;
        } else {
            src +>:relates_to(
                strength=strength,
                relationship=explanation,
                created_at=now,
                last_reinforced=now,
                reinforcement_count=1
            ):+> tgt;
        }

        self.new_edges.append({
            "source": src.name,
            "target": tgt.name,
            "type": rel_type,
            "strength": strength,
            "explanation": explanation
        });
    }
}

# Pathfinder walker — answers questions by walking conceptual paths
# through the graph, scoring them for relevance, and synthesizing answers.

import time;

import from graph.nodes { Concept, Question }
import from graph.edges { relates_to, builds_upon, sourced_from, inspired_by }
import from ai.assess { score_path_relevance, PathRelevanceScore }
import from ai.synthesize { synthesize_answer }
import from ai.narrate { narrate_path, PathNarration }

obj AnchorConcept {
    has name: str;
    has context: str = "";
}

sem identify_anchors = """
Given a user question, identify the 1-3 key concepts the question is about.
These are the anchor points we will search for in a knowledge graph. Return
concise concept names that are likely to match node names in a personal
knowledge graph. For example, the question 'How does Bayesian inference relate
to startup valuation?' should yield anchors like 'Bayesian inference' and
'startup valuation'. Prefer canonical, widely-used concept names over verbose
phrases.
""";

def identify_anchors(question: str) -> list[AnchorConcept] by llm();

def identify_anchors_fallback(question: str) -> list {
    stop = {"how", "does", "is", "are", "what", "why", "the", "like", "to",
            "and", "of", "in", "for", "with", "from", "about", "between",
            "connect", "relate", "connection", "relationship", "do", "a", "an"};
    words = [w.strip("?.,!") for w in question.lower().split() if w.strip("?.,!") not in stop and len(w) > 2];
    anchors: list = [];
    for w in words {
        anchors.append(AnchorConcept(name=w, context=""));
    }
    return anchors;
}

obj FuzzyMatchResult {
    has is_match: bool;
    has confidence: float;
}

sem fuzzy_match_concept = """
Determine whether a knowledge-graph concept node matches the anchor concept the
user is asking about. They do not need to share the exact same name - semantic
equivalence counts. For example, 'GP regression' matches 'Gaussian Processes',
and 'fundraising' matches 'startup fundraising'. Return is_match (true/false)
and confidence (0-1).
""";

def fuzzy_match_concept(
    anchor_name: str,
    anchor_context: str,
    node_name: str,
    node_description: str
) -> FuzzyMatchResult by llm();

walker Pathfinder {
    has question: str;
    has max_depth: int = 7;

    has anchors: list = [];
    has anchor_nodes: dict = {};
    has visited_ids: list = [];
    has traversal_path: list = [];
    has path_descriptions: list = [];
    has path_edges: list = [];
    has candidate_paths: list = [];
    has current_depth: int = 0;

    # Concept-to-concept adjacency built during scan (ignores root edges)
    # so we can reconstruct genuine edge-adjacent paths between anchors.
    has concept_adj: dict = {};       # node_id -> list[node_id] of typed-edge neighbors
    has id_to_name: dict = {};        # node_id -> concept name
    has id_to_desc: dict = {};        # node_id -> concept description

    has best_answer: str = "";
    has narration: str = "";
    has answer_path: list = [];

    # "scan" = locate anchors, "trace" = collect context between them
    has phase: str = "scan";

    can start with Root entry {
        try {
            self.anchors = identify_anchors(self.question);
        } except Exception as e {
            self.anchors = identify_anchors_fallback(self.question);
        }

        for a in self.anchors {
            self.anchor_nodes[a.name] = None;
        }

        self.phase = "scan";
        self.current_depth = 0;
        visit [-->];
    }

    can scan_node with Concept entry {
        if self.phase != "scan" {
            return;
        }

        node_id = str(here.__jac__.id);
        if node_id in self.visited_ids {
            return;
        }
        self.visited_ids.append(node_id);
        self.current_depth += 1;

        self.traversal_path.append(here.name);
        self.path_descriptions.append(here.description);
        self.id_to_name[node_id] = here.name;
        self.id_to_desc[node_id] = here.description;

        here.access_count = here.access_count + 1;
        here.last_accessed = time.time();

        for a in self.anchors {
            if self.anchor_nodes[a.name] is not None {
                continue;
            }

            a_lower = a.name.lower();
            n_lower = here.name.lower();
            if a_lower in n_lower or n_lower in a_lower {
                self.anchor_nodes[a.name] = {
                    "name": here.name,
                    "description": here.description,
                    "node_id": node_id
                };
                continue;
            }

            # Word overlap fallback
            a_words = set(a.name.lower().split());
            n_words = set(here.name.lower().split());
            d_words = set(here.description.lower().split());
            overlap = len(a_words & n_words) + len(a_words & d_words) * 0.5;
            if overlap >= 1.0 {
                self.anchor_nodes[a.name] = {
                    "name": here.name,
                    "description": here.description,
                    "node_id": node_id
                };
            }
        }

        # Build concept-to-concept adjacency BEFORE any early return, so every
        # visited node (including anchors) has its adjacency recorded.
        out_neighbors = [-->][?:Concept];
        in_neighbors = [<--][?:Concept];
        adj_list: list = [];
        for n in out_neighbors {
            adj_list.append(str(n.__jac__.id));
        }
        for n in in_neighbors {
            n_id = str(n.__jac__.id);
            if n_id not in adj_list {
                adj_list.append(n_id);
            }
        }
        self.concept_adj[node_id] = adj_list;

        all_found = True;
        for a in self.anchors {
            if self.anchor_nodes[a.name] is None {
                all_found = False;
                break;
            }
        }
        if all_found {
            return;
        }

        if self.current_depth < self.max_depth * 20 {
            unvisited: list = [];
            for n in out_neighbors {
                if str(n.__jac__.id) not in self.visited_ids {
                    unvisited.append(n);
                }
            }
            if len(unvisited) > 0 {
                visit unvisited;
            }
        }
    }

    # BFS over the concept-only adjacency dict.
    # Returns list of node IDs (empty list if no path exists).
    def _bfs_shortest_path(start_id: str, end_id: str) -> list {
        empty: list = [];
        if start_id == end_id {
            single: list = [start_id];
            return single;
        }
        if start_id not in self.concept_adj {
            return empty;
        }
        visited: set = set();
        visited.add(start_id);
        initial: list = [start_id];
        queue: list = [initial];
        while len(queue) > 0 {
            path = queue.pop(0);
            current = path[-1];
            neighbors_any = self.concept_adj.get(current, empty);
            neighbors: list = list(neighbors_any);
            for nb in neighbors {
                if nb == end_id {
                    result = list(path);
                    result.append(nb);
                    return result;
                }
                if nb not in visited and nb in self.concept_adj {
                    visited.add(nb);
                    if len(path) < 10 {
                        extended = list(path);
                        extended.append(nb);
                        queue.append(extended);
                    }
                }
            }
        }
        return empty;
    }

    can finish with Root exit {
        found = [];
        for a_name in self.anchor_nodes {
            if self.anchor_nodes[a_name] is not None {
                found.append(self.anchor_nodes[a_name]);
            }
        }

        if len(self.traversal_path) > 0 {
            max_path_len = self.max_depth * 2;
            trimmed_concepts = self.traversal_path[:max_path_len];
            trimmed_descs = self.path_descriptions[:max_path_len];

            if len(found) >= 2 {
                # Run BFS on the concept-only adjacency dict to find the actual
                # shortest edge-adjacent path between the two anchor concepts.
                start_id = found[0]["node_id"];
                end_id = found[1]["node_id"];
                path_ids = self._bfs_shortest_path(start_id, end_id);
                if path_ids is not None and len(path_ids) >= 2 and len(path_ids) <= 12 {
                    reconstructed_concepts: list = [];
                    reconstructed_descs: list = [];
                    for nid in path_ids {
                        if nid in self.id_to_name {
                            reconstructed_concepts.append(self.id_to_name[nid]);
                            reconstructed_descs.append(
                                self.id_to_desc[nid] if nid in self.id_to_desc else ""
                            );
                        }
                    }
                    if len(reconstructed_concepts) >= 2 {
                        trimmed_concepts = reconstructed_concepts;
                        trimmed_descs = reconstructed_descs;
                    }
                }
            }

            try {
                relevance_score = score_path_relevance(
                    self.question, trimmed_concepts, trimmed_descs
                );

                node_contexts: list = [];
                for i in range(len(trimmed_concepts)) {
                    node_contexts.append({
                        "name": trimmed_concepts[i],
                        "description": trimmed_descs[i] if i < len(trimmed_descs) else ""
                    });
                }

                paths_data = [{
                    "concepts": trimmed_concepts,
                    "descriptions": trimmed_descs,
                    "relevance": relevance_score.relevance,
                    "key_connections": relevance_score.key_connections
                }];

                self.best_answer = synthesize_answer(
                    self.question, paths_data, node_contexts
                );

                edge_labels = ["relates_to" for _ in trimmed_concepts];
                path_narration = narrate_path(
                    trimmed_concepts, edge_labels, self.question
                );
                self.narration = path_narration.narration;
            } except Exception as e {
                self.best_answer = (
                    "Path found: " + " -> ".join(trimmed_concepts) + ". "
                    + "This traversal connects " + trimmed_concepts[0]
                    + " to " + trimmed_concepts[-1]
                    + " through " + str(len(trimmed_concepts) - 2)
                    + " intermediate concepts."
                );
                self.narration = "";
            }

            self.answer_path = trimmed_concepts;
        }

        q_node = Question(
            text=self.question,
            asked_at=time.time(),
            answered=len(self.best_answer) > 0,
            answer_path=self.answer_path,
            answer_text=self.best_answer
        );
        here ++> q_node;

        report {
            "question": self.question,
            "answer": self.best_answer,
            "narration": self.narration,
            "traversal_path": self.traversal_path,
            "answer_path": self.answer_path,
            "path_descriptions": self.path_descriptions,
            "anchors_requested": [a.name for a in self.anchors],
            "anchors_found": [
                self.anchor_nodes[a_name]
                for a_name in self.anchor_nodes
                if self.anchor_nodes[a_name] is not None
            ],
            "walker_type": "pathfinder",
            "walker_color": "#00D4FF"
        };
    }
}

"""Button component for the Jac client application."""

def:pub Button(label: str, onClick: any, variant: str = "primary", disabled: bool = False) -> any {
    base_styles = {
        "padding": "0.75rem 1.5rem",
        "fontSize": "1rem",
        "fontWeight": "600",
        "borderRadius": "0.5rem",
        "border": "none",
        "cursor": "not-allowed" if disabled else "pointer",
        "transition": "all 0.2s ease"
    };

    variant_styles = {
        "primary": {
            "backgroundColor": "#9ca3af" if disabled else "#3b82f6",
            "color": "#ffffff"
        },
        "secondary": {
            "backgroundColor": "#e5e7eb" if disabled else "#6b7280",
            "color": "#ffffff"
        }
    };

    return <button
        style={{**base_styles, **variant_styles[variant]}}
        onClick={onClick}
        disabled={disabled}
    >
        {label}
    </button>;
}

