                    self.company,
                    self.company_info,
                    self.talking_points,
                    self.tone_notes,
                    parsed.get("summary", "")
                );
                report {"cover_letter": letter};
                disengage;
            }
        }
        report {"error": "Resume not found"};
    }
}

# ---------------------------------------------------------------------------
# Section & item reordering walkers
# ---------------------------------------------------------------------------

walker MoveSectionItem {
    """Move an entry up or down within a resume section (experience, projects, education, etc.)."""
    has resume_id: str;
    has section: str;    # "experience" | "projects" | "education" | "certifications" | "skills"
    has index: int;
    has direction: str;  # "up" | "down"

    can move with Root entry {
        resumes = [-->[?:Resume]];
        for r in resumes {
            if r.resume_id == self.resume_id {
                parsed = json.loads(r.parsed_data);
                items = parsed.get(self.section, []);
                idx = self.index;
                if self.direction == "up" and idx > 0 {
                    tmp = items[idx - 1];
                    items[idx - 1] = items[idx];
                    items[idx] = tmp;
                } elif self.direction == "down" and idx < len(items) - 1 {
                    tmp = items[idx + 1];
                    items[idx + 1] = items[idx];
                    items[idx] = tmp;
                }
                parsed[self.section] = items;
                r.parsed_data = json.dumps(parsed);
                r.updated_at = datetime.datetime.utcnow().isoformat();
                report {"ok": True, "section": self.section, "index": idx, "direction": self.direction};
                disengage;
            }
        }
        report {"error": "Resume not found"};
    }
}

walker UpdateSectionOrder {
    """Persist a new top-level section display order for a resume."""
    has resume_id: str;
    has section_order: list[str];

    can update with Root entry {
        resumes = [-->[?:Resume]];
        for r in resumes {
            if r.resume_id == self.resume_id {
                r.section_order = json.dumps(self.section_order);
                r.updated_at = datetime.datetime.utcnow().isoformat();
                report {"section_order": self.section_order};
                disengage;
            }
        }
        report {"error": "Resume not found"};
    }
}

walker UpdateResumeParsed {
    """Save manually edited resume content back to the DB."""
    has resume_id: str;
    has parsed_data: dict;

    can update with Root entry {
        resumes = [-->[?:Resume]];
        for r in resumes {
            if r.resume_id == self.resume_id {
                r.parsed_data = json.dumps(self.parsed_data);
                r.updated_at = datetime.datetime.utcnow().isoformat();
                report {"resume_id": self.resume_id, "updated": True};
                disengage;
            }
        }
        report {"error": "Resume not found"};
    }
}

walker ExportResume {
    """Export a resume as a DOCX file. Returns base64-encoded file content."""
    has resume_id: str;

    can export with Root entry {
        resumes = [-->[?:Resume]];
        for r in resumes {
            if r.resume_id == self.resume_id {
                parsed = json.loads(r.parsed_data);
                file_data = generate_resume_docx(parsed);
                safe_name = r.version_name.replace("/", "-").replace("\\", "-");
                report {
                    "file_data": file_data,
                    "file_name": safe_name + ".docx",
                    "format": "docx"
                };
                disengage;
            }
        }
        report {"error": "Resume not found"};
    }
}

"""3D caffeine molecule background that rotates with mouse movement."""

import from react { useRef, useEffect }

def:pub CaffeineBackground(is_dark: bool = True) -> any {
    canvas_ref = useRef(None);

    useEffect(lambda () {
        canvas = canvas_ref.current;
        if not canvas { return lambda () {}; }
        ctx = canvas.getContext("2d");

        dpr = window.devicePixelRatio or 1;
        w = {"v": window.innerWidth};
        h = {"v": window.innerHeight};

        def resize() {
            w["v"] = window.innerWidth;
            h["v"] = window.innerHeight;
            canvas.width = int(w["v"] * dpr);
            canvas.height = int(h["v"] * dpr);
            canvas.style.width = str(w["v"]) + "px";
            canvas.style.height = str(h["v"]) + "px";
            ctx.setTransform(1, 0, 0, 1, 0, 0);
            ctx.scale(dpr, dpr);
        }
        resize();

        # Element colors
        col_c = "#5a5a66" if is_dark else "#48484a";
        col_n = "#4583e8";
        col_o = "#e8554e";
        col_h = "#c5c5cc" if is_dark else "#e0e0e5";

        # Caffeine (C8H10N4O2) — ring atoms puckered slightly, methyl H's give depth.
        atoms = [
            {"c": col_n, "x": -1.20, "y": -1.05, "z": -0.25, "r": 11},
            {"c": col_c, "x":  0.05, "y": -1.55, "z":  0.30, "r": 9},
            {"c": col_n, "x":  1.25, "y": -0.85, "z": -0.35, "r": 11},
            {"c": col_c, "x":  1.20, "y":  0.65, "z":  0.25, "r": 9},
            {"c": col_c, "x": -0.05, "y":  1.35, "z": -0.20, "r": 9},
            {"c": col_c, "x": -1.25, "y":  0.55, "z":  0.35, "r": 9},
            {"c": col_n, "x":  0.30, "y":  2.80, "z": -0.30, "r": 11},
            {"c": col_c, "x":  1.65, "y":  2.75, "z":  0.40, "r": 9},
            {"c": col_n, "x":  2.15, "y":  1.45, "z": -0.25, "r": 11},
            {"c": col_o, "x":  0.10, "y": -2.95, "z":  0.45, "r": 11},
            {"c": col_o, "x": -2.45, "y":  1.20, "z":  0.50, "r": 11},
            {"c": col_c, "x": -2.55, "y": -1.80, "z": -0.10, "r": 9},
            {"c": col_c, "x":  2.55, "y": -1.65, "z": -0.20, "r": 9},
            {"c": col_c, "x": -0.55, "y":  4.10, "z": -0.15, "r": 9},
            {"c": col_h, "x":  2.45, "y":  3.70, "z":  0.55, "r": 5},
            # Methyl hydrogens out of plane give real 3D depth
            {"c": col_h, "x": -3.35, "y": -2.45, "z":  0.80, "r": 5},
            {"c": col_h, "x": -3.35, "y": -2.45, "z": -1.00, "r": 5},
            {"c": col_h, "x": -2.75, "y": -2.85, "z": -0.10, "r": 5},
            {"c": col_h, "x":  3.35, "y": -2.30, "z":  0.70, "r": 5},
            {"c": col_h, "x":  3.35, "y": -2.30, "z": -1.10, "r": 5},
            {"c": col_h, "x":  2.75, "y": -2.70, "z": -0.20, "r": 5},
            {"c": col_h, "x": -1.00, "y":  4.90, "z":  0.75, "r": 5},
            {"c": col_h, "x": -1.00, "y":  4.90, "z": -1.05, "r": 5},
            {"c": col_h, "x": -0.15, "y":  4.85, "z": -0.15, "r": 5}
        ];

        # Bonds: [atom_a, atom_b, order]
        bonds = [
            [0, 1, 1], [1, 2, 1], [2, 3, 1], [3, 4, 2], [4, 5, 1], [5, 0, 1],
            [4, 6, 1], [6, 7, 1], [7, 8, 2], [8, 3, 1],
            [1, 9, 2], [5, 10, 2],
            [0, 11, 1], [2, 12, 1], [6, 13, 1], [7, 14, 1],
            [11, 15, 1], [11, 16, 1], [11, 17, 1],
            [12, 18, 1], [12, 19, 1], [12, 20, 1],
            [13, 21, 1], [13, 22, 1], [13, 23, 1]
        ];

        target_rx = {"v": 0.0};
        target_ry = {"v": 0.0};
        rx = {"v": 0.0};
        ry = {"v": 0.0};
        auto_rot = {"v": 0.0};
        running = {"v": True};

        def rotate(p: any, ax: float, ay: float) -> any {
            cY = Math.cos(ay);
            sY = Math.sin(ay);
            x1 = p["x"] * cY + p["z"] * sY;
            y1 = p["y"];
            z1 = -p["x"] * sY + p["z"] * cY;
            cX = Math.cos(ax);
            sX = Math.sin(ax);
            x2 = x1;
            y2 = y1 * cX - z1 * sX;
            z2 = y1 * sX + z1 * cX;
            return {"x": x2, "y": y2, "z": z2};
        }

        def tick(ts: any) {
            if not running["v"] { return; }

            rx["v"] = rx["v"] + (target_rx["v"] - rx["v"]) * 0.05;
            ry["v"] = ry["v"] + (target_ry["v"] - ry["v"]) * 0.05;
            auto_rot["v"] = auto_rot["v"] + 0.0018;

            ctx.clearRect(0, 0, w["v"], h["v"]);

            # Adaptive scale based on window size; min/max clamped.
            base_scale = Math.min(w["v"], h["v"]) / 22.0;
            if base_scale < 28 { base_scale = 28; }
            if base_scale > 48 { base_scale = 48; }

            # Two instances: left and right, counter-rotating
            centers = [
                {"cx": w["v"] * 0.15, "cy": h["v"] * 0.5, "dir": 1.0, "phase": 0.0},
                {"cx": w["v"] * 0.85, "cy": h["v"] * 0.5, "dir": -1.0, "phase": Math.PI}
            ];

            ci = 0;
            while ci < len(centers) {
                center = centers[ci];
                cx = center["cx"];
                cy = center["cy"];
                dir = center["dir"];
                phase = center["phase"];

                wobble = Math.sin((ts or 0) / 3500 + phase) * 0.12;
                angle_x = rx["v"] + wobble + 0.25;
                angle_y = ry["v"] * dir + auto_rot["v"] * dir + phase;

                # Project all atoms
                projected = [];
                ai = 0;
                while ai < len(atoms) {
                    a = atoms[ai];
                    rotated = rotate(a, angle_x, angle_y);
                    persp = 600.0 / (600.0 + rotated["z"] * base_scale);
                    px = cx + rotated["x"] * base_scale * persp;
                    py = cy + (rotated["y"] - 0.6) * base_scale * persp;
                    projected.append({"px": px, "py": py, "pz": rotated["z"], "ps": persp, "a": a});
                    ai = ai + 1;
                }

                # Sort bonds by average z (back to front)
                bond_data = [];
                bi = 0;
                while bi < len(bonds) {
                    b = bonds[bi];
                    avgz = (projected[b[0]]["pz"] + projected[b[1]]["pz"]) / 2;
                    bond_data.append({"b": b, "z": avgz});
                    bi = bi + 1;
                }
                bond_data = sorted(bond_data, key=lambda (x: any) { x["z"]; });

                bdi = 0;
                while bdi < len(bond_data) {
                    b = bond_data[bdi]["b"];
                    p1 = projected[b[0]];
                    p2 = projected[b[1]];
                    order = b[2];

                    zavg = bond_data[bdi]["z"];
                    opacity = (zavg + 4) / 8;
                    if opacity < 0.25 { opacity = 0.25; }
                    if opacity > 0.8 { opacity = 0.8; }

                    lw = 4.0 * ((p1["ps"] + p2["ps"]) / 2);
                    bond_color = "rgba(150,155,165," if is_dark else "rgba(90,95,105,";
                    ctx.strokeStyle = bond_color + str(opacity) + ")";
                    ctx.lineCap = "round";

                    if order == 1 {
                        ctx.lineWidth = lw;
                        ctx.beginPath();
                        ctx.moveTo(p1["px"], p1["py"]);
                        ctx.lineTo(p2["px"], p2["py"]);
                        ctx.stroke();
                    } else {
                        dx = p2["px"] - p1["px"];
                        dy = p2["py"] - p1["py"];
                        dist = Math.sqrt(dx * dx + dy * dy) + 0.001;
                        nx = -dy / dist * 4;
                        ny = dx / dist * 4;
                        ctx.lineWidth = lw * 0.7;
                        ctx.beginPath();
                        ctx.moveTo(p1["px"] + nx, p1["py"] + ny);
                        ctx.lineTo(p2["px"] + nx, p2["py"] + ny);
                        ctx.moveTo(p1["px"] - nx, p1["py"] - ny);
                        ctx.lineTo(p2["px"] - nx, p2["py"] - ny);
                        ctx.stroke();
                    }
                    bdi = bdi + 1;
                }

                # Sort atoms by z (back to front)
                sorted_atoms = [];
                si = 0;
                while si < len(projected) {
                    sorted_atoms.append(projected[si]);
                    si = si + 1;
                }
                sorted_atoms = sorted(sorted_atoms, key=lambda (x: any) { x["pz"]; });

                di = 0;
                while di < len(sorted_atoms) {
                    item = sorted_atoms[di];
                    a = item["a"];
                    r = a["r"] * item["ps"];

                    depth = (item["pz"] + 4) / 8;
                    if depth < 0.35 { depth = 0.35; }
                    if depth > 1.0 { depth = 1.0; }

                    ctx.globalAlpha = depth;

                    # Soft glow
                    g = ctx.createRadialGradient(item["px"], item["py"], 0, item["px"], item["py"], r * 1.9);
                    g.addColorStop(0, a["c"]);
                    g.addColorStop(1, "rgba(0,0,0,0)");
                    ctx.fillStyle = g;
                    ctx.beginPath();
                    ctx.arc(item["px"], item["py"], r * 1.9, 0, Math.PI * 2);
                    ctx.fill();

                    # Core atom
                    ctx.fillStyle = a["c"];
                    ctx.beginPath();
                    ctx.arc(item["px"], item["py"], r, 0, Math.PI * 2);
                    ctx.fill();

                    # Specular highlight
                    ctx.fillStyle = "rgba(255,255,255,0.38)";
                    ctx.beginPath();
                    ctx.arc(item["px"] - r * 0.3, item["py"] - r * 0.3, r * 0.35, 0, Math.PI * 2);
                    ctx.fill();

                    ctx.globalAlpha = 1.0;
                    di = di + 1;
                }
                ci = ci + 1;
            }

            requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);

        def mmove(ev: any) {
            mx = ev.clientX / w["v"] - 0.5;
            my = ev.clientY / h["v"] - 0.5;
            target_ry["v"] = -mx * 1.4;
            target_rx["v"] = -my * 1.0;
        }

        window.addEventListener("mousemove", mmove);
        window.addEventListener("resize", resize);

        return lambda () {
            running["v"] = False;
            window.removeEventListener("mousemove", mmove);
            window.removeEventListener("resize", resize);
        };
    }, [is_dark]);

    return <canvas ref={canvas_ref} style={{
        "position": "fixed",
        "top": "0",
        "left": "0",
        "width": "100vw",
        "height": "100vh",
        "zIndex": "0",
        "pointerEvents": "none",
        "opacity": "0.32"
    }} />;
}

"""Drug interaction graph."""

import from react { useRef, useEffect }

def:pub DrugGraph(medications: list, interactions: list, flagged_paths: list, is_dark: bool = True) -> any {
    canvas_ref = useRef(None);

    if len(interactions) == 0 {
        return <div style={{
            "borderRadius": "20px",
            "padding": "20px 24px",
            "marginBottom": "16px"
        }}>
            <div style={{"fontSize": "15px", "fontWeight": "600", "color": "#f5f5f7" if is_dark else "#1d1d1f", "marginBottom": "12px"}}>{"Interaction Graph"}</div>
            <div style={{"textAlign": "center", "padding": "40px 20px", "backgroundColor": "#2c2c2e" if is_dark else "#f5f5f7", "borderRadius": "14px"}}>
                <div style={{"fontSize": "17px", "fontWeight": "600", "color": "#f5f5f7" if is_dark else "#1d1d1f"}}>{"No known interactions"}</div>
                <div style={{"fontSize": "14px", "color": "#86868b", "marginTop": "4px"}}>{"These medications have no documented pairwise interactions in our database."}</div>
            </div>
        </div>;
    }

    useEffect(lambda () {
        canvas = canvas_ref.current;
        if not canvas { return lambda () {}; }
        ctx = canvas.getContext("2d");
        dpr = window.devicePixelRatio or 1;
        rect = canvas.getBoundingClientRect();
        w = rect.width;
        h = 480;
        canvas.width = int(w * dpr);
        canvas.height = int(h * dpr);
        canvas.style.height = str(h) + "px";
        ctx.scale(dpr, dpr);
        count = len(medications);
        cx = w / 2;
        cy = h / 2;

        # Theme
        node_fill = "#2c2c2e" if is_dark else "#ffffff";
        node_fill_hv = "#3a3a3c" if is_dark else "#f0f0f5";
        node_flag_fill = "#3a1a1a" if is_dark else "#fff5f5";
        node_flag_fill_hv = "#4a2020" if is_dark else "#ffecec";
        node_stroke = "rgba(255,255,255,0.15)" if is_dark else "rgba(0,0,0,0.1)";
        label_color = "#f5f5f7" if is_dark else "#1d1d1f";
        label_dim = "#86868b";
        label_bg = "rgba(44,44,46,0.9)" if is_dark else "rgba(245,245,247,0.9)";
        tooltip_bg = "rgba(245,245,247,0.95)" if is_dark else "rgba(29,29,31,0.92)";
        tooltip_text = "#1d1d1f" if is_dark else "#ffffff";
        edge_label_bg = "rgba(44,44,46,0.92)" if is_dark else "rgba(255,255,255,0.92)";
        edge_normal = "rgba(255,255,255," if is_dark else "rgba(0,0,0,";

        # Build data structures
        node_map = {};
        i = 0;
        while i < count {
            node_map[medications[i]] = i;
            i = i + 1;
        }

        edges = [];
        seen = {};
        ei = 0;
        while ei < len(interactions) {
            a = interactions[ei]["drug_a"];
            b = interactions[ei]["drug_b"];
            key = a + "|" + b if a < b else b + "|" + a;
            if a in node_map and b in node_map and not (key in seen) {
                seen[key] = True;
                fl = False;
                fi = 0;
                while fi < len(flagged_paths) {
                    fp = flagged_paths[fi]["path"];
                    fj = 0;
                    while fj < len(fp) - 1 {
                        if (fp[fj] == a and fp[fj + 1] == b) or (fp[fj] == b and fp[fj + 1] == a) { fl = True; }
                        fj = fj + 1;
                    }
                    fi = fi + 1;
                }
                edges.append({"s": node_map[a], "t": node_map[b], "type": interactions[ei]["type"], "fl": fl, "ci": len(edges)});
            }
            ei = ei + 1;
        }

        # Per-node edge indices for curve offsets
        node_ec = {};
        nci = 0;
        while nci < count { node_ec[nci] = 0; nci = nci + 1; }
        eci = 0;
        while eci < len(edges) {
            node_ec[edges[eci]["s"]] = node_ec[edges[eci]["s"]] + 1;
            node_ec[edges[eci]["t"]] = node_ec[edges[eci]["t"]] + 1;
            eci = eci + 1;
        }
        # Assign offsets
        node_ei = {};
        nei = 0;
        while nei < count { node_ei[nei] = 0; nei = nei + 1; }
        eoi = 0;
        while eoi < len(edges) {
            s = edges[eoi]["s"];
            total = node_ec[s];
            idx = node_ei[s];
            edges[eoi]["off"] = (idx - (total - 1) / 2.0) * 20 if total > 1 else 0;
            node_ei[s] = idx + 1;
            eoi = eoi + 1;
        }

        # Flag counts
        fc = {};
        fci = 0;
        while fci < count { fc[fci] = 0; fci = fci + 1; }
        pi = 0;
        while pi < len(flagged_paths) {
            pa = flagged_paths[pi]["path"];
            pk = 0;
            while pk < len(pa) {
                if pa[pk] in node_map { fc[node_map[pa[pk]]] = fc[node_map[pa[pk]]] + 1; }
                pk = pk + 1;
            }
            pi = pi + 1;
        }

        # Build adjacency lists for layout ordering
        adj = {};
        ai = 0;
        while ai < count { adj[ai] = []; ai = ai + 1; }
        ae = 0;
        while ae < len(edges) {
            adj[edges[ae]["s"]].append(edges[ae]["t"]);
            adj[edges[ae]["t"]].append(edges[ae]["s"]);
            ae = ae + 1;
        }

        # Greedy circular ordering: place connected nodes adjacent
        # Start with highest-degree node, then greedily pick neighbor
        order = [];
        placed = {};
        # Find start: node with most edges
        best = 0;
        bval = 0;
        bi = 0;
        while bi < count {
            if len(adj[bi]) > bval { bval = len(adj[bi]); best = bi; }
            bi = bi + 1;
        }
        order.append(best);
        placed[best] = True;
        while len(order) < count {
            last = order[len(order) - 1];
            # Try to find unplaced neighbor of last
            found = -1;
            fi2 = 0;
            while fi2 < len(adj[last]) {
                cand = adj[last][fi2];
                if not (cand in placed) { found = cand; }
                fi2 = fi2 + 1;
            }
            if found < 0 {
                # No neighbor available, pick any unplaced
                ui2 = 0;
                while ui2 < count {
                    if not (ui2 in placed) { found = ui2; }
                    ui2 = ui2 + 1;
                }
            }
            order.append(found);
            placed[found] = True;
        }

        # Place nodes in this order around circle
        spread = Math.min(w * 0.40, h * 0.38);
        nodes = [];
        ni = 0;
        while ni < count {
            nodes.append({"x": 0, "y": 0, "vx": 0, "vy": 0});
            ni = ni + 1;
        }
        oi = 0;
        while oi < count {
            angle = (2 * Math.PI * oi / count) - (Math.PI / 2);
            idx2 = order[oi];
            nodes[idx2]["x"] = cx + Math.cos(angle) * spread;
            nodes[idx2]["y"] = cy + Math.sin(angle) * spread;
            oi = oi + 1;
        }

        running = {"v": True};
        mouse = {"x": -999, "y": -999, "d": -1, "h": -1};

        # Tick
        def tick(ts: any) {
            if not running["v"] { return; }

            # Physics
            a = 0;
            while a < count {
                b = a + 1;
                while b < count {
                    dx = nodes[b]["x"] - nodes[a]["x"];
                    dy = nodes[b]["y"] - nodes[a]["y"];
                    d = Math.sqrt(dx * dx + dy * dy) + 1;
                    f = 4000 / (d * d);
                    nodes[a]["vx"] = nodes[a]["vx"] - (dx / d) * f;
                    nodes[a]["vy"] = nodes[a]["vy"] - (dy / d) * f;
                    nodes[b]["vx"] = nodes[b]["vx"] + (dx / d) * f;
                    nodes[b]["vy"] = nodes[b]["vy"] + (dy / d) * f;
                    b = b + 1;
                }
                a = a + 1;
            }
            ej = 0;
            while ej < len(edges) {
                si = edges[ej]["s"];
                ti = edges[ej]["t"];
                dx = nodes[ti]["x"] - nodes[si]["x"];
                dy = nodes[ti]["y"] - nodes[si]["y"];
                d = Math.sqrt(dx * dx + dy * dy) + 1;
                f = (d - 140) * 0.006;
                nodes[si]["vx"] = nodes[si]["vx"] + (dx / d) * f;
                nodes[si]["vy"] = nodes[si]["vy"] + (dy / d) * f;
                nodes[ti]["vx"] = nodes[ti]["vx"] - (dx / d) * f;
                nodes[ti]["vy"] = nodes[ti]["vy"] - (dy / d) * f;
                ej = ej + 1;
            }
            ui = 0;
            while ui < count {
                nodes[ui]["vx"] = (nodes[ui]["vx"] + (cx - nodes[ui]["x"]) * 0.002) * 0.8;
                nodes[ui]["vy"] = (nodes[ui]["vy"] + (cy - nodes[ui]["y"]) * 0.002) * 0.8;
                if ui != mouse["d"] {
                    nodes[ui]["x"] = nodes[ui]["x"] + nodes[ui]["vx"];
                    nodes[ui]["y"] = nodes[ui]["y"] + nodes[ui]["vy"];
                }
                nodes[ui]["x"] = Math.max(65, Math.min(w - 65, nodes[ui]["x"]));
                nodes[ui]["y"] = Math.max(50, Math.min(h - 50, nodes[ui]["y"]));
                ui = ui + 1;
            }

            # Draw
            ctx.clearRect(0, 0, w, h);

            # --- EDGES ---
            di = 0;
            while di < len(edges) {
                e = edges[di];
                sx = nodes[e["s"]]["x"];
                sy = nodes[e["s"]]["y"];
                tx = nodes[e["t"]]["x"];
                ty = nodes[e["t"]]["y"];
                hl = mouse["h"] == e["s"] or mouse["h"] == e["t"];

                dx = tx - sx;
                dy = ty - sy;
                dist = Math.sqrt(dx * dx + dy * dy) + 1;
                off = e["off"];
                cpx = (sx + tx) / 2 + (-dy / dist) * off;
                cpy = (sy + ty) / 2 + (dx / dist) * off;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.quadraticCurveTo(cpx, cpy, tx, ty);
                if e["fl"] {
                    ctx.strokeStyle = "rgba(255,59,48," + ("0.85" if hl else "0.4") + ")";
                    ctx.lineWidth = 2.5 if hl else 1.8;
                    ctx.setLineDash([]);
                } else {
                    ctx.strokeStyle = edge_normal + ("0.5" if hl else "0.12") + ")";
                    ctx.lineWidth = 1.5 if hl else 0.8;
                    ctx.setLineDash([4, 4]);
                }
                ctx.stroke();
                ctx.setLineDash([]);

                di = di + 1;
            }

            # --- EDGE LABELS (drawn before nodes so node labels stay on top) ---
            dli = 0;
            while dli < len(edges) {
                e = edges[dli];
                hl = mouse["h"] == e["s"] or mouse["h"] == e["t"];
                if hl {
                    sx = nodes[e["s"]]["x"];
                    sy = nodes[e["s"]]["y"];
                    tx = nodes[e["t"]]["x"];
                    ty = nodes[e["t"]]["y"];
                    dx = tx - sx;
                    dy = ty - sy;
                    dist = Math.sqrt(dx * dx + dy * dy) + 1;
                    off = e["off"];
                    cpx = (sx + tx) / 2 + (-dy / dist) * off;
                    cpy = (sy + ty) / 2 + (dx / dist) * off;

                    label = e["type"].split("_").join(" ");
                    ctx.font = "500 10px -apple-system, sans-serif";
                    tw = ctx.measureText(label).width;
                    ctx.fillStyle = edge_label_bg;
                    ctx.fillRect(cpx - tw / 2 - 6, cpy - 9, tw + 12, 18);
                    ctx.fillStyle = "#ff3b30" if e["fl"] else label_dim;
                    ctx.textAlign = "center";
                    ctx.textBaseline = "middle";
                    ctx.fillText(label, cpx, cpy);
                }
                dli = dli + 1;
            }

            # --- NODES ---
            ni2 = 0;
            while ni2 < count {
                nx = nodes[ni2]["x"];
                ny = nodes[ni2]["y"];
                hv = mouse["h"] == ni2;
                flagged = fc[ni2] > 0;
                r = 20 if hv else 17;

                # Glow
                if flagged {
                    pulse = Math.sin((ts or 0) / 500 + ni2) * 0.03 + 0.1;
                    ctx.beginPath();
                    ctx.arc(nx, ny, r + 8, 0, Math.PI * 2);
                    ctx.fillStyle = "rgba(255,59,48," + str(pulse) + ")";
                    ctx.fill();
                }

                # Shadow
                ctx.beginPath();
                ctx.arc(nx, ny + 1, r, 0, Math.PI * 2);
                ctx.fillStyle = "rgba(0,0,0,0.2)" if is_dark else "rgba(0,0,0,0.06)";
                ctx.fill();

                # Circle fill + stroke
                ctx.beginPath();
                ctx.arc(nx, ny, r, 0, Math.PI * 2);
                if flagged {
                    ctx.fillStyle = node_flag_fill_hv if hv else node_flag_fill;
                    ctx.fill();
                    ctx.strokeStyle = "#ff3b30";
                    ctx.lineWidth = 2;
                    ctx.stroke();
                } else {
                    ctx.fillStyle = node_fill_hv if hv else node_fill;
                    ctx.fill();
                    ctx.strokeStyle = "#007aff" if hv else node_stroke;
                    ctx.lineWidth = 1.5;
                    ctx.stroke();
                }

                # Abbreviation inside circle
                abbr = medications[ni2].substring(0, 3).upper();
                ctx.font = "600 10px -apple-system, sans-serif";
                ctx.fillStyle = "#ff3b30" if flagged else label_color;
                ctx.textAlign = "center";
                ctx.textBaseline = "middle";
                ctx.fillText(abbr, nx, ny);

                # Full name label below
                name = medications[ni2];
                ctx.font = hv and "500 10px -apple-system, sans-serif" or "10px -apple-system, sans-serif";
                tw = ctx.measureText(name).width;
                ly = ny + r + 13;
                ctx.fillStyle = label_bg;
                ctx.fillRect(nx - tw / 2 - 4, ly - 7, tw + 8, 14);
                ctx.fillStyle = (hv or flagged) and label_color or label_dim;
                ctx.textAlign = "center";
                ctx.textBaseline = "middle";
                ctx.fillText(name, nx, ly);

                # Badge
                if flagged and fc[ni2] > 1 {
                    bx = nx + r * 0.65;
                    by_pos = ny - r * 0.65;
                    ctx.beginPath();
                    ctx.arc(bx, by_pos, 7, 0, Math.PI * 2);
                    ctx.fillStyle = "#ff3b30";
                    ctx.fill();
                    ctx.font = "600 8px -apple-system, sans-serif";
                    ctx.fillStyle = "#fff";
                    ctx.textAlign = "center";
                    ctx.textBaseline = "middle";
                    ctx.fillText(str(fc[ni2]), bx, by_pos);
                }

                ni2 = ni2 + 1;
            }

            # --- TOOLTIP ---
            if mouse["h"] >= 0 and mouse["h"] < count {
                hn = nodes[mouse["h"]];
                conn = 0;
                ci2 = 0;
                while ci2 < len(edges) {
                    if edges[ci2]["s"] == mouse["h"] or edges[ci2]["t"] == mouse["h"] { conn = conn + 1; }
                    ci2 = ci2 + 1;
                }
                tip = medications[mouse["h"]] + " " + String.fromCharCode(8226) + " " + str(conn) + " interaction" + ("s" if conn != 1 else "");
                if fc[mouse["h"]] > 0 {
                    tip = tip + " " + String.fromCharCode(8226) + " " + str(fc[mouse["h"]]) + " chain" + ("s" if fc[mouse["h"]] != 1 else "");
                }
                ctx.font = "500 12px -apple-system, sans-serif";
                tw2 = ctx.measureText(tip).width;
                ttx = Math.max(4, Math.min(hn["x"] - tw2 / 2 - 10, w - tw2 - 24));
                tty = hn["y"] - 48;
                if tty < 4 { tty = hn["y"] + 40; }
                ctx.fillStyle = tooltip_bg;
                ctx.fillRect(ttx, tty, tw2 + 20, 28);
                ctx.fillStyle = tooltip_text;
                ctx.textAlign = "left";
                ctx.textBaseline = "middle";
                ctx.fillText(tip, ttx + 10, tty + 14);
            }

            requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);

        # Mouse
        def hittest(mx: any, my: any) -> int {
            gi = count - 1;
            while gi >= 0 {
                dx = mx - nodes[gi]["x"];
                dy = my - nodes[gi]["y"];
                if dx * dx + dy * dy < 700 { return gi; }
                gi = gi - 1;
            }
            return -1;
        }
        def mmove(ev: any) {
            r2 = canvas.getBoundingClientRect();
            mouse["x"] = ev.clientX - r2.left;
            mouse["y"] = ev.clientY - r2.top;
            if mouse["d"] >= 0 {
                nodes[mouse["d"]]["x"] = mouse["x"];
                nodes[mouse["d"]]["y"] = mouse["y"];
                nodes[mouse["d"]]["vx"] = 0;
                nodes[mouse["d"]]["vy"] = 0;
            }
            mouse["h"] = hittest(mouse["x"], mouse["y"]);
            canvas.style.cursor = "grabbing" if mouse["d"] >= 0 else ("grab" if mouse["h"] >= 0 else "default");
        }
        def mdown(ev: any) {
            r2 = canvas.getBoundingClientRect();
            h2 = hittest(ev.clientX - r2.left, ev.clientY - r2.top);
            if h2 >= 0 { mouse["d"] = h2; canvas.style.cursor = "grabbing"; }
        }
        def mup(ev: any) { mouse["d"] = -1; }
        def mleave(ev: any) { mouse["h"] = -1; mouse["d"] = -1; canvas.style.cursor = "default"; }
        canvas.addEventListener("mousemove", mmove);
        canvas.addEventListener("mousedown", mdown);
        canvas.addEventListener("mouseup", mup);
        canvas.addEventListener("mouseleave", mleave);

        return lambda () {
            running["v"] = False;
            canvas.removeEventListener("mousemove", mmove);
            canvas.removeEventListener("mousedown", mdown);
            canvas.removeEventListener("mouseup", mup);
            canvas.removeEventListener("mouseleave", mleave);
        };
    }, [medications, interactions, flagged_paths, is_dark]);

    return <div style={{
        "borderRadius": "20px",
        "padding": "20px 24px",
        "marginBottom": "16px"
    }}>
        <div style={{"display": "flex", "justifyContent": "space-between", "alignItems": "center", "marginBottom": "12px"}}>
            <div style={{"fontSize": "15px", "fontWeight": "600", "color": "#f5f5f7" if is_dark else "#1d1d1f"}}>{"Interaction Graph"}</div>
            <div style={{"display": "flex", "gap": "12px", "fontSize": "11px", "color": "rgba(128,128,128,0.7)", "alignItems": "center"}}>
                <span style={{"display": "flex", "alignItems": "center", "gap": "4px"}}>
                    <span style={{"display": "inline-block", "width": "10px", "height": "2px", "backgroundColor": "#ff3b30", "borderRadius": "1px"}}></span>
                    {"flagged"}
                </span>
                <span style={{"display": "flex", "alignItems": "center", "gap": "4px"}}>
                    <span style={{"display": "inline-block", "width": "10px", "height": "1px", "backgroundColor": "rgba(128,128,128,0.5)"}}></span>
                    {"interaction"}
                </span>
                <span style={{"color": "rgba(128,128,128,0.4)"}}>{"drag to move"}</span>
            </div>
        </div>
        <canvas ref={canvas_ref} style={{"width": "100%", "height": "480px", "borderRadius": "14px", "backgroundColor": "#2c2c2e" if is_dark else "#f5f5f7"}} />
    </div>;
}

"""Drug multi-select dropdown component."""

import from react { useRef, useEffect }

def:pub DrugSelector(drugs: list, selected: list, customDrugs: list = [], onToggle: any = None, onAddCustom: any = None, card_bg: str = "#1c1c1e") -> any {
    has search: str = "";
    has is_open: bool = False;
    input_ref = useRef(None);

    filtered = [d for d in drugs if d.lower().includes(search.lower())];
    search_trimmed = search.strip();
    # Show "Add custom" if search doesn't exactly match any known drug (case-insensitive)
    has_exact_match = False;
    if search_trimmed {
        for d in drugs {
            if d.lower() == search_trimmed.lower() {
                has_exact_match = True;
            }
        }
    }
    show_add_custom = onAddCustom and len(search_trimmed) >= 2 and not has_exact_match;

    useEffect(lambda () {
        def handle_click(e: any) {
            if input_ref.current and not input_ref.current.closest("[data-ds]").contains(e.target) {
                is_open = False;
            }
        }
        document.addEventListener("mousedown", handle_click);
        return lambda () { document.removeEventListener("mousedown", handle_click); };
    }, []);

    return <div style={{"position": "relative", "width": "100%"}} data-ds="true">
        <div
            style={{
                "display": "flex",
                "flexWrap": "wrap",
                "gap": "6px",
                "padding": "10px 12px",
                "border": "1px solid " + ("rgba(0,122,255,0.4)" if is_open else "rgba(128,128,128,0.15)"),
                "borderRadius": "12px",
                "minHeight": "44px",
                "backgroundColor": "inherit",
                "transition": "border-color 0.2s, box-shadow 0.2s",
                "alignItems": "center",
                "cursor": "text",
                "boxShadow": "0 0 0 3px rgba(0,122,255,0.15)" if is_open else "none"
            }}
            onClick={lambda () {
                is_open = True;
                if input_ref.current { input_ref.current.focus(); }
            }}
        >
            {[
                <span
                    key={drug}
                    style={{
                        "backgroundColor": "rgba(0,122,255,0.12)" if drug in customDrugs else "rgba(128,128,128,0.1)",
                        "color": "#007aff" if drug in customDrugs else "inherit",
                        "padding": "4px 10px",
                        "borderRadius": "8px",
                        "fontSize": "13px",
                        "fontWeight": "500",
                        "display": "inline-flex",
                        "alignItems": "center",
                        "gap": "6px",
                        "whiteSpace": "nowrap",
                        "letterSpacing": "-0.01em"
                    }}
                >
                    {drug}
                    <span
                        onClick={lambda (e: any) {
                            e.stopPropagation();
                            onToggle(drug);
                        }}
                        style={{
                            "cursor": "pointer",
                            "fontSize": "11px",
                            "color": "#86868b",
                            "width": "16px",
                            "height": "16px",
                            "display": "inline-flex",
                            "alignItems": "center",
                            "justifyContent": "center",
                            "borderRadius": "50%",
                            "backgroundColor": "rgba(128,128,128,0.15)"
                        }}
                    >{"x"}</span>
                </span>
                for drug in selected
            ]}
            <input
                ref={input_ref}
                type="text"
                placeholder={"Search medications..." if len(selected) == 0 else "Add more..."}
                value={search}
                onChange={lambda (e: any) { search = e.target.value; }}
                onKeyDown={lambda (e: any) {
                    if e.key == "Backspace" and search == "" and len(selected) > 0 {
                        onToggle(selected[len(selected) - 1]);
                    }
                }}
                onFocus={lambda () { is_open = True; }}
                style={{
                    "border": "none",
                    "outline": "none",
                    "fontSize": "15px",
                    "flex": "1",
                    "minWidth": "120px",
                    "padding": "2px 4px",
                    "backgroundColor": "transparent",
                    "color": "inherit",
                    "letterSpacing": "-0.01em"
                }}
            />
        </div>
        {<div style={{
            "position": "absolute",
            "top": "100%",
            "left": "0",
            "right": "0",
            "marginTop": "6px",
            "backgroundColor": card_bg,
            "border": "1px solid rgba(128,128,128,0.15)",
            "borderRadius": "12px",
            "maxHeight": "240px",
            "overflowY": "auto",
            "zIndex": "50",
            "boxShadow": "0 8px 30px rgba(0,0,0,0.4)",
            "padding": "4px"
        }}>
            {[
                <div
                    key={drug}
                    onClick={lambda (e: any) {
                        e.stopPropagation();
                        onToggle(drug);
                        search = "";
                        if input_ref.current { input_ref.current.focus(); }
                    }}
                    style={{
                        "padding": "8px 12px",
                        "cursor": "pointer",
                        "backgroundColor": "rgba(0,122,255,0.12)" if drug in selected else "transparent",
                        "borderRadius": "8px",
                        "fontSize": "14px",
                        "color": "#007aff" if drug in selected else "inherit",
                        "fontWeight": "500" if drug in selected else "400",
                        "transition": "background-color 0.1s",
                        "display": "flex",
                        "justifyContent": "space-between",
                        "alignItems": "center"
                    }}
                >
                    <span>{drug}</span>
                    {<span style={{"color": "#007aff", "fontSize": "12px", "fontWeight": "500"}}>{"added"}</span> if drug in selected else <span></span>}
                </div>
                for drug in filtered
            ]}
            {<div
                onClick={lambda (e: any) {
                    e.stopPropagation();
                    # Capitalize first letter of each word
                    words = search_trimmed.split(" ");
                    capitalized = [w[0].upper() + w[1:] if len(w) > 0 else w for w in words];
                    drug_name = " ".join(capitalized);
                    onAddCustom(drug_name);
                    search = "";
                    if input_ref.current { input_ref.current.focus(); }
                }}
                style={{
                    "padding": "10px 12px",
                    "cursor": "pointer",
                    "borderRadius": "8px",
                    "fontSize": "14px",
                    "color": "#007aff",
                    "fontWeight": "500",
                    "display": "flex",
                    "alignItems": "center",
                    "gap": "6px",
                    "transition": "background-color 0.1s",
                    "borderTop": "1px solid rgba(128,128,128,0.1)" if len(filtered) > 0 else "none",
                    "marginTop": "2px" if len(filtered) > 0 else "0"
                }}
            >
                <span style={{"fontSize": "16px", "fontWeight": "600"}}>{"+"}</span>
{"Add " + String.fromCharCode(8220) + search_trimmed + String.fromCharCode(8221) + " as custom drug"}
            </div> if show_add_custom else <span></span>}
            {<div style={{
                "padding": "16px",
                "color": "#86868b",
                "fontSize": "14px",
                "textAlign": "center"
            }}>{"No results"}</div> if len(filtered) == 0 and not show_add_custom else <span></span>}
        </div> if is_open else <span></span>}
    </div>;
}

"""Result card component for flagged interaction chains."""

def:pub ResultCard(chain: any, onSuggestReplacement: any = None, replacementData: any = None, replacementLoading: bool = False) -> any {
    risk = chain["risk"];
    path = chain["path"];
    mechanisms = chain["mechanisms"];
    depth = chain["depth"];

    severity_label = "Critical";
    color = "#ff3b30";
    tint = "rgba(255,59,48,0.08)";
    if risk < 0.6 {
        severity_label = "Low";
        color = "#34c759";
        tint = "rgba(52,199,89,0.08)";
    } elif risk < 0.7 {
        severity_label = "Moderate";
        color = "#ff9500";
        tint = "rgba(255,149,0,0.08)";
    } elif risk < 0.9 {
        severity_label = "High";
        color = "#ff6b35";
        tint = "rgba(255,107,53,0.08)";
    }

    score = Math.min(Math.round(risk * 10 * 10) / 10, 10.0);
    bar_pct = str(Math.min(Math.round(score * 10), 100)) + "%";

    return <div style={{
        "borderRadius": "16px",
        "marginBottom": "10px",
        "overflow": "hidden"
    }}>
        <div style={{
            "display": "flex",
            "justifyContent": "space-between",
            "alignItems": "center",
            "padding": "14px 20px",
            "backgroundColor": tint
        }}>
            <div style={{"display": "flex", "alignItems": "center", "gap": "10px"}}>
                <span style={{
                    "width": "8px",
                    "height": "8px",
                    "borderRadius": "50%",
                    "backgroundColor": color,
                    "flexShrink": "0"
                }}></span>
                <span style={{
                    "fontSize": "13px",
                    "fontWeight": "600",
                    "color": color
                }}>{severity_label}</span>
            </div>
            <div style={{"display": "flex", "alignItems": "center", "gap": "10px"}}>
                <div style={{
                    "width": "48px",
                    "height": "4px",
                    "backgroundColor": "rgba(128,128,128,0.15)",
                    "borderRadius": "2px",
                    "overflow": "hidden"
                }}>
                    <div style={{"width": bar_pct, "height": "100%", "backgroundColor": color, "borderRadius": "2px"}}></div>
                </div>
                <span style={{
                    "fontSize": "20px",
                    "fontWeight": "700",
                    "color": "inherit",
                    "letterSpacing": "-0.02em"
                }}>{str(score)}</span>
            </div>
        </div>

        <div style={{"padding": "16px 20px"}}>
            <div style={{
                "display": "flex",
                "alignItems": "center",
                "gap": "6px",
                "marginBottom": "14px",
                "flexWrap": "wrap"
            }}>
                {[
                    <span key={str(idx)} style={{"display": "flex", "alignItems": "center", "gap": "6px"}}>
                        <span style={{
                            "backgroundColor": "rgba(128,128,128,0.1)",
                            "padding": "5px 12px",
                            "borderRadius": "8px",
                            "fontWeight": "500",
                            "fontSize": "13px",
                            "color": "inherit"
                        }}>{path[idx]}</span>
                        {<span style={{"color": "rgba(128,128,128,0.6)", "fontSize": "13px"}}>{" " + String.fromCharCode(8594) + " "}</span> if idx < len(path) - 1 else <span></span>}
                    </span>
                    for idx in range(len(path))
                ]}
            </div>

            {[
                <div key={str(idx)} style={{
                    "padding": "10px 0",
                    "borderTop": "1px solid rgba(128,128,128,0.1)" if idx > 0 else "none",
                    "fontSize": "13px",
                    "color": "rgba(128,128,128,0.75)",
                    "lineHeight": "1.5",
                    "display": "flex",
                    "gap": "8px"
                }}>
                    <span style={{
                        "color": "rgba(128,128,128,0.75)",
                        "fontSize": "12px",
                        "fontWeight": "600",
                        "minWidth": "16px",
                        "flexShrink": "0"
                    }}>{str(idx + 1)}</span>
                    <span>{mechanisms[idx]}</span>
                </div>
                for idx in range(len(mechanisms))
            ]}

            {<div style={{"marginTop": "14px"}}>
                {<div style={{
                    "backgroundColor": "rgba(128,128,128,0.06)",
                    "borderRadius": "12px",
                    "padding": "16px"
                }}>
                    {<div style={{"color": "rgba(128,128,128,0.6)", "fontSize": "14px", "textAlign": "center"}}>{"No safer alternative found for this chain."}</div>
                    if not replacementData["suggestion"] else
                    <div>
                        <div style={{"fontSize": "12px", "fontWeight": "600", "color": "rgba(128,128,128,0.5)", "letterSpacing": "0.02em", "marginBottom": "10px"}}>{"SUGGESTED REPLACEMENT"}</div>
                        <div style={{
                            "display": "flex",
                            "alignItems": "center",
                            "gap": "8px",
                            "marginBottom": "12px",
                            "flexWrap": "wrap"
                        }}>
                            <span style={{
                                "backgroundColor": "rgba(255,59,48,0.12)",
                                "color": "#ff3b30",
                                "padding": "5px 12px",
                                "borderRadius": "8px",
                                "fontWeight": "500",
                                "fontSize": "13px",
                                "textDecoration": "line-through"
                            }}>{replacementData["suggestion"]["drug_to_replace"]}</span>
                            <span style={{"color": "rgba(128,128,128,0.6)", "fontSize": "13px"}}>{String.fromCharCode(8594)}</span>
                            <span style={{
                                "backgroundColor": "rgba(52,199,89,0.12)",
                                "color": "#34c759",
                                "padding": "5px 12px",
                                "borderRadius": "8px",
                                "fontWeight": "500",
                                "fontSize": "13px"
                            }}>{replacementData["suggestion"]["replacement_drug"]}</span>
                            <span style={{
                                "fontSize": "11px",
                                "color": "rgba(128,128,128,0.5)",
                                "fontWeight": "500"
                            }}>{replacementData["suggestion"]["therapeutic_class"]}</span>
                        </div>
                        <div style={{
                            "fontSize": "13px",
                            "color": "rgba(128,128,128,0.75)",
                            "lineHeight": "1.5",
                            "marginBottom": "10px"
                        }}>{replacementData["suggestion"]["reasoning"]}</div>
