def build_parser() -> any {
    parser = argparse.ArgumentParser(
        prog="traceforge",
        description="Graph-backed trajectory analysis for Codex CLI and Claude Code workflows.",
        epilog=(
            "Quickstart:\n"
            + "  traceforge doctor\n"
            + "  traceforge analyze-batch --batch sample-starter\n"
            + "  traceforge run --batch sample-starter --run invalid_patch\n"
            + "  traceforge pack --batch sample-starter --run invalid_patch --mode structured\n\n"
            + "Core thesis:\n"
            + "  same failed run, same outer model, better evidence pack"
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
    );
    json_parent = argparse.ArgumentParser(add_help=False);
    json_parent.add_argument("--json", action="store_true", help="Render machine-readable JSON.");

    subparsers = parser.add_subparsers(dest="command", required=True);

    subparsers.add_parser("doctor", help="Show provider and environment readiness.", parents=[json_parent]);

    auth = subparsers.add_parser("auth", help="Manage provider preferences.");
    auth_subparsers = auth.add_subparsers(dest="auth_command", required=True);
    auth_subparsers.add_parser("status", help="Show saved provider state.", parents=[json_parent]);
    auth_use = auth_subparsers.add_parser("use", help="Save the preferred provider.", parents=[json_parent]);
    auth_use.add_argument("provider", choices=["auto", "codex", "openai", "anthropic"]);
    auth_use.add_argument("--model", `default="");
    auth_use.add_argument("--openai-api-key", `default="");
    auth_use.add_argument("--anthropic-api-key", `default="");
    auth_use.add_argument("--codex-cli-path", `default="");
    auth_subparsers.add_parser("clear", help="Clear saved API keys and reset provider selection.", parents=[json_parent]);

    analyze = subparsers.add_parser("analyze-batch", help="Analyze a sample or uploaded batch.", parents=[json_parent]);
    analyze.add_argument("--batch", `default="sample-starter");
    analyze.add_argument("--input", `default="");
    analyze.add_argument("--force-rebuild", action="store_true");

    overview = subparsers.add_parser("overview", help="Show batch overview.", parents=[json_parent]);
    overview.add_argument("--batch", required=True);

    run_parser = subparsers.add_parser("run", help="Inspect one run.", parents=[json_parent]);
    run_parser.add_argument("--batch", `default="");
    run_parser.add_argument("--run", required=True);

    cluster = subparsers.add_parser("cluster", help="Inspect one cluster.", parents=[json_parent]);
    cluster.add_argument("--cluster", required=True);

    pack = subparsers.add_parser("pack", help="Emit a raw or structured evidence pack.", parents=[json_parent]);
    pack.add_argument("--batch", `default="");
    pack.add_argument("--run", required=True);
    pack.add_argument("--mode", choices=["raw", "structured"], `default="structured");
    pack.add_argument("--output", `default="");
    pack.add_argument("--save", action="store_true");

    compare = subparsers.add_parser("compare", help="Compare raw versus structured analysis on the same run.", parents=[json_parent]);
    compare.add_argument("--batch", `default="");
    compare.add_argument("--run", required=True);
    compare.add_argument("--provider", `default="auto", choices=["auto", "codex", "openai", "anthropic"]);
    compare.add_argument("--model", `default="");
    compare.add_argument("--strict-provider", action="store_true");
    compare.add_argument("--output", `default="");
    compare.add_argument("--save", action="store_true");

    demo = subparsers.add_parser("demo", help="Generate the full sample demo artifact bundle.", parents=[json_parent]);
    demo.add_argument("--batch", `default="sample-starter");
    demo.add_argument("--run", `default="premature_completion");
    demo.add_argument("--provider", `default="auto", choices=["auto", "codex", "openai", "anthropic"]);
    demo.add_argument("--model", `default="");
    demo.add_argument("--strict-provider", action="store_true");
    demo.add_argument("--output-dir", `default="");

    report_cmd = subparsers.add_parser("export-report", help="Export the batch markdown report.", parents=[json_parent]);
    report_cmd.add_argument("--batch", required=True);

    export_eval = subparsers.add_parser("export-eval", help="Export blinded or rigorous evaluation artifacts.", parents=[json_parent]);
    export_eval.add_argument("--batch", required=True);
    export_eval.add_argument("--kind", choices=["blind", "rigorous"], `default="blind");
    export_eval.add_argument("--limit", type=int, `default=10);
    export_eval.add_argument("--substantive-only", action="store_true");
    export_eval.add_argument("--provider", `default="auto", choices=["auto", "codex", "openai", "anthropic"]);
    export_eval.add_argument("--model", `default="");
    export_eval.add_argument("--strict-provider", action="store_true");
    export_eval.add_argument("--substantive-limit", type=int, `default=20);
    export_eval.add_argument("--startup-limit", type=int, `default=5);
    export_eval.add_argument("--annotation-path", `default="");

    return parser;
}

def main(arg_list: list[str] = []) -> int {
    parser = build_parser();
    args = parser.parse_args(arg_list);

    if args.command == "doctor" {
        payload = _augment_payload(_doctor_payload(), "doctor");
        if args.json {
            return _emit_json(payload);
        }
        _render_doctor(payload);
        return 0;
    }

    if args.command == "auth" {
        if args.auth_command == "status" {
            payload = provider_status_summary();
        } elif args.auth_command == "use" {
            payload = _save_auth(args);
        } else {
            payload = _clear_auth();
        }
        payload = _augment_payload(payload, "auth");
        if args.json {
            return _emit_json(payload);
        }
        _render_doctor(payload);
        return 0;
    }

    if args.command == "analyze-batch" {
        batch_id = _resolve_batch(args);
        payload = analyze_batch_summary(root, batch_id, args.force_rebuild);
        payload = _augment_payload(payload, "analyze-batch");
        if args.json {
            return _emit_json(payload);
        }
        _render_analyze(payload);
        return 0;
    }

    if args.command == "overview" {
        payload = _augment_payload(batch_overview_summary(root, args.batch), "overview");
        if args.json {
            return _emit_json(payload);
        }
        _render_overview(payload);
        return 0;
    }

    if args.command == "run" {
        payload = _augment_payload(run_view_summary(root, args.run, args.batch), "run");
        if args.json {
            return _emit_json(payload);
        }
        _render_run(payload);
        return 0;
    }

    if args.command == "cluster" {
        payload = _augment_payload(cluster_view_summary(root, args.cluster), "cluster");
        if args.json {
            return _emit_json(payload);
        }
        _render_cluster(payload);
        return 0;
    }

    if args.command == "pack" {
        payload = _augment_payload(pack_run_summary(root, args.run, args.batch, args.mode), "pack");
        output_path = args.output or _default_pack_output_path(
            str(payload.get("batch_id") or args.batch or "batch"),
            str(payload.get("run_id") or args.run),
            str(payload.get("mode") or args.mode),
        );
        payload = _save_pack_artifact(payload, output_path if (args.output or args.save) else "", args.save);
        if args.json {
            return _emit_json(payload);
        }
        _render_pack(payload);
        return 0;
    }

    if args.command == "compare" {
        payload = compare_run_harness_summary(root, args.run, args.batch, args.provider, args.model);
        _enforce_strict_provider(payload, args.provider, args.strict_provider);
        payload = _augment_payload(payload, "compare", args.provider, args.strict_provider);
        output_path = args.output or _default_compare_output_path(
            str(payload.get("batch_id") or args.batch or "batch"),
            str(payload.get("run_id") or args.run),
            str(payload.get("provider") or args.provider or "auto"),
        );
        payload = _save_compare_artifact(payload, output_path if (args.output or args.save) else "", args.save);
        if args.json {
            return _emit_json(payload);
        }
        _render_compare(payload);
        return 0;
    }

    if args.command == "demo" {
        demo_dir = args.output_dir or _default_demo_output_dir(args.batch, args.run);
        analyze_payload = _augment_payload(analyze_batch_summary(root, args.batch), "analyze-batch");
        run_payload = _augment_payload(run_view_summary(root, args.run, args.batch), "run");
        raw_payload = _save_pack_artifact(
            _augment_payload(pack_run_summary(root, args.run, args.batch, "raw"), "pack"),
            demo_dir + "/raw.md",
            True,
        );
        structured_payload = _save_pack_artifact(
            _augment_payload(pack_run_summary(root, args.run, args.batch, "structured"), "pack"),
            demo_dir + "/structured.md",
            True,
        );
        compare_payload = compare_run_harness_summary(root, args.run, args.batch, args.provider, args.model);
        _enforce_strict_provider(compare_payload, args.provider, args.strict_provider);
        compare_payload = _save_compare_artifact(
            _augment_payload(compare_payload, "compare", args.provider, args.strict_provider),
            demo_dir + "/comparison.json",
            True,
        );
        report_payload = _augment_payload(export_report_summary(root, args.batch), "export-report");
        report_path = str(report_payload.get("path") or "");
        copied_report = "";
        if report_path {
            copied_report = _copy_text_artifact(report_path, demo_dir + "/report.md");
        }
        bundle = {
            "status": "demo_bundle_ready",
            "command": "demo",
            "batch_id": args.batch,
            "run_id": args.run,
            "provider": str(compare_payload.get("provider") or ""),
            "comparison_mode": str(compare_payload.get("comparison_mode") or ""),
            "strict_provider": args.strict_provider,
            "warning": str(compare_payload.get("warning") or ""),
            "artifact_paths": {
                "raw_pack": str(raw_payload.get("artifact_paths", {}).get("pack_path") or ""),
                "structured_pack": str(structured_payload.get("artifact_paths", {}).get("pack_path") or ""),
                "comparison": str(compare_payload.get("artifact_paths", {}).get("comparison_path") or ""),
                "report": copied_report or report_path,
            },
            "analyze": analyze_payload,
            "run": run_payload,
        };
        if args.json {
            return _emit_json(bundle);
        }
        _render_demo(bundle);
        return 0;
    }

    if args.command == "export-report" {
        payload = _augment_payload(export_report_summary(root, args.batch), "export-report");
        if args.json {
            return _emit_json(payload);
        }
        _render_export_report(payload);
        return 0;
    }

    if args.command == "export-eval" {
        strict_resolution = provider_resolution_summary(args.provider);
        strict_provider_name = str(strict_resolution.get("provider") or args.provider or "");
        if args.kind == "rigorous" {
            payload = run_rigorous_eval_summary(
                root,
                args.batch,
                args.provider,
                args.model,
                int(args.substantive_limit),
                int(args.startup_limit),
                args.annotation_path,
            );
            if args.strict_provider {
                if args.provider in {"", "auto"} and not strict_provider_name {
                    raise SystemExit("Strict provider mode requires a live resolved provider. Run `traceforge doctor` first.");
                }
                if payload.get("comparison_mode") == "deterministic_proxy" {
                    raise SystemExit(
                        "Rigorous evaluation fell back to deterministic proxy. Strict mode expected live provider `"
                        + str(strict_provider_name or args.provider)
                        + "`."
                    );
                }
            }
        } else {
            payload = export_blinded_eval_summary(
                root,
                args.batch,
                int(args.limit),
                bool(args.substantive_only),
                args.provider,
                args.model,
            );
            if args.strict_provider {
                if args.provider in {"", "auto"} and not strict_provider_name {
                    raise SystemExit("Strict provider mode requires a live resolved provider. Run `traceforge doctor` first.");
                }
                if payload.get("comparison_mode") == "deterministic_proxy" {
                    raise SystemExit(
                        "Blinded export fell back to deterministic proxy. Strict mode expected live provider `"
                        + str(strict_provider_name or args.provider)
                        + "`."
                    );
                }
            }
        }
        payload = _augment_payload(payload, "export-eval", args.provider, args.strict_provider);
        if args.json {
            return _emit_json(payload);
        }
        _render_export_eval(payload);
        return 0;
    }

    parser.error("Unknown command.");
    return 2;
}

with entry:__main__ {
    raise SystemExit(main(list(argv[1:])));
}

import from traceforge.features {
    cosine_like_overlap,
    dominant_failure_label,
    summarize_counts,
    top_k_indices
}

def failure_class_label(failure_class: str) -> str {
    labels = {
        "PREMATURE_COMPLETION": "Premature completion",
        "INVALID_PATCH": "Invalid patching",
        "WRONG_FILE_FOCUS": "Wrong-file focus",
        "OSCILLATION_LOOP": "Oscillation loop",
        "TOOL_MISUSE": "Tool misuse",
        "STALE_CONTEXT_OR_BAD_PLAN": "Stale context or bad plan",
        "REQUIREMENT_DRIFT": "Requirement drift",
        "UNKNOWN": "Recovered or unclassified",
    };
    return labels.get(failure_class, failure_class.replace("_", " ").title());
}

def _sequence_similarity(left: list[str], right: list[str]) -> float {
    if not left and not right {
        return 1.0;
    }
    return cosine_like_overlap(left, right);
}

def similarity_score(left: dict[str, any], right: dict[str, any]) -> float {
    left_scores = left.get("failure_class_scores", {});
    right_scores = right.get("failure_class_scores", {});
    left_failure_tokens: list[str] = [];
    right_failure_tokens: list[str] = [];
    for key in left_scores {
        left_failure_tokens.append(f"{key}:{round(float(left_scores[key]), 2)}");
    }
    for key in right_scores {
        right_failure_tokens.append(f"{key}:{round(float(right_scores[key]), 2)}");
    }

    failure_overlap = cosine_like_overlap(left_failure_tokens, right_failure_tokens);
    sequence_similarity = _sequence_similarity(left.get("step_kind_sequence", []), right.get("step_kind_sequence", []));
    lexical_overlap = cosine_like_overlap(
        left.get("top_files", []) + left.get("top_test_names", []) + left.get("top_error_keywords", []),
        right.get("top_files", []) + right.get("top_test_names", []) + right.get("top_error_keywords", []),
    );
    numeric_distance = (
        abs(float(left.get("num_steps", 0)) - float(right.get("num_steps", 0)))
        + abs(float(left.get("num_tests", 0)) - float(right.get("num_tests", 0)))
        + abs(float(left.get("num_patches", 0)) - float(right.get("num_patches", 0)))
        + abs(float(left.get("repeated_step_ratio", 0.0)) - float(right.get("repeated_step_ratio", 0.0)))
        + abs(float(left.get("repeated_file_ratio", 0.0)) - float(right.get("repeated_file_ratio", 0.0)))
        + abs(float(left.get("loop_score", 0.0)) - float(right.get("loop_score", 0.0)))
    );
    numeric_similarity = 1.0 - min(1.0, numeric_distance / 6.0);
    return round(
        (0.35 * failure_overlap)
        + (0.20 * sequence_similarity)
        + (0.20 * lexical_overlap)
        + (0.15 * numeric_similarity)
        + (0.10 * lexical_overlap),
        4,
    );
}

def top_k_neighbors(target_index: int, fingerprints: list[dict[str, any]], k: int = 5) -> list[dict[str, any]] {
    scores: list[dict[str, any]] = [];
    target = fingerprints[target_index];
    for (index, other) in enumerate(fingerprints) {
        if index == target_index {
            continue;
        }
        scores.append({"index": index, "score": similarity_score(target, other)});
    }
    top = top_k_indices([float(item["score"]) for item in scores], k);
    return [scores[index] for index in top];
}

def threshold_edges(neighbor_sets: list[list[dict[str, any]]], threshold: float) -> list[tuple[int, int, float]] {
    edges: list[tuple[int, int, float]] = [];
    for (source_index, neighbors) in enumerate(neighbor_sets) {
        for neighbor in neighbors {
            if float(neighbor["score"]) >= threshold {
                edges.append((source_index, int(neighbor["index"]), float(neighbor["score"])));
            }
        }
    }
    return edges;
}

def _connected_components(size: int, edges: list[tuple[int, int, float]]) -> list[list[int]] {
    adjacency: dict[int, list[int]] = {};
    for index = 0 while index<size with index+=1 {
        adjacency[index] = [];
    }
    for edge in edges {
        left = edge[0];
        right = edge[1];
        adjacency[left].append(right);
        adjacency[right].append(left);
    }

    seen: set[int] = set();
    components: list[list[int]] = [];
    for node_index = 0 while node_index<size with node_index+=1 {
        if node_index in seen {
            continue;
        }
        stack = [node_index];
        component: list[int] = [];
        seen.add(node_index);
        while stack {
            current = stack.pop();
            component.append(current);
            for neighbor in adjacency[current] {
                if neighbor in seen {
                    continue;
                }
                seen.add(neighbor);
                stack.append(neighbor);
            }
        }
        components.append(sorted(component));
    }
    return components;
}

def _medoid_run_id(component_records: list[dict[str, any]]) -> str {
    if len(component_records) == 1 {
        return str(component_records[0]["run_id"]);
    }
    best_run_id = str(component_records[0]["run_id"]);
    best_score = -1.0;
    for record in component_records {
        total = 0.0;
        count = 0;
        for other in component_records {
            if record["run_id"] == other["run_id"] {
                continue;
            }
            total += similarity_score(record["fingerprint"], other["fingerprint"]);
            count += 1;
        }
        average = total / max(count, 1);
        if average > best_score {
            best_score = average;
            best_run_id = str(record["run_id"]);
        }
    }
    return best_run_id;
}

def _component_similar_pairs(
    component: list[int],
    edges: list[tuple[int, int, float]],
    family_records: list[dict[str, any]],
) -> list[dict[str, any]] {
    component_set: set[int] = set(component);
    dedup: dict[str, dict[str, any]] = {};
    for edge in edges {
        left_index = edge[0];
        right_index = edge[1];
        if left_index not in component_set or right_index not in component_set {
            continue;
        }
        left_run_id = str(family_records[left_index]["run_id"]);
        right_run_id = str(family_records[right_index]["run_id"]);
        if left_run_id == right_run_id {
            continue;
        }
        left_id = left_run_id;
        right_id = right_run_id;
        if right_id < left_id {
            left_id = right_run_id;
            right_id = left_run_id;
        }
        pair_key = left_id + "||" + right_id;
        score = float(edge[2]);
        existing = dedup.get(pair_key);
        if existing is None or score > float(existing["score"]) {
            dedup[pair_key] = {
                "left_run_id": left_id,
                "right_run_id": right_id,
                "score": score,
            };
        }
    }
    return sorted(
        [dedup[key] for key in dedup],
        key=lambda (item: any) -> any { (-float(item["score"]), item["left_run_id"], item["right_run_id"]) },
    );
}

def build_clusters(run_records: list[dict[str, any]], batch_id: str, top_k: int = 3, threshold: float = 0.55) -> list[dict[str, any]] {
    by_family: dict[str, list[dict[str, any]]] = {};
    for record in run_records {
        family = str(record.get("primary_failure") or dominant_failure_label(record["fingerprint"]));
        if family not in by_family {
            by_family[family] = [];
        }
        by_family[family].append(record);
    }

    clusters: list[dict[str, any]] = [];
    for family in by_family {
        family_records = by_family[family];
        fingerprints = [record["fingerprint"] for record in family_records];
        neighbor_sets: list[list[dict[str, any]]] = [];
        for index = 0 while index<len(fingerprints) with index+=1 {
            neighbor_sets.append(top_k_neighbors(index, fingerprints, top_k));
        }
        edges = threshold_edges(neighbor_sets, threshold);
        components = _connected_components(len(family_records), edges);
        for (component_index, component) in enumerate(components) {
            component_records = [family_records[index] for index in component];
            similar_pairs = _component_similar_pairs(component, edges, family_records);
            component_files: list[str] = [];
            component_errors: list[str] = [];
            component_tests: list[str] = [];
            run_ids: list[str] = [];
            for record in component_records {
                run_ids.append(str(record["run_id"]));
                component_files.extend(record["fingerprint"].get("top_files", []));
                component_errors.extend(record["fingerprint"].get("top_error_keywords", []));
                component_tests.extend(record["fingerprint"].get("top_test_names", []));
            }
            cluster_id = f"{batch_id}:{family.lower()}:{component_index}";
            clusters.append(
                {
                    "cluster_id": cluster_id,
                    "label": failure_class_label(family),
                    "failure_class": family,
                    "size": len(component_records),
                    "medoid_run_id": _medoid_run_id(component_records),
                    "run_ids": run_ids,
                    "similar_pairs": similar_pairs,
                    "recurring_files": summarize_counts(component_files, 5),
                    "recurring_errors": summarize_counts(component_errors, 5),
                    "recurring_tests": summarize_counts(component_tests, 5),
                    "summary": f"{failure_class_label(family)} cluster with {len(component_records)} run(s).",
                }
            );
        }
    }

    return sorted(clusters, key=lambda (cluster: any) -> any { (-cluster["size"], cluster["cluster_id"]) });
}

def find_cluster(clusters: list[dict[str, any]], cluster_id: str) -> dict[str, any] {
    for cluster in clusters {
        if cluster["cluster_id"] == cluster_id {
            return cluster;
        }
    }
    return {};
}

import from traceforge.parser { ParsedRun, ParsedStep, step_text }
import from traceforge.features { bounded_ratio }

def _has_error_signal(text: str) -> bool {
    lower = text.lower();
    return any(token in lower for token in ["traceback", "error", "exception", "failed", "syntaxerror"]);
}

def _has_recovery_signal(text: str) -> bool {
    lower = text.lower();
    return any(token in lower for token in ["1 passed", " passed", "resolved", "fixed", "success"]);
}

def _has_submit_signal(text: str) -> bool {
    lower = text.lower();
    return "submit" in lower or "final" in lower;
}

def _has_patch_signal(text: str) -> bool {
    lower = text.lower();
    return "patch" in lower or "diff" in lower or "apply_patch" in lower;
}

def _has_test_signal(text: str) -> bool {
    lower = text.lower();
    return "pytest" in lower or "test" in lower;
}

def _step_texts(run: ParsedRun) -> list[str] {
    output: list[str] = [];
    for step in run.steps {
        output.append(step_text(step));
    }
    return output;
}

def candidate_step_indices(run: ParsedRun, fingerprint: dict[str, any]) -> list[int] {
    candidates: list[int] = [];
    for key in ["first_patch_step", "first_test_step", "first_error_step", "first_submit_step"] {
        value = int(fingerprint.get(key, -1));
        if value >= 0 and value not in candidates {
            candidates.append(value);
        }
    }

    seen_hashes: dict[str, int] = {};
    seen_files: dict[str, int] = {};
    for (index, step) in enumerate(run.steps) {
        if step.content_hash and step.content_hash in seen_hashes and index not in candidates {
            candidates.append(index);
        }
        if step.content_hash {
            seen_hashes[step.content_hash] = index;
        }
        if step.touched_files {
            key = "|".join(step.touched_files);
            if key in seen_files and index not in candidates {
                candidates.append(index);
            }
            seen_files[key] = index;
        }
    }
    return sorted(candidates);
}

def build_evidence_window(run: ParsedRun, center_index: int, radius: int = 1) -> list[dict[str, any]] {
    window: list[dict[str, any]] = [];
    if center_index < 0 {
        return window;
    }
    start = max(center_index - radius, 0);
    stop = min(center_index + radius, len(run.steps) - 1);
    for index = start while index<=stop with index+=1 {
        step = run.steps[index];
        window.append(
            {
                "idx": step.index,
                "kind": step.kind,
                "phase": step.phase,
                "excerpt": step.excerpt,
            }
        );
    }
    return window;
}

def score_candidate_step(run: ParsedRun, fingerprint: dict[str, any], index: int) -> dict[str, any] {
    texts = _step_texts(run);
    text = texts[index];
    lower = text.lower();
    later_texts = texts[index + 1:];
    current_has_error = _has_error_signal(text);
    later_has_error = any(_has_error_signal(item) for item in later_texts);
    later_has_recovery = any(_has_recovery_signal(item) for item in later_texts);
    next_has_error = False;
    if index + 1 < len(texts) {
        next_has_error = _has_error_signal(texts[index + 1]);
    }

    persistence_of_damage = 0.35 if later_has_error and not later_has_recovery else 0.0;
    new_error_after_step = 0.25 if (not current_has_error and next_has_error) else 0.0;
    no_recovery_after_step = 0.2 if not later_has_recovery else 0.0;
    divergence_from_target_files = 0.0;
    top_files = fingerprint.get("top_files", []);
    current_files = run.steps[index].touched_files;
    if current_files and top_files {
        overlap = 0;
        for file_path in current_files {
            if file_path in top_files {
                overlap += 1;
            }
        }
        if bounded_ratio(overlap, len(current_files)) < 0.34 {
            divergence_from_target_files = 0.15;
        }
    }
    premature_submit_signal = 0.0;
    first_submit = int(fingerprint.get("first_submit_step", -1));
    if bool(fingerprint.get("submit_before_recovery")) and (index == first_submit or index + 1 == first_submit) {
        premature_submit_signal = 0.3;
    }
    loop_start_signal = 0.0;
    if float(fingerprint.get("loop_score", 0.0)) >= 0.35 {
        if index + 1 < len(run.steps) {
            next_step = run.steps[index + 1];
            if next_step.content_hash == run.steps[index].content_hash {
                loop_start_signal = 0.2;
            } elif run.steps[index].touched_files and next_step.touched_files and run.steps[index].touched_files == next_step.touched_files {
                loop_start_signal = 0.15;
            }
        } elif _has_submit_signal(text) and not later_has_recovery {
            loop_start_signal = 0.1;
        }
    }
    patch_to_error_signal = 0.0;
    if _has_patch_signal(text) and later_has_error and not later_has_recovery {
        patch_to_error_signal = 0.25;
    }
    test_failure_signal = 0.0;
    if _has_test_signal(text) and current_has_error and not later_has_recovery {
        test_failure_signal = 0.15;
    }
    recovery_signal = 0.25 if later_has_recovery else 0.0;

    score = round(
        persistence_of_damage
        + new_error_after_step
        + no_recovery_after_step
        + divergence_from_target_files
        + premature_submit_signal
        + loop_start_signal
        + patch_to_error_signal
        + test_failure_signal
        - recovery_signal,
        4,
    );
    return {
        "step_idx": index,
        "score": score,
        "signals": {
            "persistence_of_damage": persistence_of_damage,
            "new_error_after_step": new_error_after_step,
            "no_recovery_after_step": no_recovery_after_step,
            "divergence_from_target_files": divergence_from_target_files,
            "premature_submit_signal": premature_submit_signal,
            "loop_start_signal": loop_start_signal,
            "patch_to_error_signal": patch_to_error_signal,
            "test_failure_signal": test_failure_signal,
            "recovery_signal": recovery_signal,
        },
    };
}

def localize_critical_step(run: ParsedRun, fingerprint: dict[str, any]) -> dict[str, any] {
    if str(run.metadata.get("status") or "").lower() in {"resolved", "passed", "success", "succeeded"} {
        return {
            "critical_step_idx": -1,
            "confidence": 0.0,
            "candidate_scores": [],
            "evidence_window": [],
            "status": "resolved_run",
        };
    }

    candidates = candidate_step_indices(run, fingerprint);
    if not candidates and len(run.steps) > 0 {
        candidates = [0];
    }

    scored: list[dict[str, any]] = [];
    for candidate in candidates {
        scored.append(score_candidate_step(run, fingerprint, candidate));
    }

    chosen_idx = -1;
    chosen_score = -999.0;
    threshold = 0.45;
    for item in scored {
        item_score = float(item["score"]);
        item_idx = int(item["step_idx"]);
        if item_score >= threshold {
            chosen_idx = item_idx;
            chosen_score = item_score;
            break;
        }
        if item_score > chosen_score or (item_score == chosen_score and (chosen_idx < 0 or item_idx < chosen_idx)) {
            chosen_idx = item_idx;
            chosen_score = item_score;
        }
    }

    rounded_score: float = round(chosen_score, 4);
    return {
        "critical_step_idx": chosen_idx,
        "confidence": max(rounded_score, 0.0),
        "candidate_scores": scored,
        "evidence_window": build_evidence_window(run, chosen_idx),
        "status": "localized",
    };
}

