    has ext: str = "";
}

node Patch {
    has patch_id: str;
    has file_path: str = "";
    has adds: int = 0;
    has dels: int = 0;
    has parse_ok: bool = True;
    has patch_hash: str = "";
}

node TestEvent {
    has test_id: str;
    has command: str = "";
    has status: str = "";
    has failing_tests: list[str] = [];
    has excerpt: str = "";
}

node ErrorEvent {
    has error_id: str;
    has error_type: str = "";
    has message: str = "";
    has severity: Severity = Severity.ERROR;
}

node FailureHypothesis {
    has hyp_id: str;
    has label: FailureClass;
    has score: float = 0.0;
    has rationale: str = "";
}

node Cluster {
    has cluster_id: str;
    has label: str = "";
    has failure_class: FailureClass = FailureClass.UNKNOWN;
    has size: int = 0;
    has medoid_run_id: str = "";
    has summary: str = "";
}

node MemoryPatch {
    has patch_id: str;
    has scope: str = "";
    has title: str = "";
    has diff_text: str = "";
    has confidence: float = 0.0;
}

obj EvidenceRef {
    has step_idx: int;
    has artifact: str;
    has quote: str = "";
}

obj RunDiagnosis {
    has failure_class: FailureClass = FailureClass.UNKNOWN;
    has critical_step_idx: int = -1;
    has irreversible_because: str = "";
    has evidence: list[EvidenceRef] = [];
    has confidence: float = 0.0;
}

obj ClusterLabel {
    has label: str;
    has summary: str = "";
    has confidence: float = 0.0;
}

obj MemoryRule {
    has title: str;
    has rationale: str = "";
    has rule_text: str = "";
    has supported_by_steps: list[int] = [];
    has confidence: float = 0.0;
}

obj MemoryPatchProposal {
    has scope: str;
    has cluster_label: str = "";
    has summary: str = "";
    has rules: list[MemoryRule] = [];
    has diff_text: str = "";
}

obj ComparisonVerdict {
    has winner: str = "";
    has raw_score: float = 0.0;
